    const isAirCombatNeoAssist = normalisedAssistOperationalModel === 'air_combat';
    const isFixedCrewNeoAssist = isFixedCrewLikeOperationalModel(normalisedAssistOperationalModel);
    const defaultAssistTaskDuration = isFixedCrewNeoAssist ? FIXED_CREW_DEFAULT_TASKING_DURATION_HOURS : 1.2;
    const defaultAssistCurrencyDuration = isFixedCrewNeoAssist ? FIXED_CREW_DEFAULT_CURRENCY_DURATION_HOURS : 1.2;
    const [assistTaskDate, setAssistTaskDate] = useState(date);
    const [assistTaskTakeoff, setAssistTaskTakeoff] = useState(flyingStartTime);
    const [assistTaskDuration, setAssistTaskDuration] = useState(defaultAssistTaskDuration);
    const [assistTaskFlightType, setAssistTaskFlightType] = useState<'Solo' | 'Dual'>('Solo');
    const [assistTaskDepPoint, setAssistTaskDepPoint] = useState(locationCode);
    const [assistTaskArrivalPoint, setAssistTaskArrivalPoint] = useState(locationCode);
    const [assistTaskAircraftCount, setAssistTaskAircraftCount] = useState(1);
    const [assistTaskConfigId, setAssistTaskConfigId] = useState(BASE_AIRCRAFT_CONFIG.id);
    const [assistTaskMandatory, setAssistTaskMandatory] = useState(true);
    const assistTaskingUnitCodes = useMemo(() => {
        const codes = String(activeUnitCode || '')
            .split(/[+/]/)
            .map(code => String(code || '').trim().toUpperCase())
            .filter(Boolean);
        return codes;
    }, [activeUnitCode]);
    const assistTaskingUnitCode = assistTaskingUnitCodes.join('+') || String(activeUnitCode || '').trim().toUpperCase();
    const getAssistTaskingScopeCodes = (request: any): string[] => {
        const explicitCodes = Array.isArray(request?.unitCodes)
            ? request.unitCodes.map((code: any) => String(code || '').trim().toUpperCase()).filter(Boolean)
            : [];
        const unitCode = String(request?.unitCode || '').trim().toUpperCase();
        if (unitCode) explicitCodes.push(...unitCode.split(/[+/]/).map(code => code.trim()).filter(Boolean));
        const uniqueCodes = Array.from(new Set(explicitCodes.filter(Boolean)));
        return uniqueCodes.length > 0 ? uniqueCodes : assistTaskingUnitCodes;
    };
    const assistTaskingMatchesActiveScope = (request: any): boolean => {
        const scopeCodes = getAssistTaskingScopeCodes(request);
        if (assistTaskingUnitCodes.length === 0) return true;
        return scopeCodes.some(code => assistTaskingUnitCodes.includes(code));
    };
    const normaliseAssistTaskRequest = (request: any) => {
        const scopeCodes = getAssistTaskingScopeCodes(request);
        const unitCode = String(request.unitCode || scopeCodes.join('+') || assistTaskingUnitCode || '').trim().toUpperCase();
        return ({
        id: request.id || uuidv4(),
        unitCode,
        unitCodes: scopeCodes,
        tasking: request.tasking || '',
        date: request.date || date,
        takeoff: Number.isFinite(Number(request.takeoff)) ? Number(request.takeoff) : flyingStartTime,
        duration: Number.isFinite(Number(request.duration)) && Number(request.duration) > 0 ? Number(request.duration) : defaultAssistTaskDuration,
        flightType: request.flightType === 'Solo' ? 'Solo' as const : 'Dual' as const,
        depPoint: request.depPoint || locationCode,
        arrivalPoint: request.arrivalPoint || locationCode,
        aircraftCount: Math.max(1, parseInt(String(request.aircraftCount || '1'), 10) || 1),
        aircraftConfigId: request.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id,
        isMandatory: request.isMandatory !== false,
        saved: Boolean(request.saved || request.submitted),
        submitted: Boolean(request.submitted),
        ignored: Boolean(request.ignored),
        });
    };
    const loadStoredAssistTaskRequests = () => {
        try {
            const stored = window.localStorage.getItem(TASKING_REQUEST_STORAGE_KEY);
            const parsed = stored ? JSON.parse(stored) : [];
            return Array.isArray(parsed) ? parsed.map(normaliseAssistTaskRequest) : [];
        } catch {
            return [];
        }
    };
    const [assistTaskRequests, setAssistTaskRequests] = useState<Array<{
        id: string;
        tasking: string;
        date: string;
        takeoff: number;
        duration: number;
        flightType: 'Solo' | 'Dual';
        depPoint: string;
        arrivalPoint: string;
        aircraftCount: number;
        aircraftConfigId: string;
        unitCode?: string;
        unitCodes?: string[];
        isMandatory: boolean;
        saved?: boolean;
        submitted?: boolean;
        ignored?: boolean;
    }>>(() => loadStoredAssistTaskRequests());
    const visibleAssistTaskRequests = useMemo(
        () => assistTaskRequests.filter(assistTaskingMatchesActiveScope),
        [assistTaskRequests, assistTaskingUnitCodes.join('|')]
    );
    const [assistCurrencyDate, setAssistCurrencyDate] = useState(date);
