// --- UTILITY FUNCTIONS ---
const isOverlapping = (f1: Omit<ScheduleEvent, 'date'>, f2: Omit<ScheduleEvent, 'date'>): boolean => {
    if (!f1 || !f2 || f1.duration <= 0 || f2.duration <= 0) return false;
    const f1_end = f1.startTime + f1.duration;
    const f2_end = f2.startTime + f2.duration;
    return f1.startTime < f2_end && f1_end > f2.startTime;
};

const getPersonnel = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): string[] => {
    const personnel = new Set<string>();
    const addPersonnel = (name?: string) => {
        if (!isPlaceholderPersonnelName(name)) personnel.add(name || '');
    };

    const isTaskingEvent = event.isTaskingRequest === true || !!event.taskingRequestId || String(event.id || '').startsWith('tasking-');
    const isSctEvent = isContinuationScheduleEvent(event);

    if (isTaskingEvent) {
        if (event.pilot) addPersonnel(event.pilot);
        if (event.crew) addPersonnel(event.crew);
        if (event.instructor) addPersonnel(event.instructor);
    } else if (isSctEvent) {
        // For continuation events: pilot (PIC) + crew (second pilot)
        if (event.pilot) addPersonnel(event.pilot);
        if (event.crew) addPersonnel(event.crew);
    } else if (event.flightType === 'Solo') {
        if (event.pilot) addPersonnel(event.pilot);
    } else {
        // For non-continuation Dual training events, the instructor field is authoritative.
        // The pilot field is a legacy mirror of instructor and may be stale after crew swaps.
        if (event.instructor) addPersonnel(event.instructor);
        else if (event.pilot) addPersonnel(event.pilot);
        if (event.crew && !event.student) addPersonnel(event.crew);
        if (event.student) addPersonnel(event.student);
    }

    if (event.attendees) event.attendees.forEach(addPersonnel);
    if (event.groupTraineeIds && event.groupTraineeIds.length > 0) {
        // In a real app you'd resolve these IDs to names, but for conflict checks, the presence of people is enough.
        // For now, let's assume if there are group IDs, the main people are already in instructor/student fields for conflict checks.
        // This function is mainly for conflict detection, not display.
    }
    return Array.from(personnel);
};

const PERSONNEL_RANK_PREFIX_RE = /^(ACM|AIRMSHL|AVM|AIRCDRE|GPCAPT|WGCDR|SQNLDR|FLTLT|FLGOFF|PLTOFF|OFFCDT|WOFF|FSGT|SGT|CPL|LACW?|ACW?|MIDN|CMDR|LCDR|LEUT|SBLT|ASLT|CDRE|CAPT|COL|LTCOL|MAJ|LT|2LT|WO1|WO2|SSGT|PTE|MR|MRS|MS|MISS|DR)\s+/i;

const PLACEHOLDER_PERSONNEL_NAMES = new Set(['tba', 'to be advised', 'multiple', 'group']);

const isPlaceholderPersonnelName = (name?: string): boolean => {
    const normalizedName = (name || '').replace(/\s+/g, ' ').trim().toLowerCase();
    return !normalizedName || PLACEHOLDER_PERSONNEL_NAMES.has(normalizedName);
};

const normalizePersonnelNameForMatch = (name?: string): string =>
    (name || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(PERSONNEL_RANK_PREFIX_RE, '')
        .replace(/\s+[–-]\s+[A-Z]{2,}\d+$/i, '')
        .toLowerCase();

const personnelNamesMatch = (a?: string, b?: string): boolean => {
    const left = normalizePersonnelNameForMatch(a);
    const right = normalizePersonnelNameForMatch(b);
    return !!left && left === right;
};

const isNeoBuildVerboseDiagnosticsEnabled = (): boolean =>
    typeof window !== 'undefined' && window.localStorage?.getItem('neo_build_verbose_diag') === 'true';

interface NeoBuildTimingPhase {
    name: string;
    durationMs: number;
    totalElapsedMs: number;
    details?: Record<string, any>;
}

interface NeoBuildTimingReport {
    timestamp: string;
    buildDate: string;
    phases: NeoBuildTimingPhase[];
    counters: Record<string, any>;
    startedAtMs?: number;
    lastMarkMs?: number;
    completedAt?: string;
    totalElapsedMs?: number;
}

const createNeoBuildTimingReport = (buildDate: string, counters: Record<string, any> = {}): NeoBuildTimingReport => {
    const now = performance.now();
    return {
        timestamp: new Date().toISOString(),
        buildDate,
        phases: [],
        counters,
        startedAtMs: now,
        lastMarkMs: now,
    };
};

const saveNeoBuildTimingReport = (report?: NeoBuildTimingReport) => {
    if (!report) return;
    try {
        localStorage.setItem('neo_build_timing_report', JSON.stringify(report));
    } catch (error) {
        console.warn('[NEO-BUILD-TIMING] Failed to save timing report:', error);
    }
};

const markNeoBuildTiming = (
    report: NeoBuildTimingReport | undefined,
    name: string,
    details?: Record<string, any>
) => {
    if (!report || report.startedAtMs === undefined || report.lastMarkMs === undefined) return;
    const now = performance.now();
    report.phases.push({
        name,
        durationMs: Math.round(now - report.lastMarkMs),
        totalElapsedMs: Math.round(now - report.startedAtMs),
        ...(details ? { details } : {}),
    });
    report.lastMarkMs = now;
    report.completedAt = new Date().toISOString();
    report.totalElapsedMs = Math.round(now - report.startedAtMs);
    saveNeoBuildTimingReport(report);
};

type PersonnelIdentityRole = 'staff' | 'trainee';

interface PersonnelIdentityRef {
    label: string;
    role: PersonnelIdentityRole;
    key: string;
}

const makePersonnelIdentityRef = (label: string | undefined, role: PersonnelIdentityRole): PersonnelIdentityRef | null => {
    if (isPlaceholderPersonnelName(label)) return null;
    const normalizedName = normalizePersonnelNameForMatch(label);
    if (!normalizedName) return null;
    return {
        label: label || '',
        role,
        key: `${role}:${normalizedName}`
    };
};

const getPersonnelIdentityRefs = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): PersonnelIdentityRef[] => {
    const refsByKey = new Map<string, PersonnelIdentityRef>();
    const addRef = (label: string | undefined, role: PersonnelIdentityRole) => {
        const ref = makePersonnelIdentityRef(label, role);
        if (ref && !refsByKey.has(ref.key)) refsByKey.set(ref.key, ref);
    };

    const isTaskingEvent = event.isTaskingRequest === true || !!event.taskingRequestId || String(event.id || '').startsWith('tasking-');
    const isSctEvent = isContinuationScheduleEvent(event);

    if (isTaskingEvent) {
        addRef(event.pilot, 'staff');
        addRef(event.crew, 'staff');
    } else if (isSctEvent) {
        addRef(event.pilot, 'staff');
        addRef(event.crew, 'staff');
    } else if (event.flightType === 'Solo') {
        addRef(event.pilot || event.student, 'trainee');
    } else {
        addRef(event.instructor || event.pilot, 'staff');
        if (event.crew && !event.student) addRef(event.crew, 'staff');
        addRef(event.student, 'trainee');
    }

    event.attendees?.forEach(personName => addRef(personName, 'trainee'));
    return Array.from(refsByKey.values());
};

const eventHasPersonWithRole = (
    event: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    personName: string | undefined,
    role: PersonnelIdentityRole
): boolean => {
    const ref = makePersonnelIdentityRef(personName, role);
    if (!ref) return false;
    return getPersonnelIdentityRefs(event).some(eventRef => eventRef.key === ref.key);
};

const eventHasPerson = (
    event: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    personName?: string
): boolean => getPersonnel(event).some(p => personnelNamesMatch(p, personName));

const getCommonPersonnel = (
    eventA: Omit<ScheduleEvent, 'date'> | ScheduleEvent,
    eventB: Omit<ScheduleEvent, 'date'> | ScheduleEvent
): string[] => {
    const eventBPersonnelKeys = new Set(getPersonnelIdentityRefs(eventB).map(person => person.key));
    return getPersonnelIdentityRefs(eventA)
        .filter(person => eventBPersonnelKeys.has(person.key))
        .map(person => person.label);
};

const normaliseCrewFieldsForSave = (event: ScheduleEvent): ScheduleEvent => {
    const normalised = { ...event };
    const isSctEvent = isContinuationScheduleEvent(normalised);

    if (isSctEvent) {
        normalised.instructor = '';
        return normalised;
    }

    if ((normalised.type === 'flight' || normalised.type === 'ftd') && normalised.flightType === 'Solo') {
        normalised.pilot = normalised.pilot || normalised.student || '';
        normalised.instructor = '';
        normalised.student = '';
        return normalised;
    }

    if ((normalised.type === 'flight' || normalised.type === 'ftd') && normalised.instructor) {
        normalised.pilot = normalised.instructor;
    }

    return normalised;
};

const isDutySupervisorEvent = (event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): boolean =>
    event.flightNumber === 'Duty Sup' ||
    event.flightNumber === 'Night Duty Sup' ||
    event.resourceId === 'Duty Sup';

const isStbyResource = (resourceId?: string): boolean =>
    !!resourceId && (resourceId.startsWith('STBY') || resourceId.startsWith('BNF-STBY'));

const getNonNegativeFiniteNumber = (value: unknown): number | null => {
    const numeric = Number(value);
    return Number.isFinite(numeric) && numeric >= 0 ? numeric : null;
};

const normaliseBookingDurationHours = (value: unknown): number => {
    const numeric = getNonNegativeFiniteNumber(value);
    if (numeric === null) return 0;
    return numeric > 24 ? numeric / 60 : numeric;
};

const getScheduleEventBookingOffsets = (
    event: Pick<ScheduleEvent, 'startTime' | 'duration' | 'preStart' | 'postEnd'>,
    syllabusItem?: SyllabusItemDetail
): { preOffset: number; postOffset: number } => {
    const startTime = Number(event.startTime) || 0;
    const duration = Math.max(0, Number(event.duration) || 0);
    const eventEnd = startTime + duration;
    const syllabusPre = getNonNegativeFiniteNumber(syllabusItem?.preFlightTime);
    const syllabusPost = getNonNegativeFiniteNumber(syllabusItem?.postFlightTime);

    let preOffset = syllabusPre === null ? 0 : normaliseBookingDurationHours(syllabusPre);
    let postOffset = syllabusPost === null ? 0 : normaliseBookingDurationHours(syllabusPost);

    if ((event as any).bookingOffsetsAreDuration === true) {
        const rawPre = getNonNegativeFiniteNumber(event.preStart);
        const rawPost = getNonNegativeFiniteNumber(event.postEnd);
        return {
            preOffset: rawPre === null ? preOffset : normaliseBookingDurationHours(rawPre),
            postOffset: rawPost === null ? postOffset : normaliseBookingDurationHours(rawPost),
        };
    }

    if (syllabusPre === null) {
        const rawPre = getNonNegativeFiniteNumber(event.preStart);
        if (rawPre !== null) {
            preOffset = rawPre > 24
                ? rawPre / 60
                : rawPre > 6 && rawPre < startTime
                    ? Math.max(0, startTime - rawPre)
                    : rawPre;
        }
    }

    if (syllabusPost === null) {
        const rawPost = getNonNegativeFiniteNumber(event.postEnd);
        if (rawPost !== null) {
            postOffset = rawPost > 24
                ? rawPost / 60
                : rawPost > eventEnd && rawPost <= 24
                    ? Math.max(0, rawPost - eventEnd)
                    : rawPost;
        }
    }

    return { preOffset, postOffset };
};

const getEventBookingWindow = (
    event: ScheduleEvent,
    syllabusDetails: SyllabusItemDetail[]
): { start: number, end: number } => {
    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    const { preOffset, postOffset } = getScheduleEventBookingOffsets(event, syllabusItem);
    return {
        start: event.startTime - preOffset,
        end: event.startTime + event.duration + postOffset,
    };
};

const getEventBookingWindowForAlgo = (
    event: Omit<ScheduleEvent, 'date'> | { startTime: number, flightNumber: string, duration: number, preStart?: number, postEnd?: number },
    syllabusDetails: SyllabusItemDetail[]
): { start: number, end: number } => {
    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    const { preOffset, postOffset } = getScheduleEventBookingOffsets(event, syllabusItem);
    return {
        start: event.startTime - preOffset,
        end: event.startTime + event.duration + postOffset,
    };
};

/**
 * Determines if an event is a Day or Night event based on the Master LMP Day/Night field
 * @param event - The event to check
 * @param syllabusDetails - The syllabus details containing Day/Night classification
 * @returns 'Day', 'Night', or 'Day/Night' based on the syllabus classification
 */
const getEventDayNightClassification = (
    event: { flightNumber: string; dayNight?: 'Day' | 'Night' | 'Day/Night' },
    syllabusDetails: SyllabusItemDetail[],
    sctEvents?: ContinuationEventInput[]
): 'Day' | 'Night' | 'Day/Night' => {
    if (event.dayNight) {
        return event.dayNight;
    }

    if (event.flightNumber === 'Night Duty Sup') {
        return 'Night';
    }
    if (event.flightNumber === 'Duty Sup') {
        return 'Day';
    }

    // Continuation events are configured outside the Master LMP list.
    const normaliseContinuationKey = (value: unknown) => String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    const eventContinuationKey = normaliseContinuationKey(event.flightNumber);
    const continuationEvent = normaliseContinuationEventSettings(sctEvents).find(candidate => (
        [candidate.name, candidate.code, candidate.currency]
            .map(normaliseContinuationKey)
            .filter(Boolean)
            .includes(eventContinuationKey)
    ));
    if (continuationEvent) {
        return continuationEvent.dayNight || 'Day';
    }

    const syllabusItem = syllabusDetails.find(s => s.id === event.flightNumber || s.code === event.flightNumber);
    if (syllabusItem && syllabusItem.dayNight) {
        return syllabusItem.dayNight;
    }
    // Default to Day if not found or not specified
    return 'Day';
};

const getMasterEventId = (item: Partial<SyllabusItemDetail>): string =>
    item.masterEventId || item.id || item.code || '';

const createLmpOrderKey = (index: number): string => String(index + 1).padStart(5, '0');
const REMEDIAL_EARLIEST_START = 10.0;
const REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY = 'neo_remedial_force_schedule_requests';
const ACTIVE_OPERATIONAL_CONTEXT_STORAGE_KEY = 'dfp_active_operational_context';
const ACTIVE_OPERATIONAL_CONTEXT_DIAG_KEY = 'neo_context_selector_diag';
const PLATFORM_CONFIG_UPDATED_EVENT = 'dfp-platform-config-updated';
const HIGHEST_PRIORITY_EVENTS_STORAGE_PREFIX = 'dfp_highest_priority_events_v1';
const REMEDIAL_EVENT_CODE_REGEX = /-(?:REM-[A-Z]+\d+|RFTD\d+|RRF\d+|RT\d+|RF\d+|FTD\d+|F\d+|T\d+)$/i;

const buildHighestPriorityEventsStorageKey = (locationCode: string, unitCode: string): string => (
    `${HIGHEST_PRIORITY_EVENTS_STORAGE_PREFIX}:${String(locationCode || 'UNKNOWN').trim().toUpperCase()}:${String(unitCode || 'UNKNOWN').trim().toUpperCase()}`
);

const loadHighestPriorityEventsFromStorage = (storageKey: string): ScheduleEvent[] => {
    try {
        if (typeof localStorage === 'undefined') return [];
        const raw = localStorage.getItem(storageKey);
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter((event: any): event is ScheduleEvent => (
            event &&
            typeof event === 'object' &&
            typeof event.id === 'string' &&
            typeof event.date === 'string'
        ));
    } catch (error) {
        console.warn('[HighestPriorityEvents] Failed to load stored events', error);
        return [];
    }
};

const normaliseHighestPriorityUnitCode = (value: unknown): string => (
    String(value || '').trim().toUpperCase()
);

const parseHighestPriorityUnitCodes = (value: unknown): string[] => Array.from(new Set(
    String(value || '')
        .split(/[+/,;&|]+/)
        .map(normaliseHighestPriorityUnitCode)
        .filter(Boolean)
));

const highestPriorityEventBelongsToUnit = (event: ScheduleEvent, unitCode: string): boolean => {
    const targetUnit = normaliseHighestPriorityUnitCode(unitCode);
    if (!targetUnit) return false;
    const source = event as any;
    const explicitUnitFields = [
        source.unitCode,
        source.crewUnitCode,
        source.fixedCrewUnitCode,
        source.taskingUnitCode,
        source.standardMissionUnitCode,
    ].map(normaliseHighestPriorityUnitCode).filter(Boolean);
    if (explicitUnitFields.includes(targetUnit)) return true;

    const displayFields = [
        source.fixedCrewGroup,
        source.fixedCrewDisplayLabel,
        source.crewGroup,
        source.crewDisplayLabel,
        source.notes,
    ].map((value) => String(value || '').toUpperCase());
    return displayFields.some((value) => (
        value.includes(`/${targetUnit}`) ||
        value.includes(` ${targetUnit}`) ||
        value.includes(`-${targetUnit}`)
    ));
};

const loadHighestPriorityEventsForUnitContext = (locationCode: string, unitCode: string): ScheduleEvent[] => {
    const targetLocation = normaliseHighestPriorityUnitCode(locationCode || 'UNKNOWN');
    const targetUnit = normaliseHighestPriorityUnitCode(unitCode || 'UNKNOWN');
    const baseKey = buildHighestPriorityEventsStorageKey(targetLocation, targetUnit);
    const baseEvents = loadHighestPriorityEventsFromStorage(baseKey);
    if (parseHighestPriorityUnitCodes(targetUnit).length > 1) return baseEvents;

    try {
        if (typeof localStorage === 'undefined') return baseEvents;
        const merged = [...baseEvents];
        const seenIds = new Set(merged.map((event) => event.id));
        const prefix = `${HIGHEST_PRIORITY_EVENTS_STORAGE_PREFIX}:${targetLocation}:`;
        for (let index = 0; index < localStorage.length; index += 1) {
            const key = localStorage.key(index) || '';
            if (!key.startsWith(prefix) || key === baseKey) continue;
            const sourceUnitKey = normaliseHighestPriorityUnitCode(key.slice(prefix.length));
            const sourceUnits = parseHighestPriorityUnitCodes(sourceUnitKey);
            if (sourceUnits.length <= 1 || !sourceUnits.includes(targetUnit)) continue;
            loadHighestPriorityEventsFromStorage(key).forEach((event) => {
                if (seenIds.has(event.id) || !highestPriorityEventBelongsToUnit(event, targetUnit)) return;
                merged.push(event);
                seenIds.add(event.id);
            });
        }
        return merged;
    } catch (error) {
        console.warn('[HighestPriorityEvents] Failed to recover combined-unit priority rows', error);
        return baseEvents;
    }
};

const isRemedialEventCode = (value?: string): boolean =>
    !!value && REMEDIAL_EVENT_CODE_REGEX.test(value);

const getRemedialBaseEventCode = (item: Partial<SyllabusItemDetail>): string =>
    String(item.code || item.id || item.masterEventId || '').replace(REMEDIAL_EVENT_CODE_REGEX, '');

const isRemedialSyllabusItem = (item?: Partial<SyllabusItemDetail>): boolean =>
    !!item && (
        item.lmpSource === 'remedial' ||
        item.isRemedial === true ||
        isRemedialEventCode(item.id) ||
        isRemedialEventCode(item.code)
    );

const normaliseRemedialRequests = (value: unknown): RemedialRequest[] => {
    if (!Array.isArray(value)) return [];
    return value
        .map((item: any) => ({
            traineeId: Number(item?.traineeId),
            eventCode: String(item?.eventCode || ''),
            forceSchedule: item?.forceSchedule === true,
            aircraftConfigId: String(item?.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id),
        }))
        .filter(item => Number.isFinite(item.traineeId) && item.eventCode && item.forceSchedule);
};

const loadStoredRemedialRequests = (): RemedialRequest[] => {
    try {
        return normaliseRemedialRequests(JSON.parse(localStorage.getItem(REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY) || '[]'));
    } catch {
        return [];
    }
};

const storeRemedialRequests = (requests: RemedialRequest[]) => {
    try {
        localStorage.setItem(
            REMEDIAL_FORCE_SCHEDULE_STORAGE_KEY,
            JSON.stringify(normaliseRemedialRequests(requests))
        );
    } catch (error) {
        console.warn('[REMEDIAL-SYNC] Failed to persist Force Schedule selections:', error);
    }
};

const stampMasterLmpItems = (masterLMP: SyllabusItemDetail[]): SyllabusItemDetail[] =>
    masterLMP.map((item, index) => ({
        ...item,
        masterEventId: getMasterEventId(item),
        lmpSource: 'master',
        orderKey: item.orderKey || createLmpOrderKey(index),
        notes: item.notes || '',
        placementNeedsReview: false,
    }));

const isLmpOverlayItem = (item: SyllabusItemDetail): boolean =>
    item.lmpSource === 'remedial' ||
    item.lmpSource === 'custom' ||
    item.isRemedial === true ||
    item.id?.includes('REM') ||
    isRemedialEventCode(item.id) ||
    item.code?.includes('REM') ||
    isRemedialEventCode(item.code) ||
    item.id?.endsWith('-CUR') ||
    item.code?.endsWith('-CUR');

const getLmpResourceNumber = (item?: Partial<SyllabusItemDetail> | null): number => {
    const resourceCountAlias = (item as any)?.resourceCount;
    const parsed = Number(item?.resourceNumber ?? resourceCountAlias);
    if (Number.isFinite(parsed) && parsed > 1) return Math.max(1, Math.round(parsed));

    const physicalResourceCount = Array.isArray(item?.resourcesPhysical)
        ? item.resourcesPhysical.filter(resource => String(resource || '').trim().length > 0).length
        : 0;
    if (physicalResourceCount > 1) return physicalResourceCount;

    const eventCode = String(item?.code || item?.id || item?.masterEventId || '').trim().toUpperCase();
    if (item?.type === 'Flight' && /^FORM/.test(eventCode)) return 2;

    return Number.isFinite(parsed) ? Math.max(1, Math.round(parsed)) : 1;
};

const getExplicitFormationResourceNumber = (item?: Partial<SyllabusItemDetail> | null): number => {
    const physicalResourceCount = Array.isArray(item?.resourcesPhysical)
        ? item.resourcesPhysical.filter(resource => String(resource || '').trim().length > 0).length
        : 0;
    if (physicalResourceCount > 1) return physicalResourceCount;

    const resourceCountAlias = Number((item as any)?.resourceCount);
    if (Number.isFinite(resourceCountAlias) && resourceCountAlias > 1) {
        return Math.max(1, Math.round(resourceCountAlias));
    }

    const eventCode = String(item?.code || item?.id || item?.masterEventId || '').trim().toUpperCase();
    if (item?.type === 'Flight' && /^FORM/.test(eventCode)) {
        return Math.max(2, Math.round(Number(item?.resourceNumber) || 2));
    }

    return 1;
};

const isMultiResourceFlightItem = (item?: Partial<SyllabusItemDetail> | null): boolean =>
    !!item && item.type === 'Flight' && getExplicitFormationResourceNumber(item) > 1;

const alignPhysicalResourcesToResourceNumber = (
    resourcesPhysical: string[] | undefined,
    resourceNumber: number,
    resourceLabel = 'Aircraft'
): string[] => {
    const count = Math.max(0, Math.round(Number(resourceNumber) || 0));
    const existing = (resourcesPhysical || []).filter(resource => String(resource || '').trim().length > 0);
    if (count === 0) return existing;

    const aligned = existing.slice(0, count);
    for (let index = aligned.length; index < count; index++) {
        aligned.push(count === 1 ? resourceLabel : `${resourceLabel} ${index + 1}`);
    }
    return aligned;
};

const getFormationEventKey = (item?: Partial<SyllabusItemDetail> | null): string =>
    String(item?.code || item?.masterEventId || item?.id || '')
        .trim()
        .toUpperCase()
        .replace(/\s+/g, '');

const AIR_COMBAT_LINKED_EVENT_NOTE_REGEX = /^\[Linked Event:\s*([^\]]+)\]$/i;

const getAirCombatLinkedEventCode = (item?: Partial<SyllabusItemDetail> | null): string => {
    const notes = String(item?.notes || '');
    const markerLine = notes
        .split(/\r?\n/)
        .map(line => line.trim())
        .find(line => AIR_COMBAT_LINKED_EVENT_NOTE_REGEX.test(line));
    return markerLine?.match(AIR_COMBAT_LINKED_EVENT_NOTE_REGEX)?.[1]?.trim() || '';
};

const INDIVIDUAL_LMP_EDITABLE_FIELDS: (keyof SyllabusItemDetail)[] = [
    'code',
    'eventDescription',
    'phase',
    'module',
    'type',
    'sortieType',
    'dayNight',
    'methodOfDelivery',
    'methodOfAssessment',
    'resourcesPhysical',
    'resourceNumber',
    'resourcesHuman',
    'eventDetailsCommon',
    'eventDetailsSortie',
    'flightOrSimHours',
    'totalEventHours',
    'duration',
    'preFlightTime',
    'postFlightTime',
    'prerequisites',
    'prerequisitesGround',
    'prerequisitesFlying',
    'location',
    'twrDiReqd',
    'cctOnly',
    'notes',
];

const getIndividualLmpMasterOverrides = (item?: SyllabusItemDetail): Partial<SyllabusItemDetail> => {
    if (!item) return {};
    return INDIVIDUAL_LMP_EDITABLE_FIELDS.reduce((overrides, field) => {
        if (Object.prototype.hasOwnProperty.call(item, field)) {
            (overrides as any)[field] = (item as any)[field];
        }
        return overrides;
    }, {} as Partial<SyllabusItemDetail>);
};

const mergeIndividualLmpWithMaster = (
    existingLmp: SyllabusItemDetail[] | undefined,
    masterLMP: SyllabusItemDetail[]
): SyllabusItemDetail[] => {
    const stampedMaster = stampMasterLmpItems(masterLMP);
    if (!existingLmp || existingLmp.length === 0) return stampedMaster;

    const masterIds = new Set(stampedMaster.map(getMasterEventId).filter(Boolean));
    const existingByMasterId = new Map<string, SyllabusItemDetail>();
    existingLmp.forEach(item => {
        if (isLmpOverlayItem(item)) return;
        const masterId = getMasterEventId(item);
        if (masterId) existingByMasterId.set(masterId, item);
    });

    const mergedMaster = stampedMaster.map((masterItem, index) => {
        const existingItem = existingByMasterId.get(getMasterEventId(masterItem));
        return {
            ...masterItem,
            ...getIndividualLmpMasterOverrides(existingItem),
            id: masterItem.id,
            masterEventId: getMasterEventId(masterItem),
            lmpSource: 'master',
            completedAt: (existingItem as any)?.completedAt ?? (masterItem as any).completedAt ?? null,
            userLockedPosition: existingItem?.userLockedPosition,
            orderKey: existingItem?.orderKey || masterItem.orderKey || createLmpOrderKey(index),
            placementNeedsReview: false,
        } as SyllabusItemDetail;
    });

    const masterIndexById = new Map<string, number>();
    mergedMaster.forEach((item, index) => {
        const masterId = getMasterEventId(item);
        if (masterId) masterIndexById.set(masterId, index);
    });

    const overlays = existingLmp.filter(isLmpOverlayItem).map((item, index) => {
        const itemIndex = existingLmp.indexOf(item);
        const fallbackAfter = item.anchorAfterMasterEventId || getMasterEventId(existingLmp.slice(0, itemIndex).reverse().find(prev => !isLmpOverlayItem(prev)) || {});
        const fallbackBefore = item.anchorBeforeMasterEventId || getMasterEventId(existingLmp.slice(itemIndex + 1).find(next => !isLmpOverlayItem(next)) || {});
        const afterExists = !!fallbackAfter && masterIds.has(fallbackAfter);
        const beforeExists = !!fallbackBefore && masterIds.has(fallbackBefore);

        return {
            ...item,
            lmpSource: item.lmpSource || (item.isRemedial ? 'remedial' : 'custom'),
            orderKey: item.orderKey || `${createLmpOrderKey(index)}.500`,
            anchorAfterMasterEventId: fallbackAfter || undefined,
            anchorBeforeMasterEventId: fallbackBefore || undefined,
            anchorPolicy: item.anchorPolicy || 'between',
            placementNeedsReview: !(afterExists || beforeExists),
        } as SyllabusItemDetail;
    });

    const overlaysBefore = new Map<string, SyllabusItemDetail[]>();
    const overlaysAfter = new Map<string, SyllabusItemDetail[]>();
    const appendOverlays: SyllabusItemDetail[] = [];

    overlays.forEach(overlay => {
        const policy = overlay.anchorPolicy || 'between';
        const beforeId = overlay.anchorBeforeMasterEventId;
        const afterId = overlay.anchorAfterMasterEventId;

        if ((policy === 'between' || policy === 'before') && beforeId && masterIndexById.has(beforeId)) {
            const list = overlaysBefore.get(beforeId) || [];
            list.push(overlay);
            overlaysBefore.set(beforeId, list);
            return;
        }

        if (afterId && masterIndexById.has(afterId)) {
            const list = overlaysAfter.get(afterId) || [];
            list.push(overlay);
            overlaysAfter.set(afterId, list);
            return;
        }

        appendOverlays.push({ ...overlay, placementNeedsReview: true });
    });

    const result: SyllabusItemDetail[] = [];
    mergedMaster.forEach(masterItem => {
        const masterId = getMasterEventId(masterItem);
        const before = masterId ? overlaysBefore.get(masterId) || [] : [];
        result.push(...before.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || '')));
        result.push(masterItem);
        const after = masterId ? overlaysAfter.get(masterId) || [] : [];
        result.push(...after.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || '')));
    });

    return [...result, ...appendOverlays.sort((a, b) => (a.orderKey || '').localeCompare(b.orderKey || ''))];
};

const getAssignableMasterLmpItemsForType = (
    syllabusItems: SyllabusItemDetail[],
    lmpType: string,
    unitCode: string | undefined,
    filterForAccess: (items: SyllabusItemDetail[], requiredAccess: 'View' | 'Assign' | 'Manage', unitCode?: string | null) => SyllabusItemDetail[]
): SyllabusItemDetail[] => {
    const requestedType = String(lmpType || '').trim();
    if (!requestedType) return [];
    const requestedTypeKey = requestedType.toUpperCase();
    return filterForAccess(syllabusItems, 'Assign', unitCode).filter(item => {
        return Array.isArray(item.courses) && item.courses.some(course => String(course || '').trim().toUpperCase() === requestedTypeKey);
    });
};

const groupSyllabusByConfiguredCourses = (syllabusItems: SyllabusItemDetail[]): Record<string, SyllabusItemDetail[]> => {
    return (Array.isArray(syllabusItems) ? syllabusItems : []).reduce((groups, item) => {
        (Array.isArray(item.courses) ? item.courses : []).forEach(course => {
            const label = String(course || '').trim();
            if (!label) return;
            if (!groups[label]) groups[label] = [];
            groups[label].push(item);
        });
        return groups;
    }, {} as Record<string, SyllabusItemDetail[]>);
};

const calculateTotalDutyHoursForPeriod = (instructorName: string, events: ScheduleEvent[], startTime: number, endTime: number, syllabusDetails: SyllabusItemDetail[]): number => {
    const instructorEvents = events.filter(e =>
        eventHasPerson(e, instructorName) &&
        // Check if event overlaps with the specified time period (considering booking windows)
        (() => {
            const bookingWindow = getEventBookingWindowForAlgo(e, syllabusDetails);
            return bookingWindow.start < endTime && bookingWindow.end > startTime;
        })()
    );

    if (instructorEvents.length === 0) return 0;

    // Calculate start/end times including pre/post brief for overlapping events
    const overlappingWindows = instructorEvents
        .map(e => getEventBookingWindowForAlgo(e, syllabusDetails))
        .map(window => ({
            start: Math.max(window.start, startTime),
            end: Math.min(window.end, endTime)
        }))
        .filter(window => window.start < window.end)
        .sort((a, b) => a.start - b.start);

    if (overlappingWindows.length === 0) return 0;

    // Merge overlapping windows to get total duty time
    let totalDutyTime = 0;
    let currentStart = overlappingWindows[0].start;
    let currentEnd = overlappingWindows[0].end;

    for (let i = 1; i < overlappingWindows.length; i++) {
        const nextWindow = overlappingWindows[i];

        if (nextWindow.start <= currentEnd) {
            // Overlapping or adjacent windows - merge them
            currentEnd = Math.max(currentEnd, nextWindow.end);
        } else {
            // Separate windows - add current window time and start new one
            totalDutyTime += currentEnd - currentStart;
            currentStart = nextWindow.start;
            currentEnd = nextWindow.end;
        }
    }

    // Add the final window
    totalDutyTime += currentEnd - currentStart;

    return parseFloat(totalDutyTime.toFixed(1));
};

const timeStringToHours = (timeStr: string | undefined): number | null => {
    if (!timeStr) return null;

    let hours: number;
    let minutes: number;

    if (timeStr.includes(':')) { // Supports HH:mm
        const parts = timeStr.split(':').map(Number);
        if (parts.length !== 2 || isNaN(parts[0]) || isNaN(parts[1])) return null;
        [hours, minutes] = parts;
    } else if (timeStr.length === 4 && /^\d{4}$/.test(timeStr)) { // Supports HHMM
        hours = parseInt(timeStr.substring(0, 2), 10);
        minutes = parseInt(timeStr.substring(2, 4), 10);
    } else {
        return null;
    }

    if (isNaN(hours) || isNaN(minutes) || hours < 0 || hours >= 24 || minutes < 0 || minutes >= 60) {
        return null;
    }
    return hours + minutes / 60;
};

const formatDecimalHourToString = (decimalHour: number): string => {
    const hours = Math.floor(decimalHour);
    const minutes = Math.round((decimalHour % 1) * 60);
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
};

// New Helpers for DFP and Neo
const calculateProjectedDuty = (
    instructorName: string,
    events: (ScheduleEvent | Omit<ScheduleEvent, 'date'>)[],
    newEvent: (ScheduleEvent | Omit<ScheduleEvent, 'date'>),
    syllabusDetails: SyllabusItemDetail[] = []
): number => {
    // Filter events for the instructor
    const instructorEvents = [...events.filter(e => eventHasPerson(e, instructorName)), newEvent];
    if (instructorEvents.length === 0) return 0;

    // Calculate start/end times including pre/post brief
    const sortedWindows = instructorEvents
        .map(e => getEventBookingWindowForAlgo(e, syllabusDetails))
        .sort((a, b) => a.start - b.start);

    const firstEventStart = sortedWindows[0].start;

    // Determine last event end time (duty end)
    const lastEvent = instructorEvents.find(e =>
        getEventBookingWindowForAlgo(e, syllabusDetails).end === sortedWindows[sortedWindows.length - 1].end
    );

    // If the last event finishes after 1700, duty ends at event finish time.
    // Otherwise, duty assumed to end at event finish time (or could be fixed 1700 if that's business rule, but sticking to simple span here)
    const lastEventEnd = sortedWindows[sortedWindows.length - 1].end;

    const dutyHours = Math.max(0, lastEventEnd - firstEventStart);
    return parseFloat(dutyHours.toFixed(1));
};

const daysSince = (dateStr: string | undefined, relativeTo: string): number => {
    if (!dateStr) return 999; // Treated as very long ago if undefined
    const eventDate = new Date(dateStr + 'T00:00:00Z');
    const baseDate = new Date(relativeTo + 'T00:00:00Z');
    return Math.floor((baseDate.getTime() - eventDate.getTime()) / (1000 * 60 * 60 * 24));
};


