// --- DFP Algorithm Helpers (moved outside for re-use in debug) ---

const isPersonStaticallyUnavailable = (
    person: Instructor | Trainee,
    periodStart: number,
    periodEnd: number,
    buildDate: string,
    eventType: 'flight' | 'ground' | 'ftd' | 'duty_sup' | 'cpt'
): boolean => {
    if (!person.unavailability) return false;
    for (const period of person.unavailability) {
        // Correct date range check: exclusive for all-day, inclusive for timed.
        const isInDateRange = period.allDay
            ? (buildDate >= period.startDate && buildDate < period.endDate)
            : (buildDate >= period.startDate && buildDate <= period.endDate);

        if (isInDateRange) {
            // Check for 'Ground Duties only' exception
            if (period.reason === 'TMUF - Ground Duties only' && eventType !== 'flight') {
                continue; // Not a conflict
            }

            if (period.allDay) {
                return true; // Conflict if it's an all-day event in range
            }

            // It's a timed event, now check for time overlap
            const unavailableStart = timeStringToHours(period.startTime);
            const unavailableEnd = timeStringToHours(period.endTime);

            if (unavailableStart !== null && unavailableEnd !== null) {
                // This logic correctly handles multi-day timed events
                let dayStart = (buildDate === period.startDate) ? unavailableStart : 0;
                let dayEnd = (buildDate === period.endDate) ? unavailableEnd : 24;

                if (periodStart < dayEnd && periodEnd > dayStart) {
                    return true; // Time overlaps
                }
            } else {
                // if times are null/invalid for a timed event, treat as all-day for that date
                return true;
            }
        }
    }
    return false; // Not unavailable
};

const findAvailableArea = (
    startTime: number,
    duration: number,
    existingEvents: Omit<ScheduleEvent, 'date'>[]
): string | null => {
    const primaryAreas = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
    const secondaryAreas = ['S', 'T', 'U', 'V', 'W', 'X', 'Y', 'Z'];

    const newEventStart = startTime;
    const newEventEnd = startTime + duration;

    const isAreaOccupied = (area: string): boolean => {
        return existingEvents.some(event => {
            if (event.type !== 'flight' || event.area !== area) {
                return false;
            }
            const existingEventStart = event.startTime;
            const existingEventEnd = event.startTime + event.duration;
            return newEventStart < existingEventEnd && newEventEnd > existingEventStart;
        });
    };

    for (const primaryArea of primaryAreas) {
        if (!isAreaOccupied(primaryArea)) {
            return primaryArea;
        }
    }

    for (const secondaryArea of secondaryAreas) {
        if (!isAreaOccupied(secondaryArea)) {
            return secondaryArea;
        }
    }

    return null; // No available areas
};

/**
 * Get Effective Last Completed Event (ELCE) from yesterday's DFP
 *
 * ELCE Logic: A trainee may have flown an event yesterday that finished successfully,
 * but the training report has not been entered yet. When building tomorrow's program,
 * the scheduler looks at yesterday's DFP and treats completed events as the trainee's
 * "Effective Last Completed Event" to ensure correct Next Event determination.
 *
 * Example: Trainee flew BGF2 yesterday at 1100. Training report not entered yet, so system
 * shows last completed as BGF1. ELCE logic finds BGF2 in yesterday's DFP (finished,
 * not cancelled, not unsuccessful) and uses it to determine Next Event = BGF3.
 */
const getEffectiveLastCompletedEvent = (
    traineeName: string,
    publishedSchedules: Record<string, ScheduleEvent[]>,
    buildDate: string
): string | null => {
    // Calculate yesterday's date
    const buildDateObj = new Date(buildDate + 'T00:00:00Z');
    buildDateObj.setDate(buildDateObj.getDate() - 1);
    const yesterdayStr = buildDateObj.toISOString().split('T')[0];

    // Get yesterday's DFP
    const yesterdayDfp = publishedSchedules[yesterdayStr] || [];

    if (yesterdayDfp.length === 0) {
        return null;
    }

    // Find all events for this trainee from yesterday's DFP
    const traineeEvents = yesterdayDfp.filter(e =>
        e.student === traineeName || e.attendees?.includes(traineeName)
    );

    if (traineeEvents.length === 0) {
        return null;
    }

    // Filter for events that were not cancelled or marked unsuccessful
    const completedEvents = traineeEvents.filter(e => {
        const notCancelled = !e.isCancelled;
        const notUnsuccessful = !e.isUnsuccessful;
        return notCancelled && notUnsuccessful;
    });

    if (completedEvents.length === 0) {
        return null;
    }

    // Return the last completed event code (latest by start time)
    const lastEvent = completedEvents.sort((a, b) => b.startTime - a.startTime)[0];

    if (isNeoBuildVerboseDiagnosticsEnabled()) {
        console.log(`✓ ELCE for ${traineeName}: ${lastEvent.flightNumber} (completed ${yesterdayStr})`);
    }

    return lastEvent.flightNumber;
};

const normalizeLmpEventId = (value?: string | null): string => {
    return String(value || '').replace(/\*/g, '').trim();
};

const addLmpCompletionAlias = (completedEventIds: Set<string>, value?: string | null): void => {
    const raw = String(value || '').trim();
    const normalized = normalizeLmpEventId(raw);
    if (raw) completedEventIds.add(raw);
    if (normalized) completedEventIds.add(normalized);
};

const isCompletedLmpItem = (item: SyllabusItemDetail, completedEventIds: Set<string>): boolean => {
    const maybeCompleted = item as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };
    return Boolean(
        item.completedAt ||
        maybeCompleted.isComplete ||
        maybeCompleted.completed ||
        completedEventIds.has(normalizeLmpEventId(item.id)) ||
        completedEventIds.has(normalizeLmpEventId(item.code)) ||
        completedEventIds.has(normalizeLmpEventId(item.masterEventId))
    );
};

const areLmpPrerequisitesMet = (item: SyllabusItemDetail, completedEventIds: Set<string>): boolean => {
    return (item.prerequisites || []).every(prerequisite => {
        const normalized = normalizeLmpEventId(prerequisite);
        return !normalized || completedEventIds.has(normalized);
    });
};

const getFallbackMasterLmpForTrainee = (
    trainee: Trainee,
    masterSyllabus: SyllabusItemDetail[]
): SyllabusItemDetail[] => {
    const normaliseToken = (value: unknown) => String(value || '').trim().toUpperCase();
    const traineeCourse = normaliseToken(trainee.course);
    const configuredLmpType = normaliseToken(trainee.lmpType);

    const masterItems = masterSyllabus.filter((item: any) => (
        item?.isActive !== false &&
        item?.lmpType !== 'Staff CAT' &&
        item?.type !== 'Academics'
    ));

    const itemCourseTokens = (item: SyllabusItemDetail): string[] => (
        Array.isArray(item.courses)
            ? item.courses.map(normaliseToken).filter(Boolean)
            : []
    );

    const matchesInferredLmp = (item: SyllabusItemDetail): boolean => {
        const courseTokens = itemCourseTokens(item);
        if (!configuredLmpType && !traineeCourse) return false;
        return (
            (configuredLmpType ? courseTokens.includes(configuredLmpType) : false) ||
            (traineeCourse ? courseTokens.includes(traineeCourse) : false)
        );
    };

    return masterItems.filter(matchesInferredLmp);
};

// Centralized logic for determining a trainee's next event(s)
const computeNextEventsForTrainee = (
    trainee: Trainee,
    traineeLMPs: Map<string, SyllabusItemDetail[]>,
    scores: Map<string, Score[]>,
    masterSyllabus: SyllabusItemDetail[], // Added fallback
    publishedSchedules?: Record<string, ScheduleEvent[]>, // NEW: Optional for ELCE
    buildDate?: string, // NEW: Optional for ELCE
    dbElceMap?: Map<string, { eventCode: string; eventDate: string; dcoResult: 'DCO' | 'DPCO' | 'DNCO'; isCountedAsElce: boolean } | null> // NEW: DB-backed ELCE
): { next: SyllabusItemDetail | null, plusOne: SyllabusItemDetail | null } => {
    const verboseNeoBuild = isNeoBuildVerboseDiagnosticsEnabled();
    // Check individual LMP first, then fallback only to the trainee's relevant Master LMP stream.
    const hasIndividualLMP = traineeLMPs.has(trainee.fullName);
    const individualLMP = traineeLMPs.get(trainee.fullName) || getFallbackMasterLmpForTrainee(trainee, masterSyllabus);

    // Debug logging for remedial tracking
    if (verboseNeoBuild && hasIndividualLMP) {
        const remedialEvents = individualLMP.filter(item => item.isRemedial);
        if (remedialEvents.length > 0) {
            console.log(`🔍 [${trainee.fullName}] Has Individual LMP with ${remedialEvents.length} remedial events`);
        }
    } else if (verboseNeoBuild) {
        console.log(`⚠️ [${trainee.fullName}] Using scoped Master LMP fallback (no Individual LMP found): ${individualLMP.length} events`);
    }

    if (!individualLMP || individualLMP.length === 0) {
        return { next: null, plusOne: null };
    }

    const traineeScores = scores.get(trainee.fullName) || [];
    const completedEventIds = new Set<string>();
    traineeScores.forEach(score => addLmpCompletionAlias(completedEventIds, score.event));

    // The Individual LMP is now composed from the Master LMP plus overlay rows.
    // Use its completion flags directly so NEO Build does not depend on stale
    // score-map timing or legacy training report tables.
    individualLMP.forEach(item => {
        const maybeCompleted = item as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };
        if (item.completedAt || maybeCompleted.isComplete || maybeCompleted.completed) {
            addLmpCompletionAlias(completedEventIds, item.id);
            addLmpCompletionAlias(completedEventIds, item.code);
            addLmpCompletionAlias(completedEventIds, item.masterEventId);
        }
    });

    // ── Source 1: DB-backed ELCE from EventCompletion table (preferred) ──────
    // This is written the moment the post-flight form is saved, before the training report
    // paperwork is entered.  Only DCO and DPCO count; DNCO must NOT advance
    // the next-event pointer.
    const dbElce = dbElceMap?.get(trainee.fullName);
    if (dbElce && (dbElce.dcoResult === 'DCO' || dbElce.dcoResult === 'DPCO')) {
        addLmpCompletionAlias(completedEventIds, dbElce.eventCode);
        if (verboseNeoBuild) console.log(
            `[ELCE/DB] ${trainee.fullName}: ${dbElce.eventCode} (${dbElce.dcoResult}) ` +
            `completed ${dbElce.eventDate} — added to completedEventIds`
        );
    } else if (dbElce && dbElce.dcoResult === 'DNCO') {
        if (verboseNeoBuild) console.log(
            `[ELCE/DB] ${trainee.fullName}: ${dbElce.eventCode} was DNCO on ${dbElce.eventDate} ` +
            `— NOT counted as ELCE (unsuccessful sortie)`
        );
    }

    // ── Source 2: Legacy DFP schedule scan (fallback) ────────────────────────
    // Used when no DB ELCE exists yet (first day of use, or post-flight form
    // has not been submitted). Scans yesterday's published DFP for events that
    // finished but are not yet in a training report.
    if (!dbElce && publishedSchedules && buildDate) {
        const elce = getEffectiveLastCompletedEvent(trainee.fullName, publishedSchedules, buildDate);
        if (elce) {
            addLmpCompletionAlias(completedEventIds, elce);
            if (verboseNeoBuild) console.log(`[ELCE/DFP] ${trainee.fullName}: ${elce} — DFP-scan fallback (no DB ELCE found)`);
        }
    }

    let nextEvt: SyllabusItemDetail | null = null;
    let plusOneEvt: SyllabusItemDetail | null = null;
    let nextEventIndex = -1;

    // Find Next Event
    for (let i = 0; i < individualLMP.length; i++) {
        const item = individualLMP[i];
        if (isCompletedLmpItem(item, completedEventIds) || item.code.includes(' MB')) {
            continue;
        }

        const prereqsMet = areLmpPrerequisitesMet(item, completedEventIds);
        if (prereqsMet) {
            nextEvt = item;
            nextEventIndex = i;

            // Debug logging for remedial events
            if (verboseNeoBuild && item.isRemedial) {
                console.log(`✅ [${trainee.fullName}] Next event is REMEDIAL: ${item.code}`);
            }
            break;
        }
    }

    // Find Next +1 Event (sequentially)
    if (nextEventIndex !== -1) {
        for (let i = nextEventIndex + 1; i < individualLMP.length; i++) {
            const item = individualLMP[i];
            // Skip non-schedulable events
            if (!item.code.includes(' MB') && !isCompletedLmpItem(item, completedEventIds)) {
                plusOneEvt = item;
                break;
            }
        }
    }

    return { next: nextEvt, plusOne: plusOneEvt };
};

// Helper for Trainee Priority Scoring
const calculateTraineePriorityScore = (
    trainee: Trainee,
    buildDate: string,
    courseMedian: number,
    traineeProgress: number,
    isRemedial: boolean
): number => {
    const today = new Date(buildDate + 'T00:00:00Z').getTime();
    const lastEvent = trainee.lastEventDate ? new Date(trainee.lastEventDate + 'T00:00:00Z').getTime() : 0;
    const lastFlight = trainee.lastFlightDate ? new Date(trainee.lastFlightDate + 'T00:00:00Z').getTime() : 0;

    const daysSinceEvent = lastEvent === 0 ? 100 : Math.floor((today - lastEvent) / (1000 * 3600 * 24));
    const daysSinceFlight = lastFlight === 0 ? 100 : Math.floor((today - lastFlight) / (1000 * 3600 * 24));

    // Lag is positive if they are behind the median
    const lag = courseMedian - traineeProgress;

    // Weighting Logic
    let score = 0;
    score += daysSinceEvent * 2;
    score += daysSinceFlight * 1;
    score += lag * 5; // High weight for being behind

    if (isRemedial) score += 500; // Massive boost for remedial

    return score;
};

// Planned Event Interface
interface PlannedEvent {
    id: string;
    type: 'manual' | 'sct' | 'trainee';
    subType: 'flight' | 'ftd' | 'ground' | 'cpt' | 'stby';
    priorityScore: number;
    trainee?: Trainee;
    instructor?: Instructor;
    eventCode: string;
    isRemedial: boolean;
    isSct: boolean;
}

interface CourseAnalysis {
    courseName: string;
    targetPercentage: number;
    actualPercentage: number;
    deviation: number;
    eventCount: number;
    possibleEvents: number;
    schedulingEfficiency: number;
    eventsByType: {
        flight: number;
        ftd: number;
        cpt: number;
        ground: number;
    };
    limitingFactors: {
        insufficientInstructors: number;
        noAircraftSlots: number;
        noFtdSlots: number;
        noCptSlots: number;
        traineeLimit: number;
        instructorLimit: number;
        noTimeSlots: number;
    };
    status: 'good' | 'fair' | 'poor';
}

interface TimeDistribution {
    eventsByHour: Map<number, number>;
    clusteringScore: number;
    uniformityScore: number;
}

interface ResourceUtilization {
    aircraftUtilization: number;
    instructorUtilization: number;
    ftdUtilization: number;
    standbyCount: number;
}

interface Insight {
    type: 'success' | 'warning' | 'error' | 'info';
    message: string;
    recommendation?: string;
}

interface BuildAnalysis {
    buildDate: string;
    totalEvents: number;
    availableAircraft: number;
    courseAnalysis: CourseAnalysis[];
    timeDistribution: TimeDistribution;
    resourceUtilization: ResourceUtilization;
    insights: Insight[];
}


// Helper function to count possible events per course
function countPossibleEvents(
    allTraineesData: Trainee[],
    coursePriorities: string[],
    traineeLMPs: Map<string, LMP[]>,
    scores: Map<string, Score[]>,
    syllabusDetails: SyllabusDetail[],
    publishedSchedules: Map<string, Omit<ScheduleEvent, 'date'>[]>,
    buildDate: string
): Map<string, number> {
    const possibleEventCounts = new Map<string, number>();

    // Initialize counts
    coursePriorities.forEach(course => {
        possibleEventCounts.set(course, 0);
    });

    // Count trainees with next events per course
    const activeTrainees = allTraineesData.filter(t => !t.isPaused);

    activeTrainees.forEach(trainee => {
        if (!coursePriorities.includes(trainee.course)) return;

        const { next, plusOne } = computeNextEventsForTrainee(
            trainee,
            traineeLMPs,
            scores,
            syllabusDetails,
            publishedSchedules,
            buildDate
        );

        // Count next event
        if (next) {
            const currentCount = possibleEventCounts.get(trainee.course) || 0;
            possibleEventCounts.set(trainee.course, currentCount + 1);
        }

        // Count plus-one event
        if (plusOne) {
            const currentCount = possibleEventCounts.get(trainee.course) || 0;
            possibleEventCounts.set(trainee.course, currentCount + 1);
        }
    });

    return possibleEventCounts;
}

// Analyze build results and compare to targets
function analyzeBuildResults(
    events: Omit<ScheduleEvent, 'date'>[],
    coursePercentages: Map<string, number>,
    coursePriorities: string[],
    availableAircraft: number,
    buildDate: string,
    allTraineesData: Trainee[],
    traineeLMPs: Map<string, LMP[]>,
    scores: Map<string, Score[]>,
    syllabusDetails: SyllabusDetail[],
    publishedSchedules: Map<string, Omit<ScheduleEvent, 'date'>[]>
): BuildAnalysis {
    // Filter out Duty Sup events and STBY events from analytics.
    // STBY events are not shown in build analytics until moved to the active Daily schedule.
    const scheduledEvents = events.filter(e => {
        if (e.flightNumber.includes('Duty Sup')) return false;
        if (e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')) return false;
        return true;
    });

    const totalEvents = scheduledEvents.length;

    // Normalize percentages
    const normalizePercentages = (percentages: Map<string, number>): Map<string, number> => {
        const total = Array.from(percentages.values()).reduce((sum, val) => sum + val, 0);
        if (total === 0) return percentages;
        const normalized = new Map<string, number>();
        percentages.forEach((value, key) => {
            normalized.set(key, (value / total) * 100);
        });
        return normalized;
    };

    const normalizedPercentages = normalizePercentages(coursePercentages);

    // Calculate actual distribution per course
    const courseEventCounts = new Map<string, number>();
    const courseEventsByType = new Map<string, { flight: number, ftd: number, cpt: number, ground: number }>();

    coursePriorities.forEach(course => {
        courseEventCounts.set(course, 0);
        courseEventsByType.set(course, { flight: 0, ftd: 0, cpt: 0, ground: 0 });
    });

    scheduledEvents.forEach(event => {
        const trainee = allTraineesData.find(t => t.fullName === event.student || t.fullName === event.pilot);
        if (trainee && coursePriorities.includes(trainee.course)) {
            const course = trainee.course;
            courseEventCounts.set(course, (courseEventCounts.get(course) || 0) + 1);

            const typeCount = courseEventsByType.get(course)!;
            if (event.type === 'flight') typeCount.flight++;
            else if (event.type === 'ftd') typeCount.ftd++;
            else if (event.type === 'cpt') typeCount.cpt++;
            else if (event.type === 'ground') typeCount.ground++;
        }
    });

    // Build course analysis
    // Count possible events per course
    const possibleEventCounts = countPossibleEvents(
        allTraineesData,
        coursePriorities,
        traineeLMPs,
        scores,
        syllabusDetails,
        publishedSchedules,
        buildDate
    );

    const courseAnalysis: CourseAnalysis[] = coursePriorities.map(course => {
        const targetPercentage = normalizedPercentages.get(course) || 0;
        const eventCount = courseEventCounts.get(course) || 0;
        const possibleEvents = possibleEventCounts.get(course) || 0;
        const actualPercentage = totalEvents > 0 ? (eventCount / totalEvents) * 100 : 0;
        const deviation = actualPercentage - targetPercentage;
        const schedulingEfficiency = possibleEvents > 0 ? (eventCount / possibleEvents) * 100 : 0;

        let status: 'good' | 'fair' | 'poor';
        if (Math.abs(deviation) <= 5) status = 'good';
        else if (Math.abs(deviation) <= 10) status = 'fair';
        else status = 'poor';

        return {
            courseName: course,
            targetPercentage,
            actualPercentage,
            deviation,
            eventCount,
            possibleEvents,
            schedulingEfficiency,
            eventsByType: courseEventsByType.get(course) || { flight: 0, ftd: 0, cpt: 0, ground: 0 },
            limitingFactors: {
                insufficientInstructors: 0,
                noAircraftSlots: 0,
                noFtdSlots: 0,
                noCptSlots: 0,
                traineeLimit: 0,
                instructorLimit: 0,
                noTimeSlots: 0
            },
            status
        };
    });

    // Calculate time distribution
    const eventsByHour = new Map<number, number>();
    for (let h = 0; h < 24; h++) {
        eventsByHour.set(h, 0);
    }

    scheduledEvents.forEach(event => {
        const hour = Math.floor(event.startTime);
        eventsByHour.set(hour, (eventsByHour.get(hour) || 0) + 1);
    });

    // Calculate clustering score (0 = perfect uniform, 1 = highly clustered)
    const avgEventsPerHour = totalEvents / 24;
    let clusteringScore = 0;
    eventsByHour.forEach(count => {
        clusteringScore += Math.abs(count - avgEventsPerHour);
    });
    clusteringScore = clusteringScore / (totalEvents * 2); // Normalize to 0-1

    // Calculate uniformity score (inverse of clustering)
    const uniformityScore = 1 - clusteringScore;

    // Calculate resource utilization
    const flightEvents = scheduledEvents.filter(e => e.type === 'flight').length;
    const ftdEvents = scheduledEvents.filter(e => e.type === 'ftd').length;
    const standbyCount = events.filter(e =>
        e.resourceId.startsWith('STBY') || e.resourceId.startsWith('BNF-STBY')
    ).length;

    const aircraftUtilization = availableAircraft > 0 ? (flightEvents / availableAircraft) * 100 : 0;

    // Generate insights
    const insights: Insight[] = [];

    // Overall status
    const allGood = courseAnalysis.every(c => c.status === 'good');
    const anyPoor = courseAnalysis.some(c => c.status === 'poor');

    if (allGood) {
        insights.push({
            type: 'success',
            message: 'Excellent! All courses achieved their target percentages within ±5%.',
            recommendation: 'Current settings are optimal. Continue monitoring future builds.'
        });
    } else if (anyPoor) {
        insights.push({
            type: 'warning',
            message: 'Some courses deviated significantly from targets (>10%).',
            recommendation: 'Review resource constraints and unavailability periods. Consider adjusting percentages or increasing resources.'
        });
    } else {
        insights.push({
            type: 'info',
            message: 'Most courses achieved their targets. Minor deviations detected.',
            recommendation: 'Monitor trends over multiple builds. Small deviations are normal with limited resources.'
        });
    }

    // Time distribution insight
    if (uniformityScore > 0.8) {
        insights.push({
            type: 'success',
            message: 'Events are well-distributed throughout the day.',
            recommendation: 'Random shuffle is working effectively to prevent clustering.'
        });
    } else if (uniformityScore < 0.6) {
        insights.push({
            type: 'warning',
            message: 'Events show some clustering in certain time periods.',
            recommendation: 'This may be due to resource constraints or unavailability. Review instructor and aircraft availability.'
        });
    }

    // Resource utilization insight
    if (aircraftUtilization > 90) {
        insights.push({
            type: 'success',
            message: `High aircraft utilization (${aircraftUtilization.toFixed(0)}%).`,
            recommendation: 'Resources are being used efficiently.'
        });
    } else if (aircraftUtilization < 60) {
        insights.push({
            type: 'info',
            message: `Aircraft utilization is ${aircraftUtilization.toFixed(0)}%.`,
            recommendation: 'Consider reducing available aircraft count or increasing trainee demand.'
        });
    }

    // Standby events insight
    if (standbyCount > 0) {
        insights.push({
            type: 'warning',
            message: `${standbyCount} events placed on standby.`,
            recommendation: 'These trainees could not be scheduled due to resource constraints. Consider increasing resources or adjusting schedules.'
        });
    }

    return {
        buildDate,
        totalEvents,
        availableAircraft,
        courseAnalysis,
        timeDistribution: {
            eventsByHour,
            clusteringScore,
            uniformityScore
        },
        resourceUtilization: {
            aircraftUtilization,
            instructorUtilization: 0, // TODO: Calculate if needed
            ftdUtilization: 0, // TODO: Calculate if needed
            standbyCount
        },
        insights
    };
}

// ═══════════════════════════════════════════════════════════════════════════
// INSTRUCTOR ALLOCATION DIAGNOSTIC SYSTEM
// Pure localStorage-based. No React state. No UI props.
// Run a build → open DevTools console → type: __downloadBuildDiagnostic()
// ═══════════════════════════════════════════════════════════════════════════

interface InstructorDiagTraineeEntry {
    traineeName: string;
    traineeUnit: string;
    eventType: string;
    syllabusCode: string;
    totalInstructorsInConfig: number;
    afterQualificationFilter: number;
    afterUnitFilter: number;
    candidatesEnteringLoop: number;
    rejections: {
        staticUnavailable: number;
        softDutyLimit: number;
        groundLimit: number;
        eventLimit: number;
        timeOverlap: number;
        crewDutyPeriod: number;
    };
    finalAvailable: number;
    instructorFound: boolean;
    zeroReason: string | null;
}

interface InstructorDiagReport {
    timestamp: string;
    buildDate: string;
    totalInstructorsInConfig: number;
    sampleInstructors: Array<{ id: string; name: string; role: string; unit: string; location: string }>;
    totalTraineesProcessed: number;
    entries: InstructorDiagTraineeEntry[];
    summary: {
        totalSchedulingAttempts: number;
        instructorFound: number;
        instructorNotFound: number;
        zeroInstructorCases: {
            noInstructorsLoaded: number;
            noQualified: number;
            noUnitMatch: number;
            allFilteredOut: number;
        };
    };
}

let _instructorDiag: InstructorDiagReport | null = null;

function _diagInitInstructors(buildDate: string, instructors: any[]) {
    if (!isNeoBuildVerboseDiagnosticsEnabled()) {
        _instructorDiag = null;
        return;
    }
    _instructorDiag = {
        timestamp: new Date().toISOString(),
        buildDate,
        totalInstructorsInConfig: instructors.length,
        sampleInstructors: instructors.slice(0, 10).map(i => ({
            id: i.idNumber || 'unknown',
            name: i.name || 'unknown',
            role: i.role || 'unknown',
            unit: i.unit || 'unknown',
            location: i.location || 'unknown',
        })),
        totalTraineesProcessed: 0,
        entries: [],
        summary: {
            totalSchedulingAttempts: 0,
            instructorFound: 0,
            instructorNotFound: 0,
            zeroInstructorCases: {
                noInstructorsLoaded: 0,
                noQualified: 0,
                noUnitMatch: 0,
                allFilteredOut: 0,
            },
        },
    };
    console.log('[INSTR-DIAG] Initialized. Instructors in config:', instructors.length);
}

function _diagRecordEntry(entry: InstructorDiagTraineeEntry) {
    if (!_instructorDiag) return;
    _instructorDiag.entries.push(entry);
    _instructorDiag.summary.totalSchedulingAttempts++;
    if (entry.instructorFound) {
        _instructorDiag.summary.instructorFound++;
    } else {
        _instructorDiag.summary.instructorNotFound++;
        if (entry.zeroReason === 'NO_INSTRUCTORS_LOADED') _instructorDiag.summary.zeroInstructorCases.noInstructorsLoaded++;
        else if (entry.zeroReason === 'NO_QUALIFIED') _instructorDiag.summary.zeroInstructorCases.noQualified++;
        else if (entry.zeroReason === 'NO_UNIT_MATCH') _instructorDiag.summary.zeroInstructorCases.noUnitMatch++;
        else if (entry.zeroReason === 'ALL_FILTERED_OUT') _instructorDiag.summary.zeroInstructorCases.allFilteredOut++;
    }
}

function _diagFinalizeInstructors() {
    if (!_instructorDiag) return;
    _instructorDiag.totalTraineesProcessed = _instructorDiag.entries.length;
    try {
        localStorage.setItem('instructor_diag_report', JSON.stringify(_instructorDiag));
        console.log('[INSTR-DIAG] ✅ Report saved to localStorage. Attempts:', _instructorDiag.summary.totalSchedulingAttempts,
            'Found:', _instructorDiag.summary.instructorFound,
            'NOT found:', _instructorDiag.summary.instructorNotFound);
        console.log('[INSTR-DIAG] Zero instructor breakdown:', JSON.stringify(_instructorDiag.summary.zeroInstructorCases));
        console.log('[INSTR-DIAG] To download: open console and type __downloadBuildDiagnostic()');
    } catch (e) {
        console.warn('[INSTR-DIAG] Failed to save to localStorage:', e);
    }
}

// Global download helper — callable from browser DevTools console
(window as any).__downloadBuildDiagnostic = () => {
    const raw = localStorage.getItem('instructor_diag_report');
    if (!raw) { console.error('No diagnostic report found. Run a build first.'); return; }
    const report = JSON.parse(raw);
    const filename = `instructor-diag-${getDiagnosticTimestamp(report.timestamp)}.json`;
    downloadJsonDiagnosticFile(filename, report);
    console.log('[INSTR-DIAG] Download triggered:', filename);
};

