    const savePlatformConfigDebounced = useCallback((nextConfig: PlatformConfig) => {
        if (platformConfigSaveTimerRef.current) {
            clearTimeout(platformConfigSaveTimerRef.current);
        }
        platformConfigSaveTimerRef.current = setTimeout(() => {
            if (isSetupTestMode()) {
                writeSetupTestPlatformConfig(nextConfig);
                return;
            }
            const sessionToken = localStorage.getItem('dfp_session_token') || '';
            fetch(`${getApiBase()}/platform-config`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    ...(sessionToken ? { Authorization: `Bearer ${sessionToken}` } : {}),
                },
                body: JSON.stringify(nextConfig),
            }).then((res) => {
                if (!res.ok) throw new Error(`Save failed (${res.status})`);
                window.dispatchEvent(new CustomEvent(PLATFORM_CONFIG_UPDATED_EVENT, { detail: { config: nextConfig } }));
            }).catch((error) => {
                console.warn('[PlatformConfig] Failed to save unit training report settings:', error);
            });
        }, 900);
    }, []);
    const handleUpdatePlatformConfigFromSchedule = useCallback((updater: (current: PlatformConfig) => PlatformConfig) => {
        setPlatformConfig((prev) => {
            if (!prev) return prev;
            const nextConfig = updater(prev);
            if (!isSetupTestMode()) {
                window.setTimeout(() => {
                    window.dispatchEvent(new CustomEvent(PLATFORM_CONFIG_UPDATED_EVENT, { detail: { config: nextConfig } }));
                }, 0);
            }
            savePlatformConfigDebounced(nextConfig);
            return nextConfig;
        });
    }, [savePlatformConfigDebounced]);
    const registerSetupTestCoursesFromTrainees = useCallback((trainees: any[]) => {
        const defaultColors = [
            'bg-sky-400/80', 'bg-purple-400/80', 'bg-yellow-400/80', 'bg-pink-400/80',
            'bg-orange-400/80', 'bg-teal-400/80', 'bg-indigo-400/80', 'bg-green-400/80',
            'bg-red-400/80', 'bg-cyan-400/80'
        ];
        const courseNames = Array.from(new Set(
            (trainees || [])
                .map((trainee: any) => String(trainee?.course || '').trim())
                .filter(Boolean),
        ));
        if (courseNames.length === 0) return;
        setCourseColors(prev => {
            const next = { ...prev };
            courseNames.forEach((courseName, index) => {
                if (!next[courseName]) next[courseName] = defaultColors[(Object.keys(next).length + index) % defaultColors.length];
            });
            return next;
        });
        setCourses(prevCourses => {
            const seen = new Set(prevCourses.map(course => normaliseCourseName(course.name || (course as any).code)).filter(Boolean));
            const nextCourses = [...prevCourses];
            courseNames.forEach((courseName, index) => {
                const normalisedName = normaliseCourseName(courseName);
                if (!normalisedName || seen.has(normalisedName)) return;
                nextCourses.push({
                    id: `setup-course-${normalisedName.replace(/[^A-Z0-9]+/gi, '-')}`,
                    name: courseName,
                    color: defaultColors[(nextCourses.length + index) % defaultColors.length],
                    startDate: '',
                    gradDate: '',
                    raafStart: 0,
                    navyStart: 0,
                    armyStart: 0,
                    location: school,
                    unit: activeUnitCode,
                    status: 'ACTIVE',
                });
                seen.add(normalisedName);
            });
            return nextCourses;
        });
    }, [activeUnitCode, normaliseCourseName, school]);
    const handleSaveSetupTestPersonnel = useCallback((payload: { instructors: any[]; trainees: any[] }) => {
        if (!isSetupTestMode()) return;
        const existingPersonnel = readSetupTestPersonnel();
        const instructors = payload.instructors || [];
        const trainees = payload.trainees || [];
        const normalisedInstructors = instructors.map((person: any) => ({
            ...normalisePersonnelRecord(person),
            _dataSource: 'setup-test' as const,
        }));
        const normalisedTrainees = trainees.map((trainee: any) => ({
            ...trainee,
            fullName: trainee.fullName || trainee.name || [trainee.surname, trainee.givenNames].filter(Boolean).join(', '),
            name: trainee.name || trainee.fullName || [trainee.surname, trainee.givenNames].filter(Boolean).join(', '),
            _dataSource: 'setup-test' as const,
        }));
        const nextInstructors = normalisedInstructors.length > 0
            ? normalisedInstructors
            : (existingPersonnel.instructors || []).map((person: any) => ({
                ...normalisePersonnelRecord(person),
                _dataSource: 'setup-test' as const,
            }));
        const nextTrainees = normalisedTrainees.length > 0
            ? normalisedTrainees
            : (existingPersonnel.trainees || []).map((trainee: any) => ({
                ...trainee,
                fullName: trainee.fullName || trainee.name || [trainee.surname, trainee.givenNames].filter(Boolean).join(', '),
                name: trainee.name || trainee.fullName || [trainee.surname, trainee.givenNames].filter(Boolean).join(', '),
                _dataSource: 'setup-test' as const,
            }));
        pushSetupTestPersonnelDiag('save:requested', {
            incomingInstructors: normalisedInstructors.length,
            incomingTrainees: normalisedTrainees.length,
            preservedExistingInstructors: normalisedInstructors.length === 0 && (existingPersonnel.instructors || []).length > 0,
            preservedExistingTrainees: normalisedTrainees.length === 0 && (existingPersonnel.trainees || []).length > 0,
            savedInstructors: nextInstructors.length,
            savedTrainees: nextTrainees.length,
            instructorSample: nextInstructors.slice(0, 8).map((person: any) => ({
                name: person.name,
                unit: person.unit,
                location: person.location,
                role: person.role,
                source: person._dataSource,
            })),
            traineeSample: nextTrainees.slice(0, 8).map((person: any) => ({
                name: person.name || person.fullName,
                unit: person.unit,
                location: person.location,
                course: person.course,
                source: person._dataSource,
            })),
        });
        writeSetupTestPersonnel(nextInstructors, nextTrainees);
        setInstructorsData(nextInstructors);
        setTraineesData(nextTrainees);
        registerSetupTestCoursesFromTrainees(nextTrainees);
        setIsStaffLoaded(true);
        setIsTraineeLoaded(true);
        setSuccessMessage(`Setup Wizard committed ${nextInstructors.length} staff profile${nextInstructors.length === 1 ? '' : 's'}${nextTrainees.length > 0 ? ` and ${nextTrainees.length} trainee profile${nextTrainees.length === 1 ? '' : 's'}` : ''} to this setup.`);
    }, [pushSetupTestPersonnelDiag, registerSetupTestCoursesFromTrainees]);
    const handleSaveStandardMissionProfileFromPlanner = useCallback((profileId: string, changes: Partial<StandardMissionProfile>) => {
        const targetId = String(profileId || '').trim();
        if (!targetId) return;
        setPlatformConfig((prev) => {
            if (!prev) return prev;
            const activeOrganisation = (prev.organisations || []).find((organisation: any) => (
                String(organisation.status || 'ACTIVE').toUpperCase() === 'ACTIVE'
            )) || prev.organisations?.[0];
            if (!activeOrganisation) return prev;
            const nextConfig = {
                ...prev,
                organisations: (prev.organisations || []).map((organisation: any) => {
                    if (organisation !== activeOrganisation) return organisation;
                    const source = organisation.settings?.standardMissionProfiles;
                    const rows = Array.isArray(source?.profiles) ? source.profiles : Array.isArray(source) ? source : [];
                    const targetRow = rows.find((row: any, index: number) => String(row?.id || `standard-mission-${index + 1}`) === targetId);
                    const targetCompositeProfileId = String(targetRow?.compositeProfileId || '').trim();
                    return {
                        ...organisation,
                        settings: {
                            ...(organisation.settings || {}),
                            standardMissionProfiles: {
                                profiles: rows.map((row: any, index: number) => {
                                    const rowId = String(row?.id || `standard-mission-${index + 1}`);
                                    const rowCompositeProfileId = String(row?.compositeProfileId || '').trim();
                                    const isSameCompositeGroup = targetCompositeProfileId && rowCompositeProfileId === targetCompositeProfileId;
                                    return rowId === targetId || isSameCompositeGroup ? { ...row, ...changes } : row;
                                }),
                            },
                        },
                    };
                }),
            };
            savePlatformConfigDebounced(nextConfig);
            return nextConfig;
        });
    }, [savePlatformConfigDebounced]);
