    const getLocalIsoDateForResourceRows = useCallback((offsetDays = 0): string => {
        const dateValue = new Date();
        dateValue.setDate(dateValue.getDate() + offsetDays);
        const year = dateValue.getFullYear();
        const month = String(dateValue.getMonth() + 1).padStart(2, '0');
        const day = String(dateValue.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }, []);

    const getResourceRowHistoryMatchForDiag = useCallback((settings: Record<string, any>, targetDate: string) => {
        const history = Array.isArray(settings?.dfpResourceRowsHistory) ? settings.dfpResourceRowsHistory : [];
        const matches = history
            .map((entry: any, index: number) => {
                const effectiveFrom = String(entry?.effectiveFrom || '0000-01-01').slice(0, 10);
                const effectiveTo = String(entry?.effectiveTo || '9999-12-31').slice(0, 10);
                const hasRows = !!entry?.rows && typeof entry.rows === 'object';
                const matchesDate = effectiveFrom === '0000-01-01' && effectiveTo !== '9999-12-31'
                    ? targetDate === effectiveTo && hasRows
                    : targetDate >= effectiveFrom && targetDate <= effectiveTo && hasRows;
                return {
                    index,
                    matchesDate,
                    effectiveFrom,
                    effectiveTo,
                    rows: entry?.rows || null,
                    rawEntry: entry,
                };
            })
            .filter((entry: any) => entry.matchesDate);
        return matches.length ? matches[matches.length - 1] : null;
    }, []);

    const buildDfpResourceRowsDiagnosticReport = useCallback(() => {
        let lastSaveTrace: any = null;
        let lastSaveAttemptTrace: any = null;
        try {
            lastSaveTrace = JSON.parse(localStorage.getItem('dfp_resource_rows_last_save_trace') || 'null');
        } catch {
            lastSaveTrace = null;
        }
        try {
            lastSaveAttemptTrace = JSON.parse(localStorage.getItem('dfp_resource_rows_last_save_attempt_trace') || 'null');
        } catch {
            lastSaveAttemptTrace = null;
        }
        const targetDates = Array.from(new Set([
            getLocalIsoDateForResourceRows(-1),
            getLocalIsoDateForResourceRows(0),
            date,
            getLocalIsoDateForResourceRows(1),
        ].filter(Boolean)));
        const rowKeys = ['aircraft', 'ftd', 'cpt', 'standby', 'ground'] as const;
        const pools = Array.isArray(platformConfig?.resourcePools) ? platformConfig.resourcePools : [];
        const activePoolKey = String(activePlatformResourcePool?.id || activePlatformResourcePool?.code || '').trim();
        const contextLocation = String(school || '').trim().toUpperCase();
        const contextUnitCodes = String(activeUnitCode || '').split(/[+/]/).map(unit => unit.trim().toUpperCase()).filter(Boolean);
        const contextPools = pools.filter((pool: any) => {
            const poolKey = String(pool?.id || pool?.code || '').trim();
            const poolLocation = String(pool?.locationCode || '').trim().toUpperCase();
            const poolUnit = String(pool?.unitCode || '').trim().toUpperCase();
            if (activePoolKey && poolKey === activePoolKey) return true;
            if (contextLocation && poolLocation && poolLocation !== contextLocation) return false;
            return !poolUnit || contextUnitCodes.includes(poolUnit) || contextUnitCodes.length === 0;
        });
        const poolsToReport = contextPools.length ? contextPools : (activePlatformResourcePool ? [activePlatformResourcePool] : pools.slice(0, 10));

        return {
            reportType: 'DFP resource row diagnostics',
            diagnosticVersion: 'CCH 3.257',
            generatedAt: new Date().toISOString(),
            url: window.location.href,
            userAgent: navigator.userAgent,
            resourceRowSaveTrace: lastSaveTrace,
            resourceRowSaveAttemptTrace: lastSaveAttemptTrace,
            activeContext: {
                selectedDate: date,
                browserYesterday: getLocalIsoDateForResourceRows(-1),
                browserToday: getLocalIsoDateForResourceRows(0),
                browserTomorrow: getLocalIsoDateForResourceRows(1),
                school,
                activeUnitCode,
                activeView,
                activePoolKey: activePoolKey || null,
            },
            activeDfpCounts: {
                aircraft: configuredAirframeCount,
                ftd: configuredFtdCount,
                cpt: configuredCptCount,
                standby: configuredStandbyCount,
                ground: configuredGroundCount,
            },
            resourcePools: poolsToReport.map((pool: any, poolIndex: number) => {
                const settings = pool?.settings || {};
                return {
                    index: pools.indexOf(pool),
                    fallbackIndex: poolIndex,
                    isActivePool: activePoolKey
                        ? String(pool?.id || pool?.code || '').trim() === activePoolKey
                        : pool === activePlatformResourcePool,
                    id: pool?.id || null,
                    code: pool?.code || null,
                    name: pool?.name || null,
                    poolType: pool?.poolType || null,
                    locationCode: pool?.locationCode || null,
                    unitCode: pool?.unitCode || null,
                    aircraftTypeCode: pool?.aircraftTypeCode || null,
                    rawCurrentSettings: Object.fromEntries(rowKeys.map(key => [key, settings[key] ?? null])),
                    aircraftInventoryNumbers: Array.isArray(settings.aircraftInventoryNumbers) ? settings.aircraftInventoryNumbers : [],
                    dfpResourceRowsEffectiveFrom: settings.dfpResourceRowsEffectiveFrom || null,
                    dfpResourceRowsHistory: Array.isArray(settings.dfpResourceRowsHistory) ? settings.dfpResourceRowsHistory : [],
                    dateReads: Object.fromEntries(targetDates.map(targetDate => [
                        targetDate,
                        {
                            historyMatch: getResourceRowHistoryMatchForDiag(settings, targetDate),
                            counts: Object.fromEntries(rowKeys.map(key => [
                                key,
                                getResourcePoolCount(pool, key, key === 'aircraft' ? 24 : key === 'ftd' ? availableFtdCount : key === 'cpt' ? availableCptCount : key === 'standby' ? 4 : 6, targetDate),
                            ])),
                        },
                    ])),
                };
            }),
        };
    }, [
        activePlatformResourcePool,
        activeUnitCode,
        activeView,
        availableCptCount,
        availableFtdCount,
        configuredAirframeCount,
        configuredCptCount,
        configuredFtdCount,
        configuredGroundCount,
        configuredStandbyCount,
        date,
        getLocalIsoDateForResourceRows,
        getResourceRowHistoryMatchForDiag,
        platformConfig?.resourcePools,
        school,
    ]);

    const downloadDfpResourceRowsDiagnosticReport = useCallback(() => {
        const report = buildDfpResourceRowsDiagnosticReport();
        const contextStamp = [school, activeUnitCode, date].map(value => String(value || '').replace(/[^a-z0-9-]+/gi, '-')).filter(Boolean).join('_');
        const filename = `dfp-resource-rows-diag_${contextStamp || 'app'}_${getDiagnosticTimestamp(report.generatedAt)}.json`;
        if (!downloadJsonDiagnosticFile(filename, report)) {
            console.error('[DFP-RESOURCE-ROWS-DIAG] Could not download diagnostic report:', report);
        }
    }, [activeUnitCode, buildDfpResourceRowsDiagnosticReport, date, school]);
    const currentAircraftConfigState = useMemo(() => ({
        availableAircraftCount: Math.max(0, Math.floor(Number(neoAvailableAircraftCount) || 0)),
        aircraftConfigCapacities: neoAircraftConfigCapacities,
        aircraftConfigurationDefinitions: aircraftConfigCapacityDefinitions,
    }), [aircraftConfigCapacityDefinitions, neoAircraftConfigCapacities, neoAvailableAircraftCount]);

    const buildAircraftConfigIdsByResource = useCallback((configState = currentAircraftConfigState) => {
        const definitions = configState.aircraftConfigurationDefinitions?.length
            ? configState.aircraftConfigurationDefinitions
            : aircraftConfigCapacityDefinitions;
        const cleanConfig = definitions.find(definition => definition.id === BASE_AIRCRAFT_CONFIG.id) || BASE_AIRCRAFT_CONFIG;
        const configuredDefinitions = definitions.filter(definition => definition.id !== cleanConfig.id);
        const capacities = configState.aircraftConfigCapacities || {};
        const totalAvailable = Math.max(0, Math.floor(Number(configState.availableAircraftCount) || 0));
        const configuredIds = configuredDefinitions.flatMap((definition) => {
            const count = Math.max(0, parseInt(capacities[definition.id] || '', 10) || 0);
            return Array.from({ length: count }, () => definition.id);
        });
        const cleanCount = Math.max(0, totalAvailable - configuredIds.length);
        const availableConfigIds = [
            ...Array.from({ length: cleanCount }, () => cleanConfig.id),
            ...configuredIds,
        ].slice(0, totalAvailable);

        return Array.from({ length: configuredAirframeCount }, (_, index) => {
            const resourceId = `${activeAircraftResourcePrefix} ${index + 1}`;
            return [resourceId, availableConfigIds[index] || cleanConfig.id] as const;
        }).reduce<Record<string, string>>((acc, [resourceId, label]) => {
            acc[resourceId] = label;
            return acc;
        }, {});
    }, [activeAircraftResourcePrefix, aircraftConfigCapacityDefinitions, configuredAirframeCount, currentAircraftConfigState]);

    const buildAircraftConfigLabelsByResource = useCallback((configState = currentAircraftConfigState) => {
        const definitions = configState.aircraftConfigurationDefinitions?.length
            ? configState.aircraftConfigurationDefinitions
            : aircraftConfigCapacityDefinitions;
        const definitionLabels = new Map(definitions.map(definition => [definition.id, definition.label]));
        const cleanConfig = definitions.find(definition => definition.id === BASE_AIRCRAFT_CONFIG.id) || BASE_AIRCRAFT_CONFIG;
        const idsByResource = buildAircraftConfigIdsByResource(configState);

        return Object.entries(idsByResource).reduce<Record<string, string>>((acc, [resourceId, configId]) => {
            acc[resourceId] = definitionLabels.get(configId) || cleanConfig.label;
            return acc;
        }, {});
    }, [aircraftConfigCapacityDefinitions, buildAircraftConfigIdsByResource, currentAircraftConfigState]);

    const aircraftConfigLabelsByResource = useMemo(() => {
        const snapshotKey = getDailySnapshotKey(date);
        const dateConfigState = aircraftConfigStateByDate[snapshotKey];
        const isFutureBuildDate = /^\d{4}-\d{2}-\d{2}$/.test(date) && date > getLocalDateString();
        return buildAircraftConfigLabelsByResource(isFutureBuildDate ? currentAircraftConfigState : (dateConfigState || currentAircraftConfigState));
    }, [aircraftConfigStateByDate, buildAircraftConfigLabelsByResource, currentAircraftConfigState, date, timezoneOffset]);
    const nextDayBuildAircraftConfigLabelsByResource = useMemo(() => (
        buildAircraftConfigLabelsByResource(currentAircraftConfigState)
    ), [buildAircraftConfigLabelsByResource, currentAircraftConfigState]);
    const [flyingStartTime, setFlyingStartTime] = useState(8.0); // 08:00
    const [flyingEndTime, setFlyingEndTime] = useState(17.0); // 17:00
    const [ftdStartTime, setFtdStartTime] = useState(8.0); // 08:00
    const [ftdEndTime, setFtdEndTime] = useState(17.0); // 17:00
    const [allowNightFlying, setAllowNightFlying] = useState(true);
    const [commenceNightFlying, setCommenceNightFlying] = useState(18.5); // 18:30
    const [ceaseNightFlying, setCeaseNightFlying] = useState(23.5); // 23:30
    const [flyingWindowExclusions, setFlyingWindowExclusions] = useState<FlyingWindowExclusionPeriod[]>([]);
    const [flyingWindowExclusionsByUnit, setFlyingWindowExclusionsByUnit] = useState<Record<string, FlyingWindowExclusionPeriod[]>>({});
    const formatDecimalTimeInput = useCallback((decimalHour: number): string => {
        const bounded = Math.max(0, Math.min(23 + 55 / 60, Number(decimalHour) || 0));
        const totalMinutes = Math.round(bounded * 60 / 5) * 5;
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
    }, []);
    const activeFlyingWindowExclusionUnitKey = useMemo(() => (
        String(activeUnitCode || school || 'DEFAULT').trim().toUpperCase() || 'DEFAULT'
    ), [activeUnitCode, school]);
    const handleUpdateFlyingWindowExclusions = useCallback((periods: FlyingWindowExclusionPeriod[]) => {
        const nextPeriods = Array.isArray(periods) ? periods : [];
        setFlyingWindowExclusions(nextPeriods);
        setFlyingWindowExclusionsByUnit(prev => ({
            ...prev,
            [activeFlyingWindowExclusionUnitKey]: nextPeriods,
        }));
    }, [activeFlyingWindowExclusionUnitKey]);

    useEffect(() => {
        setFlyingWindowExclusions(flyingWindowExclusionsByUnit[activeFlyingWindowExclusionUnitKey] || []);
    }, [activeFlyingWindowExclusionUnitKey, flyingWindowExclusionsByUnit]);

    const classifyStartBySolarDaylight = useCallback((startTime: number, targetDate: string = date): 'Day' | 'Night' => {
        const sunTimes = targetDate === date ? selectedDfpSunTimes : getSunTimesForDate(targetDate);
        const solarClassification = classifyDayNightBySunTimes(startTime, sunTimes);
        if (solarClassification === 'Day' || solarClassification === 'Night') return solarClassification;
        return startTime >= commenceNightFlying && startTime < ceaseNightFlying ? 'Night' : 'Day';
    }, [ceaseNightFlying, commenceNightFlying, date, getSunTimesForDate, selectedDfpSunTimes]);

    // Wrapper function to update aircraft count AND save to database
    const handleUpdateAircraftCount = async (count: number) => {
        const previousCount = availableAircraftCount;
        setAvailableAircraftCount(count);

        // Save to database if count changed and user is logged in
        if (count !== previousCount && sessionUser?.userId) {
            logAvailabilityDebug(`[AV] Aircraft count changed: ${previousCount} -> ${count}, saving to database`);
            await postAvailabilityEvent(
                count,
                'change',
                undefined,
                `Aircraft availability updated: ${count}`
            );
        }
    };
    const handleUpdateNeoAvailableAircraftCount = useCallback((value: React.SetStateAction<number>) => {
        setNeoAvailableAircraftCount(previous => {
            const next = typeof value === 'function' ? (value as (current: number) => number)(previous) : value;
            setNeoAircraftCapacityByUnit(current => ({
                ...current,
                [activeNeoAircraftCapacityUnitKey]: {
                    ...(current[activeNeoAircraftCapacityUnitKey] || {}),
                    availableAircraftCount: next,
                    aircraftConfigCapacities: current[activeNeoAircraftCapacityUnitKey]?.aircraftConfigCapacities || neoAircraftConfigCapacities,
                },
            }));
            return next;
        });
    }, [activeNeoAircraftCapacityUnitKey, neoAircraftConfigCapacities]);
    const handleUpdateNeoAircraftConfigCapacities = useCallback((value: React.SetStateAction<Record<string, string>>) => {
        setNeoAircraftConfigCapacities(previous => {
            const next = typeof value === 'function' ? (value as (current: Record<string, string>) => Record<string, string>)(previous) : value;
            setNeoAircraftCapacityByUnit(current => ({
                ...current,
                [activeNeoAircraftCapacityUnitKey]: {
                    ...(current[activeNeoAircraftCapacityUnitKey] || {}),
                    availableAircraftCount: current[activeNeoAircraftCapacityUnitKey]?.availableAircraftCount ?? neoAvailableAircraftCount,
                    aircraftConfigCapacities: next,
                },
            }));
            return next;
        });
    }, [activeNeoAircraftCapacityUnitKey, neoAvailableAircraftCount]);
    const [preferredDutyPeriod, setPreferredDutyPeriod] = useState(8);
    const [maxCrewDutyPeriod, setMaxCrewDutyPeriod] = useState(10);
    const [maxDispatchPerHour, setMaxDispatchPerHour] = useState(8);
    const [dispatchStaggerSettings, setDispatchStaggerSettings] = useState<DispatchStaggerSettings>(DEFAULT_DISPATCH_STAGGER_SETTINGS);
    const [flightTurnaround, setFlightTurnaround] = useState(1.2);
    const [ftdTurnaround, setFtdTurnaround] = useState(0.5);
    const [cptTurnaround, setCptTurnaround] = useState(0.5);
    const [isBuildingDfp, setIsBuildingDfp] = useState(false);
    const [isStaffLoaded, setIsStaffLoaded] = useState(false);
    const [isTraineeLoaded, setIsTraineeLoaded] = useState(false);
    const [isCoursesLoaded, setIsCoursesLoaded] = useState(false);
    const [dfpBuildProgress, setDfpBuildProgress] = useState({ message: '', percentage: 0 });
    const [showDateWarning, setShowDateWarning] = useState(false);
    const [unavailabilityNotifications, setUnavailabilityNotifications] = useState<string[]>([]);
    const [isPriorityEventCreation, setIsPriorityEventCreation] = useState(false);
    const highestPriorityEventsStorageKey = useMemo(
        () => buildHighestPriorityEventsStorageKey(school, activeUnitCode),
        [activeUnitCode, school],
    );
    const skipNextHighestPriorityPersistRef = useRef(false);
    const [highestPriorityEvents, setHighestPriorityEvents] = useState<ScheduleEvent[]>(() => (
        loadHighestPriorityEventsForUnitContext(initialOperationalContext.location, initialOperationalContext.unit)
    ));
    const [instructorPriority, setInstructorPriority] = useState<InstructorPriorityConfig>(DEFAULT_INSTRUCTOR_PRIORITY_CONFIG);

    useEffect(() => {
        skipNextHighestPriorityPersistRef.current = true;
        setHighestPriorityEvents(loadHighestPriorityEventsForUnitContext(school, activeUnitCode));
    }, [activeUnitCode, highestPriorityEventsStorageKey, school]);

    useEffect(() => {
        if (skipNextHighestPriorityPersistRef.current) {
            skipNextHighestPriorityPersistRef.current = false;
            return;
        }
        try {
            localStorage.setItem(highestPriorityEventsStorageKey, JSON.stringify(highestPriorityEvents));
        } catch (error) {
            console.warn('[HighestPriorityEvents] Failed to persist events', error);
        }
    }, [highestPriorityEvents, highestPriorityEventsStorageKey]);

    // Cancellation Records State
    const [cancellationRecords, setCancellationRecords] = useState<CancellationRecord[]>(() => {
        const stored = localStorage.getItem('cancellationRecords');
        return stored ? JSON.parse(stored) : [];
    });

    // Shared API base helper — always use relative /api when served from same origin
    const getApiBase = () => '/api';

    // Selected Academic LMP — persisted in DB so last selection survives hard reset
    const [persistedAcademicLmp, setPersistedAcademicLmp] = useState<string>('');
    // Courses excluded from NEO Build (e.g. in Academics phase or on course pause)
    const [excludedCourses, setExcludedCourses] = useState<string[]>([]);

    useEffect(() => {
        const loadCourseSettings = async () => {
            try {
                const res = await fetch(`${getApiBase()}/settings/course-settings`);
                if (res.ok) {
                    const data = await res.json();
                    setPersistedAcademicLmp(data.selectedAcademicLmp || '');
                    setExcludedCourses(data.excludedCourses || []);
                }
            } catch (error) {
                console.error('[CourseSettings] Failed to load:', error);
            }
        };
        loadCourseSettings();
    }, []);

    const handleUpdateExcludedCourses = async (courses: string[]) => {
        setExcludedCourses(courses);
        try {
            await fetch(`${getApiBase()}/settings/course-settings`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ excludedCourses: courses })
            });
        } catch (error) {
            console.error('[ExcludedCourses] Failed to save:', error);
        }
    };

    const handleUpdatePersistedAcademicLmp = async (lmp: string) => {
        setPersistedAcademicLmp(lmp);
        try {
            await fetch(`${getApiBase()}/settings/course-settings`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ selectedAcademicLmp: lmp })
            });
        } catch (error) {
            console.error('[SelectedAcademicLmp] Failed to save:', error);
        }
    };

    // Course Academic Progress — persisted in DB: Map<courseCode, Set<lessonCode>>
    const [courseAcademicProgress, setCourseAcademicProgress] = useState<Map<string, Set<string>>>(new Map());
    useEffect(() => {
        const loadCourseAcademicProgress = async () => {
            try {
                const res = await fetch(`${getApiBase()}/settings/course-academic-progress`);
                if (res.ok) {
                    const json = await res.json();
                    if (json.success && json.data) {
                        const map = new Map<string, Set<string>>();
                        Object.entries(json.data).forEach(([courseCode, lessons]) => {
                            map.set(courseCode, new Set(lessons as string[]));
                        });
                        setCourseAcademicProgress(map);
                    }
                }
            } catch (error) {
                console.error('[CourseAcademicProgress] Failed to load:', error);
            }
        };
        loadCourseAcademicProgress();
    }, []);
    const handleUpdateCourseAcademicProgress = async (courseCode: string, lessonCode: string, completed: boolean) => {
        // Optimistic UI update
        setCourseAcademicProgress(prev => {
            const next = new Map(prev);
            if (completed) {
                if (!next.has(courseCode)) next.set(courseCode, new Set());
                next.get(courseCode)!.add(lessonCode);
            } else {
                next.get(courseCode)?.delete(lessonCode);
            }
            return next;
        });
        // Persist to DB
        try {
            if (completed) {
                await fetch(`${getApiBase()}/settings/course-academic-progress`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ courseCode, lessonCode })
                });
            } else {
                await fetch(`${getApiBase()}/settings/course-academic-progress?courseCode=${encodeURIComponent(courseCode)}&lessonCode=${encodeURIComponent(lessonCode)}`, {
                    method: 'DELETE'
                });
            }
        } catch (error) {
            console.error('[CourseAcademicProgress] Failed to save:', error);
        }
    };

    // Cancellation Codes State
    const [cancellationCodes, setCancellationCodes] = useState<CancellationCode[]>(() => {
        try {
            const stored = localStorage.getItem('cancellationCodes');
            if (stored) {
                const parsed = JSON.parse(stored);
                return Array.isArray(parsed) ? parsed : [];
            }
        } catch (error) {
            console.warn('[CancellationCodes] Ignoring invalid browser cancellation-code cache:', error);
        }
        return [];
    });
    const [showNightFlyingInfo, setShowNightFlyingInfo] = useState(false);
    const [nightFlyingTraineeCount, setNightFlyingTraineeCount] = useState(0);
    const [showUnavailabilityReport, setShowUnavailabilityReport] = useState(false);

    // Oracle State
    const [isOracleMode, setIsOracleMode] = useState(false);
    const [oracleAnalysis, setOracleAnalysis] = useState<OracleAnalysisResult | null>(null);
    const [oraclePreviewEvent, setOraclePreviewEvent] = useState<ScheduleEvent | null>(null);
    const [oracleContextForModal, setOracleContextForModal] = useState<{
        availableInstructors: string[];
        availableTraineesAnalysis: OracleTraineeAnalysis[];
    } | null>(null);
    const [oracleContext, setOracleContext] = useState<'program' | 'nextDayBuild'>('program');


    // Continuation and remedial state.
    const [sctFlights, setSctFlights] = useState<SctRequest[]>([]);
    const [sctFtds, setSctFtds] = useState<SctRequest[]>([]);

    // Helper: get current userId from multiple sources
    const getCurrentUserId = (): string | null => {
        // 1. Try sessionUser (set after login)
        if (sessionUser?.userId) return sessionUser.userId;
        // 2. Try authUser (set after regular login)
        if (authUser?.userId) return authUser.userId;
        // 3. Try localStorage SSO data
        try {
            const ssoData = localStorage.getItem('dfp_sso_user');
            if (ssoData) {
                const ssoUser = JSON.parse(ssoData);
                if (ssoUser?.userId) return ssoUser.userId;
            }
        } catch (e) {}
        return null;
    };

    // Load continuation requests from database when sessionUser is available
    useEffect(() => {
        if (!sessionUser?.userId) return;
        const loadSctRequests = async () => {
            try {
                const res = await fetch(`/api/sct-requests?userId=${sessionUser.userId}`);
                if (!res.ok) {
                    const errData = await res.json().catch(() => ({}));
                    console.error('[CONTINUATION] Failed to load from DB:', res.status, errData);
                    return;
                }
                const data = await res.json();
                const normaliseSctAcceptableConfigs = (value: unknown): string[] | undefined => {
                    if (Array.isArray(value)) return value.map(configId => String(configId || '').trim()).filter(Boolean);
                    if (typeof value === 'string' && value.trim()) {
                        try {
                            const parsed = JSON.parse(value);
                            if (Array.isArray(parsed)) return parsed.map(configId => String(configId || '').trim()).filter(Boolean);
                        } catch {
                            return [value.trim()];
                        }
                    }
                    return undefined;
                };
                setSctFlights(data.filter((r: any) => r.requestType === 'flight').map((r: any) => ({
                    id: r.id, name: r.name, event: r.event, eventCode: r.eventCode || '', flightType: r.flightType as 'Solo' | 'Dual',
                    currency: r.currency, currencyExpire: r.currencyExpire, priority: r.priority as 'High' | 'Medium' | 'Low',
                    notes: r.notes, dateRequested: r.dateRequested, requestedTime: r.requestedTime,
                    dayNight: r.dayNight || undefined,
                    submitted: r.submitted, includeInBuild: r.includeInBuild,
                    aircraftConfigId: r.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id,
                    acceptableAircraftConfigs: normaliseSctAcceptableConfigs(r.acceptableAircraftConfigs),
                    crewMember: r.crewMember || '',
                    crewGroup: r.crewGroup || '',
                    crewGroupKey: r.crewGroupKey || '',
                    crewUnitCode: r.crewUnitCode || '',
                    crewDisplayLabel: r.crewDisplayLabel || '',
                    crewIndividual: r.crewIndividual || '',
                    aircraftCount: Math.max(1, Math.floor(Number(r.aircraftCount) || 1)),
                })));
                setSctFtds(data.filter((r: any) => r.requestType === 'ftd').map((r: any) => ({
                    id: r.id, name: r.name, event: r.event, eventCode: r.eventCode || '', flightType: r.flightType as 'Solo' | 'Dual',
                    currency: r.currency, currencyExpire: r.currencyExpire, priority: r.priority as 'High' | 'Medium' | 'Low',
                    notes: r.notes, dateRequested: r.dateRequested, requestedTime: r.requestedTime,
                    dayNight: r.dayNight || undefined,
                    submitted: r.submitted, includeInBuild: r.includeInBuild,
                    aircraftConfigId: r.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id,
                    acceptableAircraftConfigs: normaliseSctAcceptableConfigs(r.acceptableAircraftConfigs),
                    crewMember: r.crewMember || '',
                    crewGroup: r.crewGroup || '',
                    crewGroupKey: r.crewGroupKey || '',
                    crewUnitCode: r.crewUnitCode || '',
                    crewDisplayLabel: r.crewDisplayLabel || '',
                    crewIndividual: r.crewIndividual || '',
                    aircraftCount: Math.max(1, Math.floor(Number(r.aircraftCount) || 1)),
                })));
            } catch (err) {
                console.error('[CONTINUATION] Failed to load continuation requests from DB:', err);
            }
        };
        loadSctRequests();
    }, [sessionUser?.userId]);

    // ─── Aircraft Availability Event-Based Tracking ──────────────────────────────
    // Helper: format decimal hour (e.g. 8.5) to "0830"
    const formatWindowTime = (decimalHour: number): string => {
        const h = Math.floor(decimalHour);
        const m = Math.round((decimalHour - h) * 60);
        return `${h.toString().padStart(2, '0')}${m.toString().padStart(2, '0')}`;
    };

    // Helper: get the correct API base URL for cross-origin deployments
    const getApiBaseUrl = (): string => getAppApiBase();

    const logAvailabilityDebug = (...args: any[]) => {
        try {
            if (typeof window !== 'undefined' && window.localStorage?.getItem('dfp_availability_debug') === 'true') {
                console.log(...args);
            }
        } catch {
            // Debug logging must never affect availability tracking.
        }
    };

    // Helper: post an aircraft availability event to the database
    const postAvailabilityEvent = async (
        availableCount: number,
        changeType: 'startup' | 'reset' | 'change' | 'window_start' | 'window_end' | 'shutdown',
        totalAircraftOverride?: number,
        notesOverride?: string,
        timestampOverride?: Date
    ): Promise<{ success: boolean; data?: any; error?: string }> => {
        const requestId = `post_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
        logAvailabilityDebug(`\n${'='.repeat(60)}`);
        logAvailabilityDebug(`[AV] postAvailabilityEvent START ${requestId}`);

        const apiBase = getApiBaseUrl();
        const totalAircraftCount = totalAircraftOverride ?? availableAircraftCount;
        const windowStart = formatWindowTime(flyingStartTime);
        const windowEnd   = formatWindowTime(flyingEndTime);
        const today = new Date();
        const dateStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
        const ts = timestampOverride ?? new Date();

        logAvailabilityDebug(`[AV] Event details:`, {
            requestId,
            type: changeType,
            date: dateStr,
            available: `${availableCount}/${totalAircraftCount}`,
            window: `${windowStart}-${windowEnd}`,
            timestamp: ts.toISOString(),
            sessionUser: sessionUser?.userId ?? 'not logged in',
            apiBase
        });

        const requestBody = {
            timestamp: ts.toISOString(),
            date: dateStr,
            availableCount,
            totalAircraft: totalAircraftCount,
            changeType,
            recordedBy: sessionUser?.userId ?? null,
            locationCode: school,
            unitCode: activeUnitCode,
            notes: notesOverride ?? null,
            flyingWindowStart: windowStart,
            flyingWindowEnd:   windowEnd,
            // Send explicit timezone offset (hours) — more reliable than inferring from local clock
            clientTimezoneOffsetHours: timezoneOffset,
        };

        logAvailabilityDebug(`[AV] Request body:`, JSON.stringify(requestBody, null, 2));
        logAvailabilityDebug(`[AV] API URL: ${apiBase}/aircraft-availability-events`);

        try {
            logAvailabilityDebug(`[AV] Starting fetch...`);
            const fetchStart = Date.now();

            const res = await fetch(`${apiBase}/aircraft-availability-events`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(requestBody)
            });

            const fetchDuration = Date.now() - fetchStart;
            logAvailabilityDebug(`[AV] Fetch completed in ${fetchDuration}ms`);
            logAvailabilityDebug(`[AV] Response status: ${res.status} ${res.statusText}`);
            logAvailabilityDebug(`[AV] Response headers:`, Object.fromEntries(res.headers.entries()));

            if (res.ok) {
                const data = await res.json();
                logAvailabilityDebug(`[AV] Response data:`, data);
                if (data.skipped) {
                    logAvailabilityDebug(`[AV] Event skipped: ${data.reason}`);
                } else {
                    logAvailabilityDebug(`[AV] Event recorded successfully!`);
                }
                logAvailabilityDebug(`${'='.repeat(60)}\n`);
                return { success: true, data };
            } else {
                const errText = await res.text();
                console.error(`[AV] ❌ Request failed: ${res.status} ${errText}`);
                logAvailabilityDebug(`${'='.repeat(60)}\n`);
                return { success: false, error: `${res.status}: ${errText}` };
            }
        } catch (err) {
            console.error(`[AV] ❌ Exception during fetch:`, err);
            console.error(`[AV] ❌ Error type:`, (err as Error)?.constructor?.name);
            console.error(`[AV] ❌ Error message:`, (err as Error)?.message);
            console.error(`[AV] ❌ Error stack:`, (err as Error)?.stack);
            logAvailabilityDebug(`${'='.repeat(60)}\n`);
            return { success: false, error: String(err) };
        }
    };

    // 🧪 Global debug helper - call from browser console
    // Usage: window.testAvailabilityAPI() or window.debugAvailability()
    useEffect(() => {
        (window as any).testAvailabilityAPI = async () => {
            console.log('\n🧪 TESTING AVAILABILITY API FROM CONSOLE');
            console.log('🧪 Current origin:', window.location.origin);
            console.log('🧪 API Base URL:', getApiBaseUrl());
            const result = await postAvailabilityEvent(99, 'debug_test', undefined, 'Console test');
            console.log('🧪 Test result:', result);
            return result;
        };

        (window as any).debugAvailabilityDB = async () => {
            console.log('\n🧪 DEBUGGING AVAILABILITY DATABASE');
            const apiBase = getApiBaseUrl();
            const url = `${apiBase}/aircraft-availability-debug`;
            console.log('🧪 API URL:', url);
            console.log('🧪 Current origin:', window.location.origin);
            try {
                const res = await fetch(url, {
                    method: 'GET',
                    credentials: 'include',
                    headers: { 'Content-Type': 'application/json' }
                });
                console.log('🧪 Response status:', res.status, res.statusText);
                console.log('🧪 Response headers:', Object.fromEntries(res.headers.entries()));

                const text = await res.text();
                console.log('🧪 Response text (first 500 chars):', text.substring(0, 500));

                let data;
                try {
                    data = JSON.parse(text);
                } catch (parseErr) {
                    console.error('🧪 JSON parse failed - response is not JSON!');
                    console.error('🧪 Full response text:', text);
                    return {
                        error: 'Response is not JSON',
                        status: res.status,
                        statusText: res.statusText,
                        responseText: text.substring(0, 2000),
                        parseError: String(parseErr),
                        url: url
                    };
                }

                console.log('🧪 Debug result:', data);
                return data;
            } catch (e) {
                console.error('🧪 Debug failed:', e);
                return { error: String(e), url };
            }
        };

        (window as any).forceInsertAvailability = async (count: number = 15) => {
            console.log('\n🧪 FORCE INSERTING AVAILABILITY RECORD');
            const apiBase = getApiBaseUrl();
            const url = `${apiBase}/aircraft-availability-debug`;
            console.log('🧪 API URL:', url);
            try {
                const res = await fetch(url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify({ availableCount: count })
                });
                const text = await res.text();
                console.log('🧪 Response text:', text.substring(0, 500));
                let data;
                try {
                    data = JSON.parse(text);
                } catch (parseErr) {
                    return { error: 'Not JSON', responseText: text.substring(0, 2000), url };
                }
                console.log('🧪 Force insert result:', data);
                return data;
            } catch (e) {
                console.error('🧪 Force insert failed:', e);
                return { error: String(e), url };
            }
        };

        logAvailabilityDebug('[AV] Debug helpers available: window.testAvailabilityAPI(), window.debugAvailabilityDB(), window.forceInsertAvailability(count)');
    }, [sessionUser?.userId, availableAircraftCount, flyingStartTime, flyingEndTime]);

    // Track whether we've loaded the persisted availability
    const [hasLoadedPersistedAvailability, setHasLoadedPersistedAvailability] = useState(false);
    // Ref to hold the loaded availability value immediately (avoids async state issue)
    const loadedAvailabilityRef = useRef<number | null>(null);
    // Track whether the events table has provided a value (prevents settings from overriding it)
    const availabilityLoadedFromEventsRef = useRef<boolean>(false);

    // Fetch current availability from database on startup
    // This ensures the availability persists across app restarts/hard refreshes
    // Depends on settingsLoaded so it always overrides any stale value from loadSettings
    useEffect(() => {
        if (!sessionUser?.userId) return;
        // Wait until settings have been loaded so we always override with the events-table value
        if (!settingsLoaded) return;
        if (!school || !activeUnitCode) return;

        const fetchCurrentAvailability = async () => {
            try {
                const apiBase = getApiBaseUrl();
                const params = new URLSearchParams({
                    locationCode: school,
                    unitCode: activeUnitCode,
                });
                const res = await fetch(`${apiBase}/aircraft-availability-current?${params.toString()}`, {
                    credentials: 'include'
                });

                if (res.ok) {
                    const data = await res.json();
                    if (data.success && data.availableCount !== undefined) {
                        // Always use the persisted value for the active location/unit if it exists
                        // (even from previous days) so availability survives restarts without leaking
                        // changes between units.
                        if (!data.isDefault) {
                            logAvailabilityDebug(`[AV] Restored availability from database for ${school} - ${activeUnitCode}: ${data.availableCount} aircraft (from ${data.date || 'unknown date'})`);
                            setAvailableAircraftCount(data.availableCount);
                            // Store in ref for immediate use in startup
                            loadedAvailabilityRef.current = data.availableCount;
                            availabilityLoadedFromEventsRef.current = true;
                        } else {
                            logAvailabilityDebug(`[AV] No saved availability found, using default: 15`);
                            setAvailableAircraftCount(data.availableCount ?? 15);
                            loadedAvailabilityRef.current = 15; // Explicit default
                            availabilityLoadedFromEventsRef.current = false;
                        }
                    }
                }
            } catch (err) {
                console.error('[AV] ❌ Failed to fetch current availability:', err);
            } finally {
                // Mark that we've attempted to load persisted availability
                setHasLoadedPersistedAvailability(true);
            }
        };

        fetchCurrentAvailability();
    }, [sessionUser?.userId, settingsLoaded, school, activeUnitCode]);

    // Startup: fire once when user logs in AND after persisted availability is loaded
    // - Posts a "startup" event with current availability
    // - Runs recovery: checks if today's summary is missing and triggers recalculation
    useEffect(() => {
        if (!sessionUser?.userId || !hasLoadedPersistedAvailability) return;

        const runStartup = async () => {
            logAvailabilityDebug('[AV] Startup: recording initial availability state');

            // 1. Fire startup event (1s delay to allow state to settle)
            await new Promise(resolve => setTimeout(resolve, 1000));

            // Use the ref value if available (avoids async state issue), otherwise fall back to state
            const availabilityToRecord = loadedAvailabilityRef.current ?? availableAircraftCount;
            logAvailabilityDebug(`[AV] Startup: using availability ${availabilityToRecord} (ref: ${loadedAvailabilityRef.current}, state: ${availableAircraftCount})`);

            await postAvailabilityEvent(
                availabilityToRecord,
                'startup',
                undefined,
                `App startup - initial availability: ${availabilityToRecord}`
            );

            // 2. Recovery: check if today's summary exists, rebuild from events if missing
            const today = new Date();
            const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
            const windowStart = formatWindowTime(flyingStartTime);
            const windowEnd   = formatWindowTime(flyingEndTime);

            logAvailabilityDebug(`[AV] Running recovery check for ${todayStr}`);
            try {
                const apiBase = getApiBaseUrl();
                const recovRes = await fetch(`${apiBase}/aircraft-availability-recalculate`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify({
                        date: todayStr,
                        flyingWindowStart: windowStart,
                        flyingWindowEnd:   windowEnd,
                        locationCode: school,
                        unitCode: activeUnitCode,
                        clientTimezoneOffsetHours: timezoneOffset,
                    })
                });
                if (recovRes.ok) {
                    const recovData = await recovRes.json();
                    if (recovData.skipped) {
                        logAvailabilityDebug(`[AV] Recovery: summary for ${todayStr} is recent, no rebuild needed`);
                    } else {
                        logAvailabilityDebug(`[AV] Recovery: rebuilt daily summary for ${todayStr}`, recovData.record);
                    }
                }
            } catch (err) {
                console.error('[AV] Recovery check failed:', err);
            }
        };

        runStartup();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [sessionUser?.userId]);

    // Flying-window boundary events: fire when time crosses window start/end
    useEffect(() => {
        if (!sessionUser?.userId) return;

        const checkWindowBoundaries = () => {
            const now = new Date();
            const currentMinutes = now.getHours() * 60 + now.getMinutes();
            const windowStartMin = Math.floor(flyingStartTime) * 60 + Math.round((flyingStartTime % 1) * 60);
            const windowEndMin   = Math.floor(flyingEndTime) * 60 + Math.round((flyingEndTime % 1) * 60);

            // Fire window_start event at exact flying window start (within 1-min window)
            if (currentMinutes >= windowStartMin && currentMinutes < windowStartMin + 1) {
                logAvailabilityDebug(`[AV] Flying window START reached (${formatWindowTime(flyingStartTime)})`);
                postAvailabilityEvent(
                    availableAircraftCount,
                    'window_start',
                    undefined,
                    `Flying window start: ${formatWindowTime(flyingStartTime)}`
                );
            }
            // Fire window_end event at exact flying window end (within 1-min window)
            if (currentMinutes >= windowEndMin && currentMinutes < windowEndMin + 1) {
                logAvailabilityDebug(`[AV] Flying window END reached (${formatWindowTime(flyingEndTime)})`);
                postAvailabilityEvent(
                    availableAircraftCount,
                    'window_end',
                    undefined,
                    `Flying window end: ${formatWindowTime(flyingEndTime)}`
                );
            }
        };

        // Check every minute
        const interval = setInterval(checkWindowBoundaries, 60 * 1000);
        return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [sessionUser?.userId, flyingStartTime, flyingEndTime, availableAircraftCount]);

