    const shouldInsertTrainingReportExtraEvent = (assessment: Pt051Assessment): boolean => (
        (assessment.dcoResult === 'DPCO' && assessment.dpcoFollowUp?.action === 'extra-event') ||
        (assessment.dcoResult === 'DNCO' && assessment.dncoFollowUp?.requestExtraFlight === true)
    );

    const shouldExtendTrainingReportNextEvent = (assessment: Pt051Assessment): boolean => (
        assessment.dcoResult === 'DPCO' &&
        assessment.dpcoFollowUp?.action === 'extra-hours-next-event' &&
        Number(assessment.dpcoFollowUp?.extraHours) > 0
    );

    const shouldPassTrainingReportNotesToNextEvent = (assessment: Pt051Assessment): boolean => (
        assessment.passNotesToNextEvent === true &&
        String(assessment.trainingReportNotes || '').trim().length > 0
    );

    const getNextTrainingReportExtraEventCode = (sourceCode: string, existingCodes: Set<string>): string => {
        const cleanedSourceCode = String(sourceCode || '').trim();
        if (!cleanedSourceCode) return '';

        const buildCandidate = (code: string): string => {
            const suffixMatch = code.match(/^(.*?)(?:X(\d+))$/i);
            if (!suffixMatch) return `${code}X2`;

            const baseCode = suffixMatch[1] || code.replace(/X\d+$/i, '');
            const currentNumber = Number(suffixMatch[2]);
            const nextNumber = Number.isFinite(currentNumber)
                ? (currentNumber <= 3 ? 4 : currentNumber + 1)
                : 2;
            return `${baseCode}X${nextNumber}`;
        };

        let candidate = buildCandidate(cleanedSourceCode);
        while (candidate && existingCodes.has(candidate.toUpperCase())) {
            candidate = buildCandidate(candidate);
        }
        return candidate;
    };

    const findTrainingReportSourceLmpItem = (
        lmp: SyllabusItemDetail[],
        trainee: Trainee,
        assessment: Pt051Assessment
    ): { item: SyllabusItemDetail; index: number } | null => {
        const eventRefs = new Set([
            assessment.eventId,
            assessment.flightNumber,
        ].filter(Boolean).map(value => String(value).trim()));
        const generatedEventId = (item: SyllabusItemDetail): string =>
            `lmp-${(trainee as any).id || trainee.idNumber}-${item.code}`;

        const sourceIndex = lmp.findIndex(item => {
            const itemRefs = [
                item.id,
                item.code,
                item.masterEventId,
                item.eventDescription,
                generatedEventId(item),
            ].filter(Boolean).map(value => String(value).trim());
            return itemRefs.some(ref => eventRefs.has(ref));
        });

        return sourceIndex === -1 ? null : { item: lmp[sourceIndex], index: sourceIndex };
    };

    const maybeInsertTrainingReportExtraLmpEvent = async (assessment: Pt051Assessment): Promise<void> => {
        pushDfpDataDiag('report-lmp:extra-event:evaluate', {
            assessmentId: assessment.id,
            eventId: assessment.eventId,
            flightNumber: assessment.flightNumber,
            traineeFullName: assessment.traineeFullName,
            dcoResult: assessment.dcoResult,
            dpcoFollowUp: assessment.dpcoFollowUp || null,
            dncoFollowUp: assessment.dncoFollowUp || null,
            shouldInsert: shouldInsertTrainingReportExtraEvent(assessment),
        });
        if (!shouldInsertTrainingReportExtraEvent(assessment)) return;

        const trainee = allTraineesData.find(candidate => candidate.fullName === assessment.traineeFullName);
        if (!trainee) {
            pushDfpDataDiag('report-lmp:extra-event:no-trainee', {
                assessmentId: assessment.id,
                traineeFullName: assessment.traineeFullName,
            });
            console.warn('[Training Report] Could not insert extra event: trainee not found', assessment.traineeFullName);
            return;
        }

        const persistedLmp = await loadPersistedTraineeLmp(trainee);
        const stateLmp = traineeLMPs.get(trainee.fullName);
        const originalLmp = persistedLmp || stateLmp;
        pushDfpDataDiag('report-lmp:extra-event:original-lmp', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            source: persistedLmp ? 'persisted-first' : stateLmp ? 'state-fallback' : 'missing',
            persistedCount: Array.isArray(persistedLmp) ? persistedLmp.length : 0,
            stateCount: Array.isArray(stateLmp) ? stateLmp.length : 0,
            ...summariseTrainingReportLmpItems(originalLmp),
        });
        if (!originalLmp || originalLmp.length === 0) {
            console.warn('[Training Report] Could not insert extra event: Individual LMP not found', assessment.traineeFullName);
            return;
        }

        const existingFollowUp = originalLmp.find(item =>
            (item as any).trainingReportSourceAssessmentId === assessment.id ||
            (item as any).trainingReportSourceEventId === assessment.eventId
        );
        if (existingFollowUp) {
            pushDfpDataDiag('report-lmp:extra-event:already-exists', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                existingId: existingFollowUp.id,
                existingCode: existingFollowUp.code,
            });
            return;
        }

        const sourceMatch = findTrainingReportSourceLmpItem(originalLmp, trainee, assessment);
        if (!sourceMatch) {
            pushDfpDataDiag('report-lmp:extra-event:no-source-match', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
                sample: originalLmp.slice(0, 20).map(item => ({
                    id: item.id,
                    code: item.code,
                    masterEventId: item.masterEventId,
                    eventDescription: item.eventDescription,
                })),
            });
            console.warn('[Training Report] Could not insert extra event: assessed event not found in Individual LMP', {
                trainee: assessment.traineeFullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
            });
            return;
        }

        const { item: sourceItem, index: sourceIndex } = sourceMatch;
        if (sourceItem.type !== 'Flight' && sourceItem.type !== 'FTD') {
            pushDfpDataDiag('report-lmp:extra-event:wrong-source-type', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                sourceType: sourceItem.type,
            });
            console.warn('[Training Report] Extra follow-up was selected for a non-flight/sim event; no LMP event inserted', {
                trainee: assessment.traineeFullName,
                event: sourceItem.code,
                type: sourceItem.type,
            });
            return;
        }

        const existingCodes = new Set(originalLmp.map(item => String(item.code || item.id || '').trim().toUpperCase()).filter(Boolean));
        const extraEventCode = getNextTrainingReportExtraEventCode(sourceItem.code || assessment.flightNumber, existingCodes);
        if (!extraEventCode) return;

        const nextMasterItem = originalLmp.slice(sourceIndex + 1).find(item => !isLmpOverlayItem(item));
        const requestedHours = assessment.dcoResult === 'DPCO'
            ? Number(assessment.dpcoFollowUp?.extraEventHours)
            : NaN;
        const eventHours = Number.isFinite(requestedHours) && requestedHours > 0
            ? requestedHours
            : Number(sourceItem.flightOrSimHours || sourceItem.duration || sourceItem.totalEventHours || 1);
        const preFlightTime = Number(sourceItem.preFlightTime || 0);
        const postFlightTime = Number(sourceItem.postFlightTime || 0);
        const anchorAfterMasterEventId = getMasterEventId(sourceItem);
        const anchorBeforeMasterEventId = nextMasterItem ? getMasterEventId(nextMasterItem) : undefined;
        const completedSafeSourceItem = sourceItem as SyllabusItemDetail & { isComplete?: boolean; completed?: boolean };
        const { completedAt: _completedAt, isComplete: _isComplete, completed: _completed, ...sourceTemplate } = completedSafeSourceItem;

        const extraEvent: SyllabusItemDetail = {
            ...sourceTemplate,
            id: `training-report-extra-${assessment.id || assessment.eventId}-${extraEventCode}`,
            code: extraEventCode,
            eventDescription: extraEventCode,
            completedAt: null,
            isRemedial: true,
            lmpSource: 'remedial',
            masterEventId: undefined,
            prerequisites: [sourceItem.id || sourceItem.code].filter(Boolean),
            prerequisitesGround: [],
            prerequisitesFlying: [],
            flightOrSimHours: eventHours,
            duration: eventHours,
            totalEventHours: eventHours + preFlightTime + postFlightTime,
            module: sourceItem.module || 'Training Report Follow-up',
            orderKey: `${createLmpOrderKey(sourceIndex)}.${String(Date.now()).slice(-6)}`,
            anchorAfterMasterEventId,
            anchorBeforeMasterEventId,
            anchorPolicy: 'between',
            userLockedPosition: true,
            placementNeedsReview: !anchorAfterMasterEventId && !anchorBeforeMasterEventId,
            location: sourceItem.location || school,
            courses: sourceItem.courses || (trainee.course ? [trainee.course] : []),
            lmpType: sourceItem.lmpType || getLmpTypeForTrainee(trainee),
            trainingReportSourceAssessmentId: assessment.id,
            trainingReportSourceEventId: assessment.eventId,
            trainingReportSourceResult: assessment.dcoResult,
        } as SyllabusItemDetail & Record<string, any>;

        const updatedLmp = [
            ...originalLmp.slice(0, sourceIndex + 1),
            extraEvent,
            ...originalLmp.slice(sourceIndex + 1),
        ];
        pushDfpDataDiag('report-lmp:extra-event:prepared', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            sourceCode: sourceItem.code,
            sourceIndex,
            extraEventCode,
            anchorAfterMasterEventId,
            anchorBeforeMasterEventId,
            eventHours,
            beforeCount: originalLmp.length,
            afterCount: updatedLmp.length,
            inserted: {
                id: extraEvent.id,
                code: extraEvent.code,
                lmpSource: (extraEvent as any).lmpSource,
                isRemedial: (extraEvent as any).isRemedial,
                trainingReportSourceAssessmentId: (extraEvent as any).trainingReportSourceAssessmentId,
                trainingReportSourceEventId: (extraEvent as any).trainingReportSourceEventId,
            },
        });

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            pushDfpDataDiag('report-lmp:extra-event:persisted', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                extraEventCode,
                ...summariseTrainingReportLmpItems(persistedLmp),
            });
            setTraineeLMPs(prev => {
                const updated = new Map(prev);
                updated.set(trainee.fullName, persistedLmp);
                return updated;
            });
            logAudit(
                'Individual LMP',
                'Insert',
                `Inserted ${extraEventCode} from ${assessment.dcoResult} training report for ${trainee.fullName}`,
                [
                    `Source event: ${sourceItem.code}`,
                    `Inserted event: ${extraEventCode}`,
                    `Type: ${sourceItem.type}`,
                    `Hours: ${eventHours}`,
                    `Training report: ${assessment.id || assessment.eventId}`,
                ].join('; ')
            );
            setSuccessMessage(`${extraEventCode} inserted into ${trainee.fullName}'s Individual LMP.`);
        } catch (error) {
            pushDfpDataDiag('report-lmp:extra-event:error', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                extraEventCode,
                error: error instanceof Error ? error.message : String(error),
            });
            console.error('[Training Report] Failed to persist extra event from training report:', error);
            void showDarkAlert(
                `The training report was saved, but the extra ${sourceItem.type === 'FTD' ? 'sim' : 'flight'} could not be inserted into the trainee Individual LMP.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Extra Event Insert Failed',
                'error'
            );
        }
    };

    const maybeExtendTrainingReportNextLmpEvent = async (assessment: Pt051Assessment): Promise<void> => {
        pushDfpDataDiag('report-lmp:extend-next:evaluate', {
            assessmentId: assessment.id,
            eventId: assessment.eventId,
            flightNumber: assessment.flightNumber,
            traineeFullName: assessment.traineeFullName,
            dcoResult: assessment.dcoResult,
            dpcoFollowUp: assessment.dpcoFollowUp || null,
            shouldExtend: shouldExtendTrainingReportNextEvent(assessment),
        });
        if (!shouldExtendTrainingReportNextEvent(assessment)) return;

        const trainee = allTraineesData.find(candidate => candidate.fullName === assessment.traineeFullName);
        if (!trainee) {
            pushDfpDataDiag('report-lmp:extend-next:no-trainee', {
                assessmentId: assessment.id,
                traineeFullName: assessment.traineeFullName,
            });
            console.warn('[Training Report] Could not extend next event: trainee not found', assessment.traineeFullName);
            return;
        }

        const persistedLmp = await loadPersistedTraineeLmp(trainee);
        const stateLmp = traineeLMPs.get(trainee.fullName);
        const originalLmp = persistedLmp || stateLmp;
        pushDfpDataDiag('report-lmp:extend-next:original-lmp', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            source: persistedLmp ? 'persisted-first' : stateLmp ? 'state-fallback' : 'missing',
            persistedCount: Array.isArray(persistedLmp) ? persistedLmp.length : 0,
            stateCount: Array.isArray(stateLmp) ? stateLmp.length : 0,
            ...summariseTrainingReportLmpItems(originalLmp),
        });
        if (!originalLmp || originalLmp.length === 0) {
            console.warn('[Training Report] Could not extend next event: Individual LMP not found', assessment.traineeFullName);
            return;
        }

        const sourceMatch = findTrainingReportSourceLmpItem(originalLmp, trainee, assessment);
        if (!sourceMatch) {
            pushDfpDataDiag('report-lmp:extend-next:no-source-match', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
                sample: originalLmp.slice(0, 20).map(item => ({
                    id: item.id,
                    code: item.code,
                    masterEventId: item.masterEventId,
                    eventDescription: item.eventDescription,
                })),
            });
            console.warn('[Training Report] Could not extend next event: assessed event not found in Individual LMP', {
                trainee: assessment.traineeFullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
            });
            return;
        }

        const { item: sourceItem, index: sourceIndex } = sourceMatch;
        if (sourceItem.type !== 'Flight' && sourceItem.type !== 'FTD') {
            pushDfpDataDiag('report-lmp:extend-next:wrong-source-type', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                sourceType: sourceItem.type,
            });
            console.warn('[Training Report] Extend next event was selected for a non-flight/sim event; no LMP event changed', {
                trainee: assessment.traineeFullName,
                event: sourceItem.code,
                type: sourceItem.type,
            });
            return;
        }

        const nextEventIndex = originalLmp.findIndex((item, index) =>
            index > sourceIndex &&
            item.type === sourceItem.type &&
            !item.completedAt
        );
        if (nextEventIndex === -1) {
            pushDfpDataDiag('report-lmp:extend-next:no-next-event', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                sourceIndex,
                sourceType: sourceItem.type,
            });
            console.warn('[Training Report] Could not extend next event: no matching next flight/sim found', {
                trainee: assessment.traineeFullName,
                event: sourceItem.code,
                type: sourceItem.type,
            });
            return;
        }

        const nextEvent = originalLmp[nextEventIndex] as SyllabusItemDetail & Record<string, any>;
        const extensionKey = assessment.id || assessment.eventId;
        const legacyExtensionKeys = [
            assessment.eventId,
            `${assessment.eventId}`,
            `${assessment.flightNumber}-${assessment.traineeFullName}`,
        ].map(value => String(value || '').trim()).filter(Boolean);
        const extensionLedger = {
            ...(nextEvent.trainingReportNextEventExtensions || {}),
        } as Record<string, number>;
        const previousAssessmentKey = String(nextEvent.trainingReportLastExtendedByAssessmentId || '').trim();
        const previousExtension = Number(
            extensionLedger[extensionKey] ||
            (previousAssessmentKey && previousAssessmentKey !== extensionKey ? extensionLedger[previousAssessmentKey] : 0) ||
            legacyExtensionKeys.map(key => Number(extensionLedger[key] || 0)).find(value => value > 0) ||
            0
        );
        const requestedExtension = Number(assessment.dpcoFollowUp?.extraHours || 0);
        const delta = requestedExtension - previousExtension;
        if (Math.abs(delta) < 0.0001) {
            pushDfpDataDiag('report-lmp:extend-next:no-delta', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                nextEventCode: nextEvent.code,
                requestedExtension,
                previousExtension,
            });
            return;
        }

        const existingFlightOrSimHours = Number(nextEvent.flightOrSimHours || nextEvent.duration || 0);
        const existingDuration = Number(nextEvent.duration || nextEvent.flightOrSimHours || 0);
        const existingTotalEventHours = Number(nextEvent.totalEventHours || existingDuration || existingFlightOrSimHours || 0);
        legacyExtensionKeys.forEach(key => {
            if (key !== extensionKey && Object.prototype.hasOwnProperty.call(extensionLedger, key)) {
                delete extensionLedger[key];
            }
        });
        if (previousAssessmentKey && previousAssessmentKey !== extensionKey && Object.prototype.hasOwnProperty.call(extensionLedger, previousAssessmentKey)) {
            delete extensionLedger[previousAssessmentKey];
        }
        extensionLedger[extensionKey] = requestedExtension;

        const updatedNextEvent: SyllabusItemDetail & Record<string, any> = {
            ...nextEvent,
            flightOrSimHours: Math.max(0, Number((existingFlightOrSimHours + delta).toFixed(2))),
            duration: Math.max(0, Number((existingDuration + delta).toFixed(2))),
            totalEventHours: Math.max(0, Number((existingTotalEventHours + delta).toFixed(2))),
            trainingReportNextEventExtensions: extensionLedger,
            trainingReportLastExtendedByAssessmentId: extensionKey,
        };

        const updatedLmp = originalLmp.map((item, index) => index === nextEventIndex ? updatedNextEvent : item);
        pushDfpDataDiag('report-lmp:extend-next:prepared', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            sourceCode: sourceItem.code,
            sourceIndex,
            nextEventCode: nextEvent.code,
            nextEventIndex,
            requestedExtension,
            previousExtension,
            delta,
            before: {
                flightOrSimHours: existingFlightOrSimHours,
                duration: existingDuration,
                totalEventHours: existingTotalEventHours,
            },
            after: {
                flightOrSimHours: updatedNextEvent.flightOrSimHours,
                duration: updatedNextEvent.duration,
                totalEventHours: updatedNextEvent.totalEventHours,
                trainingReportNextEventExtensions: updatedNextEvent.trainingReportNextEventExtensions,
                trainingReportLastExtendedByAssessmentId: updatedNextEvent.trainingReportLastExtendedByAssessmentId,
            },
        });

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            pushDfpDataDiag('report-lmp:extend-next:persisted', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                nextEventCode: nextEvent.code,
                ...summariseTrainingReportLmpItems(persistedLmp),
            });
            setTraineeLMPs(prev => {
                const updated = new Map(prev);
                updated.set(trainee.fullName, persistedLmp);
                return updated;
            });
            logAudit(
                'Individual LMP',
                'Edit',
                `Extended ${nextEvent.code} from DPCO training report for ${trainee.fullName}`,
                [
                    `Source event: ${sourceItem.code}`,
                    `Extended event: ${nextEvent.code}`,
                    `Added hours: ${requestedExtension}`,
                    `Previous applied hours: ${previousExtension}`,
                    `Training report: ${extensionKey}`,
                ].join('; ')
            );
            setSuccessMessage(`${nextEvent.code} extended by ${requestedExtension.toFixed(1)} hrs in ${trainee.fullName}'s Individual LMP.`);
        } catch (error) {
            pushDfpDataDiag('report-lmp:extend-next:error', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                nextEventCode: nextEvent.code,
                error: error instanceof Error ? error.message : String(error),
            });
            console.error('[Training Report] Failed to persist next event extension from training report:', error);
            void showDarkAlert(
                `The training report was saved, but the next ${sourceItem.type === 'FTD' ? 'sim' : 'flight'} could not be extended in the trainee Individual LMP.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Next Event Extension Failed',
                'error'
            );
        }
    };

    const maybePassTrainingReportNotesToNextLmpEvent = async (assessment: Pt051Assessment): Promise<void> => {
        pushDfpDataDiag('report-notes:forward:evaluate', {
            assessmentId: assessment.id,
            eventId: assessment.eventId,
            flightNumber: assessment.flightNumber,
            traineeFullName: assessment.traineeFullName,
            dcoResult: assessment.dcoResult,
            dpcoFollowUp: assessment.dpcoFollowUp || null,
            dncoFollowUp: assessment.dncoFollowUp || null,
            passNotesToNextEvent: assessment.passNotesToNextEvent === true,
            trainingReportNotesLength: String(assessment.trainingReportNotes || '').trim().length,
            trainingReportNotesPreview: String(assessment.trainingReportNotes || '').trim().slice(0, 160),
            shouldPass: shouldPassTrainingReportNotesToNextEvent(assessment),
        });
        if (!shouldPassTrainingReportNotesToNextEvent(assessment)) return;

        const trainee = allTraineesData.find(candidate => candidate.fullName === assessment.traineeFullName);
        if (!trainee) {
            pushDfpDataDiag('report-notes:forward:no-trainee', {
                assessmentId: assessment.id,
                traineeFullName: assessment.traineeFullName,
            });
            console.warn('[Training Report] Could not pass notes forward: trainee not found', assessment.traineeFullName);
            return;
        }

        const originalLmp = await loadPersistedTraineeLmp(trainee) || traineeLMPs.get(trainee.fullName);
        pushDfpDataDiag('report-notes:forward:original-lmp', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            source: 'persisted-first',
            ...summariseTrainingReportLmpItems(originalLmp),
        });
        if (!originalLmp || originalLmp.length === 0) {
            pushDfpDataDiag('report-notes:forward:no-lmp', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
            });
            console.warn('[Training Report] Could not pass notes forward: Individual LMP not found', assessment.traineeFullName);
            return;
        }

        const sourceMatch = findTrainingReportSourceLmpItem(originalLmp, trainee, assessment);
        if (!sourceMatch) {
            pushDfpDataDiag('report-notes:forward:no-source-match', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
                sample: originalLmp.slice(0, 20).map(item => ({
                    id: item.id,
                    code: item.code,
                    type: item.type,
                    masterEventId: item.masterEventId,
                    forwardedKeys: Object.keys(((item as any).trainingReportForwardedNotes || {}) as Record<string, any>),
                })),
            });
            console.warn('[Training Report] Could not pass notes forward: assessed event not found in Individual LMP', {
                trainee: assessment.traineeFullName,
                eventId: assessment.eventId,
                flightNumber: assessment.flightNumber,
            });
            return;
        }

        const { item: sourceItem, index: sourceIndex } = sourceMatch;
        if (sourceItem.type !== 'Flight' && sourceItem.type !== 'FTD') {
            pushDfpDataDiag('report-notes:forward:wrong-source-type', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                sourceType: sourceItem.type,
            });
            return;
        }

        const assessmentKey = assessment.id || assessment.eventId;
        const insertedFollowUpIndex = originalLmp.findIndex(item => (
            (item as any).trainingReportSourceAssessmentId === assessmentKey ||
            (item as any).trainingReportSourceEventId === assessment.eventId
        ));
        const nextEventIndex = insertedFollowUpIndex >= 0
            ? insertedFollowUpIndex
            : originalLmp.findIndex((item, index) =>
                index > sourceIndex &&
                item.type === sourceItem.type &&
                !item.completedAt
            );
        pushDfpDataDiag('report-notes:forward:target-selection', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            sourceCode: sourceItem.code,
            sourceType: sourceItem.type,
            sourceIndex,
            insertedFollowUpIndex,
            nextEventIndex,
            nextEventCode: nextEventIndex >= 0 ? originalLmp[nextEventIndex]?.code : null,
            nextEventType: nextEventIndex >= 0 ? originalLmp[nextEventIndex]?.type : null,
            candidateWindow: originalLmp.slice(Math.max(0, sourceIndex), Math.min(originalLmp.length, sourceIndex + 8)).map((item, index) => ({
                relativeIndex: index,
                absoluteIndex: Math.max(0, sourceIndex) + index,
                id: item.id,
                code: item.code,
                type: item.type,
                completedAt: (item as any).completedAt || null,
                extensionKeys: Object.keys(((item as any).trainingReportNextEventExtensions || {}) as Record<string, any>),
                forwardedKeys: Object.keys(((item as any).trainingReportForwardedNotes || {}) as Record<string, any>),
            })),
        });

        if (nextEventIndex === -1) {
            pushDfpDataDiag('report-notes:forward:no-target', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                sourceCode: sourceItem.code,
                sourceType: sourceItem.type,
            });
            console.warn('[Training Report] Could not pass notes forward: no matching next flight/sim found', {
                trainee: assessment.traineeFullName,
                event: sourceItem.code,
                type: sourceItem.type,
            });
            return;
        }

        const targetEvent = originalLmp[nextEventIndex] as SyllabusItemDetail & Record<string, any>;
        const baseNotes = typeof targetEvent.trainingReportBaseNotes === 'string'
            ? targetEvent.trainingReportBaseNotes
            : String(targetEvent.notes || '');
        const nextNotes = stripGeneratedTrainingReportFollowUpLines(assessment.trainingReportNotes);
        const forwardedNotes = {
            ...(targetEvent.trainingReportForwardedNotes || {}),
        } as Record<string, { sourceCode?: string; notes?: string }>;
        const sourceCodeForNotes = String(sourceItem.code || assessment.flightNumber || '').trim();
        let removedStaleForwardedNotes = false;
        Object.entries(forwardedNotes).forEach(([key, entry]) => {
            const entrySourceCode = String(entry?.sourceCode || '').trim();
            if (key !== assessmentKey && sourceCodeForNotes && entrySourceCode === sourceCodeForNotes) {
                delete forwardedNotes[key];
                removedStaleForwardedNotes = true;
            }
        });
        if (!nextNotes) {
            if (Object.prototype.hasOwnProperty.call(forwardedNotes, assessmentKey)) {
                delete forwardedNotes[assessmentKey];
                removedStaleForwardedNotes = true;
            }
            if (!removedStaleForwardedNotes) {
                pushDfpDataDiag('report-notes:forward:no-free-text-after-clean', {
                    assessmentId: assessment.id,
                    traineeFullName: trainee.fullName,
                    sourceCode: sourceItem.code,
                    targetCode: targetEvent.code,
                });
                return;
            }
        } else {
            forwardedNotes[assessmentKey] = {
                sourceCode: sourceCodeForNotes,
                notes: nextNotes,
            };
        }
        const updatedTargetEvent: SyllabusItemDetail & Record<string, any> = {
            ...targetEvent,
            trainingReportBaseNotes: baseNotes,
            trainingReportForwardedNotes: Object.keys(forwardedNotes).length > 0 ? forwardedNotes : undefined,
            trainingReportLastForwardedNotesAssessmentId: assessmentKey,
            notes: baseNotes,
        };
        const updatedLmp = originalLmp.map((item, index) => index === nextEventIndex ? updatedTargetEvent : item);
        pushDfpDataDiag('report-notes:forward:prepared', {
            assessmentId: assessment.id,
            traineeFullName: trainee.fullName,
            sourceCode: sourceItem.code,
            targetCode: targetEvent.code,
            targetType: targetEvent.type,
            assessmentKey,
            baseNotesLength: baseNotes.length,
            forwardedKeysBefore: Object.keys((targetEvent.trainingReportForwardedNotes || {}) as Record<string, any>),
            forwardedKeysAfter: Object.keys(forwardedNotes),
            forwardedNoteLength: nextNotes.length,
            extensionKeysOnTarget: Object.keys((targetEvent.trainingReportNextEventExtensions || {}) as Record<string, any>),
            targetHours: {
                flightOrSimHours: targetEvent.flightOrSimHours,
                duration: targetEvent.duration,
                totalEventHours: targetEvent.totalEventHours,
            },
        });

        try {
            const persistedLmp = await persistTraineeLmp(trainee, updatedLmp);
            const persistedTarget = Array.isArray(persistedLmp)
                ? persistedLmp.find(item => (
                    String(item.id || '') === String(updatedTargetEvent.id || '') ||
                    String(item.code || '').trim().toUpperCase() === String(updatedTargetEvent.code || '').trim().toUpperCase()
                )) as (SyllabusItemDetail & Record<string, any>) | undefined
                : undefined;
            setTraineeLMPs(prev => {
                const updated = new Map(prev);
                updated.set(trainee.fullName, persistedLmp);
                return updated;
            });
            pushDfpDataDiag('report-notes:forward:persisted', {
                assessmentId: assessment.id,
                traineeFullName: trainee.fullName,
                targetCode: targetEvent.code,
                persistedTargetCode: persistedTarget?.code || null,
                persistedForwardedKeys: Object.keys((persistedTarget?.trainingReportForwardedNotes || {}) as Record<string, any>),
                persistedForwardedNoteLength: getForwardedNotesFromLmpItem(persistedTarget).length,
                persistedExtensionKeys: Object.keys((persistedTarget?.trainingReportNextEventExtensions || {}) as Record<string, any>),
                persistedTargetHours: persistedTarget ? {
                    flightOrSimHours: persistedTarget.flightOrSimHours,
                    duration: persistedTarget.duration,
                    totalEventHours: persistedTarget.totalEventHours,
                } : null,
            });
            logAudit(
                'Individual LMP',
                'Edit',
                `Passed training report notes from ${sourceItem.code || assessment.flightNumber} to ${targetEvent.code || 'next event'} for ${trainee.fullName}`,
                `Training report: ${assessmentKey}`
            );
        } catch (error) {
            console.error('[Training Report] Failed to pass notes to next LMP event:', error);
            void showDarkAlert(
                `The training report was saved, but the notes could not be passed to the next ${sourceItem.type === 'FTD' ? 'sim' : 'flight'} event.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Forward Notes Failed',
                'error'
            );
        }
    };

    const onSavePT051Assessment = async (assessment: Pt051Assessment) => {
        // Use traineeFullName for the key to ensure consistency across the app
        const saveKey = `pt051-${assessment.eventId}-${assessment.traineeFullName}`;
        const updatedAssessments = new Map(pt051Assessments).set(saveKey, assessment);
        setPt051Assessments(updatedAssessments);
        void persistPt051AssessmentsForDate(assessment.date || date, updatedAssessments);

        // Log to audit trail
        const changes = [
            assessment.overallGrade ? `Overall Grade: ${assessment.overallGrade}` : null,
            assessment.overallResult ? `Overall Result: ${assessment.overallResult}` : null,
            assessment.dcoResult ? `${configuredTrainingReportStatusFieldLabel}: ${getConfiguredMissionStatusLabel(assessment.dcoResult)}` : null,
            assessment.overallComments ? `Comments: ${assessment.overallComments.substring(0, 50)}...` : null
        ].filter(Boolean).join(', ');

        logAudit('Mass Completion', 'Edit', `Updated ${configuredTrainingReportDisplayName} for ${assessment.traineeFullName} - Event: ${assessment.flightNumber} (${assessment.date})`, changes);
        await maybeInsertTrainingReportExtraLmpEvent(assessment);
        await maybeExtendTrainingReportNextLmpEvent(assessment);
        await maybePassTrainingReportNotesToNextLmpEvent(assessment);
    };

    const onDeletePT051Assessment = (assessmentId: string, eventId: string, traineeFullName: string) => {
        setPt051Assessments(prev => {
            const updated = new Map(prev);
            updated.delete(`pt051-${eventId}-${traineeFullName}`);
            Array.from(updated.entries()).forEach(([key, assessment]) => {
                if (
                    assessment.traineeFullName === traineeFullName &&
                    (assessment.eventId === eventId || assessment.id === assessmentId)
                ) {
                    updated.delete(key);
                }
            });
            return updated;
        });
        setLoadedPt051Keys(prev => {
            const updated = new Set(prev);
            updated.delete(`${eventId}-${traineeFullName}`);
            return updated;
        });
    };

    const findAvailableResourceId = (eventToPlace: ScheduleEvent, existingEvents: ScheduleEvent[]): string => {
        const normaliseResourceLookup = (value: string): string => (
            String(value || '')
                .replace(/[‐‑‒–—]/g, '-')
                .replace(/\s+/g, ' ')
                .trim()
                .toUpperCase()
        );
        const resourceStartsWithPrefix = (resourceId: string, prefix: string): boolean => (
            normaliseResourceLookup(resourceId).startsWith(normaliseResourceLookup(prefix))
        );

        // Handle deployment events - find an available Deployed resource
        if (eventToPlace.type === 'deployment') {
            // Count existing deployments to determine how many Deployed resources we need
            const existingDeploymentCount = existingEvents.filter(e => e.type === 'deployment').length;
            const totalDeploymentCount = existingDeploymentCount + 1; // +1 for the new one being placed

            // Generate the correct number of Deployed resources
            const deployedResources = Array.from({ length: totalDeploymentCount }, (_, i) => `Deployed ${i + 1}`);


            // Find the first available Deployed resource
            for (const resourceId of deployedResources) {
                const conflictingEvents = existingEvents.filter(e =>
                    e.resourceId === resourceId && isOverlapping(e, eventToPlace)
                );
                logRoutineAppDebug(`Checking ${resourceId}:`, conflictingEvents.length > 0 ? 'OCCUPIED' : 'AVAILABLE', conflictingEvents);

                if (conflictingEvents.length === 0) {
                    return resourceId;
                }
            }

            // If all are occupied, return the next available number
            return `Deployed ${totalDeploymentCount}`;
        }

        let resourcePrefix: string;
        const aircraftResourcePrefix = `${activeAircraftResourcePrefix} `;

        const syllabusItem = syllabusDetails.find(s => s.id === eventToPlace.flightNumber);

        if (syllabusItem) {
            // Primary logic: Use the syllabus item as the single source of truth.
            switch (syllabusItem.type) {
                case 'Flight':
                    resourcePrefix = aircraftResourcePrefix;
                    break;
                case 'FTD':
                    resourcePrefix = 'FTD ';
                    break;
                case 'Ground School':
                    if (syllabusItem.methodOfDelivery.includes('CPT')) {
                        resourcePrefix = 'CPT ';
                    } else {
                        // This explicitly handles MB, TUT, QUIZ, and any other Ground School event.
                        resourcePrefix = 'Ground ';
                    }
                    break;
                default:
                    // This case should be unreachable due to TypeScript types,
                    // but as a fallback, we'll assume Ground to be safer than Flight.
                    console.warn(`Unexpected syllabus type for ${syllabusItem.code}: ${(syllabusItem as any).type}`);
                    resourcePrefix = 'Ground ';
                    break;
            }
        } else {
            // Fallback logic for events not found in the syllabus, including duty and continuation events.
            switch (eventToPlace.type) {
                case 'flight':
                    resourcePrefix = aircraftResourcePrefix;
                    break;
                case 'ftd':
                    resourcePrefix = 'FTD ';
                    break;
                case 'cpt':
                    resourcePrefix = 'CPT ';
                    break;
                case 'ground':
                    if (eventToPlace.flightNumber.toUpperCase().includes('CPT')) {
                        resourcePrefix = 'CPT ';
                    } else {
                        resourcePrefix = 'Ground ';
                    }
                    break;
                default:
                    // Default fallback if event type is unknown.
                    resourcePrefix = 'Ground ';
            }
        }

        const relevantResources = buildResources.filter(r => resourceStartsWithPrefix(r, resourcePrefix));

        for (const resourceId of relevantResources) {
            const isOccupied = existingEvents.some(e =>
                e.resourceId === resourceId && isOverlapping(e, eventToPlace)
            );
            if (!isOccupied) {
                return resourceId;
            }
        }
        return relevantResources[0] || `${resourcePrefix}1`; // Fallback
    };

    const handleOpenModal = (event: ScheduleEvent | null, options: { type?: 'flight' | 'ftd' | 'ground', isPriority?: boolean, oracleContext?: typeof oracleContextForModal } = {}) => {
        if (!event) { // Creating a new event
            const targetDate = oracleContext === 'nextDayBuild' || activeView === 'NextDayBuild' || activeView === 'Priorities' || activeView === 'ProgramData' ? buildDfpDate : date;
            if (!options.isPriority && isPastDfpDate(targetDate)) {
                denyPastDfpEdit('add tiles');
                return;
            }
            const newEvent: ScheduleEvent = {
                id: uuidv4(),
                date: targetDate,
                type: options.type || 'flight',
                flightNumber: '',
                duration: 1.5,
                startTime: 8.0,
                resourceId: '', // Will be assigned on save
                color: 'bg-gray-400/50',
                flightType: 'Dual',
                locationType: 'Local',
                origin: school,
                destination: school,
                isTimeFixed: true,
            };
            setSelectedEvent(newEvent);
            setIsEditingDefault(true);
            setHighlightedField(null);
            setIsPriorityEventCreation(!!options.isPriority);
            setOracleContextForModal(options.oracleContext || null);
        } else {
            // CRITICAL FIX: Always fetch the latest version of the event from the schedule
            // This ensures we get the most up-to-date data, especially after NEO remedies
            // EXCEPTION: Academic tile clicks use a synthetic event — skip the lookup so the
            // individual lesson details (lessonCode, startTime, duration) are preserved.
            let eventToOpen = event;
            if (!(event as any)._academicTileClick) {
                const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
                const currentEvents = isNextDayContext ? nextDayBuildEvents.map(e => ({ ...e, date: buildDfpDate })) : eventsForDate;
                const latestEvent = currentEvents.find(e => e.id === event.id);
                // Use the latest version if found, otherwise fall back to the passed event
                eventToOpen = latestEvent || event;
            }

            setSelectedEvent(eventToOpen);
            setIsEditingDefault(false);
            setHighlightedField(null);
            setIsAddingTile(false); // Reset isAddingTile when editing existing event
            const isHighPriority = highestPriorityEvents.some(p => p.id === event.id);
            setIsPriorityEventCreation(isHighPriority);
            setOracleContextForModal(null);
        }
    };

    // Helper function to get Dual/Solo status from Individual LMP
    const getDualSoloFromIndividualLMP = (flightNumber: string, traineeName: string): 'Dual' | 'Solo' => {
        if (!traineeLMPs || !traineeName) {
            return 'Dual'; // Default to Dual if no data available
        }

        const individualLMP = traineeLMPs.get(traineeName);
        if (!individualLMP) {
            return 'Dual'; // Default to Dual if no Individual LMP found
        }

        const syllabusItem = individualLMP.find(item =>
            item.id === flightNumber || item.code === flightNumber
        );

        if (syllabusItem && syllabusItem.sortieType) {
            return syllabusItem.sortieType;
        }

        return 'Dual'; // Default to Dual if not specified
    };

    // Helper function to add currency event to trainee's Individual LMP
    const addCurrencyEventToTraineeLMP = (traineeFullName: string, currencyEventId: string) => {
        setTraineeLMPs(prev => {
            const newLMPs = new Map(prev);
            const traineeLMP: SyllabusItemDetail[] | undefined = newLMPs.get(traineeFullName);

            if (!traineeLMP) {
                console.warn(`No Individual LMP found for trainee: ${traineeFullName}`);
                return prev;
            }

            // Find the base event in the syllabus
            const baseEvent = syllabusDetails.find(item => item.id === currencyEventId);
            if (!baseEvent) {
                console.warn(`Currency event ${currencyEventId} not found in syllabus`);
                return prev;
            }

            // Create currency version with -CUR suffix
            const currencyEvent: SyllabusItemDetail = {
                ...baseEvent,
                id: `${baseEvent.id}-CUR`,
                code: `${baseEvent.code}-CUR`,
                eventDescription: `${baseEvent.eventDescription} (Currency)`,
            };

            // Find the index of the base event in the trainee's LMP
            const baseEventIndex = traineeLMP.findIndex(item => item.id === currencyEventId);

            if (baseEventIndex === -1) {
                console.warn(`Base event ${currencyEventId} not found in trainee's LMP`);
                return prev;
            }

            // Check if currency event already exists
            const currencyEventExists = traineeLMP.some(item => item.id === `${currencyEventId}-CUR`);
            if (currencyEventExists) {
                logScheduleDebug(`Currency event ${currencyEventId}-CUR already exists in trainee's LMP`);
                return prev;
            }

            // Insert currency event right after the base event
            const updatedLMP = [
                ...traineeLMP.slice(0, baseEventIndex + 1),
                currencyEvent,
                ...traineeLMP.slice(baseEventIndex + 1)
            ];

            newLMPs.set(traineeFullName, updatedLMP);
            logScheduleDebug(`Added currency event ${currencyEvent.id} to ${traineeFullName}'s Individual LMP`);

            return newLMPs;
        });
    };

    const logScheduleDebug = (...args: any[]) => {
        try {
            if (typeof window !== 'undefined' && window.localStorage?.getItem('dfp_schedule_debug') === 'true') {
                console.log(...args);
            }
        } catch {
            // Debug logging must never affect schedule save behaviour.
        }
    };

    // ─── persistScheduleForDate ─────────────────────────────────────────────────
    // Reads the current publishedSchedules state for a given date and saves it
    // to the DailySnapshot database so manually added/edited/deleted/cancelled
    // events survive a hard refresh or server restart.
    // persistScheduleForDate: saves the full schedule for a date to the DB.
    // Pass allEventsForDate directly (after setPublishedSchedules has been called)
    // to avoid race conditions with React's async state updates.
    const persistScheduleForDate = (targetDate: string, allEventsForDate: ScheduleEvent[], baselineEventsForDate?: ScheduleEvent[]) => {
        // Skip seed data
        if (allEventsForDate.some((e: any) => e.isHistoricalSeed === true)) {
            logScheduleDebug('[Persist] Skipped seed data for', targetDate);
            return;
        }
        if (allEventsForDate.length === 0 && (!baselineEventsForDate || baselineEventsForDate.length === 0)) {
            logScheduleDebug('[Persist] No events for', targetDate, '- nothing to persist');
            return;
        }

        const apiBase = getApiBaseUrl();
        const savedBy = authUser?.userId ?? sessionUser?.userId ?? null;
        const snapshotKey = getDailySnapshotKey(targetDate);

        const staffEventsForDate = allEventsForDate.filter((e: ScheduleEvent) =>
            e.instructor && !e.student && e.type !== 'logbook'
        );
        const traineeEventsForDate = allEventsForDate.filter((e: ScheduleEvent) =>
            !!e.student
        );

        // Build per-staff currency map
        const staffCurrencyMap: Record<string, any> = {};
        instructorsData.forEach((inst: any) => {
            if (inst.currencyStatus && inst.currencyStatus.length > 0) {
                staffCurrencyMap[inst.name] = inst.currencyStatus;
            }
        });

        // Build trainee profiles snapshot
        const traineeProfilesSnapshot = traineesData.map((t: any) => ({
            idNumber: t.idNumber,
            fullName: t.fullName,
            name: t.name,
            rank: t.rank,
            course: t.course,
            lmpType: t.lmpType,
            service: t.service,
            unit: t.unit,
            primaryInstructor: t.primaryInstructor,
            currencyStatus: t.currencyStatus || [],
            isPaused: t.isPaused || false,
        }));

        const staffProfilesSnapshot = instructorsData.map((inst: any) => ({
            id: inst.id,
            idNumber: inst.idNumber,
            name: inst.name,
            rank: inst.rank,
            role: inst.role,
            unit: inst.unit,
            location: inst.location,
            flight: inst.flight,
            service: inst.service,
            category: inst.category,
            isQFI: !!inst.isQFI,
            isOFI: !!inst.isOFI,
            isCFI: !!inst.isCFI,
            isFlyingSupervisor: !!inst.isFlyingSupervisor,
            isTestingOfficer: !!inst.isTestingOfficer,
            isCommandingOfficer: !!inst.isCommandingOfficer,
            isExecutive: !!inst.isExecutive,
            isPaused: !!inst.isPaused,
            currencyStatus: inst.currencyStatus || [],
            snapshotSchool: school,
            snapshotUnit: activeUnitCode,
            operationalModel: activeOperationalModel,
            snapshotDate: targetDate,
        }));

        // Build per-trainee LMP completedEventIds map
        const lmpCompletedIdsMap: Record<string, string[]> = {};
        traineesData.forEach((t: any) => {
            const individualLMP = traineeLMPs.get(t.fullName);
            if (individualLMP) {
                const completedIds = (individualLMP as any[])
                    .filter((item: any) => item.completedAt || item.isComplete)
                    .map((item: any) => (item.id || item.code || '').replace('*', ''));
                if (completedIds.length > 0) {
                    lmpCompletedIdsMap[t.fullName] = completedIds;
                }
            }
        });

        const snapshotPayload: Record<string, any> = {
            date: snapshotKey,
            locationCode: school,
            unitCode: activeUnitCode,
            operationalModel: activeOperationalModel,
            scheduleEvents: allEventsForDate,
            staffEvents: staffEventsForDate,
            traineeEvents: traineeEventsForDate,
            traineeProfiles: traineeProfilesSnapshot,
            staffProfiles: staffProfilesSnapshot,
            lmpCompletedIds: lmpCompletedIdsMap,
            staffCurrency: staffCurrencyMap,
            staffLogbook: {},
            aircraftConfigState: currentAircraftConfigState,
            savedBy,
        };
        // Only include baselineEvents if explicitly provided (initial publish)
        // This preserves the original published baseline for change-bar detection after page reload
        if (baselineEventsForDate !== undefined) {
            snapshotPayload.baselineEvents = baselineEventsForDate;
        }

        logScheduleDebug(`[Persist] Saving snapshot for ${targetDate} (${school} - ${activeUnitCode}), ${allEventsForDate.length} events...`);
        cacheDailySnapshot(snapshotKey, snapshotPayload, targetDate);
        fetch(`${apiBase}/daily-snapshot/save`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(snapshotPayload),
        })
        .then(res => res.json())
        .then(result => {
            if (result.success) {
                loadedSnapshotDates.current.add(snapshotKey);
                cacheDailySnapshot(snapshotKey, snapshotPayload, targetDate);
                logScheduleDebug(`✅ [Persist] Saved snapshot for ${targetDate} (${school} - ${activeUnitCode}), ${allEventsForDate.length} events`);
            } else {
                console.warn(`⚠️ [Persist] Snapshot save failed for ${targetDate}:`, result.error);
            }
        })
        .catch(err => {
            console.warn(`⚠️ [Persist] Could not save snapshot for ${targetDate}:`, err);
        });
    };
    // ────────────────────────────────────────────────────────────────────────────

    const persistPt051AssessmentsForDate = async (
        targetDate: string,
        assessmentsMap: Map<string, Pt051Assessment>
    ) => {
        logScheduleDebug(`[Training Report] Snapshot persistence skipped for ${targetDate}; ${assessmentsMap.size} active records use TraineePerformance`);
    };

    const persistPt051AssessmentRecord = async (assessment: Pt051Assessment) => {
        const apiBase = getApiBaseUrl();
        const trainee = allTraineesData.find((t: any) => t.fullName === assessment.traineeFullName);
        const traineeId = (trainee as any)?.id;
        if (!traineeId) {
            throw new Error(`Cannot save ${configuredTrainingReportDisplayName}: trainee database record not found for ${assessment.traineeFullName}`);
        }

        pushDfpDataDiag('pt051:persist:request', {
            assessmentId: assessment.id,
            eventId: assessment.eventId,
            flightNumber: assessment.flightNumber,
            traineeFullName: assessment.traineeFullName,
            dcoResult: assessment.dcoResult,
            dpcoFollowUp: assessment.dpcoFollowUp || null,
            dncoFollowUp: assessment.dncoFollowUp || null,
            passNotesToNextEvent: assessment.passNotesToNextEvent === true,
            trainingReportNotesLength: String(assessment.trainingReportNotes || '').trim().length,
            trainingReportNotesPreview: String(assessment.trainingReportNotes || '').trim().slice(0, 120),
        });
        const response = await fetch(`${apiBase}/trainee-performance`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                ...assessment,
                traineeId,
                course: (trainee as any)?.course || null,
                createdBy: authUser?.userId ?? sessionUser?.userId ?? null,
            }),
        });

        if (!response.ok) {
            const errorText = await response.text();
            pushDfpDataDiag('pt051:persist:error', {
                assessmentId: assessment.id,
                eventId: assessment.eventId,
                status: response.status,
                errorText,
            });
            throw new Error(errorText || `Failed to save ${configuredTrainingReportDisplayName} record (${response.status})`);
        }

        const saved = await response.json();
        pushDfpDataDiag('pt051:persist:response', {
            assessmentId: assessment.id,
            eventId: assessment.eventId,
            flightNumber: assessment.flightNumber,
            traineeFullName: assessment.traineeFullName,
            responseDpcoFollowUp: saved?.dpcoFollowUp || null,
            responseDncoFollowUp: saved?.dncoFollowUp || null,
        });
        return saved;
    };

    const handleSaveEvents = async (eventsToSave: ScheduleEvent[], isPriority?: boolean) => {
        logScheduleDebug('🔵 ========== handleSaveEvents START ==========');
        logScheduleDebug('🔵 Called from:', new Error().stack?.split('\\n')[2]?.trim());

        // System freeze check - prevent modifications when system is frozen
        // Read directly from localStorage as most reliable freeze check
        const _freezeData = localStorage.getItem('systemFreezeState');
        const _isFrozen = _freezeData ? JSON.parse(_freezeData).isFrozen === true : false;
        if (_isFrozen) {
            showDarkAlert('System is currently frozen. No modifications are allowed during a system freeze.', 'System Frozen', 'error');
            return;
        }
        logScheduleDebug('🔵 Events to save:', eventsToSave.length);
        logScheduleDebug('🔵 First event details:', {
            id: eventsToSave[0]?.id,
            instructor: eventsToSave[0]?.instructor,
            student: eventsToSave[0]?.student,
            pilot: eventsToSave[0]?.pilot,
            flightNumber: eventsToSave[0]?.flightNumber,
            date: eventsToSave[0]?.date,
            resourceId: eventsToSave[0]?.resourceId
        });
        logScheduleDebug('🔵 isPriority:', isPriority);
        logScheduleDebug('🔵 activeView:', activeView);
        logScheduleDebug('🔵 date:', date);
        logScheduleDebug('🔵 buildDfpDate:', buildDfpDate);
        if (!eventsToSave || eventsToSave.length === 0) return;
        const isNextDaySaveContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const lockedPastEvents = eventsToSave.filter(event => (
            !isPriority && !isNextDaySaveContext && isPastDfpDate(event.date)
        ));
        if (lockedPastEvents.length > 0) {
            denyPastDfpEdit('save changes');
            return;
        }
        eventsToSave = eventsToSave.map(normaliseCrewFieldsForSave);

        const proposedMainEvent = eventsToSave[0];
        const isPotentialNextDayView = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const saveToNextDayBuildForConflict = oracleContextForModal
            ? oracleContext === 'nextDayBuild'
            : proposedMainEvent.date === buildDfpDate && isPotentialNextDayView;
        const removedPublishedConflictIdsByDate = new Map<string, Set<string>>();
        const removedNextDayConflictIds = new Set<string>();
        const dayNightConflicts = collectDayNightSaveConflicts(eventsToSave, saveToNextDayBuildForConflict);

        if (dayNightConflicts.length > 0) {
            const decision = await showDayNightConflictDecision(dayNightConflicts);
            if (decision === 'skip') {
                logScheduleDebug('SAVE CANCELLED - user chose not to schedule after day/night conflict:', dayNightConflicts);
                return;
            }

            if (decision === 'remove-conflicts') {
                const nonRemovableConflicts = dayNightConflicts.filter(conflict => !conflict.canRemove);
                if (nonRemovableConflicts.length > 0) {
                    await showDarkAlert(
                        `The conflicting event cannot be removed because ${nonRemovableConflicts[0].cannotRemoveReason || 'it has already started or finished'}.\n\nThe proposed event was not scheduled. Re-open the event and choose Accept Conflict if you still want to proceed.`,
                        'Conflict Cannot Be Removed',
                        'warning',
                    );
                    return;
                }
                removeDayNightConflictingEvents(dayNightConflicts);
                dayNightConflicts.forEach(conflict => {
                    if (conflict.source === 'next-day-build') {
                        removedNextDayConflictIds.add(conflict.conflictingEvent.id);
                    } else {
                        const ids = removedPublishedConflictIdsByDate.get(conflict.conflictingEvent.date) || new Set<string>();
                        ids.add(conflict.conflictingEvent.id);
                        removedPublishedConflictIdsByDate.set(conflict.conflictingEvent.date, ids);
                    }
                });
            }

            if (decision === 'accept-conflict') {
                const conflictDetails = dayNightConflicts.map(conflict => (
                    `${conflict.personName}: ${conflict.proposedEvent.flightNumber} conflicts with ${conflict.conflictingEvent.flightNumber} at ${formatTimeForAudit(conflict.conflictingEvent.startTime)}`
                ));
                eventsToSave = eventsToSave.map(event => ({
                    ...event,
                    forcedInstructorConflict: true,
                    forcedInstructorConflictDetails: Array.from(new Set([
                        ...(event.forcedInstructorConflictDetails || []),
                        ...conflictDetails,
                    ])),
                }));
                logAudit('Program Schedule', 'Override', 'Accepted day/night personnel conflict', conflictDetails.join('; '));
            }
        }

        const mainEvent = eventsToSave[0];
        const isNewEvent = !mainEvent.resourceId;
        const wasOracleEvent = !!oracleContextForModal;

        // Determine if we should save to priority list or schedule
        // If editing an existing event in Next Day Build view, save to nextDayBuildEvents
        const isEditingInNextDayView = !isNewEvent && ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const shouldSaveToPriority = isPriority && !isEditingInNextDayView;

        if (shouldSaveToPriority) {
            const priorityEvent = { ...mainEvent, isTimeFixed: mainEvent.isTimeFixed ?? true };

            setHighestPriorityEvents(prev => {
                const existingIndex = prev.findIndex(p => p.id === priorityEvent.id);
                if (existingIndex > -1) {
                    const newEvents = [...prev];
                    newEvents[existingIndex] = priorityEvent;
                    return newEvents;
                }
                return [...prev, priorityEvent];
            });
        } else {
            let saveToNextDayBuild = false;

            if (wasOracleEvent) {
                // If the save comes from Oracle, the context is king.
                saveToNextDayBuild = oracleContext === 'nextDayBuild';
            } else {
                // If it's a normal save/edit, check the view and date.
                const isNextDayView = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
                saveToNextDayBuild = mainEvent.date === buildDfpDate && isNextDayView;

                // Debug logging for continuation events
                if (isContinuationScheduleEvent(mainEvent)) {
                    logScheduleDebug('🔍 Continuation Save Decision:', {
                        activeView,
                        isNextDayView,
                        mainEventDate: mainEvent.date,
                        buildDfpDate,
                        datesMatch: mainEvent.date === buildDfpDate,
                        saveToNextDayBuild
                    });
                }
            }

            if (saveToNextDayBuild) {
                if (isNewEvent) {
                    // Track already assigned events in this batch
                    const alreadyAssigned: ScheduleEvent[] = [];

                    eventsToSave.forEach(e => {
                        // Assign resourceId based on event type
                        if (!e.resourceId || e.type === 'deployment') {
                            const allEventsForCheck = nextDayBuildEvents.map(ev => ({ ...ev, date: buildDfpDate }));
                            // Include already assigned events from this batch
                            const eventsToCheck = [...allEventsForCheck, ...alreadyAssigned];
                            e.resourceId = findAvailableResourceId(e, eventsToCheck);
                            // Add to already assigned list
                            alreadyAssigned.push(e);
                        }
                    });
                }
                const existingEventIds = new Set(eventsToSave.map(e => e.id));
                const otherEvents = nextDayBuildEvents.filter(e => !existingEventIds.has(e.id) && !removedNextDayConflictIds.has(e.id));
                const eventsForBuild = eventsToSave.map(({ date, ...rest }) => rest);

                // Debug logging for continuation event updates
                eventsToSave.forEach(e => {
                    if (isContinuationScheduleEvent(e)) {
                        logScheduleDebug('🔄 Updating continuation event in nextDayBuildEvents:', {
                            id: e.id,
                            student: e.student,
                            pilot: e.pilot,
                            flightType: e.flightType
                        });
                    }
                });

                setNextDayBuildEvents([...otherEvents, ...eventsForBuild]);
            } else {
                if (isNewEvent) {
                    // Track already assigned events in this batch
                    const alreadyAssigned: ScheduleEvent[] = [];

                    eventsToSave.forEach(e => {
                        // Assign resourceId based on event type
                        // For deployments, always reassign to get correct numbered resource
                        if (!e.resourceId || e.type === 'deployment') {
                            const allEventsForDate = publishedSchedules[mainEvent.date] || [];
                            // Include already assigned events from this batch
                            const eventsToCheck = [...allEventsForDate, ...alreadyAssigned];
                            const assignedResourceId = findAvailableResourceId(e, eventsToCheck);
                            logScheduleDebug(`Assigning resourceId to ${e.type} event:`, assignedResourceId);
                            e.resourceId = assignedResourceId;
                            // Add to already assigned list
                            alreadyAssigned.push(e);
                        }
                    });
                }
                setPublishedSchedules((prev) => {
                    logScheduleDebug('🟢 setPublishedSchedules: START');
                    logScheduleDebug('🟢 Previous publishedSchedules keys:', Object.keys(prev));
                    const newSchedules = { ...prev };

                    // Group events by their date (deployment tiles may have different dates)
                    const eventsByDate = new Map<string, ScheduleEvent[]>();
                    eventsToSave.forEach(event => {
                        const eventDate = event.date;
                        if (!eventsByDate.has(eventDate)) {
                            eventsByDate.set(eventDate, []);
                        }
                        eventsByDate.get(eventDate)!.push(event);
                    });

                    logScheduleDebug('🟢 Events grouped by date:', Array.from(eventsByDate.entries()).map(([date, events]) => ({
                        date,
                        count: events.length,
                        eventIds: events.map(e => e.id),
                        instructors: events.map(e => e.instructor)
                    })));

                    // Save each group of events to their respective dates
                    eventsByDate.forEach((events, eventDate) => {
                        const currentScheduleForDate = newSchedules[eventDate] || [];
                        logScheduleDebug(`🟢 Processing date ${eventDate}:`, {
                            currentEventsCount: currentScheduleForDate.length,
                            eventsToSaveCount: events.length
                        });

                        const existingEventIds = new Set(events.map(e => e.id));
                        const removedConflictIds = removedPublishedConflictIdsByDate.get(eventDate) || new Set<string>();
                        const otherEvents = currentScheduleForDate.filter(e => !existingEventIds.has(e.id) && !removedConflictIds.has(e.id));

                        logScheduleDebug(`🟢 Filtered out ${currentScheduleForDate.length - otherEvents.length} existing events`);

                        newSchedules[eventDate] = [...otherEvents, ...events] as ScheduleEvent[];

                        logScheduleDebug(`🟢 Saved ${events.length} events to date ${eventDate}`);
                        logScheduleDebug(`🟢 New total for ${eventDate}:`, newSchedules[eventDate].length);

                        // Log the specific event we just saved
                        const savedEvent = newSchedules[eventDate].find(e => e.id === events[0].id);
                        logScheduleDebug(`🟢 Saved event details:`, {
                            id: savedEvent?.id,
                            instructor: savedEvent?.instructor,
                            student: savedEvent?.student,
                            pilot: savedEvent?.pilot
                        });
                    });

                    logScheduleDebug('🟢 setPublishedSchedules: COMPLETE');
                    logScheduleDebug('🟢 New publishedSchedules keys:', Object.keys(newSchedules));

                    return newSchedules;
                });

                // NEW APPROACH: Trigger training report sync after any Active DFP change
                // Use functional setState to access the latest state
                logScheduleDebug('📋 Triggering training report sync after Active DFP change...');
                setTimeout(() => {
                    logScheduleDebug('⏰ Executing delayed training report sync...');
                    setPublishedSchedules(currentSchedules => {
                        setPt051Assessments(currentAssessments => {
                            syncPt051WithActiveDfp(currentSchedules, currentAssessments);
                            return currentAssessments;
                        });
                        return currentSchedules;
                    });
                }, 500);

                // Persist all affected dates to database immediately
                // We compute the merged events per date right here (same logic as setPublishedSchedules above)
                const _affectedDates = new Set<string>(eventsToSave.map(e => e.date));
                _affectedDates.forEach(d => {
                    const _prevForDate = publishedSchedules[d] || [];
                    const _newEventIds = new Set(eventsToSave.filter(e => e.date === d).map(e => e.id));
                    const _removedConflictIds = removedPublishedConflictIdsByDate.get(d) || new Set<string>();
                    const _otherEvents = _prevForDate.filter((e: ScheduleEvent) => !_newEventIds.has(e.id) && !_removedConflictIds.has(e.id));
                    const _newEventsForDate = eventsToSave.filter(e => e.date === d);
                    persistScheduleForDate(d, [..._otherEvents, ..._newEventsForDate]);
                });

                // Keep deployment assignment behaviour consistent whether the user
                // ticks the Flight Details deployment box or drags a tile onto the
                // Deployed row.
                setTimeout(() => {
                    setPublishedSchedules(currentSchedules => {
                        const allEvents = Object.values(currentSchedules).flat();
                        void handleDeploymentUnavailability(allEvents);
                        return currentSchedules;
                    });
                }, 600);
            }
        }

        // Handle LMP Currency events - add to trainee's Individual LMP
        eventsToSave.forEach(event => {
            if (event.eventCategory === 'lmp_currency' && event.flightNumber) {
                // Get trainee name from the event
                const traineeName = event.flightType === 'Dual' ? event.student : event.pilot;

                if (traineeName) {
                    addCurrencyEventToTraineeLMP(traineeName, event.flightNumber);
                } else if (event.groupTraineeIds && event.groupTraineeIds.length > 0) {
                    // Handle group events - add currency to all trainees in the group
                    event.groupTraineeIds.forEach(traineeId => {
                        const trainee = allTraineesData.find(t => t.idNumber === traineeId);
                        if (trainee) {
                            addCurrencyEventToTraineeLMP(trainee.fullName, event.flightNumber);
                        }
                    });
                }
            }
        });


           // Log the action to audit trail with detailed field-level changes
           const saveToNextDayBuild = mainEvent.date === buildDfpDate && ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
           eventsToSave.forEach(event => {
               const pageName = saveToNextDayBuild ? 'Next Day Build' : 'Program Schedule';
               const eventType = event.type || 'event';
               const personName = event.student || event.pilot || event.instructor || 'Unknown';

               if (isNewEvent) {
                   // Log new event creation
                   const description = `Added ${eventType} event for ${personName}`;
                   const changes = `Event: ${event.syllabusItem || event.flightNumber || eventType}, Time: ${event.startTime}, Duration: ${event.duration}hrs, Resource: ${event.resourceId}`;
                   logAudit(pageName, 'Add', description, changes);
               } else {
                   // Find the original event to compare changes
                   const originalEvent = publishedSchedules[event.date]?.find(e => e.id === event.id) ||
                                       nextDayBuildEvents.find(e => e.id === event.id);

                   if (originalEvent) {
                       const changesList: string[] = [];

                       // Check for pilot/instructor changes
                       if (event.instructor !== originalEvent.instructor) {
                           changesList.push(`${instructorLabel}: ${originalEvent.instructor || 'None'} → ${event.instructor || 'None'}`);
                       }
                       if (event.pilot !== originalEvent.pilot) {
                           changesList.push(`Pilot: ${originalEvent.pilot || 'None'} → ${event.pilot || 'None'}`);
                       }
                       if (event.student !== originalEvent.student) {
                           changesList.push(`Student: ${originalEvent.student || 'None'} → ${event.student || 'None'}`);
                       }

                       // Check for LMP event/syllabus item changes
                       if (event.syllabusItem !== originalEvent.syllabusItem) {
                           changesList.push(`LMP Event: ${originalEvent.syllabusItem || 'None'} → ${event.syllabusItem || 'None'}`);
                       }
                       if (event.flightNumber !== originalEvent.flightNumber) {
                           changesList.push(`Event Number: ${originalEvent.flightNumber || 'None'} → ${event.flightNumber || 'None'}`);
                       }

                       // Check for area changes
                       if (event.area !== originalEvent.area) {
                           changesList.push(`Area: ${originalEvent.area || 'None'} → ${event.area || 'None'}`);
                       }

                       // Check for time changes
                       if (event.startTime !== originalEvent.startTime) {
                           changesList.push(`Start time: ${formatTimeForAudit(originalEvent.startTime)} → ${formatTimeForAudit(event.startTime)}`);
                       }

                       // Check for duration changes
                       if (event.duration !== originalEvent.duration) {
                           changesList.push(`Duration: ${originalEvent.duration}hrs → ${event.duration}hrs`);
                       }

                       // Check for resource changes
                       if (event.resourceId !== originalEvent.resourceId) {
                           changesList.push(`Resource: ${originalEvent.resourceId} → ${event.resourceId}`);
                       }

                       // Check for type changes
                       if (event.type !== originalEvent.type) {
                           changesList.push(`Type: ${originalEvent.type} → ${event.type}`);
                       }

                       // Only log if there are actual changes
                       if (changesList.length > 0) {
                           const description = `Modified ${eventType} event for ${personName}`;
                           logAudit(pageName, 'Edit', description, changesList.join(', '));
                       }
                   } else {
                       // Fallback if original event not found
                       const description = `Modified ${eventType} event for ${personName}`;
                       const changes = `Event: ${event.syllabusItem || event.flightNumber || eventType}, Time: ${event.startTime}, Duration: ${event.duration}hrs, Resource: ${event.resourceId}`;
                       logAudit(pageName, 'Edit', description, changes);
                   }
               }
           });
        logScheduleDebug('🔵 Setting selectedEvent to null (closing modal)');
        setSelectedEvent(null);
        setOracleContextForModal(null);

        // If the event came from Oracle, deactivate Oracle mode now.
        if (wasOracleEvent) {
            setIsOracleMode(false);
            setOracleAnalysis(null);
            setOraclePreviewEvent(null);
        }

        logScheduleDebug('🔵 ========== handleSaveEvents END ==========');
    };

    const handleCancelEvent = async (eventId: string, cancellationCode: string, manualCodeEntry?: string) => {
        // System freeze check - read directly from localStorage to avoid stale closure
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. No modifications are allowed during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        if (!selectedEvent) {
            return;
        }
        const eventDate = selectedEvent.date;
        const isNextDay = eventDate === buildDfpDate && (activeView === 'NextDayBuild' || activeView === 'Priorities' || activeView === 'ProgramData');
        if (!isNextDay && isPastDfpDate(eventDate)) {
            denyPastDfpEdit('cancel events');
            return;
        }

        // Create cancellation record
        const personnelNames = [
            selectedEvent.instructor,
            selectedEvent.student,
            selectedEvent.pilot
        ].filter(Boolean).join(', ');

        const cancellationRecord: CancellationRecord = {
            eventId: selectedEvent.id,
            cancellationCode: cancellationCode,
            cancelledBy: `${currentUser}`,
            cancelledAt: new Date().toISOString(),
            manualCodeEntry: manualCodeEntry,
            eventDate: selectedEvent.date,
            eventType: selectedEvent.type === 'ftd' ? 'ftd' : 'flight',
            resourceType: selectedEvent.resourceId || 'Unknown',
            eventName: selectedEvent.flightNumber || selectedEvent.syllabusItem || 'N/A',
            personnelAffected: personnelNames || 'N/A',
            notes: selectedEvent.notes || '',
        };

        // Save cancellation record
        const updatedRecords = [...cancellationRecords, cancellationRecord];
        setCancellationRecords(updatedRecords);
        localStorage.setItem('cancellationRecords', JSON.stringify(updatedRecords));

        // Mark event as cancelled (leave in original position, just add red X)
        const cancelledEvent: ScheduleEvent = {
            ...selectedEvent,
            isCancelled: true,
            cancellationCode: cancellationCode,
            cancellationManualEntry: manualCodeEntry,
            cancelledBy: `${currentUser}`,
            cancelledAt: new Date().toISOString(),
            // Keep original resourceId - don't move to STBY
        };

        if (isNextDay) {
            setNextDayBuildEvents(prev =>
                prev.map(e => e.id === selectedEvent.id ? cancelledEvent : e)
            );
        } else {
            setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
                const scheduleForDate = prev[eventDate] || [];
                const updatedSchedule = scheduleForDate.map(e => e.id === selectedEvent.id ? cancelledEvent : e);
                return { ...prev, [eventDate]: updatedSchedule };
            });
            // Persist cancellation to database immediately
            setPublishedSchedules(prev => {
                const _updated = (prev[eventDate] || []).map((e: ScheduleEvent) => e.id === selectedEvent.id ? cancelledEvent : e);
                persistScheduleForDate(eventDate, _updated);
                return prev; // no state change here — already updated above
            });
        }

        // Remove from highest priority events
        setHighestPriorityEvents(prev => prev.filter(e => e.id !== selectedEvent.id));

        // Note: No need to force a date refresh - the state updates above
        // (setNextDayBuildEvents / setPublishedSchedules) will trigger re-render automatically.
        // Previously used setDate('') which caused RangeError: invalid date in AircraftAvailabilityOverlay.

        // Log the cancellation to audit trail
        const pageName = isNextDay ? 'Next Day Build' : 'Program Schedule';
        const eventType = selectedEvent.type || 'event';
        const personName = selectedEvent.student || selectedEvent.pilot || selectedEvent.instructor || 'Unknown';
        const codeDisplay = cancellationCode === 'OTHER' && manualCodeEntry ? manualCodeEntry : cancellationCode;
        const description = `Cancelled ${eventType} event for ${personName} (Code: ${codeDisplay})`;
        const changes = `Event: ${selectedEvent.syllabusItem || selectedEvent.flightNumber || eventType}, Time: ${selectedEvent.startTime}, Duration: ${selectedEvent.duration}hrs, Marked as cancelled`;

        logAudit(pageName, "Cancel", description, changes);

        // ── Deployment unavailability cleanup after cancel ─────────────────────────────
        // When a flight is cancelled, remove its __deploy__ tag from all personnel
        // (the person is no longer required to fly, so the Deployed unavailability block
        // created for this flight should be removed).
        // If it was a deployment tile being cancelled, re-run the full check.
        const _cancelledId   = selectedEvent.id;
        const _cancelledType = selectedEvent.type;
        setTimeout(() => {
            if (_cancelledType === 'deployment') {
                setPublishedSchedules(prevSchedules => {
                    const allEvents = Object.values(prevSchedules).flat();
                    handleDeploymentUnavailability(allEvents);
                    return prevSchedules;
                });
            } else {
                removeDeployedUnavailability(_cancelledId);
            }
        }, 600);
        // ─────────────────────────────────────────────────────────────────────────────

        setSelectedEvent(null);


    };

    const handleDeleteEvent = async () => {
        // System freeze check - read directly from localStorage to avoid stale closure
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. No modifications are allowed during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        if (!selectedEvent) return;
        const eventDate = selectedEvent.date;
        const isNextDay = eventDate === buildDfpDate && (activeView === 'NextDayBuild' || activeView === 'Priorities' || activeView === 'ProgramData');
        if (!isNextDay && isPastDfpDate(eventDate)) {
            denyPastDfpEdit('delete events');
            return;
        }

        const isDeploymentDelete = selectedEvent.type === 'deployment';
        const selectedDeploymentSeriesId = selectedEvent.deploymentSeriesId;
        const selectedDeploymentPeriodKey = [
            selectedEvent.deploymentSource || '',
            selectedEvent.deploymentStartDate || selectedEvent.date || '',
            selectedEvent.deploymentStartTime || '',
            selectedEvent.deploymentEndDate || selectedEvent.date || '',
            selectedEvent.deploymentEndTime || '',
            selectedEvent.deploymentAircraftCount || '',
        ].join('|');
        const isSameDeploymentToDelete = (event: ScheduleEvent): boolean => {
            if (!isDeploymentDelete || event.type !== 'deployment') return event.id === selectedEvent.id;
            if (selectedDeploymentSeriesId) return event.deploymentSeriesId === selectedDeploymentSeriesId;
            const eventPeriodKey = [
                event.deploymentSource || '',
                event.deploymentStartDate || event.date || '',
                event.deploymentStartTime || '',
                event.deploymentEndDate || event.date || '',
                event.deploymentEndTime || '',
                event.deploymentAircraftCount || '',
            ].join('|');
            return event.id === selectedEvent.id || eventPeriodKey === selectedDeploymentPeriodKey;
        };

        const deletedEventIds = new Set<string>([selectedEvent.id]);
        if (isDeploymentDelete) {
            Object.values(publishedSchedulesRef.current).flat().forEach(event => {
                if (isSameDeploymentToDelete(event)) deletedEventIds.add(event.id);
            });
        }

        setHighestPriorityEvents(prev => prev.filter(e => !deletedEventIds.has(e.id)));

        if (isNextDay) {
            setNextDayBuildEvents(prev => prev.filter(e => !deletedEventIds.has(e.id)));
        } else {
            setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
                const nextSchedules = { ...prev };
                Object.entries(prev).forEach(([scheduleDate, scheduleEvents]) => {
                    const newScheduleForDate = scheduleEvents.filter(e => !isSameDeploymentToDelete(e));
                    if (newScheduleForDate.length !== scheduleEvents.length) {
                        nextSchedules[scheduleDate] = newScheduleForDate;
                        persistScheduleForDate(scheduleDate, newScheduleForDate, scheduleEvents);
                    }
                });
                if (!isDeploymentDelete) {
                    const scheduleForDate = prev[eventDate] || [];
                    const newScheduleForDate = scheduleForDate.filter(e => e.id !== selectedEvent.id);
                    nextSchedules[eventDate] = newScheduleForDate;
                    persistScheduleForDate(eventDate, newScheduleForDate, scheduleForDate);
                }
                return nextSchedules;
            });
        }

        // NEW APPROACH: Trigger training report sync after deletion (only for Active DFP)
        if (!isNextDay) {
            logRoutineAppDebug('📋 Triggering training report sync after event deletion...');
            setTimeout(() => {
                logRoutineAppDebug('⏰ Executing delayed training report sync after deletion...');
                setPublishedSchedules(currentSchedules => {
                    setPt051Assessments(currentAssessments => {
                        syncPt051WithActiveDfp(currentSchedules, currentAssessments);
                        return currentAssessments;
                    });
                    return currentSchedules;
                });
            }, 500);
        }

           // Log the deletion to audit trail
           const pageName = isNextDay ? 'Next Day Build' : 'Program Schedule';
           const eventType = selectedEvent.type || 'event';
           const personName = selectedEvent.student || selectedEvent.pilot || selectedEvent.instructor || 'Unknown';
           const description = isDeploymentDelete && deletedEventIds.size > 1
               ? `Deleted deployment period (${deletedEventIds.size} segments)`
               : `Deleted ${eventType} event for ${personName}`;
           const changes = `Event: ${selectedEvent.syllabusItem || selectedEvent.flightNumber || eventType}, Time: ${selectedEvent.startTime}, Duration: ${selectedEvent.duration}hrs`;

           logAudit(pageName, "Delete", description, changes);

        // ── Deployment unavailability cleanup after delete ────────────────────
        // Capture the deleted event's id and type before clearing selectedEvent
        const _deletedId   = selectedEvent.id;
        const _deletedType = selectedEvent.type;
        setTimeout(() => {
            if (_deletedType === 'deployment') {
                // A deployment tile was removed — re-run the full check on the
                // updated schedule so all previously tagged Deployed unavailabilities
                // are cleaned up for everyone.
                setPublishedSchedules(prevSchedules => {
                    const allEvents = Object.values(prevSchedules).flat();
                    handleDeploymentUnavailability(allEvents);
                    return prevSchedules;
                });
            } else {
                // A flight/FTD/CPT tile was removed — remove its specific tag only
                removeDeployedUnavailability(_deletedId);
            }
        }, 600); // slight delay to allow state to settle after delete
        // ─────────────────────────────────────────────────────────────────────

        setSelectedEvent(null);
    };
    const handleRestoreEvent = async (eventId: string) => {
        // System freeze check
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. No modifications are allowed during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        if (!selectedEvent || selectedEvent.id !== eventId) return;

        const eventDate = selectedEvent.date;
        const isNextDay = eventDate === buildDfpDate && (activeView === 'NextDayBuild' || activeView === 'Priorities' || activeView === 'ProgramData');
        if (!isNextDay && isPastDfpDate(eventDate)) {
            denyPastDfpEdit('restore events');
            return;
        }

        // Build the restored event — strip all cancellation fields
        const { isCancelled, cancellationCode, cancellationManualEntry, cancelledBy, cancelledAt, ...rest } = selectedEvent as any;
        const restoredEvent: ScheduleEvent = { ...rest };

        if (isNextDay) {
            setNextDayBuildEvents(prev =>
                prev.map(e => e.id === eventId ? restoredEvent : e)
            );
        } else {
            setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
                const scheduleForDate = prev[eventDate] || [];
                const updated = scheduleForDate.map(e => e.id === eventId ? restoredEvent : e);
                return { ...prev, [eventDate]: updated };
            });
            // Persist immediately
            setPublishedSchedules(prev => {
                const _updated = (prev[eventDate] || []).map((e: ScheduleEvent) => e.id === eventId ? restoredEvent : e);
                persistScheduleForDate(eventDate, _updated);
                return prev;
            });
        }

        // Log to audit trail
        const pageName = isNextDay ? 'Next Day Build' : 'Program Schedule';
        const eventType = selectedEvent.type || 'event';
        const personName = selectedEvent.student || selectedEvent.pilot || selectedEvent.instructor || 'Unknown';
        const description = `Restored ${eventType} event for ${personName} (was cancelled with code: ${(selectedEvent as any).cancellationCode || 'N/A'})`;
        const changes = `Event: ${selectedEvent.syllabusItem || selectedEvent.flightNumber || eventType}, Time: ${selectedEvent.startTime}, Duration: ${selectedEvent.duration}hrs, Restored to active`;
        logAudit(pageName, 'Restore', description, changes);

        setSelectedEvent(null);
    };


    // handleSendAlert
    const handleSendAlert = async (eventId: string, recipients: string[], description: string = ''): Promise<boolean> => {
        // Always use relative /api - works on any domain
        const apiBase = '/api';
        const userId = getCurrentUserId() || currentUserName;
        const eventForAlert = events.find(e => e.id === eventId) || selectedEvent;
        if (isPastDfpDate(eventForAlert?.date || date)) {
            denyPastDfpEdit('send alerts');
            return false;
        }
        const snapshotDate = getDailySnapshotKey(date);

        logRoutineAppDebug('🔔 [Alert] ========== SEND ALERT START ==========');
        logRoutineAppDebug('🔔 [Alert] eventId:', eventId);
        logRoutineAppDebug('🔔 [Alert] date:', date);
        logRoutineAppDebug('🔔 [Alert] snapshotDate:', snapshotDate);
        logRoutineAppDebug('🔔 [Alert] sentBy:', userId);
        logRoutineAppDebug('🔔 [Alert] recipients:', recipients);
        logRoutineAppDebug('🔔 [Alert] URL:', `${apiBase}/alerts/send`);
        logRoutineAppDebug('🔔 [Alert] eventForAlert:', eventForAlert ? eventForAlert.flightNumber || eventForAlert.type : 'NOT FOUND');

        if (!recipients || recipients.length === 0) {
            console.warn('🔔 [Alert] No recipients - alert not sent');
            return false;
        }

        try {
            const payload = {
                date: snapshotDate,
                eventDate: date,
                school,
                unit: activeUnitCode,
                operationalModel: activeOperationalModel,
                eventId,
                sentBy: userId,
                recipients,
                description,
                eventDetails: eventForAlert ? {
                    flightNumber: eventForAlert.flightNumber,
                    startTime: eventForAlert.startTime,
                    duration: eventForAlert.duration,
                    resourceId: eventForAlert.resourceId,
                    instructor: eventForAlert.instructor,
                    student: eventForAlert.student,
                    pilot: eventForAlert.pilot,
                } : {},
            };

            logRoutineAppDebug('🔔 [Alert] Payload:', JSON.stringify(payload, null, 2));

            const res = await fetch(`${apiBase}/alerts/send`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });

            const responseText = await res.text();
            logRoutineAppDebug('🔔 [Alert] Response status:', res.status);
            logRoutineAppDebug('🔔 [Alert] Response body:', responseText);

            if (res.ok) {
                const data = JSON.parse(responseText);
                setAlertsDataByDate(prev => ({
                    ...prev,
                    [date]: {
                        ...(prev[date] || {}),
                        [eventId]: data.alertEntry || data,
                    },
                }));
                logRoutineAppDebug('🔔 [Alert] Alert sent successfully! alertId:', data.alertId);
                return true;
            } else {
                console.warn('🔔 [Alert] Failed to send alert. Status:', res.status, 'Body:', responseText);
                return false;
            }
        } catch (err) {
            console.error('🔔 [Alert] Exception sending alert:', err);
            return false;
        }
        finally {
            logRoutineAppDebug('🔔 [Alert] ========== SEND ALERT END ==========');
        }
    };

    // handleClearAlert - Clear alert history for an event to allow re-sending
    const handleClearAlert = async (eventId: string) => {
        if (isPastDfpDate(date)) {
            denyPastDfpEdit('clear alerts');
            return;
        }
        const apiBase = '/api';
        try {
            const res = await fetch(`${apiBase}/alerts/clear`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ eventId, date, clearedBy: getCurrentUserId() || currentUserName }),
            });
            if (res.ok) {
                // Remove from local state immediately
                setAlertsDataByDate(prev => {
                    const dateData = { ...(prev[date] || {}) };
                    delete dateData[eventId];
                    return { ...prev, [date]: dateData };
                });
                logRoutineAppDebug('🔔 [Alert] Alert cleared for event:', eventId);
            } else {
                console.warn('🔔 [Alert] Failed to clear alert:', res.status);
            }
        } catch (err) {
            console.error('🔔 [Alert] Exception clearing alert:', err);
        }
    };

    // Visual Adjust handlers
    const handleVisualAdjustStart = async (event: ScheduleEvent) => {
        logRoutineAppDebug('Visual Adjust Start - Event:', event);
        if (isPastDfpDate(event.date || date)) {
            denyPastDfpEdit('visually adjust tiles');
            return;
        }
        // System freeze check - prevent dragging when frozen
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. Dragging events is not permitted during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        setIsVisualAdjustMode(true);
        setVisualAdjustEvent(event);
        logRoutineAppDebug('Visual Adjust Mode set to true');
    };

    const handleVisualAdjustEnd = (event: ScheduleEvent) => {
        const finalEvent = visualAdjustEvent && visualAdjustEvent.id === event.id
            ? visualAdjustEvent
            : event;
        const eventDate = finalEvent.date || date;
        if (isPastDfpDate(eventDate)) {
            denyPastDfpEdit('visually adjust tiles');
            setIsVisualAdjustMode(false);
            setVisualAdjustEvent(null);
            return;
        }

        setPublishedSchedules(prev => {
            const scheduleForDate = prev[eventDate] || [];
            const updatedSchedule = scheduleForDate.map(e =>
                e.id === finalEvent.id ? finalEvent : e
            );
            persistScheduleForDate(eventDate, updatedSchedule);
            return { ...prev, [eventDate]: updatedSchedule };
        });

        setIsVisualAdjustMode(false);
        setVisualAdjustEvent(null);
        // Close the modal completely when visual adjust ends
        setSelectedEvent(null);
    };

    // Continuation/currency and remedial auto-add system.
    // Auto-adds high-priority continuation/currency and force-scheduled remedial events to the highest priority list.
    const syncPriorityEventsWithSctAndRemedial = () => {
        const continuationShortLabel = getSctTerminology(platformConfig, activeUnitCode).shortLabel;
        logRoutineAppDebug(`\ud83d\udccb Starting sync of priority events with ${continuationShortLabel} and remedial requests...`);

        let added = 0;
        const newPriorityEvents = [...highestPriorityEvents];
        const remedialPrioritySyncTrace: any[] = [];
        const remedialDataMovementTrace: any[] = [];
        const traceRemedialSyncMovement = (entry: Record<string, any>) => {
            remedialDataMovementTrace.push({
                sequence: remedialDataMovementTrace.length + 1,
                timestamp: new Date().toISOString(),
                ...entry,
            });
        };
        const buildSctEventNotes = (sctReq: SctRequest): string => {
            const noteLines: string[] = [];
            const existingNotes = String(sctReq.notes || '').trim();
            if (existingNotes) noteLines.push(existingNotes);
            if (String(sctReq.crewDisplayLabel || '').trim()) noteLines.push(`Crew: ${sctReq.crewDisplayLabel}`);
            if (String(sctReq.crewIndividual || '').trim()) noteLines.push(`Individual: ${sctReq.crewIndividual}`);
            if (String(sctReq.currency || '').trim()) noteLines.push(`Currency: ${sctReq.currency}`);
            if (Number(sctReq.aircraftCount) > 1) noteLines.push(`Aircraft requested: ${Math.floor(Number(sctReq.aircraftCount))}`);
            if (String(sctReq.currencyExpire || '').trim()) noteLines.push(`Currency Expire: ${sctReq.currencyExpire}`);
            if (String(sctReq.dateRequested || '').trim()) noteLines.push(`Date Requested: ${sctReq.dateRequested}`);
            if (String(sctReq.currencyExpire || '').trim()) {
                const expiry = new Date(`${sctReq.currencyExpire}T00:00:00Z`);
                const buildDate = new Date(`${buildDfpDate}T00:00:00Z`);
                if (!Number.isNaN(expiry.getTime()) && !Number.isNaN(buildDate.getTime())) {
                    const daysToExpire = Math.ceil((expiry.getTime() - buildDate.getTime()) / (1000 * 60 * 60 * 24));
                    noteLines.push(`Days to Expire: ${daysToExpire}`);
                }
            }
            return noteLines.join('\n');
        };
        const getSctCrewGroupKey = (sctReq: SctRequest): string => {
            const explicitKey = String(sctReq.crewGroupKey || '').trim();
            if (explicitKey) return explicitKey;
            const unitCode = String(sctReq.crewUnitCode || '').trim().toUpperCase();
            const crewGroup = String(sctReq.crewGroup || '').replace(/^CREW\s*/i, '').trim().toUpperCase();
            return unitCode && crewGroup ? `${unitCode}::${crewGroup}` : '';
        };
        const getSctCrewDisplayLabel = (sctReq: SctRequest): string => String(sctReq.crewDisplayLabel || '').trim();
        const getSctSelectedPerson = (sctReq: SctRequest): string => String(sctReq.crewIndividual || sctReq.name || '').trim();
        const getSctTileCrew = (sctReq: SctRequest): string => (
            getSctCrewDisplayLabel(sctReq)
            || (sctReq.flightType === 'Dual' ? String(sctReq.crewMember || '').trim() : '')
            || 'TBA'
        );
        const getSctCallsign = (sctReq: SctRequest): string => {
            const explicitCallsign = String(sctReq.callsign || '').trim();
            if (explicitCallsign) return explicitCallsign;
            const callsignBase = String(sctReq.callsignBase || '').trim();
            if (!callsignBase) return '';
            const callsignNumber = Number.isFinite(Number(sctReq.callsignNumber)) ? Number(sctReq.callsignNumber) : 0;
            return buildUnitEventCallsign(callsignBase, callsignNumber);
        };
        const getSctDayNight = (sctReq: SctRequest): 'Day' | 'Night' | 'Day/Night' => {
            const configured = sctReq.dayNight;
            if (configured === 'Night' || configured === 'Day/Night') return configured;
            if (/\bnight\b/i.test(String(sctReq.event || sctReq.eventCode || ''))) return 'Night';
            return 'Day';
        };
        const getSctAcceptableAircraftConfigs = (sctReq: SctRequest, fallbackConfigId: string): string[] => {
            const configured = Array.isArray(sctReq.acceptableAircraftConfigs)
                ? sctReq.acceptableAircraftConfigs.map(configId => String(configId || '').trim()).filter(Boolean)
                : [];
            return configured.length > 0 ? Array.from(new Set(configured)) : [fallbackConfigId];
        };
        const hasSctParticipant = (sctReq: SctRequest): boolean => Boolean(getSctSelectedPerson(sctReq) || getSctCrewDisplayLabel(sctReq));

        // 1. Auto-add high-priority continuation/currency requests and medium/low requests with includeInBuild=true.
        logRoutineAppDebug(`🔍 ${continuationShortLabel} Sync - buildDfpDate:`, buildDfpDate);
        const highPrioritySctFlights = sctFlights.filter(req =>
            (req.priority === 'High' || req.includeInBuild) && hasSctParticipant(req) && req.event.trim() !== ''
        );
        const highPrioritySctFtds = sctFtds.filter(req =>
            (req.priority === 'High' || req.includeInBuild) && hasSctParticipant(req) && req.event.trim() !== ''
        );
        logRoutineAppDebug(`🔍 Found ${continuationShortLabel} flights to include:`, highPrioritySctFlights.length, '| FTDs:', highPrioritySctFtds.length);
        const fixedCrewCurrencyEventDuration = isFixedCrewLikeOperationalModel(activeOperationalModel)
            ? FIXED_CREW_DEFAULT_CURRENCY_DURATION_HOURS
            : null;

        // Process continuation flights
        highPrioritySctFlights.forEach(sctReq => {
            const sctEventCode = String(sctReq.eventCode || sctReq.event || '').trim().toUpperCase().slice(0, 8) || sctReq.event;
            const sctCrewGroupKey = getSctCrewGroupKey(sctReq);
            const sctSelectedPerson = getSctSelectedPerson(sctReq);
            const sctTileCrew = getSctTileCrew(sctReq);
            const sctCallsign = getSctCallsign(sctReq);
            // Check both highestPriorityEvents AND nextDayBuildEvents for existing event
            const existingInPriorityIndex = newPriorityEvents.findIndex(e =>
                e.id === `sct-flight-${sctReq.id}`
            );
            const existingInNextDay = nextDayBuildEvents.find(e =>
                e.id === `sct-flight-${sctReq.id}`
            );

            if (existingInPriorityIndex > -1) {
                // Update existing event in priority list
                const syllabusItem = syllabusDetails.find(s => s.code === sctReq.event);
                const duration = fixedCrewCurrencyEventDuration ?? syllabusItem?.duration ?? 1.5;

                // Convert requested time to decimal hours
                let startTime = 8.0;
                if (sctReq.requestedTime) {
                    const [hours, minutes] = sctReq.requestedTime.split(':').map(Number);
                    startTime = hours + (minutes / 60);
                }

                // Update the existing event with new data from continuation request
                const aircraftConfigId = sctReq.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id;
                const acceptableAircraftConfigs = getSctAcceptableAircraftConfigs(sctReq, aircraftConfigId);
                newPriorityEvents[existingInPriorityIndex] = {
                    ...newPriorityEvents[existingInPriorityIndex],
                    student: sctReq.flightType === 'Dual' ? sctTileCrew : '',
                    pilot: sctSelectedPerson,
                    flightNumber: sctEventCode,
                    callsign: sctCallsign,
                    duration: duration,
                    startTime: startTime,
                    flightType: sctReq.flightType,
                    soloOrDual: sctReq.flightType,
                    sctRequestId: sctReq.id,
                    sctRequestType: 'flight',
                    currency: sctReq.currency,
                    notes: buildSctEventNotes(sctReq),
                    aircraftConfigId,
                    acceptableAircraftConfigs,
                    dayNight: getSctDayNight(sctReq),
                    fixedCrewGroup: sctCrewGroupKey || undefined,
                };
                logRoutineAppDebug(`🔄 Updated HIGH priority ${continuationShortLabel} flight:`, sctEventCode, 'for', sctReq.name, 'at', sctReq.requestedTime || '08:00');
            } else {
                if (existingInNextDay) {
                    setNextDayBuildEvents(prev => prev.filter(event => event.id !== `sct-flight-${sctReq.id}`));
                }
                const syllabusItem = syllabusDetails.find(s => s.code === sctReq.event);
                const trainee = allTraineesData.find(t => t.fullName === sctReq.name);
                const duration = fixedCrewCurrencyEventDuration ?? syllabusItem?.duration ?? 1.5;
                const aircraftConfigId = sctReq.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id;
                const acceptableAircraftConfigs = getSctAcceptableAircraftConfigs(sctReq, aircraftConfigId);

                // Convert requested time to decimal hours (e.g., "15:00" -> 15.0)
                let startTime = 8.0; // Default
                if (sctReq.requestedTime) {
                    const [hours, minutes] = sctReq.requestedTime.split(':').map(Number);
                    startTime = hours + (minutes / 60);
                }

                const newEvent: ScheduleEvent = {
                    id: `sct-flight-${sctReq.id}`,
                    date: buildDfpDate,
                    type: 'flight',
                    instructor: '', // Crew field - blank initially, can be selected
                    student: sctReq.flightType === 'Dual' ? sctTileCrew : '', // Fixed Crew tiles display the selected crew group.
                    pilot: sctSelectedPerson, // Optional selected individual/PIC candidate.
                    flightNumber: sctEventCode,
                    callsign: sctCallsign,
                    duration: duration,
                    startTime: startTime, // Use requested time
                    resourceId: '', // Will be assigned during scheduling
                    color: 'bg-gray-500/80', // continuation events use grey color (red is for conflicts)
                    flightType: sctReq.flightType,
                    soloOrDual: sctReq.flightType,
                    locationType: 'Local',
                    origin: school,
                    destination: school,
                    isTimeFixed: true,
                    isSct: true,
                    eventCategory: 'sct', // Saved compatibility category for continuation scheduling logic.
                    sctRequestId: sctReq.id,
                    sctRequestType: 'flight',
                    currency: sctReq.currency,
                    notes: buildSctEventNotes(sctReq),
                    aircraftConfigId,
                    acceptableAircraftConfigs,
                    dayNight: getSctDayNight(sctReq),
                    fixedCrewGroup: sctCrewGroupKey || undefined,
                };

                newPriorityEvents.push(newEvent);
                added++;
                logRoutineAppDebug(`\u2705 Added HIGH priority ${continuationShortLabel} flight:`, sctEventCode, 'for', sctReq.name, 'at', sctReq.requestedTime || '08:00');
                logRoutineAppDebug('  - Event date:', newEvent.date, '| isTimeFixed:', newEvent.isTimeFixed, '| startTime:', newEvent.startTime);
            }
        });

        // Process continuation/currency FTDs
        highPrioritySctFtds.forEach(sctReq => {
            const sctEventCode = String(sctReq.eventCode || sctReq.event || '').trim().toUpperCase().slice(0, 8) || sctReq.event;
            const sctCrewGroupKey = getSctCrewGroupKey(sctReq);
            const sctSelectedPerson = getSctSelectedPerson(sctReq);
            const sctTileCrew = getSctTileCrew(sctReq);
            const sctCallsign = getSctCallsign(sctReq);
            // Check both highestPriorityEvents AND nextDayBuildEvents for existing event
            const existingInPriorityIndex = newPriorityEvents.findIndex(e =>
                e.id === `sct-ftd-${sctReq.id}`
            );
            const existingInNextDay = nextDayBuildEvents.find(e =>
                e.id === `sct-ftd-${sctReq.id}`
            );

            if (existingInPriorityIndex > -1) {
                // Update existing event in priority list
                const syllabusItem = syllabusDetails.find(s => s.code === sctReq.event);
                const duration = fixedCrewCurrencyEventDuration ?? syllabusItem?.duration ?? 1.5;

                // Convert requested time to decimal hours
                let startTime = 8.0;
                if (sctReq.requestedTime) {
                    const [hours, minutes] = sctReq.requestedTime.split(':').map(Number);
                    startTime = hours + (minutes / 60);
                }

                // Update the existing event with new data from continuation request
                const aircraftConfigId = sctReq.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id;
                const acceptableAircraftConfigs = getSctAcceptableAircraftConfigs(sctReq, aircraftConfigId);
                newPriorityEvents[existingInPriorityIndex] = {
                    ...newPriorityEvents[existingInPriorityIndex],
                    student: sctReq.flightType === 'Dual' ? sctTileCrew : '',
                    pilot: sctSelectedPerson,
                    flightNumber: sctEventCode,
                    callsign: sctCallsign,
                    duration: duration,
                    startTime: startTime,
                    flightType: 'Dual',
                    soloOrDual: 'Dual',
                    sctRequestId: sctReq.id,
                    sctRequestType: 'ftd',
                    currency: sctReq.currency,
                    notes: buildSctEventNotes(sctReq),
                    aircraftConfigId,
                    acceptableAircraftConfigs,
                    dayNight: getSctDayNight(sctReq),
                    fixedCrewGroup: sctCrewGroupKey || undefined,
                };
                logRoutineAppDebug(`🔄 Updated HIGH priority ${continuationShortLabel} FTD:`, sctEventCode, 'for', sctReq.name, 'at', sctReq.requestedTime || '08:00');
            } else {
                if (existingInNextDay) {
                    setNextDayBuildEvents(prev => prev.filter(event => event.id !== `sct-ftd-${sctReq.id}`));
                }
                const syllabusItem = syllabusDetails.find(s => s.code === sctReq.event);
                const trainee = allTraineesData.find(t => t.fullName === sctReq.name);
                const duration = fixedCrewCurrencyEventDuration ?? syllabusItem?.duration ?? 1.5;
                const aircraftConfigId = sctReq.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id;
                const acceptableAircraftConfigs = getSctAcceptableAircraftConfigs(sctReq, aircraftConfigId);

                // Convert requested time to decimal hours (e.g., "15:00" -> 15.0)
                let startTime = 8.0; // Default
                if (sctReq.requestedTime) {
                    const [hours, minutes] = sctReq.requestedTime.split(':').map(Number);
                    startTime = hours + (minutes / 60);
                }

                const newEvent: ScheduleEvent = {
                    id: `sct-ftd-${sctReq.id}`,
                    date: buildDfpDate,
                    type: 'ftd',
                    instructor: '', // Crew field - blank initially, can be selected
                    student: sctReq.flightType === 'Dual' ? sctTileCrew : '', // Fixed Crew tiles display the selected crew group.
                    pilot: sctSelectedPerson, // Optional selected individual/PIC candidate.
                    flightNumber: sctEventCode,
                    callsign: sctCallsign,
                    duration: duration,
                    startTime: startTime, // Use requested time
                    resourceId: '', // Will be assigned during scheduling
                    color: 'bg-gray-500/80', // continuation events use grey color (red is for conflicts)
                    flightType: 'Dual',
                    soloOrDual: 'Dual',
                    locationType: 'Local',
                    origin: school,
                    destination: school,
                    isTimeFixed: true,
                    isSct: true,
                    eventCategory: 'sct', // Saved compatibility category for continuation scheduling logic.
                    sctRequestId: sctReq.id,
                    sctRequestType: 'ftd',
                    currency: sctReq.currency,
                    notes: buildSctEventNotes(sctReq),
                    aircraftConfigId,
                    acceptableAircraftConfigs,
                    dayNight: getSctDayNight(sctReq),
                    fixedCrewGroup: sctCrewGroupKey || undefined,
                };
                logRoutineAppDebug(`\u2705 Added HIGH priority ${continuationShortLabel} FTD:`, sctEventCode, 'for', sctReq.name, 'at', sctReq.requestedTime || '08:00');
                logRoutineAppDebug('  - Event date:', newEvent.date, '| isTimeFixed:', newEvent.isTimeFixed, '| startTime:', newEvent.startTime);

                newPriorityEvents.push(newEvent);
                added++;
            }
        });

        // 2. Auto-add Force Schedule remedial events
        const storedRemedialRequests = loadStoredRemedialRequests();
        const remedialRequestsForSync = remedialRequests.length > 0 ? remedialRequests : storedRemedialRequests;
        traceRemedialSyncMovement({
            phase: 'pre-build-sync-source-summary',
            buildDate: buildDfpDate,
            inMemoryRemedialRequests: remedialRequests.length,
            inMemoryForcedRemedialRequests: remedialRequests.filter(r => r.forceSchedule).length,
            storedRemedialRequests: storedRemedialRequests.length,
            storedForcedRemedialRequests: storedRemedialRequests.filter(r => r.forceSchedule).length,
            selectedSource: remedialRequests.length > 0 ? 'react-state' : storedRemedialRequests.length > 0 ? 'localStorage-fallback' : 'none',
            selectedRequestsForSync: remedialRequestsForSync.length,
            highestPriorityBeforeSync: highestPriorityEvents.length,
            remedialHighestPriorityBeforeSync: highestPriorityEvents.filter(e => e.isRemedial || e.id?.startsWith('remedial-')).length,
            nextDayBuildEventsBeforeSync: nextDayBuildEvents.length,
        });
        logRoutineAppDebug(`🔍 Checking ${remedialRequestsForSync.length} remedial requests for Force Schedule...`);
        if (remedialRequests.length === 0 && storedRemedialRequests.length > 0) {
            logRoutineAppDebug(`📦 Using ${storedRemedialRequests.length} persisted Force Schedule remedial request(s) for pre-build sync`);
        }
        const forceScheduledRemedials = remedialRequestsForSync.filter(r => r.forceSchedule);
        logRoutineAppDebug(`📌 Found ${forceScheduledRemedials.length} Force Scheduled remedial events`);

        remedialRequestsForSync.forEach(remedialReq => {
            if (!remedialReq.forceSchedule) {
                traceRemedialSyncMovement({
                    phase: 'remedial-request-skipped-before-priority-sync',
                    traineeId: remedialReq.traineeId,
                    eventCode: remedialReq.eventCode,
                    forceSchedule: remedialReq.forceSchedule,
                    outcome: 'skipped',
                    reason: 'FORCE_SCHEDULE_FALSE',
                });
                remedialPrioritySyncTrace.push({
                    phase: 'remedial-request-skipped',
                    traineeId: remedialReq.traineeId,
                    eventCode: remedialReq.eventCode,
                    forceSchedule: remedialReq.forceSchedule,
                    reason: 'FORCE_SCHEDULE_FALSE',
                });
                return;
            }
            if (remedialReq.forceSchedule) {
                logRoutineAppDebug(`🔎 Processing Force Schedule remedial: traineeId=${remedialReq.traineeId}, eventCode=${remedialReq.eventCode}`);

                const remedialPriorityEventId = `remedial-${remedialReq.traineeId}-${remedialReq.eventCode}`;
                const existingEventIndex = newPriorityEvents.findIndex(e =>
                    e.id === remedialPriorityEventId
                );
                const existingEvent = existingEventIndex >= 0 ? newPriorityEvents[existingEventIndex] : null;

                // For remedial events, look in the trainee's Individual LMP first, then fallback to master syllabus.
                // The Individual LMP is authoritative for inserted remedial details such as Day/Night and assigned instructor.
                const trainee = allTraineesData.find(t => t.idNumber === remedialReq.traineeId);
                let syllabusItem: SyllabusItemDetail | null = null;
                let syllabusSource: 'individual-lmp' | 'master-syllabus' | 'not-found' = 'not-found';
                let individualLmpLength: number | null = null;

                if (trainee) {
                    const individualLMP = traineeLMPs.get(trainee.fullName);
                    individualLmpLength = individualLMP?.length ?? null;
                    if (individualLMP) {
                        syllabusItem = individualLMP.find(s => s.id === remedialReq.eventCode || s.code === remedialReq.eventCode) || null;
                        if (syllabusItem) {
                            syllabusSource = 'individual-lmp';
                            logRoutineAppDebug(`✅ Found remedial event in Individual LMP: ${remedialReq.eventCode}`);
                        }
                    }
                }

                if (!syllabusItem) {
                    syllabusItem = syllabusDetails.find(s => s.id === remedialReq.eventCode || s.code === remedialReq.eventCode) || null;
                    if (syllabusItem) {
                        syllabusSource = 'master-syllabus';
                        logRoutineAppDebug(`✅ Found event in master syllabus: ${remedialReq.eventCode}`);
                    }
                }

                const duration = syllabusItem?.duration || 1.5;
                const mappedScheduleType = syllabusItem?.type === 'FTD' ? 'ftd' :
                    syllabusItem?.type === 'Ground School' ? 'ground' :
                    syllabusItem?.type === 'Flight' ? 'flight' : null;
                const remedialAircraftConfigId = remedialReq.aircraftConfigId || BASE_AIRCRAFT_CONFIG.id;
                const allocatedInstructor = syllabusItem?.resourcesHuman && syllabusItem.resourcesHuman.length > 0
                    ? syllabusItem.resourcesHuman[0]
                    : existingEvent?.instructor || '';
                traceRemedialSyncMovement({
                    phase: existingEvent ? 'force-remedial-refresh-lookup' : 'force-remedial-create-lookup',
                    traineeId: remedialReq.traineeId,
                    eventCode: remedialReq.eventCode,
                    priorityEventId: remedialPriorityEventId,
                    existingPriorityEvent: !!existingEvent,
                    traineeFound: !!trainee,
                    traineeName: trainee?.fullName || null,
                    traineeCourse: trainee?.course || null,
                    individualLmpLength,
                    syllabusFound: !!syllabusItem,
                    syllabusSource,
                    syllabusId: syllabusItem?.id || null,
                    syllabusCode: syllabusItem?.code || null,
                    rawSyllabusType: syllabusItem?.type || null,
                    mappedScheduleType,
                    isGroundOrTutorial: mappedScheduleType === 'ground',
                    methodOfDelivery: syllabusItem?.methodOfDelivery || [],
                    dayNight: syllabusItem?.dayNight || null,
                    duration,
                    resourcesHuman: syllabusItem?.resourcesHuman || [],
                    allocatedInstructor,
                    expectedOutcome: trainee && syllabusItem
                        ? existingEvent ? 'refresh-existing-highest-priority-event' : 'create-highest-priority-event'
                        : 'skip-missing-trainee-or-syllabus',
                });
                remedialPrioritySyncTrace.push({
                    phase: existingEvent ? 'force-remedial-refresh-check' : 'force-remedial-create-check',
                    traineeId: remedialReq.traineeId,
                    eventCode: remedialReq.eventCode,
                    priorityEventId: remedialPriorityEventId,
                    existingPriorityEvent: !!existingEvent,
                    traineeFound: !!trainee,
                    traineeName: trainee?.fullName || null,
                    traineeCourse: trainee?.course || null,
                    individualLmpLength,
                    syllabusFound: !!syllabusItem,
                    syllabusSource,
                    syllabusId: syllabusItem?.id || null,
                    syllabusCode: syllabusItem?.code || null,
                    rawSyllabusType: syllabusItem?.type || null,
                    mappedScheduleType,
                    methodOfDelivery: syllabusItem?.methodOfDelivery || [],
                    dayNight: syllabusItem?.dayNight || null,
                    duration,
                    preFlightTime: syllabusItem?.preFlightTime ?? null,
                    postFlightTime: syllabusItem?.postFlightTime ?? null,
                    resourcesHuman: syllabusItem?.resourcesHuman || [],
                    allocatedInstructor,
                    resourceNumber: syllabusItem?.resourceNumber ?? null,
                    prerequisites: syllabusItem?.prerequisites || [],
                    expectedOutcome: trainee && syllabusItem
                        ? existingEvent ? 'REFRESH_EXISTING_PRIORITY_EVENT' : 'CREATE_PRIORITY_EVENT'
                        : 'SKIP_MISSING_TRAINEE_OR_SYLLABUS',
                });

                if (existingEvent) {
                    if (trainee && syllabusItem) {
                        newPriorityEvents[existingEventIndex] = {
                            ...existingEvent,
                            type: syllabusItem.type === 'FTD' ? 'ftd' :
                                  syllabusItem.type === 'Ground School' ? 'ground' :
                                  syllabusItem.type === 'Flight' ? 'flight' : existingEvent.type,
                            instructor: allocatedInstructor,
                            pilot: existingEvent.pilot || allocatedInstructor,
                            student: trainee.fullName,
                            flightNumber: syllabusItem.code,
                            duration,
                            flightType: syllabusItem.sortieType === 'Solo' ? 'Solo' : 'Dual',
                            dayNight: syllabusItem.dayNight,
                            preStart: syllabusItem.preFlightTime,
                            postEnd: syllabusItem.postFlightTime,
                            isRemedial: true,
                            isTimeFixed: true,
                            ...(syllabusItem.type === 'Flight' ? {
                                aircraftConfigId: remedialAircraftConfigId,
                                acceptableAircraftConfigs: [remedialAircraftConfigId],
                            } : {}),
                        };
                        traceRemedialSyncMovement({
                            phase: 'highest-priority-remedial-refreshed',
                            traineeId: remedialReq.traineeId,
                            eventCode: remedialReq.eventCode,
                            priorityEventId: remedialPriorityEventId,
                            type: newPriorityEvents[existingEventIndex].type,
                            startTime: newPriorityEvents[existingEventIndex].startTime,
                            date: newPriorityEvents[existingEventIndex].date,
                            isTimeFixed: newPriorityEvents[existingEventIndex].isTimeFixed === true,
                            isRemedial: newPriorityEvents[existingEventIndex].isRemedial === true,
                            outcome: 'refreshed-existing-highest-priority-event',
                            nextHandoff: 'runBuildAlgorithm.highestPriorityEvents',
                        });
                        logRoutineAppDebug(`🔄 Refreshed Force Schedule remedial from Individual LMP: ${syllabusItem.code} for ${trainee.fullName}`);
                    } else {
                        traceRemedialSyncMovement({
                            phase: 'highest-priority-remedial-refresh-skipped',
                            traineeId: remedialReq.traineeId,
                            eventCode: remedialReq.eventCode,
                            priorityEventId: remedialPriorityEventId,
                            outcome: 'skipped',
                            reason: !trainee ? 'TRAINEE_NOT_FOUND' : 'SYLLABUS_ITEM_NOT_FOUND',
                        });
                        logRoutineAppDebug(`⚠️ Event already exists in priority list but current LMP details were not found: ${remedialReq.eventCode} for trainee ${remedialReq.traineeId}`);
                    }
                } else if (!existingEvent) {
                    if (!syllabusItem) {
                        console.error(`❌ Event not found in Individual LMP or master syllabus: ${remedialReq.eventCode}`);
                    }
                    if (!trainee) {
                        console.error(`❌ Trainee not found for ID: ${remedialReq.traineeId}`);
                    }

                    if (trainee && syllabusItem) {
                        // CRITICAL FIX: Get allocated instructor from remedial package
                        logRoutineAppDebug(`📋 Allocated instructor for ${syllabusItem.code}: ${allocatedInstructor || 'None'}`);

                        const newEvent: ScheduleEvent = {
                            id: remedialPriorityEventId,
                            date: buildDfpDate,
                            type: syllabusItem.type === 'FTD' ? 'ftd' :
                                  syllabusItem.type === 'Ground School' ? 'ground' :
                                  syllabusItem.type === 'Flight' ? 'flight' : 'flight',
                            instructor: allocatedInstructor, // Use allocated instructor from remedial package
                            student: trainee.fullName,
                            flightNumber: syllabusItem.code,
                            duration: duration,
                            startTime: REMEDIAL_EARLIEST_START,
                            resourceId: '', // Will be assigned during scheduling
                            color: courseColors[trainee.course] || 'bg-gray-500',
                            flightType: syllabusItem.sortieType === 'Solo' ? 'Solo' : 'Dual',
                            dayNight: syllabusItem.dayNight,
                            locationType: 'Local',
                            origin: school,
                            destination: school,
                            preStart: syllabusItem.preFlightTime,
                            postEnd: syllabusItem.postFlightTime,
                            isTimeFixed: true,
                            isRemedial: true,
                            ...(syllabusItem.type === 'Flight' ? {
                                aircraftConfigId: remedialAircraftConfigId,
                                acceptableAircraftConfigs: [remedialAircraftConfigId],
                            } : {}),
                        };

                        newPriorityEvents.push(newEvent);
                        traceRemedialSyncMovement({
                            phase: 'highest-priority-remedial-created',
                            traineeId: remedialReq.traineeId,
                            traineeName: trainee.fullName,
                            eventCode: remedialReq.eventCode,
                            priorityEventId: remedialPriorityEventId,
                            createdEvent: {
                                id: newEvent.id,
                                date: newEvent.date,
                                type: newEvent.type,
                                flightNumber: newEvent.flightNumber,
                                instructor: newEvent.instructor || null,
                                student: newEvent.student || null,
                                duration: newEvent.duration,
                                startTime: newEvent.startTime,
                                resourceId: newEvent.resourceId || null,
                                isTimeFixed: newEvent.isTimeFixed === true,
                                isRemedial: newEvent.isRemedial === true,
                            },
                            outcome: 'created-highest-priority-event',
                            nextHandoff: 'runBuildAlgorithm.highestPriorityEvents',
                        });
                        added++;
                        logRoutineAppDebug('\u2705 Added Force Schedule remedial:', syllabusItem.code, 'for', trainee.fullName);
                    } else {
                        traceRemedialSyncMovement({
                            phase: 'highest-priority-remedial-create-skipped',
                            traineeId: remedialReq.traineeId,
                            eventCode: remedialReq.eventCode,
                            priorityEventId: remedialPriorityEventId,
                            outcome: 'skipped',
                            reason: !trainee ? 'TRAINEE_NOT_FOUND' : 'SYLLABUS_ITEM_NOT_FOUND',
                        });
                    }
                }
            }
        });

        // Always update state if there are any changes (additions or updates)
        const hasChanges = added > 0 || JSON.stringify(newPriorityEvents) !== JSON.stringify(highestPriorityEvents);

        if (hasChanges) {
            setHighestPriorityEvents(newPriorityEvents);
            if (added > 0) {
                logRoutineAppDebug(`\\ud83d\\udcca Priority Events Sync Complete: Added ${added} auto-generated events`);
            } else {
                logRoutineAppDebug('\\ud83d\\udd04 Priority Events Sync Complete: Updated existing events');
            }
        } else {
            logRoutineAppDebug('\\u2705 No changes to priority events');
        }
        traceRemedialSyncMovement({
            phase: 'pre-build-sync-complete',
            buildDate: buildDfpDate,
            highestPriorityAfterSync: newPriorityEvents.length,
            remedialHighestPriorityAfterSync: newPriorityEvents.filter(e => e.isRemedial || e.id?.startsWith('remedial-')).length,
            addedAutoGeneratedEvents: added,
            stateWillBeUpdated: hasChanges,
        });

        try {
            (window as any).__lastRemedialPrioritySyncTrace = remedialPrioritySyncTrace;
            (window as any).__lastRemedialDataMovementTrace = remedialDataMovementTrace;
            localStorage.setItem('remedial_priority_sync_diag', JSON.stringify({
                timestamp: new Date().toISOString(),
                buildDate: buildDfpDate,
                trace: remedialPrioritySyncTrace,
                dataMovementTrace: remedialDataMovementTrace,
            }));
        } catch (error) {
            console.warn('[REMEDIAL-SYNC-DIAG] Failed to save remedial sync diagnostics:', error);
        }

        // CRITICAL: Return the updated events so they can be used immediately
        return newPriorityEvents;









        return newPriorityEvents;

    };
    // Training report sync system.
    // Syncs training report assessments with Active DFP events.
    const syncPt051WithActiveDfp = (currentPublishedSchedules?: Record<string, ScheduleEvent[]>, currentPt051Assessments?: Map<string, Pt051Assessment>) => {
        // Use provided parameters or fall back to current state
        const schedules = currentPublishedSchedules || publishedSchedules;
        const assessments = currentPt051Assessments || pt051Assessments;

        logRoutineAppDebug('🔄 Starting training report sync with Active DFP...');
        logRoutineAppDebug('Published schedules keys:', Object.keys(schedules));

        // Get all events from Active DFP (published schedules only)
        const activeDfpEvents: ScheduleEvent[] = [];
        Object.values(schedules).forEach(scheduleEvents => {
            activeDfpEvents.push(...scheduleEvents);
        });

        logRoutineAppDebug('Total events on Active DFP:', activeDfpEvents.length);
        logRoutineAppDebug('Current training report count:', assessments.size);
        logRoutineAppDebug('Sample events:', activeDfpEvents.slice(0, 3).map(e => ({
            id: e.id,
            flightNumber: e.flightNumber,
            date: e.date,
            student: e.student,
            pilot: e.pilot,
            instructor: e.instructor
        })));

        const newAssessments = new Map(assessments);
        let created = 0;
        let deleted = 0;
        const processedPt051LogicalKeys = new Set<string>();

        // FORWARD CHECK: Create training reports for events that don't have them.
        activeDfpEvents.forEach(event => {
            // Skip DUTY SUP events
            const isDutySup = event?.flightNumber?.includes('Duty Sup');

            // Skip events on STBY line (both by flight number and resource allocation)
            const isStbyFlightNumber = event?.flightNumber?.toUpperCase().includes('STBY');
            const isStbyResource = event?.resourceId?.startsWith('STBY') ||
                                   event?.resourceId?.startsWith('BNF-STBY');

            // Skip deployment events
            const isDeployment = event?.type === 'deployment';

            // Include flight, FTD, ground, and CPT events for training report creation.
            const isValidEventType = event?.type === 'flight' ||
                                    event?.type === 'ftd' ||
                                    event?.type === 'ground' ||
                                    event?.type === 'cpt';

            if (isDutySup || isStbyFlightNumber || isStbyResource || isDeployment || !isValidEventType) {
                logRoutineAppDebug('⏭️ Skipping event:', {
                    flightNumber: event?.flightNumber,
                    type: event?.type,
                    resourceId: event?.resourceId,
                    date: event?.date,
                    reason: isDutySup ? 'DUTY SUP' :
                           isStbyFlightNumber || isStbyResource ? 'STBY allocation' :
                           isDeployment ? 'Deployment' : 'Invalid event type'
                });
                return;
            }

            // Get trainees on this event
            const trainees: string[] = [];
            if (event.student) trainees.push(event.student);
            if (event.pilot && event.flightType === 'Solo') trainees.push(event.pilot);
            if (event.attendees && Array.isArray(event.attendees)) {
                trainees.push(...event.attendees);
            }

            // Log event types being processed for training report creation.
            if (trainees.length > 0) {
                logRoutineAppDebug(`📋 Processing ${event.type} event for training report:`, {
                    flightNumber: event.flightNumber,
                    type: event.type,
                    date: event.date,
                    trainees: trainees
                });
            }

            // For each trainee, check if a training report exists.
            trainees.forEach(traineeFullName => {
                const logicalAssessmentKey = `${event.date}|||${event.flightNumber}|||${traineeFullName}`;
                if (processedPt051LogicalKeys.has(logicalAssessmentKey)) {
                    return;
                }
                processedPt051LogicalKeys.add(logicalAssessmentKey);
                const assessmentKey = `${event.id}-${traineeFullName}`;

                // Check if a training report already exists for this event-trainee combination.
                const existingAssessment = Array.from(newAssessments.values()).find(
                    a => a.eventId === event.id && a.traineeFullName === traineeFullName
                );

                if (!existingAssessment) {
                    // DEDUP CHECK: If same date + flightNumber + trainee already has an unassessed report.
                    // (none of DCO/DNCO/DPCO result checked, i.e. overallResult is null/empty)
                    // → remove the old placeholder and replace with new event details
                    // Historical events can legitimately repeat the same flightNumber for the same trainee
                    // on different dates, so date must be part of this check.
                    const existingUnassessedForFlight = Array.from(newAssessments.values()).find(
                        (a: Pt051Assessment) => a.traineeFullName === traineeFullName &&
                            a.flightNumber === event.flightNumber &&
                            a.date === event.date &&
                            (a.overallResult === null || a.overallResult === undefined || a.overallResult === '')
                    );
                    if (existingUnassessedForFlight) {
                        newAssessments.delete(existingUnassessedForFlight.id);
                        logRoutineAppDebug('🔄 Replacing unassessed training report for', traineeFullName, 'on', event.flightNumber, '- overwriting with rescheduled event details');
                    }

                    // Create new report, either fresh or replacing the old unassessed one.
                    const newAssessment: Pt051Assessment = {
                        id: `pt051-${assessmentKey}`,
                        traineeFullName: traineeFullName,
                        eventId: event.id,
                        flightNumber: event.flightNumber,
                        date: event.date,
                        instructorName: event.instructor || '',
                        overallGrade: null,
                        overallResult: null,
                        dcoResult: null,
                        overallComments: '',
                        isCompleted: false,
                        scores: ALL_ELEMENTS.map(element => ({
                            element,
                            grade: null,
                            comment: ''
                        }))
                    };

                    newAssessments.set(newAssessment.id, newAssessment);
                    created++;
                    logRoutineAppDebug('✅ Created training report for', traineeFullName, 'on', event.flightNumber, event.date);
                }
            });
        });

        // UPDATE CHECK: Update existing training reports when event details change.
        let updated = 0;
        newAssessments.forEach((assessment, assessmentId) => {
            // Find the corresponding event for this assessment
            const correspondingEvent = activeDfpEvents.find(e => e.id === assessment.eventId);

            if (correspondingEvent) {
                // Check if any fields need updating
                let needsUpdate = false;
                const updates: Partial<Pt051Assessment> = {};

                if (assessment.instructorName !== (correspondingEvent.instructor || '')) {
                    updates.instructorName = correspondingEvent.instructor || '';
                    needsUpdate = true;
                    logRoutineAppDebug('📝 Instructor changed:', assessment.instructorName, '→', correspondingEvent.instructor);
                }

                if (assessment.flightNumber !== correspondingEvent.flightNumber) {
                    updates.flightNumber = correspondingEvent.flightNumber;
                    needsUpdate = true;
                    logRoutineAppDebug('📝 Flight number changed:', assessment.flightNumber, '→', correspondingEvent.flightNumber);
                }

                if (assessment.date !== correspondingEvent.date) {
                    updates.date = correspondingEvent.date;
                    needsUpdate = true;
                    logRoutineAppDebug('📝 Date changed:', assessment.date, '→', correspondingEvent.date);
                }

                if (needsUpdate) {
                    newAssessments.set(assessmentId, { ...assessment, ...updates });
                    updated++;
                    logRoutineAppDebug('✏️ Updated training report for', assessment.traineeFullName, 'on', assessment.flightNumber);
                }
            }
        });

        // REVERSE CHECK: Delete reports whose events no longer exist on Active DFP.
        const activeDfpEventIds = new Set(activeDfpEvents.map(e => e.id));
        const assessmentsToDelete: string[] = [];

        newAssessments.forEach((assessment, assessmentId) => {
            if (!activeDfpEventIds.has(assessment.eventId)) {
                assessmentsToDelete.push(assessmentId);
                logRoutineAppDebug('🗑️ Deleting training report for', assessment.traineeFullName, 'on', assessment.flightNumber, assessment.date, '(event no longer on Active DFP)');
            }
        });

        assessmentsToDelete.forEach(id => {
            newAssessments.delete(id);
            deleted++;
        });

        // DUPLICATE CLEANUP: Remove duplicate unassessed reports for same date + flightNumber + trainee,
        // while preserving legitimate repeats of the same event code on different dates.
        // Handles existing duplicates from
        // rescheduled events created before the dedup logic was added.
        const dupCleanupMap = new Map<string, Pt051Assessment[]>();
        newAssessments.forEach((assessment) => {
            if (assessment.overallResult === null || assessment.overallResult === undefined || assessment.overallResult === '') {
                const dupKey = `${assessment.date}|||${assessment.flightNumber}|||${assessment.traineeFullName}`;
                if (!dupCleanupMap.has(dupKey)) {
                    dupCleanupMap.set(dupKey, []);
                }
                dupCleanupMap.get(dupKey)!.push(assessment);
            }
        });
        let dupDeleted = 0;
        dupCleanupMap.forEach((dupes) => {
            if (dupes.length > 1) {
                dupes.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
                dupes.slice(1).forEach(old => {
                    newAssessments.delete(old.id);
                    dupDeleted++;
                    logRoutineAppDebug('🧹 Removed duplicate unassessed training report for', old.traineeFullName, 'on', old.flightNumber, old.date);
                });
            }
        });

        // Update state if changes were made
        if (created > 0 || deleted > 0 || updated > 0 || dupDeleted > 0) {
            setPt051Assessments(newAssessments);
            logRoutineAppDebug(`📊 Training report sync complete: Created ${created}, Updated ${updated}, Deleted ${deleted}, Duplicates removed ${dupDeleted}`);
        } else {
            logRoutineAppDebug('✅ Training reports already in sync with Active DFP');
        }
    };

    const handleUpdatePriorityEvent = (eventId: string, updates: Partial<ScheduleEvent>) => {
        setHighestPriorityEvents(prevEvents =>
            prevEvents.map(event =>
                event.id === eventId ? { ...event, ...updates } : event
            )
        );
    };

    const handleDeletePriorityEvent = async (eventId: string) => {
        // System freeze check
        const _freezeRaw2 = localStorage.getItem('systemFreezeState');
        if (_freezeRaw2) {
            const _freeze2 = JSON.parse(_freezeRaw2);
            if (_freeze2.isFrozen) {
                showDarkAlert('System is currently frozen. No modifications are allowed during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        setHighestPriorityEvents(prevEvents =>
            prevEvents.filter(event => event.id !== eventId)
        );
        logRoutineAppDebug('🗑️ Deleted priority event:', eventId);
    };

    const handleSelectInstructorFromSchedule = (instructorName: string) => {
        const instructor = instructorsData.find(i => i.name === instructorName);
        if (instructor) {
            setSelectedPersonForProfile(instructor);
            handleNavigation('Instructors');
        }
    };

    const handleSelectTraineeFromSchedule = (traineeFullName: string) => {
        const trainee = allTraineesData.find(t => t.fullName === traineeFullName);
        if (trainee) {
            setSelectedPersonForProfile(trainee);
            handleNavigation('CourseRoster');
        }
    };

    const showFixedCrewCrewChoiceModal = (
        eventLabel: string,
        picName: string,
        crews: { key: string; label: string }[]
    ): Promise<{ mode: 'crew'; crewKey: string } | { mode: 'random' } | null> => (
        new Promise(resolve => {
            setFixedCrewCrewChoiceModal({
                eventLabel,
                picName,
                crews,
                selectedMode: 'random',
                selectedCrewKey: '',
                onResolve: choice => {
                    setFixedCrewCrewChoiceModal(null);
                    resolve(choice);
                },
            });
        })
    );

    const resolveFixedCrewPicPriorityEventsWithoutCrew = async (events: ScheduleEvent[]): Promise<ScheduleEvent[] | null> => {
        if (!isFixedCrewLikeOperationalModel(activeOperationalModel)) return events;

        const normalisePromptUnitCode = (value?: string | null): string => String(value || '').trim().toUpperCase();
        const normalisePromptCrewKey = (value?: string | null): string => String(value || '').replace(/^CREW\s*/i, '').trim().toUpperCase();
        const formatPromptCrewLabel = (unitCode: string, crewKey: string): string => (
            unitCode ? `CREW ${crewKey}/${unitCode}` : `CREW ${crewKey}`
        );
        const eventMatchesBuildDate = (event: ScheduleEvent): boolean => {
            const eventDate = String(event.date || '').trim();
            return !eventDate || eventDate === buildDfpDate;
        };
        const isPromptCurrencyPriority = (event: ScheduleEvent): boolean => (
            event.eventCategory === 'currency' || !!event.currencyDraftId || event.flightNumber === 'CURR'
        );
        const isPromptTaskingPriority = (event: ScheduleEvent): boolean => (
            event.isTaskingRequest === true || !!event.taskingRequestId || String(event.id || '').startsWith('tasking-')
        );
        const getEventPicName = (event: ScheduleEvent): string => (
            String(event.fixedCrewPic || event.pilot || event.instructor || '').trim()
        );
        const hasAssignedCrew = (event: ScheduleEvent): boolean => (
            Boolean(String(event.fixedCrewGroup || '').trim())
        );
        const activeUnitSet = activeContextUnitCodeSet.size > 0
            ? activeContextUnitCodeSet
            : new Set(activeContextUnitCodes.length > 0 ? activeContextUnitCodes : [activeUnitCode]);
        const crewGroups = new Map<string, { key: string; unit: string; crew: string; label: string; members: Instructor[] }>();

        instructorsData
            .filter(staff => Boolean(staff.name) && !staff.isAdminStaff)
            .filter(staff => {
                const unitCode = normalisePromptUnitCode(staff.unit);
                return activeUnitSet.size === 0 || !unitCode || activeUnitSet.has(unitCode);
            })
            .forEach(staff => {
                const unitCode = normalisePromptUnitCode(staff.unit);
                const crewKey = normalisePromptCrewKey(staff.crew);
                if (!crewKey) return;
                const groupKey = unitCode ? `${unitCode}::${crewKey}` : crewKey;
                if (!crewGroups.has(groupKey)) {
                    crewGroups.set(groupKey, {
                        key: groupKey,
                        unit: unitCode,
                        crew: crewKey,
                        label: formatPromptCrewLabel(unitCode, crewKey),
                        members: [],
                    });
                }
                crewGroups.get(groupKey)!.members.push(staff);
            });

        const replacements = new Map<string, ScheduleEvent>();

        for (const event of events) {
            if (!eventMatchesBuildDate(event)) continue;
            if (!isPromptCurrencyPriority(event) && !isPromptTaskingPriority(event)) continue;
            if (hasAssignedCrew(event)) continue;

            const picName = getEventPicName(event);
            if (!picName || isPlaceholderPersonnelName(picName) || /^CREW\b/i.test(picName)) continue;

            const picStaff = instructorsData.find(staff => personnelNamesMatch(staff.name, picName));
            const eventUnit = normalisePromptUnitCode((event as any).fixedCrewUnit || (event as any).unit || picStaff?.unit || activeUnitCode);
            const sameUnitCrews = Array.from(crewGroups.values())
                .filter(group => !eventUnit || group.unit === eventUnit)
                .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true }));

            if (sameUnitCrews.length === 0) {
                showDarkAlert(
                    `${event.flightNumber || event.taskingName || 'Priority event'} has PIC ${picName}, but no same-unit crews are available to assign. Assign a crew in Build Planner or update the staff crew assignments before running NEO Build.`,
                    'Crew Required',
                    'warning'
                );
                return null;
            }

            const eventLabel = String(event.taskingName || event.taskingDisplayLabel || event.flightNumber || event.id || 'Priority event').trim();
            const choice = await showFixedCrewCrewChoiceModal(
                eventLabel,
                picName,
                sameUnitCrews.map(group => ({ key: group.key, label: group.label }))
            );

            if (!choice) return null;

            if (choice.mode === 'random') {
                replacements.set(event.id, {
                    ...event,
                    fixedCrewRandomCrew: true,
                    fixedCrewPic: picName,
                    pilot: picName,
                    crew: 'Any same-unit crew',
                    fixedCrewManifestNotes: [
                        event.fixedCrewManifestNotes,
                        'NEO Build prompted for crew selection; user selected any same-unit crew with the assigned PIC carried onto the event.',
                    ].filter(Boolean).join(' '),
                });
                continue;
            }

            const selectedCrew = sameUnitCrews.find(group => group.key === choice.crewKey);
            if (!selectedCrew) {
                showDarkAlert(
                    `NEO Build was paused because the selected crew is no longer available for ${eventLabel}.`,
                    'Crew Selection Required',
                    'warning'
                );
                return null;
            }

            replacements.set(event.id, {
                ...event,
                fixedCrewGroup: selectedCrew.key,
                fixedCrewRandomCrew: false,
                fixedCrewPic: picName,
                pilot: picName,
                crew: selectedCrew.label,
                fixedCrewManifestNotes: [
                    event.fixedCrewManifestNotes,
                    `NEO Build prompted for crew selection; user selected ${selectedCrew.label}.`,
                ].filter(Boolean).join(' '),
            });
        }

        if (replacements.size === 0) return events;

        const resolvedEvents = events.map(event => replacements.get(event.id) || event);
        setHighestPriorityEvents(prevEvents => prevEvents.map(event => replacements.get(event.id) || event));
        return resolvedEvents;
    };

    const startBuildProcess = async () => {
        const continuationShortLabel = getSctTerminology(platformConfig, activeUnitCode).shortLabel;
        logNeoBuildUiDebug('🚀 [NEO-Build] startBuildProcess called');
        // Critical first step: sync continuation/currency and remedial requests to Highest Priority.
        logNeoBuildUiDebug('🚀 [NEO-Build] DEBUG ===== PRE-BUILD ANALYSIS START =====');
        logNeoBuildUiDebug(`🚀 [NEO-Build] Pre-Build Step 1: Syncing ${continuationShortLabel} and Remedial requests...`);
        const taskTraceLabels = Array.from(new Set([
            ...(activeTaskProfiles || []),
            'Task',
            'Tasking',
        ]));
        const normaliseTaskTraceText = (value?: any): string => String(value || '').trim().toLowerCase();
        const eventMatchesTaskTrace = (event: Partial<ScheduleEvent> | any): boolean => {
            const text = [
                event.id,
                event.flightNumber,
                event.taskingName,
                event.taskingDisplayLabel,
                event.notes,
                event.group,
                event._source,
            ].map(normaliseTaskTraceText).join(' | ');
            return event.isTaskingRequest === true ||
                !!event.taskingRequestId ||
                String(event.id || '').startsWith('tasking-') ||
                taskTraceLabels.some(label => text.includes(normaliseTaskTraceText(label)));
        };
        const summariseTaskTraceEvent = (event: Partial<ScheduleEvent> | any, origin: string) => ({
            origin,
            id: event.id || null,
            date: event.date || buildDfpDate || null,
            type: event.type || null,
            flightNumber: event.flightNumber || null,
            taskingName: event.taskingName || null,
            taskingDisplayLabel: event.taskingDisplayLabel || null,
            isTaskingRequest: event.isTaskingRequest === true,
            taskingRequestId: event.taskingRequestId || null,
            isMandatoryTasking: event.isMandatoryTasking ?? null,
            group: event.group || null,
            startTime: event.startTime ?? null,
            duration: event.duration ?? null,
            resourceId: event.resourceId || null,
            pilot: event.pilot || null,
            crew: event.crew || null,
            instructor: event.instructor || null,
            student: event.student || null,
            source: event._source || null,
            notes: event.notes || null,
            matchedLabels: taskTraceLabels.filter(label => [
                event.flightNumber,
                event.taskingName,
                event.taskingDisplayLabel,
                event.notes,
                event.group,
            ].map(normaliseTaskTraceText).join(' | ').includes(normaliseTaskTraceText(label))),
        });
        let storedTaskingRequestsForTrace: any[] = [];
        try {
            const parsed = JSON.parse(localStorage.getItem('neoTaskingRequests') || '[]');
            storedTaskingRequestsForTrace = Array.isArray(parsed) ? parsed : [];
        } catch {
            storedTaskingRequestsForTrace = [];
        }
        const highestPriorityEventsBeforeSync = highestPriorityEvents;
        const rawSyncedPriorityEvents = syncPriorityEventsWithSctAndRemedial();
        const isTaskingEvent = (event: ScheduleEvent) => (
            event.isTaskingRequest === true || !!event.taskingRequestId || String(event.id || '').startsWith('tasking-')
        );
        const isSctPriorityEvent = (event: ScheduleEvent) => (
            isContinuationScheduleEvent(event) || /^sct-(flight|ftd)-/.test(String(event.id || ''))
        );
        const getSctRequestIdFromEvent = (event: ScheduleEvent): string => {
            const explicitId = String(event.sctRequestId || '').trim();
            if (explicitId) return explicitId;
            const parsed = String(event.id || '').match(/^sct-(?:flight|ftd)-(.+)$/);
            return parsed?.[1] || '';
        };
        const submittedTaskingRequestIds = (() => {
            try {
                const parsed = JSON.parse(localStorage.getItem('neoTaskingRequests') || '[]');
                if (!Array.isArray(parsed)) return new Set<string>();
                return new Set(
                    parsed
                        .filter((request: any) => request?.submitted && String(request.id || '').trim())
                        .map((request: any) => String(request.id).trim())
                );
            } catch {
                return new Set<string>();
            }
        })();
        const liveSctRequestIds = new Set(
            [...sctFlights, ...sctFtds]
                .map(request => String(request.id || '').trim())
                .filter(Boolean)
        );
        const syncedPriorityEvents = rawSyncedPriorityEvents.filter(event => {
            if (isTaskingEvent(event)) {
                const requestId = String(event.taskingRequestId || '').trim();
                const stillRequested = !!requestId && submittedTaskingRequestIds.has(requestId);
                if (!stillRequested) {
                    logNeoBuildUiDebug(`DEBUG Removing stale tasking priority before build: ${event.flightNumber} (ID: ${event.id}, taskingRequestId: ${requestId || 'none'})`);
                }
                return stillRequested;
            }
            if (isSctPriorityEvent(event)) {
                const requestId = getSctRequestIdFromEvent(event);
                const stillRequested = !!requestId && liveSctRequestIds.has(requestId);
                if (!stillRequested) {
                    logNeoBuildUiDebug(`DEBUG Removing stale ${continuationShortLabel} priority before build: ${event.flightNumber} (ID: ${event.id}, sctRequestId: ${requestId || 'none'})`);
                }
                return stillRequested;
            }
            return true;
        });
        const removedStaleTaskingPriorities = rawSyncedPriorityEvents
            .filter(event => isTaskingEvent(event))
            .filter(event => !syncedPriorityEvents.some(kept => kept.id === event.id));
        const removedStaleSctPriorities = rawSyncedPriorityEvents
            .filter(event => isSctPriorityEvent(event))
            .filter(event => !syncedPriorityEvents.some(kept => kept.id === event.id));
        (window as any).__lastTaskingProvenancePreBuild = {
            timestamp: new Date().toISOString(),
            buildDate: buildDfpDate,
            activeUnitCode,
            school,
            watchedLabels: taskTraceLabels,
            localStorageTaskingRequests: storedTaskingRequestsForTrace,
            submittedTaskingRequestIds: Array.from(submittedTaskingRequestIds),
            highestPriorityBeforeSync: highestPriorityEventsBeforeSync.filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'highestPriorityEvents-before-sync')),
            syncedPriorityBeforePurge: rawSyncedPriorityEvents.filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'syncedPriorityEvents-before-tasking-purge')),
            removedStaleTaskingPriorities: removedStaleTaskingPriorities.map(event => summariseTaskTraceEvent(event, 'removed-stale-tasking-priority')),
            removedStaleSctPriorities: removedStaleSctPriorities.map(event => summariseTaskTraceEvent(event, 'removed-stale-sct-priority')),
            syncedPriorityAfterPurge: syncedPriorityEvents.filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'syncedPriorityEvents-after-tasking-purge')),
            publishedScheduleForBuildDate: (publishedSchedules[buildDfpDate] || []).filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'publishedSchedules-buildDate')),
            nextDayBuildEventsBeforeBuild: (nextDayBuildEvents || []).filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'nextDayBuildEvents-before-build')),
        };
        if (syncedPriorityEvents.length !== rawSyncedPriorityEvents.length) {
            setHighestPriorityEvents(syncedPriorityEvents);
        }

        // SECOND STEP: Analyze Active DFP for the build date and preserve only explicitly fixed events
        logNeoBuildUiDebug(`Pre-Build Step 2: Checking Active DFP for ${buildDfpDate}...`);

        const existingEventsForDate = publishedSchedules[buildDfpDate] || [];
        const currentTaskingPriorityIds = new Set(
            syncedPriorityEvents
                .filter(isTaskingEvent)
                .map(event => event.id)
        );
        const currentTaskingRequestIds = new Set(
            syncedPriorityEvents
                .filter(isTaskingEvent)
                .map(event => event.taskingRequestId)
                .filter(Boolean) as string[]
        );
        const isCurrentTaskingEvent = (event: ScheduleEvent): boolean => (
            currentTaskingPriorityIds.has(event.id) ||
            (!!event.taskingRequestId && currentTaskingRequestIds.has(event.taskingRequestId))
        );
        const staleExistingTaskingEventsForDate = existingEventsForDate.filter(event =>
            isTaskingEvent(event) && !isCurrentTaskingEvent(event)
        );
        const staleExistingSctEventsForDate = existingEventsForDate.filter(event =>
            isSctPriorityEvent(event)
        );
        const buildPublishedSchedulesForRun: Record<string, ScheduleEvent[]> = staleExistingTaskingEventsForDate.length > 0 || staleExistingSctEventsForDate.length > 0
            ? {
                ...publishedSchedules,
                [buildDfpDate]: existingEventsForDate.filter(event =>
                    (!isTaskingEvent(event) || isCurrentTaskingEvent(event)) &&
                    !isSctPriorityEvent(event)
                ),
            }
            : publishedSchedules;
        const fixedExistingEventsForDate = existingEventsForDate.filter(event => {
            if (!event.isTimeFixed) return false;
            if (isSctPriorityEvent(event)) {
                logNeoBuildUiDebug(`DEBUG Skipping fixed ${continuationShortLabel} event from Active DFP preservation so live requests can regenerate it: ${event.flightNumber} (ID: ${event.id}, sctRequestId: ${getSctRequestIdFromEvent(event) || 'none'})`);
                return false;
            }
            if (!isTaskingEvent(event)) return true;

            const stillRequestedTasking = isCurrentTaskingEvent(event);

            if (!stillRequestedTasking) {
                logNeoBuildUiDebug(`DEBUG Skipping stale fixed tasking event from Active DFP preservation: ${event.flightNumber} (ID: ${event.id}, taskingRequestId: ${event.taskingRequestId || 'none'})`);
            }
            return stillRequestedTasking;
        });
        if (staleExistingTaskingEventsForDate.length > 0) {
            logNeoBuildUiDebug(`DEBUG Removed ${staleExistingTaskingEventsForDate.length} stale tasking event(s) from build-date published schedule before NEO Build input handoff.`);
            (window as any).__lastTaskingProvenancePreBuild = {
                ...((window as any).__lastTaskingProvenancePreBuild || {}),
                removedStalePublishedTaskingEvents: staleExistingTaskingEventsForDate.map(event => summariseTaskTraceEvent(event, 'removed-stale-published-tasking-before-build-handoff')),
                sanitizedPublishedScheduleForBuildDate: (buildPublishedSchedulesForRun[buildDfpDate] || []).filter(eventMatchesTaskTrace).map(event => summariseTaskTraceEvent(event, 'sanitized-publishedSchedules-buildDate')),
            };
        }
        if (staleExistingSctEventsForDate.length > 0) {
            logNeoBuildUiDebug(`DEBUG Removed ${staleExistingSctEventsForDate.length} stale ${continuationShortLabel} event(s) from build-date published schedule before NEO Build input handoff.`);
        }

        logNeoBuildUiDebug(`DEBUG Active DFP has ${existingEventsForDate.length} events for ${buildDfpDate}`);

        // Declare these outside the if block so they're accessible later
        // CRITICAL: Use the synced events, not the old state
        let newHighestPriorityEvents = [...syncedPriorityEvents];
        let addedCount = 0;

        if (fixedExistingEventsForDate.length > 0) {
            logNeoBuildUiDebug(`DEBUG Preserving ${fixedExistingEventsForDate.length} explicitly fixed Active DFP event(s); ${existingEventsForDate.length - fixedExistingEventsForDate.length} non-fixed event(s) will be rebuilt.`);
            logNeoBuildUiDebug('DEBUG Fixed existing event details:');
            fixedExistingEventsForDate.forEach((event, index) => {
                logNeoBuildUiDebug(`  ${index + 1}. ${event.flightNumber} - ${event.student || event.pilot || 'N/A'} with ${event.instructor} at ${event.startTime.toFixed(2)} (ID: ${event.id}, isTimeFixed: ${event.isTimeFixed})`);
            });

            logNeoBuildUiDebug('Adding explicitly fixed Active DFP events to Highest Priority to preserve them...');

            fixedExistingEventsForDate.forEach(event => {
                // Check if this event is already in highest priority
                const alreadyExists = newHighestPriorityEvents.some(hpe =>
                    hpe.id === event.id
                );

                if (!alreadyExists) {
                    // CRITICAL: Mark event as time-fixed so it's preserved in the build
                    const preservedEvent = {
                        ...event,
                        isTimeFixed: true  // This ensures the build algorithm includes it
                    };
                    newHighestPriorityEvents.push(preservedEvent);
                    addedCount++;
                    logNeoBuildUiDebug(`  DEBUG LOCKED: ${event.flightNumber} - ${event.student || event.pilot || 'N/A'} with ${event.instructor} at ${event.startTime.toFixed(2)} (ID: ${event.id})`);
                } else {
                    logNeoBuildUiDebug(`  DEBUG SKIP: ${event.flightNumber} already in highest priority (ID: ${event.id})`);
                }
            });

            if (addedCount > 0) {
                setHighestPriorityEvents(newHighestPriorityEvents);
                logNeoBuildUiDebug(`DEBUG Pre-Build Complete: ${addedCount} events LOCKED as highest priority (MUST be included in build)`);
                logNeoBuildUiDebug(`DEBUG Total Highest Priority Events: ${newHighestPriorityEvents.length}`);
            } else {
                logNeoBuildUiDebug('DEBUG Pre-Build Complete: All existing events already locked');
            }
        } else {
            logNeoBuildUiDebug(`DEBUG Pre-Build Analysis: No fixed Active DFP events found for this date; ${existingEventsForDate.length} non-fixed event(s) will be rebuilt`);
        }

        logNeoBuildUiDebug('DEBUG ===== PRE-BUILD ANALYSIS END =====');

        const resolvedPicCrewPriorityEvents = await resolveFixedCrewPicPriorityEventsWithoutCrew(newHighestPriorityEvents);
        if (!resolvedPicCrewPriorityEvents) {
            logNeoBuildUiDebug('DEBUG NEO Build paused: fixed crew PIC priority event requires crew selection.');
            return;
        }

        // Use the updated list (which includes any newly added events from Active DFP and resolved PIC/crew prompts)
        const finalPreservedEvents = resolvedPicCrewPriorityEvents;

        logNeoBuildUiDebug(`DEBUG Final preserved events count: ${finalPreservedEvents.length}`);

        // Now proceed with normal build process
        const activeTrainees = allTraineesData.filter(t => !t.isPaused && !excludedCourses.includes(t.course) && !isPersonStaticallyUnavailable(t, flyingStartTime, ceaseNightFlying, buildDfpDate, 'flight'));
        let bnfTraineeCount = 0;

        activeTrainees.forEach(trainee => {
            const { next } = computeNextEventsForTrainee(trainee, traineeLMPs, scores, syllabusDetails, buildPublishedSchedulesForRun, buildDfpDate);
            if (next && next.code.startsWith('BNF') && next.type === 'Flight') {
                bnfTraineeCount++;
            }
        });

        setNightFlyingTraineeCount(bnfTraineeCount);
        setShowNightFlyingInfo(true);

        setTimeout(() => {
            setShowNightFlyingInfo(false);
            // CRITICAL: Pass the preserved events directly to avoid state timing issues
            void runBuildAlgorithm(finalPreservedEvents, buildPublishedSchedulesForRun);
        }, 3000);
    };

    const handleBuildDfp = async () => {
        if (!canRunNeoBuild) {
            denyPlatformAction('Run NEO Build is not permitted for your assigned permission profile');
            return;
        }
        if (!isNeoCapableOperationalModel) {
            setShowInfoNotification(`${activeOperationalModelLabel} is selected for ${school} - ${activeUnitCode}. NEO Build is not available for this operational model yet.`);
            return;
        }
        // System freeze check - prevent NEO Build when frozen
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. NEO Build is not permitted during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        logNeoBuildUiDebug('🚀 [NEO-Build] handleBuildDfp called');
        logNeoBuildUiDebug('🚀 [NEO-Build] buildDfpDate:', buildDfpDate);

        // Note: Priority analysis is now integrated in the Build Analysis sidebar item
        // No need to open external tab

        // Use robust string comparison to avoid timezone issues between Local and UTC dates
        const todayStr = getLocalDateString();
        logNeoBuildUiDebug('🚀 [NEO-Build] todayStr:', todayStr);
        logNeoBuildUiDebug('🚀 [NEO-Build] Date comparison:', buildDfpDate, '<=', todayStr, '=', buildDfpDate <= todayStr);

        // If the build date is today or in the past, show the warning
        if (buildDfpDate <= todayStr) {
            logNeoBuildUiDebug('🚀 [NEO-Build] Build date is today or in the past, showing warning');
            setShowDateWarning(true);
            return;
        }

        logNeoBuildUiDebug('🚀 [NEO-Build] Starting build process');
        void startBuildProcess();
    };

    const handleConfirmDateAndBuild = () => {
        setShowDateWarning(false);
        void startBuildProcess();
    };

    const runBuildAlgorithm = async (preservedEvents?: ScheduleEvent[], buildPublishedSchedulesOverride?: Record<string, ScheduleEvent[]>) => {
        logNeoBuildUiDebug('🚀 [NEO-Build] runBuildAlgorithm called');
        logNeoBuildUiDebug('🚀 [NEO-Build] buildDfpDate:', buildDfpDate);
        logNeoBuildUiDebug('🚀 [NEO-Build] preservedEvents:', preservedEvents?.length || 0);
        logNeoBuildUiDebug('🚀 [NEO-Build] highestPriorityEvents:', highestPriorityEvents.length);
        const buildPublishedSchedules = buildPublishedSchedulesOverride || publishedSchedules;
        const normaliseBuildUnitCode = (value: unknown): string => String(value || '').split('/')[0].trim().toUpperCase();
        const assignableFlightSchoolBuildSyllabus = activeOperationalModel === 'flight_school'
            ? getFlightSchoolAssignableSyllabusForActiveScope(syllabusDetails, 'Assign')
                .filter((item: any) => item.type !== 'Academics' && item.lmpType !== 'Staff CAT')
            : [];
        const assignableFlightSchoolEventKeys = new Set(
            assignableFlightSchoolBuildSyllabus
                .flatMap((item: any) => [item.id, item.code, item.masterEventId])
                .map(key => String(key || '').replace(/\*/g, '').trim())
                .filter(Boolean)
        );
        const isFlightSchoolLmpOverlayItem = (item: SyllabusItemDetail): boolean => (
            item.lmpSource === 'remedial' ||
            item.lmpSource === 'custom' ||
            item.isRemedial === true ||
            String(item.id || item.code || '').includes('REM') ||
            String(item.id || item.code || '').endsWith('-RF') ||
            String(item.id || item.code || '').endsWith('-CUR')
        );
        const getFlightSchoolLmpEventKeys = (item: SyllabusItemDetail): string[] => (
            [item.id, item.code, item.masterEventId]
                .map(key => String(key || '').replace(/\*/g, '').trim())
                .filter(Boolean)
        );
        const filterFlightSchoolLmpEventsForBuildScope = (events?: SyllabusItemDetail[] | null): SyllabusItemDetail[] => {
            if (activeOperationalModel !== 'flight_school') return Array.isArray(events) ? events : [];
            if (!Array.isArray(events) || events.length === 0) return [];
            if (assignableFlightSchoolEventKeys.size === 0) return events;
            return events.filter(item => (
                isFlightSchoolLmpOverlayItem(item) ||
                getFlightSchoolLmpEventKeys(item).some(key => assignableFlightSchoolEventKeys.has(key))
            ));
        };
        const activeScopedCourseNames = scopedCourseNameSet;
        const flightSchoolTraineeMatchesBuildScope = (trainee: Trainee | any): boolean => {
            if (activeOperationalModel !== 'flight_school') return true;
            const traineeUnitCode = normaliseBuildUnitCode(trainee?.unit);
            if (traineeUnitCode && activeContextUnitCodeSet.size > 0 && !activeContextUnitCodeSet.has(traineeUnitCode)) {
                return false;
            }

            const traineeCourse = String(trainee?.course || '').trim();
            if (activeScopedCourseNames.size > 0) {
                return Boolean(traineeCourse && activeScopedCourseNames.has(traineeCourse));
            }

            return true;
        };
        let traineesForBuildScope = activeOperationalModel === 'flight_school'
            ? traineesData.filter(flightSchoolTraineeMatchesBuildScope)
            : traineesData;
        let traineeNamesForBuildScope = new Set(
            traineesForBuildScope
                .flatMap((trainee: any) => [trainee.fullName, trainee.name])
                .map(name => String(name || '').trim())
                .filter(Boolean)
        );
        localStorage.removeItem('neo_build_runtime_error_report');
        localStorage.removeItem('neo_dfp_data_diag');
        localStorage.removeItem('neo_staff_schedule_render_diag');
        const timingReport = createNeoBuildTimingReport(buildDfpDate, {
            preservedEvents: preservedEvents?.length || 0,
            highestPriorityEvents: highestPriorityEvents.length,
            trainees: traineesForBuildScope.length,
            instructors: instructorsData.length,
            currentTraineeLMPs: traineeLMPs.size,
            scoresTrainees: scores.size,
            publishedEventsForBuildDate: (buildPublishedSchedules[buildDfpDate] || []).length,
        });
        markNeoBuildTiming(timingReport, 'runBuildAlgorithm:start');
        let neoBuildDiagnosticDownloaded = false;
        const downloadNeoBuildDiagnosticAfterRun = (source: string) => {
            if (neoBuildDiagnosticDownloaded) return;
            markNeoBuildTiming(timingReport, `diagnostic-export:${source}:start`);
            const filename = downloadNeoBuildDiagnosticReport(source);
            if (filename) {
                neoBuildDiagnosticDownloaded = true;
                markNeoBuildTiming(timingReport, `diagnostic-export:${source}:downloaded`, { filename });
                setShowInfoNotification(`${activeOperationalModelLabel} NEO Build diagnostic downloaded: ${filename}`);
            } else {
                markNeoBuildTiming(timingReport, `diagnostic-export:${source}:unavailable`);
            }
        };

        setIsBuildingDfp(true);
        pushDfpDataDiag('build:start-visible-draft-state', {
            buildDate: buildDfpDate,
            existingDraftEvents: nextDayBuildEvents.length,
            publishedEventsForBuildDate: (buildPublishedSchedules[buildDfpDate] || []).length,
            preservedEvents: preservedEvents?.length || 0,
            highestPriorityEvents: highestPriorityEvents.length,
            note: 'Previous draft remains visible while the new build runs; generated events replace it atomically at build completion.',
            sampleDraftEvents: nextDayBuildEvents.slice(0, 12).map(event => ({
                id: event.id,
                type: event.type,
                resourceId: event.resourceId,
                startTime: event.startTime,
                duration: event.duration,
                flightNumber: event.flightNumber,
                pilot: event.pilot,
                crew: event.crew,
                fixedCrewGroup: event.fixedCrewGroup,
            })),
        });

        // Use preserved events if provided, otherwise use state
        const eventsToUse = preservedEvents || highestPriorityEvents;
        markNeoBuildTiming(timingReport, 'state:preserve-visible-draft-during-build', {
            eventsToUse: eventsToUse.length,
            visibleDraftEvents: nextDayBuildEvents.length,
        });

        // ── Fetch DB-backed ELCE for all active trainees ──────────────────────
        // This gives the build algorithm real DCO tracking data written the moment
        // the post-flight form is saved, before training report paperwork is entered.
        // Non-fatal: if the fetch fails, the build proceeds with legacy DFP-scan ELCE.
        let dbElceMap: Map<string, { eventCode: string; eventDate: string; dcoResult: 'DCO' | 'DPCO' | 'DNCO'; isCountedAsElce: boolean } | null> | undefined;
        try {
            const activeTraineeNames = traineesForBuildScope
                .filter((t: any) => !t.isPaused)
                .map((t: any) => t.fullName as string)
                .filter(Boolean);

            if (activeTraineeNames.length > 0) {
                const apiBase = getAppApiBase();

                markNeoBuildTiming(timingReport, 'elce:request-start', { activeTrainees: activeTraineeNames.length });
                const elceRes = await fetch(`${apiBase}/event-completions/elce`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ traineeFullNames: activeTraineeNames, buildDate: buildDfpDate }),
                });
                markNeoBuildTiming(timingReport, 'elce:response-received', { status: elceRes.status });

                if (elceRes.ok) {
                    const elceData = await elceRes.json() as {
                        elceMap: Record<string, { eventCode: string; eventDate: string; dcoResult: 'DCO' | 'DPCO' | 'DNCO'; isCountedAsElce: boolean } | null>;
                    };
                    dbElceMap = new Map(Object.entries(elceData.elceMap));
                    const withElce = [...dbElceMap.values()].filter(Boolean).length;
                    markNeoBuildTiming(timingReport, 'elce:json-parsed', { trainees: dbElceMap.size, withElce });
                    logNeoBuildUiDebug(`[ELCE] Bulk fetch complete — ${dbElceMap.size} trainees, ${withElce} with DB ELCE record`);
                } else {
                    console.warn(`[ELCE] Bulk fetch failed (status ${elceRes.status}) — falling back to DFP-scan ELCE`);
                }
            }
        } catch (elceErr) {
            markNeoBuildTiming(timingReport, 'elce:error', { message: elceErr instanceof Error ? elceErr.message : String(elceErr) });
            console.warn('[ELCE] Bulk fetch threw — falling back to DFP-scan ELCE:', elceErr);
        }
        markNeoBuildTiming(timingReport, 'elce:complete');

        let buildTraineeLMPs = traineeLMPs;
        const shouldRefreshComposedLmpsBeforeBuild = activeOperationalModel !== 'air_combat';
        if (!shouldRefreshComposedLmpsBeforeBuild) {
            markNeoBuildTiming(timingReport, 'lmp-refresh:skipped', {
                operationalModel: activeOperationalModel,
                reason: 'air-combat-build-uses-configured-training-inputs',
                currentTraineeLMPs: buildTraineeLMPs.size,
            });
        } else try {
            const apiBase = getApiBaseUrl();
            const assignableBuildSyllabus = activeOperationalModel === 'flight_school'
                ? assignableFlightSchoolBuildSyllabus
                : filterSyllabusForMasterLmpAccess(syllabusDetails, 'Assign', activeUnitCode);
            const syllabusData = groupSyllabusByConfiguredCourses(assignableBuildSyllabus);

            logNeoBuildUiDebug('[NEO-Build] Refreshing composed Individual LMPs before build...');
            markNeoBuildTiming(timingReport, 'lmp-sync:request-start', {
                syllabusGroups: Object.keys(syllabusData).length,
            });
            const syncRes = await fetch(`${apiBase}/trainees/lmp-sync`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ syllabusData }),
            });
            markNeoBuildTiming(timingReport, 'lmp-sync:response-received', { status: syncRes.status });
            if (!syncRes.ok) {
                console.warn(`[NEO-Build] Pre-build LMP sync failed (${syncRes.status}); using current in-memory LMPs`);
            }

            markNeoBuildTiming(timingReport, 'lmp-fetch:request-start', { buildPayload: true });
            const lmpRes = await fetch(`${apiBase}/trainees/lmp-sync?includeEvents=true&build=true`, {
                credentials: 'include',
            });
            markNeoBuildTiming(timingReport, 'lmp-fetch:response-received', { status: lmpRes.status });
            if (lmpRes.ok) {
                const lmpData = await lmpRes.json();
                const freshLMPs = new Map<string, SyllabusItemDetail[]>();
                let freshEventCount = 0;
                (lmpData.lmps || []).forEach((lmp: any) => {
                    if (lmp.traineeFullName && Array.isArray(lmp.events)) {
                        const traineeForLmp = traineesForBuildScope.find((candidate: any) => candidate.fullName === lmp.traineeFullName || candidate.name === lmp.traineeFullName);
                        if (activeOperationalModel === 'flight_school' && !traineeForLmp) {
                            logNeoBuildUiDebug(`[NEO-Build] Skipped ${lmp.traineeFullName} ${lmp.lmpType} LMP outside active Flight School build scope`);
                            return;
                        }
                        const lmpEventsForBuild = activeOperationalModel === 'flight_school'
                            ? filterFlightSchoolLmpEventsForBuildScope(lmp.events)
                            : lmp.events;
                        if (activeOperationalModel === 'flight_school' && lmpEventsForBuild.length === 0) {
                            logNeoBuildUiDebug(`[NEO-Build] Skipped ${lmp.traineeFullName} ${lmp.lmpType} LMP because it has no events in the active Flight School Master LMP scope`);
                            return;
                        }
                        const traineeUnitCode = activeOperationalModel === 'flight_school'
                            ? resolveMasterLmpUnitForTrainee(traineeForLmp, lmp.lmpType, 'Assign')
                            : traineeForLmp?.unit || activeUnitCode;
                        if (!hasMasterLmpUnitAccess(lmp.lmpType, traineeUnitCode, 'Assign')) {
                            logNeoBuildUiDebug(`[NEO-Build] Skipped ${lmp.traineeFullName} ${lmp.lmpType} LMP for unauthorised unit ${traineeUnitCode || 'unknown'}`);
                            return;
                        }
                        freshLMPs.set(lmp.traineeFullName, lmpEventsForBuild);
                        freshEventCount += lmpEventsForBuild.length;
                    }
                });
                markNeoBuildTiming(timingReport, 'lmp-fetch:json-parsed', {
                    lmps: freshLMPs.size,
                    events: freshEventCount,
                });
                if (freshLMPs.size > 0) {
                    buildTraineeLMPs = freshLMPs;
                    setTraineeLMPs(freshLMPs);
                    markNeoBuildTiming(timingReport, 'lmp-fetch:state-updated', { lmps: freshLMPs.size });
                    logNeoBuildUiDebug(`[NEO-Build] ✅ Loaded ${freshLMPs.size} fresh composed Individual LMPs for build`);
                } else {
                    console.warn('[NEO-Build] Pre-build LMP refresh returned no events; using current in-memory LMPs');
                }
            } else {
                console.warn(`[NEO-Build] Pre-build LMP fetch failed (${lmpRes.status}); using current in-memory LMPs`);
            }
        } catch (lmpRefreshErr) {
            markNeoBuildTiming(timingReport, 'lmp-refresh:error', { message: lmpRefreshErr instanceof Error ? lmpRefreshErr.message : String(lmpRefreshErr) });
            console.warn('[NEO-Build] Pre-build LMP refresh threw; using current in-memory LMPs:', lmpRefreshErr);
        }
        markNeoBuildTiming(timingReport, 'lmp-refresh:complete', { buildTraineeLMPs: buildTraineeLMPs.size });

        if (activeOperationalModel === 'flight_school' && buildTraineeLMPs.size > 0) {
            const buildTraineeNameSet = new Set(
                traineesForBuildScope
                    .flatMap((trainee: any) => [trainee.fullName, trainee.name])
                    .map(name => String(name || '').trim())
                    .filter(Boolean)
            );
            const findReportSourceLmpIndex = (lmp: SyllabusItemDetail[], trainee: Trainee | any, assessment: Pt051Assessment): number => {
                const eventRefs = new Set([
                    assessment.eventId,
                    assessment.flightNumber,
                    `lmp-${(trainee as any).id || trainee.idNumber}-${assessment.flightNumber}`,
                ].map(value => String(value || '').trim().toUpperCase()).filter(Boolean));
                return lmp.findIndex(item => {
                    const itemRefs = [
                        item.id,
                        item.code,
                        item.masterEventId,
                        item.eventDescription,
                    ].map(value => String(value || '').trim().toUpperCase()).filter(Boolean);
                    return itemRefs.some(ref => eventRefs.has(ref));
                });
            };
            const getAssessmentFollowUpText = (assessment: Pt051Assessment): string => [
                assessment.trainingReportNotes,
                assessment.overallComments,
                (assessment as any).comments,
            ].map(value => String(value || '')).join('\n');
            const recoverExtraHoursFromAssessmentText = (assessment: Pt051Assessment): { hours: number; targetCode?: string } | null => {
                const text = getAssessmentFollowUpText(assessment);
                const match = text.match(/(\d+(?:\.\d+)?)\s*(?:hrs?|hours?)\s+added\s+to\s+([A-Z0-9 _-]+)/i);
                if (!match) return null;
                const hours = Number(match[1]);
                const rawTarget = String(match[2] || '').split(/[.\n\r]/)[0].trim();
                if (!Number.isFinite(hours) || hours <= 0) return null;
                return {
                    hours,
                    targetCode: rawTarget || undefined,
                };
            };
            const getAssessmentRequestedExtension = (assessment: Pt051Assessment): { hours: number; targetCode?: string; source: string } | null => {
                const configuredHours = assessment.dcoResult === 'DPCO' &&
                    assessment.dpcoFollowUp?.action === 'extra-hours-next-event'
                    ? Number(assessment.dpcoFollowUp?.extraHours || 0)
                    : 0;
                if (Number.isFinite(configuredHours) && configuredHours > 0) {
                    return { hours: configuredHours, source: 'structured-follow-up' };
                }
                const recovered = recoverExtraHoursFromAssessmentText(assessment);
                return recovered ? { ...recovered, source: 'notes-prefix-recovery' } : null;
            };
            const applyAssessmentFollowUpToLmp = (
                trainee: Trainee | any,
                lmp: SyllabusItemDetail[],
                assessment: Pt051Assessment
            ): { lmp: SyllabusItemDetail[]; changed: boolean; updates: Record<string, any>[] } => {
                const sourceIndex = findReportSourceLmpIndex(lmp, trainee, assessment);
                const updates: Record<string, any>[] = [];
                if (sourceIndex < 0) {
                    updates.push({
                        assessmentId: assessment.id || assessment.eventId,
                        flightNumber: assessment.flightNumber,
                        outcome: 'no-source-match',
                    });
                    return { lmp, changed: false, updates };
                }

                const sourceItem = lmp[sourceIndex] as SyllabusItemDetail & Record<string, any>;
                if (sourceItem.type !== 'Flight' && sourceItem.type !== 'FTD') {
                    updates.push({
                        assessmentId: assessment.id || assessment.eventId,
                        flightNumber: assessment.flightNumber,
                        sourceCode: sourceItem.code,
                        sourceType: sourceItem.type,
                        outcome: 'source-not-flight-or-ftd',
                    });
                    return { lmp, changed: false, updates };
                }

                const requestedExtensionInfo = getAssessmentRequestedExtension(assessment);
                const requestedTargetCode = String(requestedExtensionInfo?.targetCode || '').trim().toUpperCase();
                const targetIndex = requestedTargetCode
                    ? lmp.findIndex((item, index) =>
                        index > sourceIndex &&
                        item.type === sourceItem.type &&
                        String(item.code || item.id || '').trim().toUpperCase() === requestedTargetCode
                    )
                    : lmp.findIndex((item, index) =>
                        index > sourceIndex &&
                        item.type === sourceItem.type &&
                        !(item as any).completedAt
                    );
                if (targetIndex < 0) {
                    updates.push({
                        assessmentId: assessment.id || assessment.eventId,
                        flightNumber: assessment.flightNumber,
                        sourceCode: sourceItem.code,
                        sourceType: sourceItem.type,
                        outcome: 'no-next-target',
                        requestedTargetCode: requestedTargetCode || null,
                    });
                    return { lmp, changed: false, updates };
                }

                const assessmentKey = String(assessment.id || assessment.eventId || `${assessment.flightNumber}-${assessment.traineeFullName}`).trim();
                const targetItem = lmp[targetIndex] as SyllabusItemDetail & Record<string, any>;
                let updatedTarget: SyllabusItemDetail & Record<string, any> = { ...targetItem };
                let changed = false;

                if (requestedExtensionInfo) {
                    const requestedExtension = Number(requestedExtensionInfo.hours);
                    const extensionLedger = {
                        ...(updatedTarget.trainingReportNextEventExtensions || {}),
                    } as Record<string, number>;
                    const previousAssessmentKey = String(updatedTarget.trainingReportLastExtendedByAssessmentId || '').trim();
                    const previousExtension = Number(
                        extensionLedger[assessmentKey] ||
                        (previousAssessmentKey && previousAssessmentKey !== assessmentKey ? extensionLedger[previousAssessmentKey] : 0) ||
                        0
                    );
                    const delta = requestedExtension - previousExtension;
                    if (Math.abs(delta) >= 0.0001) {
                        const existingFlightOrSimHours = Number(updatedTarget.flightOrSimHours || updatedTarget.duration || 0);
                        const existingDuration = Number(updatedTarget.duration || updatedTarget.flightOrSimHours || 0);
                        const existingTotalEventHours = Number(updatedTarget.totalEventHours || existingDuration || existingFlightOrSimHours || 0);
                        if (previousAssessmentKey && previousAssessmentKey !== assessmentKey && Object.prototype.hasOwnProperty.call(extensionLedger, previousAssessmentKey)) {
                            delete extensionLedger[previousAssessmentKey];
                        }
                        extensionLedger[assessmentKey] = requestedExtension;
                        updatedTarget = {
                            ...updatedTarget,
                            flightOrSimHours: Math.max(0, Number((existingFlightOrSimHours + delta).toFixed(2))),
                            duration: Math.max(0, Number((existingDuration + delta).toFixed(2))),
                            totalEventHours: Math.max(0, Number((existingTotalEventHours + delta).toFixed(2))),
                            trainingReportNextEventExtensions: extensionLedger,
                            trainingReportLastExtendedByAssessmentId: assessmentKey,
                        };
                        changed = true;
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: 'extended-next-event',
                            requestedExtension,
                            requestedExtensionSource: requestedExtensionInfo.source,
                            requestedTargetCode: requestedTargetCode || null,
                            previousExtension,
                            delta,
                            before: {
                                flightOrSimHours: existingFlightOrSimHours,
                                duration: existingDuration,
                                totalEventHours: existingTotalEventHours,
                            },
                            after: {
                                flightOrSimHours: updatedTarget.flightOrSimHours,
                                duration: updatedTarget.duration,
                                totalEventHours: updatedTarget.totalEventHours,
                            },
                        });
                    } else {
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: 'extension-already-applied',
                            requestedExtension,
                            requestedExtensionSource: requestedExtensionInfo.source,
                            requestedTargetCode: requestedTargetCode || null,
                            previousExtension,
                        });
                    }
                }

                if (
                    assessment.passNotesToNextEvent === true &&
                    String(assessment.trainingReportNotes || '').trim().length > 0
                ) {
                    const existingForwardedNotes = {
                        ...(updatedTarget.trainingReportForwardedNotes || {}),
                    } as Record<string, { sourceCode?: string; notes?: string }>;
                    const nextNotes = stripGeneratedTrainingReportFollowUpLines(assessment.trainingReportNotes);
                    const previousNotes = String(existingForwardedNotes[assessmentKey]?.notes || '').trim();
                    const sourceCodeForNotes = String(sourceItem.code || assessment.flightNumber || '').trim();
                    let removedStaleForwardedNotes = false;
                    Object.entries(existingForwardedNotes).forEach(([key, entry]) => {
                        const entrySourceCode = String(entry?.sourceCode || '').trim();
                        if (key !== assessmentKey && sourceCodeForNotes && entrySourceCode === sourceCodeForNotes) {
                            delete existingForwardedNotes[key];
                            removedStaleForwardedNotes = true;
                        }
                    });
                    if (!nextNotes) {
                        if (Object.prototype.hasOwnProperty.call(existingForwardedNotes, assessmentKey)) {
                            delete existingForwardedNotes[assessmentKey];
                            removedStaleForwardedNotes = true;
                        }
                        if (removedStaleForwardedNotes) {
                            updatedTarget = {
                                ...updatedTarget,
                                trainingReportBaseNotes: typeof updatedTarget.trainingReportBaseNotes === 'string'
                                    ? updatedTarget.trainingReportBaseNotes
                                    : String(updatedTarget.notes || ''),
                                trainingReportForwardedNotes: Object.keys(existingForwardedNotes).length > 0 ? existingForwardedNotes : undefined,
                                trainingReportLastForwardedNotesAssessmentId: assessmentKey,
                            };
                            changed = true;
                        }
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: removedStaleForwardedNotes ? 'removed-forwarded-notes' : 'notes-generated-prefix-only',
                        });
                    } else if (previousNotes !== nextNotes) {
                        existingForwardedNotes[assessmentKey] = {
                            sourceCode: sourceCodeForNotes,
                            notes: nextNotes,
                        };
                        updatedTarget = {
                            ...updatedTarget,
                            trainingReportBaseNotes: typeof updatedTarget.trainingReportBaseNotes === 'string'
                                ? updatedTarget.trainingReportBaseNotes
                                : String(updatedTarget.notes || ''),
                            trainingReportForwardedNotes: existingForwardedNotes,
                            trainingReportLastForwardedNotesAssessmentId: assessmentKey,
                        };
                        changed = true;
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: 'forwarded-notes',
                            noteLength: nextNotes.length,
                            forwardedKeys: Object.keys(existingForwardedNotes),
                        });
                    } else if (removedStaleForwardedNotes) {
                        updatedTarget = {
                            ...updatedTarget,
                            trainingReportBaseNotes: typeof updatedTarget.trainingReportBaseNotes === 'string'
                                ? updatedTarget.trainingReportBaseNotes
                                : String(updatedTarget.notes || ''),
                            trainingReportForwardedNotes: Object.keys(existingForwardedNotes).length > 0 ? existingForwardedNotes : undefined,
                            trainingReportLastForwardedNotesAssessmentId: assessmentKey,
                        };
                        changed = true;
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: 'removed-stale-forwarded-notes',
                            noteLength: nextNotes.length,
                            forwardedKeys: Object.keys(existingForwardedNotes),
                        });
                    } else {
                        updates.push({
                            assessmentId: assessmentKey,
                            sourceCode: sourceItem.code,
                            targetCode: targetItem.code,
                            outcome: 'notes-already-applied',
                            noteLength: nextNotes.length,
                        });
                    }
                }

                if (!changed) return { lmp, changed: false, updates };
                const updatedLmp = lmp.map((item, index) => index === targetIndex ? updatedTarget : item);
                return { lmp: updatedLmp, changed: true, updates };
            };

            try {
                const apiBase = getApiBaseUrl();
                const allAssessments: Pt051Assessment[] = [];
                const pageSize = 2000;
                let offset = 0;
                markNeoBuildTiming(timingReport, 'report-followups:request-start', {
                    buildTrainees: buildTraineeNameSet.size,
                    lmpCount: buildTraineeLMPs.size,
                });
                const buildTraineeNames = Array.from(buildTraineeNameSet);
                let useScopedFollowUpFetch = true;
                while (true) {
                    const scopedFollowUpParams = new URLSearchParams({
                        limit: String(pageSize),
                        offset: String(offset),
                        followUpOnly: 'true',
                        traineeFullNames: JSON.stringify(buildTraineeNames),
                    });
                    const legacyFollowUpParams = new URLSearchParams({
                        limit: String(pageSize),
                        offset: String(offset),
                    });
                    const scopedUrl = `${apiBase}/trainee-performance?${scopedFollowUpParams.toString()}`;
                    const legacyUrl = `${apiBase}/trainee-performance?${legacyFollowUpParams.toString()}`;
                    let response = await fetch(useScopedFollowUpFetch ? scopedUrl : legacyUrl, {
                        credentials: 'include',
                    });
                    if (useScopedFollowUpFetch && !response.ok && offset === 0) {
                        useScopedFollowUpFetch = false;
                        pushDfpDataDiag('build:report-followups:scoped-fetch-failed-fallback', {
                            status: response.status,
                            text: await response.text().catch(() => ''),
                        });
                        response = await fetch(legacyUrl, {
                            credentials: 'include',
                        });
                    }
                    if (!response.ok) {
                        pushDfpDataDiag('build:report-followups:fetch-failed', {
                            status: response.status,
                            offset,
                            text: await response.text().catch(() => ''),
                        });
                        break;
                    }
                    const page = await response.json();
                    if (!Array.isArray(page) || page.length === 0) break;
                    allAssessments.push(...page);
                    if (offset === 0) {
                        pushDfpDataDiag('build:report-followups:fetch-mode', {
                            mode: useScopedFollowUpFetch ? 'scoped-follow-up-only' : 'legacy-full-table',
                            buildTrainees: buildTraineeNames.length,
                            firstPageAssessments: page.length,
                        });
                    }
                    if (page.length < pageSize) break;
                    offset += pageSize;
                }

                const followUpAssessments = allAssessments.filter((assessment: Pt051Assessment) => (
                    buildTraineeNameSet.has(String(assessment.traineeFullName || '').trim()) &&
                    (
                        Boolean(getAssessmentRequestedExtension(assessment)) ||
                        (
                            assessment.passNotesToNextEvent === true &&
                            String(assessment.trainingReportNotes || '').trim().length > 0
                        )
                    )
                ));
                const reconciledLMPs = new Map(buildTraineeLMPs);
                const changedTrainees: { trainee: Trainee | any; lmp: SyllabusItemDetail[]; updates: Record<string, any>[] }[] = [];
                const updatesByTrainee = new Map<string, Record<string, any>[]>();

                followUpAssessments.forEach((assessment: Pt051Assessment) => {
                    const trainee = traineesForBuildScope.find((candidate: any) =>
                        candidate.fullName === assessment.traineeFullName ||
                        candidate.name === assessment.traineeFullName
                    );
                    const currentLmp = reconciledLMPs.get(assessment.traineeFullName);
                    if (!trainee || !Array.isArray(currentLmp) || currentLmp.length === 0) return;
                    const result = applyAssessmentFollowUpToLmp(trainee, currentLmp, assessment);
                    const previousUpdates = updatesByTrainee.get(assessment.traineeFullName) || [];
                    updatesByTrainee.set(assessment.traineeFullName, [...previousUpdates, ...result.updates]);
                    if (result.changed) {
                        reconciledLMPs.set(assessment.traineeFullName, result.lmp);
                    }
                });

                Array.from(updatesByTrainee.entries()).forEach(([traineeFullName, updates]) => {
                    const changed = updates.some(update => update.outcome === 'extended-next-event' || update.outcome === 'forwarded-notes');
                    if (!changed) return;
                    const trainee = traineesForBuildScope.find((candidate: any) =>
                        candidate.fullName === traineeFullName ||
                        candidate.name === traineeFullName
                    );
                    const lmp = reconciledLMPs.get(traineeFullName);
                    if (trainee && lmp) changedTrainees.push({ trainee, lmp, updates });
                });

                if (changedTrainees.length > 0) {
                    buildTraineeLMPs = reconciledLMPs;
                    setTraineeLMPs(reconciledLMPs);
                    const persistStart = performance.now();
                    let persistedFollowUpLmps = 0;
                    for (const changed of changedTrainees) {
                        try {
                            await persistTraineeLmp(changed.trainee, changed.lmp, [], {
                                skipReadBack: true,
                                source: 'neo-build-report-followups',
                            });
                            persistedFollowUpLmps += 1;
                        } catch (persistError) {
                            pushDfpDataDiag('build:report-followups:persist-failed', {
                                traineeFullName: changed.trainee.fullName,
                                error: persistError instanceof Error ? persistError.message : String(persistError),
                            });
                        }
                    }
                    pushDfpDataDiag('build:report-followups:persist-complete', {
                        changedTrainees: changedTrainees.length,
                        persistedFollowUpLmps,
                        durationMs: Math.round(performance.now() - persistStart),
                    });
                }

                pushDfpDataDiag('build:report-followups:reconciled', {
                    fetchedAssessments: allAssessments.length,
                    followUpAssessments: followUpAssessments.length,
                    changedTrainees: changedTrainees.length,
                    samples: Array.from(updatesByTrainee.entries()).slice(0, 20).map(([traineeFullName, updates]) => ({
                        traineeFullName,
                        updates: updates.slice(0, 12),
                    })),
                });
                markNeoBuildTiming(timingReport, 'report-followups:complete', {
                    fetchedAssessments: allAssessments.length,
                    followUpAssessments: followUpAssessments.length,
                    changedTrainees: changedTrainees.length,
                });
            } catch (followUpError) {
                pushDfpDataDiag('build:report-followups:error', {
                    error: followUpError instanceof Error ? followUpError.message : String(followUpError),
                });
                markNeoBuildTiming(timingReport, 'report-followups:error', {
                    message: followUpError instanceof Error ? followUpError.message : String(followUpError),
                });
            }
        }

        logNeoBuildUiDebug(`🚀 [NEO-Build] DEBUG runBuildAlgorithm called with ${eventsToUse.length} highest priority events`);

        const staffDataSourceAllowedForBuild = (staff: Instructor): boolean => {
            const isDatabase = (staff as any)._dataSource === 'database';
            const isMock = !isDatabase;
            return (dataSourceSettings.staffDb && isDatabase) || (dataSourceSettings.staff && isMock);
        };
        const airCombatSharedStaffUnitCodes = new Set<string>(activeContextUnitCodes);
        if (activeOperationalModel === 'air_combat' && organisationSettings.staffSharingEnabled) {
            const configuredStaffSharingGroups = Array.isArray(organisationSettings.staffSharingGroups) && organisationSettings.staffSharingGroups.length > 0
                ? organisationSettings.staffSharingGroups
                    .filter((group: any) => group?.enabled !== false)
                    .map((group: any) => Array.from(new Set((group?.selectedUnits || []).map(normaliseBuildUnitCode).filter(Boolean))))
                    .filter((groupUnits: string[]) => groupUnits.length > 1)
                : (organisationSettings.staffSharingUnits || []).length > 1
                    ? [Array.from(new Set((organisationSettings.staffSharingUnits || []).map(normaliseBuildUnitCode).filter(Boolean)))]
                    : [];
            configuredStaffSharingGroups
                .filter((groupUnits: string[]) => activeContextUnitCodes.some(unitCode => groupUnits.includes(normaliseBuildUnitCode(unitCode))))
                .forEach((groupUnits: string[]) => groupUnits.forEach(unitCode => airCombatSharedStaffUnitCodes.add(unitCode)));
        }
        const instructorsInBuild = activeOperationalModel === 'air_combat'
            ? allInstructorsData
                .filter(staffDataSourceAllowedForBuild)
                .filter((staff: any) => {
                    const staffUnitCode = normaliseBuildUnitCode(staff.unit);
                    if (!staffUnitCode) return true;
                    if (activeContextUnitCodeSet.has(staffUnitCode)) return personMatchesActiveLocation(staff);
                    return organisationSettings.staffSharingEnabled && airCombatSharedStaffUnitCodes.has(staffUnitCode);
                })
            : instructorsData;
        if (activeOperationalModel === 'flight_school') {
            traineesForBuildScope = traineesData.filter(flightSchoolTraineeMatchesBuildScope);
            traineeNamesForBuildScope = new Set(
                traineesForBuildScope
                    .flatMap((trainee: any) => [trainee.fullName, trainee.name])
                    .map(name => String(name || '').trim())
                    .filter(Boolean)
            );
        }
        const traineesInBuild = traineesForBuildScope;
        if (activeOperationalModel === 'flight_school') {
            const scopedLmpEntries = Array.from(buildTraineeLMPs.entries())
                .map(([traineeName, events]) => [traineeName, filterFlightSchoolLmpEventsForBuildScope(events)] as [string, SyllabusItemDetail[]])
                .filter(([traineeName, events]) => (
                    traineeNamesForBuildScope.has(String(traineeName || '').trim()) &&
                    events.length > 0
                ));
            if (scopedLmpEntries.length !== buildTraineeLMPs.size) {
                logNeoBuildUiDebug('[NEO-Build] Scoped Flight School Individual LMPs to active build trainees:', {
                    before: buildTraineeLMPs.size,
                    after: scopedLmpEntries.length,
                    activeContextUnitCodes,
                    activeCourses: Array.from(activeScopedCourseNames),
                    assignableMasterEvents: assignableFlightSchoolEventKeys.size,
                });
                buildTraineeLMPs = new Map(scopedLmpEntries);
            }
        }
        const storedRemedialRequestsForBuild = loadStoredRemedialRequests();
        const remedialRequestsForBuild = remedialRequests.length > 0 ? remedialRequests : storedRemedialRequestsForBuild;
        logNeoBuildUiDebug('🔍 [NEO BUILD CONFIG DEBUG] Data source settings:', dataSourceSettings);
        logNeoBuildUiDebug('🔍 [NEO BUILD CONFIG DEBUG] instructorsData (filtered):', instructorsInBuild.length, '| mockData count:', instructorsInBuild.filter((i: any) => (i as any)._dataSource !== 'database').length, '| DB count:', instructorsInBuild.filter((i: any) => (i as any)._dataSource === 'database').length);
        if (activeOperationalModel === 'air_combat') {
            logNeoBuildUiDebug('🔍 [NEO BUILD CONFIG DEBUG] Air Combat build staff scope:', {
                activeContextUnitCodes,
                staffSharingEnabled: organisationSettings.staffSharingEnabled,
                includedStaffUnits: Array.from(new Set(instructorsInBuild.map((staff: any) => normaliseBuildUnitCode(staff.unit)).filter(Boolean))).sort(),
                roleCounts: instructorsInBuild.reduce((counts: Record<string, number>, staff: any) => {
                    const role = String(staff.role || 'Unspecified').trim() || 'Unspecified';
                    counts[role] = (counts[role] || 0) + 1;
                    return counts;
                }, {}),
            });
        }
        logNeoBuildUiDebug('🔍 [NEO BUILD CONFIG DEBUG] traineesData (filtered):', traineesInBuild.length, '| mockData count:', traineesInBuild.filter((t: any) => (t as any)._dataSource !== 'database').length, '| DB count:', traineesInBuild.filter((t: any) => (t as any)._dataSource === 'database').length);
        logNeoBuildUiDebug('🔍 [NEO BUILD CONFIG DEBUG] Instructors sample:', instructorsInBuild.slice(0, 5).map((i: any) => ({ id: i.idNumber, name: i.name, role: i.role, unit: i.unit, src: (i as any)._dataSource })));
        const effectiveInstructorPriority = isFixedCrewLikeOperationalModel(activeOperationalModel)
            ? { ...instructorPriority, enabled: false }
            : instructorPriority;

        const config: DfpConfig = {
            operationalModel: activeOperationalModel,
            activeUnitCode,
            activeContextUnitCodes,
            platformConfig,
            airCombatSchedulingWeights: organisationSettings.airCombatScheduling?.defaultWeights,
            fixedCrewTrainingPriorities,
            fixedCrewTileColourMode: activeFixedCrewTileColourMode,
            instructors: instructorsInBuild,
            trainees: traineesInBuild,
            syllabus: syllabusDetails,
            scores,
            coursePriorities,
            coursePercentages,
            availableAircraftCount: neoAvailableAircraftCount,
            ftdCount: configuredFtdCount,
            cptCount: configuredCptCount,
            courseColors,
            school,
            dayStart: flyingStartTime,
            dayEnd: flyingEndTime,
            ftdStart: ftdStartTime,
            ftdEnd: ftdEndTime,
            allowNightFlying,
            commenceNightFlying,
            ceaseNightFlying,
            flyingWindowExclusions,
            buildDate: buildDfpDate,
            highestPriorityEvents: eventsToUse,
            instructorPriority: effectiveInstructorPriority,
            traineeLMPs: buildTraineeLMPs,
            flightTurnaround,
            ftdTurnaround,
            cptTurnaround,
            preferredDutyPeriod,
            maxCrewDutyPeriod,
            maxDispatchPerHour,
            dispatchStaggerSettings,
            eventLimits,
            sctFtds: sctFtds,
            sctFlights: sctFlights,
            remedialRequests: remedialRequestsForBuild,
            sctEvents: sctEvents,
            formationCallsigns,
            locationAbbreviations,
            unitLocations,
            resourceDisplayNames,
            aircraftConfigurationDefinitions: aircraftConfigCapacityDefinitions,
            aircraftConfigIdsByResource: buildAircraftConfigIdsByResource(currentAircraftConfigState),
            aircraftCrewComposition: activeAircraftCrewComposition,
            runtimeResourceContext: {
                location: school,
                unit: activeUnitCode,
                operationalModel: activeOperationalModel,
                resourcePoolCode: activePlatformResourcePool?.code || null,
                resourcePoolName: activePlatformResourcePool?.name || null,
                resourcePoolAircraftTypeCode: activePlatformResourcePool?.aircraftTypeCode || null,
                runtimeAircraftTypeCode: activeRuntimeAircraftTypeCode,
                runtimeAircraftTypeName: activeRuntimeAircraftType?.name || null,
                runtimeAircraftTypeCategory: activeRuntimeAircraftType?.category || null,
                runtimeAircraftCrewComposition: activeAircraftCrewComposition,
            },
            crewPositionTerminology: activeCrewPositionTerminology,
            staffQualificationCatalogue: activeStaffQualificationCatalogue,
            personnelDisplaySettings,
            remedialPrioritySyncTrace: (window as any).__lastRemedialPrioritySyncTrace || [],
            remedialDataMovementTrace: (window as any).__lastRemedialDataMovementTrace || [],
            taskProvenancePreBuild: (window as any).__lastTaskingProvenancePreBuild || null,
            getEventDayNightClassification: getEventDayNightClassification,
            staffSharingEnabled: organisationSettings.staffSharingEnabled,
            staffSharingUnits: organisationSettings.staffSharingUnits,
            staffSharingGroups: organisationSettings.staffSharingGroups,
            excludedCourses: excludedCourses,
            dbElceMap,  // DB-backed ELCE map (undefined = fall back to DFP-scan)
            timingReport,
        };

        markNeoBuildTiming(timingReport, 'generate:setTimeout-queued', { delayMs: 500 });
        setTimeout(() => {
            try {
                markNeoBuildTiming(timingReport, 'generate:setTimeout-fired');
                logNeoBuildUiDebug('🚀 [NEO-Build] Starting DFP build process for', buildDfpDate);
                logNeoBuildUiDebug('🚀 [NEO-Build] Config:', {
                    instructors: config.instructors.length,
                    trainees: config.trainees.length,
                    syllabus: config.syllabus.length,
                    highestPriorityEvents: config.highestPriorityEvents.length,
                    buildDate: config.buildDate
                });
                const buildInputTrace = {
                    timestamp: new Date().toISOString(),
                    stage: 'before-generateDfpInternal',
                    buildDate: config.buildDate,
                    location: school,
                    activeUnitCode,
                    activeContextUnitCodes,
                    operationalModel: activeOperationalModel,
                    inputs: {
                        instructors: config.instructors.length,
                        trainees: config.trainees.length,
                        syllabus: config.syllabus.length,
                        traineeLMPs: config.traineeLMPs.size,
                        scoresTrainees: config.scores.size,
                        highestPriorityEvents: config.highestPriorityEvents.length,
                        remedialRequests: config.remedialRequests.length,
                        sctFlights: config.sctFlights.length,
                        sctFtds: config.sctFtds.length,
                    },
                    resources: {
                        availableAircraftCount: config.availableAircraftCount,
                        ftdCount: config.ftdCount,
                        cptCount: config.cptCount,
                        aircraftConfigCapacities: config.aircraftConfigCapacities || null,
                        resourceContext: config.runtimeResourceContext || null,
                    },
                    eventLimits: config.eventLimits,
                    buildWindows: {
                        dayStart: config.dayStart,
                        dayEnd: config.dayEnd,
                        ftdStart: config.ftdStart,
                        ftdEnd: config.ftdEnd,
                        allowNightFlying: config.allowNightFlying,
                        commenceNightFlying: config.commenceNightFlying,
                        ceaseNightFlying: config.ceaseNightFlying,
                        flyingWindowExclusions: config.flyingWindowExclusions,
                    },
                    samples: {
                        trainees: config.trainees.slice(0, 20).map((trainee: any) => ({
                            name: trainee.fullName || trainee.name,
                            course: trainee.course,
                            unit: trainee.unit,
                            paused: trainee.isPaused === true,
                            lmpEvents: config.traineeLMPs.get(trainee.fullName || trainee.name)?.length || 0,
                        })),
                        instructors: config.instructors.slice(0, 20).map((staff: any) => ({
                            name: staff.name,
                            role: staff.role,
                            unit: staff.unit,
                            category: staff.category,
                            isAdminStaff: staff.isAdminStaff === true,
                        })),
                    },
                };
                logNeoBuildUiDebug('[NEO-Build][InputTrace]', buildInputTrace);
                try {
                    localStorage.setItem('neo_build_input_trace', JSON.stringify(buildInputTrace));
                } catch (error) {
                    console.warn('[NEO-Build][InputTrace] Failed to save input trace:', error);
                }

                markNeoBuildTiming(timingReport, 'generateDfpInternal:start');
                const generated = generateDfpInternal(config, setDfpBuildProgress, buildPublishedSchedules);
                markNeoBuildTiming(timingReport, 'generateDfpInternal:complete', { generated: generated.length });
                logNeoBuildUiDebug('🚀 [NEO-Build] DFP build completed, generated', generated.length, 'events');
                logNeoBuildUiDebug('🚀 [NEO-Build] Generated events sample:', generated.slice(0, 3));

                pushDfpDataDiag('build:replace-visible-draft-with-generated', {
                    buildDate: buildDfpDate,
                    previousDraftEvents: nextDayBuildEvents.length,
                    generatedEvents: generated.length,
                    generatedSample: generated.slice(0, 12).map(event => ({
                        id: event.id,
                        type: event.type,
                        resourceId: event.resourceId,
                        startTime: event.startTime,
                        duration: event.duration,
                        flightNumber: event.flightNumber,
                        pilot: event.pilot,
                        crew: event.crew,
                        fixedCrewGroup: event.fixedCrewGroup,
                        source: (event as any)._source || (event as any).source || null,
                    })),
                });
                setNextDayBuildEvents(generated);
                setAircraftConfigStateByDate(prev => ({
                    ...prev,
                    [getDailySnapshotKey(buildDfpDate)]: currentAircraftConfigState,
                }));
                markNeoBuildTiming(timingReport, 'state:setNextDayBuildEvents', { generated: generated.length });
                logNeoBuildUiDebug('🚀 [NEO-Build] setNextDayBuildEvents called with', generated.length, 'events');

                const consumedRemedialPriorityIds = new Set(
                    config.remedialRequests
                        .filter(request => request.forceSchedule)
                        .map(request => `remedial-${request.traineeId}-${request.eventCode}`)
                );
                if (consumedRemedialPriorityIds.size > 0) {
                    setRemedialRequests([]);
                    storeRemedialRequests([]);
                    setHighestPriorityEvents(prevEvents =>
                        prevEvents.filter(event => !consumedRemedialPriorityIds.has(event.id))
                    );
                    markNeoBuildTiming(timingReport, 'state:clear-consumed-remedial-priority', {
                        clearedRequests: consumedRemedialPriorityIds.size,
                    });
                }

                const remedialInstructorConflictEvents = generated.filter(event => event.forcedInstructorConflict);
                if (remedialInstructorConflictEvents.length > 0) {
                    const conflictLines = remedialInstructorConflictEvents.slice(0, 5).map(event => {
                        const details = event.forcedInstructorConflictDetails?.[0] || 'assigned instructor has an overlapping event';
                        return `${event.flightNumber} for ${event.student || event.pilot || 'trainee'}: ${details}`;
                    });
                    const moreText = remedialInstructorConflictEvents.length > conflictLines.length
                        ? `\n+${remedialInstructorConflictEvents.length - conflictLines.length} more remedial instructor conflict(s).`
                        : '';
                    void showDarkAlert(
                        `NEO Build scheduled remedial priority event(s) with the assigned instructor despite an instructor conflict:\n\n${conflictLines.join('\n')}${moreText}`,
                        'Remedial Instructor Conflict',
                        'warning',
                        9000
                    );
                }

                // Analyze build results
                markNeoBuildTiming(timingReport, 'analysis:start');
                const analysis = analyzeBuildResults(
                    generated,
                    coursePercentages,
                    coursePriorities,
                    neoAvailableAircraftCount,
                    buildDfpDate,
                    allTraineesData,
                    buildTraineeLMPs,
                    scores,
                    syllabusDetails,
                    publishedSchedules
                );
                markNeoBuildTiming(timingReport, 'analysis:complete', { totalEvents: analysis.totalEvents });

                // Store analysis in state for BuildAnalysisView
                setLastBuildAnalysis(analysis);

                // Store analysis in localStorage for priority analysis page
                localStorage.setItem('lastBuildAnalysis', JSON.stringify({
                    ...analysis,
                    timeDistribution: {
                        eventsByHour: Array.from(analysis.timeDistribution.eventsByHour.entries()),
                        clusteringScore: analysis.timeDistribution.clusteringScore,
                        uniformityScore: analysis.timeDistribution.uniformityScore
                    }
                }));
                markNeoBuildTiming(timingReport, 'analysis:stored');

                logNeoBuildUiDebug('Build analysis:', analysis);

                markNeoBuildTiming(timingReport, 'notifications:start');
                const notifications: string[] = [];
                const allPersonnel = [...allInstructorsData, ...allTraineesData];
                generated.forEach(event => {
                    getPersonnel(event).forEach(personName => {
                        const person = allPersonnel.find(p => p.name === personName || ('fullName' in p && p.fullName === personName));
                        if(person && isPersonStaticallyUnavailable(person, event.startTime, event.startTime + event.duration, buildDfpDate, event.type)) {
                            notifications.push(`${personName} in event ${event.flightNumber} at ${event.startTime.toFixed(2)} conflicts with a static unavailability period.`);

                   // Log the build action to audit trail
                   logAudit(
                       "Next Day Build",
                       "Add",
                       `NEO-Build completed for ${buildDfpDate}`,
                       `Generated ${generated.length} events, Flight: ${generated.filter(e => e.type === 'flight').length}, ${resourceDisplayNames.ftd}: ${generated.filter(e => e.type === 'ftd').length}, Ground: ${generated.filter(e => e.type === 'ground').length}`
                   );
                        }
                    });
                });

                if (notifications.length > 0) {
                    setUnavailabilityNotifications(notifications);
                }
                markNeoBuildTiming(timingReport, 'notifications:complete', { notifications: notifications.length });
                downloadNeoBuildDiagnosticAfterRun('build-complete');

            } catch (error) {
                const runtimeErrorReport = {
                    timestamp: new Date().toISOString(),
                    stage: 'build-error',
                    buildDate: buildDfpDate,
                    message: error instanceof Error ? error.message : String(error),
                    stack: error instanceof Error ? error.stack : null,
                    configSummary: {
                        highestPriorityEvents: config.highestPriorityEvents.length,
                        remedialRequests: config.remedialRequests.length,
                        operationalModel: activeOperationalModel,
                        activeUnitCode,
                        crewPositionTerminology: normaliseCrewPositionTerminology(activeCrewPositionTerminology),
                        activeAircraftCrewComposition,
                        staffRoleSummary: instructorsData.slice(0, 200).map(staff => {
                            const matchedCrewPosition = findCrewPositionEntry(staff.role, activeCrewPositionTerminology);
                            return {
                                name: staff.name,
                                role: staff.role || null,
                                unit: staff.unit || null,
                                isAdminStaff: !!staff.isAdminStaff,
                                matchedCrewPosition: matchedCrewPosition ? {
                                    id: matchedCrewPosition.id,
                                    genericName: matchedCrewPosition.genericName,
                                    label: matchedCrewPosition.label,
                                } : null,
                            };
                        }),
                        highestPriorityCrewRequirements: config.highestPriorityEvents.slice(0, 200).map(event => ({
                            id: event.id,
                            flightNumber: event.flightNumber,
                            type: event.type,
                            date: event.date,
                            startTime: event.startTime,
                            crewRequirement: event.crewRequirement || null,
                            aircraftConfigId: event.aircraftConfigId || null,
                        })),
                        remedialHighestPriorityEvents: config.highestPriorityEvents.filter(event => event.isRemedial || event.id?.startsWith('remedial-')).map(event => ({
                            id: event.id,
                            flightNumber: event.flightNumber,
                            type: event.type,
                            date: event.date,
                            startTime: event.startTime,
                            duration: event.duration,
                            student: event.student || null,
                            pilot: event.pilot || null,
                            instructor: event.instructor || null,
                            isTimeFixed: event.isTimeFixed === true,
                            isRemedial: event.isRemedial === true,
                        })),
                    },
                };
                markNeoBuildTiming(timingReport, 'build:error', { message: runtimeErrorReport.message });
                try {
                    localStorage.setItem('neo_build_runtime_error_report', JSON.stringify(runtimeErrorReport));
                    const existingDiagRaw = localStorage.getItem('neo_build_diag_report');
                    const existingDiag = existingDiagRaw ? JSON.parse(existingDiagRaw) : {};
                    const fallbackAirCombatPriority = existingDiag.airCombatPriority || {
                        enabled: activeOperationalModel === 'air_combat',
                        model: activeOperationalModel,
                        context: {
                            locationCode: school,
                            unitCode: activeUnitCode,
                            buildDate: buildDfpDate,
                        },
                        inputs: {
                            staffTotal: instructorsData.length,
                            pilotRoleStaff: instructorsData.filter(staff => {
                                const roleText = String(staff.role || '').trim().toLowerCase();
                                return !staff.isAdminStaff && Boolean(staff.name) &&
                                    (roleText === 'pilot' || roleText === 'qfi' || roleText === 'instructor' || isPilotCrewPosition(staff.role, activeCrewPositionTerminology));
                            }).length,
                            highestPriorityEvents: config.highestPriorityEvents.length,
                            syllabusItems: syllabusDetails.length,
                        },
                        stageTrace: [{
                            stage: 'runtime-error-before-air-combat-diagnostics',
                            timestamp: runtimeErrorReport.timestamp,
                        }],
                        conclusion: activeOperationalModel === 'air_combat'
                            ? ['Build failed before the Air Combat scheduler diagnostics completed. See runtimeError for the exact exception.']
                            : [`Air Combat scheduler did not run because active model was ${activeOperationalModel || 'blank'}.`],
                        rejectionReasons: {},
                        skipReasons: [],
                        placements: [],
                        placementCycles: [],
                        schedulerSummary: null,
                    };
                    localStorage.setItem('neo_build_diag_report', JSON.stringify({
                        ...existingDiag,
                        stage: 'build-error',
                        updatedAt: runtimeErrorReport.timestamp,
                        runtimeError: runtimeErrorReport,
                        airCombatPriority: fallbackAirCombatPriority,
                    }));
                } catch (diagError) {
                    console.warn('[NEO-BUILD-DIAG] Failed to persist runtime error diagnostic:', diagError);
                }
                console.error("🚀 [NEO-Build] DFP Build Failed:", error);
                console.error("🚀 [NEO-Build] Error stack:", error instanceof Error ? error.stack : 'No stack trace');
                setDfpBuildProgress({ message: 'Error during build!', percentage: 100 });
                downloadNeoBuildDiagnosticAfterRun('build-error');
            } finally {
                markNeoBuildTiming(timingReport, 'navigation:setTimeout-queued', { delayMs: 1000 });
                setTimeout(() => {
                    markNeoBuildTiming(timingReport, 'navigation:setTimeout-fired');
                    logNeoBuildUiDebug('🚀 [NEO-Build] Build process complete, navigating to NextDayBuild');
                    setIsBuildingDfp(false);
                    handleNavigation('NextDayBuild');
                    markNeoBuildTiming(timingReport, 'runBuildAlgorithm:complete');
                }, 1000);
            }
        }, 500);
    };

    const handlePublish = async () => {
        if (!canPublishDfp) {
            denyPlatformAction('Publish DFP is not permitted for your assigned permission profile');
            return;
        }
        if(nextDayBuildEvents.length > 0) {
        // System freeze check - prevent publishing when frozen
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen) {
                showDarkAlert('System is currently frozen. Publishing from NEO Build is not permitted during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
            setShowPublishConfirm(true);
        } else {
            showDarkAlert("No DFP has been built to publish. Please run 'Build DFP' first.", 'Publish Error', 'warning');
        }
    };

    // ── Pause Flight Ops: handlePauseBuild ────────────────────────────────────────────────────────
    const handlePauseBuild = async (config: PauseBuildConfig): Promise<ScheduleEvent[]> => {
        const {
            date: pauseDate,
            pauseStart,
            pauseEnd,
            pauseRule,
            affectedTypes,
            completedEventIds,
            flyingStartTime: dayStart,
            flyingEndTime: dayEnd,
            ftdStartTime: pFtdStart,
            ftdEndTime: pFtdEnd,
        } = config;

        // IMPORTANT: Always use the FULL raw publishedSchedules[date].
        const fullRawEvents: ScheduleEvent[] = publishedSchedules[pauseDate] || [];
        logRoutineAppDebug('[PauseBuild] Starting pause build for', pauseDate,
            'pauseEnd:', pauseEnd, 'dayEnd:', dayEnd,
            'fullRawEvents:', fullRawEvents.length);

        // Record the pause window overlay for the NEO Build schedule view
        setPauseOverlayStart(pauseStart);
        setPauseOverlayEnd(pauseEnd);

        // ── Step 1: Determine which events must be cleared for rebuild ──────────────────────
        // ALL non-completed events of the affected types are cleared from the ENTIRE day
        // (both during the pause window AND after it) — they will be rescheduled from pauseEnd.
        // Only completed events and non-affected event types are kept locked in place.
        const isToBeCleared = (e: ScheduleEvent): boolean => {
            if (e.isCancelled) return false;                          // already cancelled
            if (completedEventIds.has(e.id)) return false;            // completed, keep in place
            const typeKey = e.type === 'ground' ? 'ground' : e.type;
            if (!(affectedTypes as string[]).includes(typeKey)) return false; // not affected type
            // Flight and FTD events: clear ALL for the entire day so they can be rescheduled.
            // Flights reschedule from pauseEnd; FTDs cascade on their resource lines.
            if (e.type === 'flight' || e.type === 'ftd') return true;
            // CPT / Ground: ONLY cancel events that overlap the pause window.
            // Events after the pause remain unchanged — they are NOT rescheduled.
            const eEnd = e.startTime + e.duration;
            const overlapsPause = e.startTime < pauseEnd && eEnd > pauseStart;
            return overlapsPause;
        };

        // ── Step 2: Mark all clearable events as cancelled (OPS_PAUSE) ───────────────────
        const cancelledIds = new Set<string>();
        const eventsAfterCancel: ScheduleEvent[] = fullRawEvents.map(e => {
            if (isToBeCleared(e)) {
                cancelledIds.add(e.id);
                return {
                    ...e,
                    isCancelled: true,
                    cancellationCode: 'OPS_PAUSE' as any,
                    cancelledBy: authUser?.displayName || 'Ops',
                    cancelledAt: new Date().toISOString(),
                };
            }
            return e;
        });
        logRoutineAppDebug('[PauseBuild] Cleared for rebuild:', cancelledIds.size, 'events');

        // ── Step 3: Locked events = completed events + non-affected-type events ─────────
        // These stay exactly where they are; everything else will be rebuilt from pauseEnd.
        const lockedEvents: ScheduleEvent[] = eventsAfterCancel.filter(e => !e.isCancelled);
        logRoutineAppDebug('[PauseBuild] Locked (completed + non-affected type) events:', lockedEvents.length);

        if (isFixedCrewLikeOperationalModel(activeOperationalModel)) {
            const slotStep = 5 / 60;
            const scheduledEvents: ScheduleEvent[] = [...lockedEvents];
            const rescheduledCancelledIds = new Set<string>();
            const roundUpTo5Min = (time: number): number => {
                const totalMinutes = Math.round(time * 60);
                const remainder = totalMinutes % 5;
                if (remainder === 0) return totalMinutes / 60;
                return (totalMinutes + (5 - remainder)) / 60;
            };
            const normalisePausePersonName = (value?: string | null): string => String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
            const getPauseEventPeople = (event: ScheduleEvent): string[] => {
                const ignored = new Set(['', 'tba', 'pooled crew']);
                const names = [
                    event.instructor,
                    event.pilot,
                    event.student,
                    ...((event.attendees || []) as string[]),
                    ...(((event as any).crewSelectionOrder || []) as string[]),
                ]
                    .map(name => String(name || '').trim())
                    .filter(name => !ignored.has(normalisePausePersonName(name)));
                return Array.from(new Set(names.map(normalisePausePersonName)))
                    .map(key => names.find(name => normalisePausePersonName(name) === key) || '')
                    .filter(Boolean);
            };
            const getPausePersonRecord = (personName: string): Instructor | Trainee | null => {
                const key = normalisePausePersonName(personName);
                return instructorsData.find(person => normalisePausePersonName(person.name) === key)
                    || allTraineesData.find(person => normalisePausePersonName(person.fullName) === key || normalisePausePersonName(person.name) === key)
                    || null;
            };
            const getPauseBookingWindow = (event: ScheduleEvent): { start: number; end: number } => (
                getEventBookingWindowForAlgo(event, syllabusDetails)
            );
            const resourceOptionsForPauseType = (eventType: ScheduleEvent['type'], fallbackResourceId?: string): string[] => {
                const resources = fullRawEvents
                    .filter(event => event.type === eventType)
                    .map(event => String(event.resourceId || '').trim())
                    .filter(resourceId => resourceId && !resourceId.startsWith('STBY') && !resourceId.startsWith('BNF-STBY'));
                if (fallbackResourceId && !resources.includes(fallbackResourceId)) resources.unshift(fallbackResourceId);
                return Array.from(new Set(resources));
            };
            const pauseTurnaroundForType = (eventType: ScheduleEvent['type']): number => {
                if (eventType === 'flight') return flightTurnaround;
                if (eventType === 'ftd') return ftdTurnaround;
                if (eventType === 'cpt') return cptTurnaround;
                return 0;
            };
            const pauseWindowForType = (eventType: ScheduleEvent['type']): { start: number; end: number } => {
                if (eventType === 'ftd') return { start: pFtdStart, end: pFtdEnd };
                return { start: dayStart, end: dayEnd };
            };
            const resourceIsBusy = (resourceId: string, startTime: number, duration: number, eventType: ScheduleEvent['type']): boolean => {
                const endTime = startTime + duration;
                const turnaround = pauseTurnaroundForType(eventType);
                return scheduledEvents.some(event => {
                    if (event.isCancelled || event.resourceId !== resourceId) return false;
                    const eventEnd = event.startTime + event.duration;
                    return startTime < eventEnd + turnaround && endTime > event.startTime;
                });
            };
            const hasPauseDispatchStaggerConflict = (candidate: ScheduleEvent): boolean => {
                const minMinutes = getEffectiveDispatchStaggerMinutes(dispatchStaggerSettings, candidate.type);
                if (minMinutes <= 0) return false;
                const type = String(candidate.type || '').trim().toLowerCase();
                const isSimulator = type === 'ftd' || type === 'sim' || type === 'simulator' || type === 'cpt';
                return scheduledEvents.some(event => {
                    if (event.isCancelled || event.resourceId?.startsWith('STBY')) return false;
                    const existingType = String(event.type || '').trim().toLowerCase();
                    const existingIsSimulator = existingType === 'ftd' || existingType === 'sim' || existingType === 'simulator' || existingType === 'cpt';
                    if (type === 'flight') {
                        if (existingType !== 'flight') return false;
                    } else if (isSimulator) {
                        if (!existingIsSimulator) return false;
                    } else {
                        return false;
                    }
                    return Math.abs(event.startTime - candidate.startTime) * 60 < minMinutes - 0.001;
                });
            };
            const exceedsPauseDispatchLimit = (candidate: ScheduleEvent): boolean => {
                if (candidate.type !== 'flight') return false;
                return scheduledEvents.filter(event =>
                    event.type === 'flight'
                    && !event.isCancelled
                    && !event.resourceId?.startsWith('STBY')
                    && event.startTime > candidate.startTime - 1
                    && event.startTime <= candidate.startTime
                ).length >= maxDispatchPerHour;
            };
            const peopleAreBusy = (candidate: ScheduleEvent): boolean => {
                const candidatePeople = getPauseEventPeople(candidate).map(normalisePausePersonName);
                if (candidatePeople.length === 0) return false;
                const candidateWindow = getPauseBookingWindow(candidate);
                return scheduledEvents.some(event => {
                    if (event.isCancelled || event.resourceId?.startsWith('STBY')) return false;
                    const eventWindow = getPauseBookingWindow(event);
                    if (!(eventWindow.start < candidateWindow.end && candidateWindow.start < eventWindow.end)) return false;
                    const existingPeople = getPauseEventPeople(event).map(normalisePausePersonName);
                    return candidatePeople.some(name => existingPeople.includes(name));
                });
            };
            const peopleAreAvailable = (candidate: ScheduleEvent): boolean => {
                const window = getPauseBookingWindow(candidate);
                return getPauseEventPeople(candidate).every(personName => {
                    const person = getPausePersonRecord(personName);
                    if (!person) return true;
                    return !isPersonStaticallyUnavailable(person as any, window.start, window.end, pauseDate, candidate.type as any);
                });
            };
            const peopleWithinEventLimits = (candidate: ScheduleEvent): boolean => {
                const candidatePeople = getPauseEventPeople(candidate).map(normalisePausePersonName);
                if (candidatePeople.length === 0) return true;
                return candidatePeople.every(personKey => {
                    const person = getPausePersonRecord(personKey);
                    const isExec = Boolean((person as Instructor | null)?.isExecutive);
                    const limits = isExec ? eventLimits.exec : eventLimits.instructor;
                    const existingEvents = scheduledEvents.filter(event => {
                        if (event.isCancelled || event.resourceId?.startsWith('STBY')) return false;
                        return getPauseEventPeople(event).some(name => normalisePausePersonName(name) === personKey);
                    });
                    const flightFtdCount = existingEvents.filter(event => event.type === 'flight' || event.type === 'ftd').length;
                    const totalCount = existingEvents.length;
                    if ((candidate.type === 'flight' || candidate.type === 'ftd') && flightFtdCount >= limits.maxFlightFtd) return false;
                    if (totalCount >= limits.maxTotal) return false;
                    return true;
                });
            };
            const candidateObeysPauseRules = (candidate: ScheduleEvent): boolean => (
                !hasPauseDispatchStaggerConflict(candidate)
                && !exceedsPauseDispatchLimit(candidate)
                && !peopleAreBusy(candidate)
                && peopleAreAvailable(candidate)
                && peopleWithinEventLimits(candidate)
            );
            const cancelledCrewEvents = eventsAfterCancel
                .filter(event => cancelledIds.has(event.id) && !completedEventIds.has(event.id))
                .filter(event => event.type === 'flight' || event.type === 'ftd' || event.type === 'cpt' || event.type === 'ground')
                .sort((left, right) => left.startTime - right.startTime);

            for (const original of cancelledCrewEvents) {
                const duration = Number(original.duration) || 0;
                const window = pauseWindowForType(original.type);
                const resources = resourceOptionsForPauseType(original.type, original.resourceId);
                let slot = Math.max(roundUpTo5Min(pauseEnd), roundUpTo5Min(original.startTime));
                let placed: ScheduleEvent | null = null;

                while (duration > 0 && slot + duration <= window.end + 0.001) {
                    if (slot < window.start) {
                        slot += slotStep;
                        continue;
                    }
                    const resourceId = resources.find(resource => !resourceIsBusy(resource, slot, duration, original.type));
                    if (!resourceId) {
                        slot += slotStep;
                        continue;
                    }
                    const candidate: ScheduleEvent = {
                        ...original,
                        id: uuidv4(),
                        date: pauseDate,
                        startTime: slot,
                        duration,
                        resourceId,
                        isCancelled: false,
                        cancellationCode: undefined as any,
                        cancelledBy: undefined,
                        cancelledAt: undefined,
                    };
                    if (!candidateObeysPauseRules(candidate)) {
                        slot += slotStep;
                        continue;
                    }
                    placed = candidate;
                    break;
                }

                if (placed) {
                    scheduledEvents.push(placed);
                    rescheduledCancelledIds.add(original.id);
                    logRoutineAppDebug(`[PauseBuild][CrewModel] Reprogrammed ${original.flightNumber} from ${original.startTime.toFixed(2)} to ${placed.startTime.toFixed(2)} on ${placed.resourceId}`);
                } else {
                    logRoutineAppDebug(`[PauseBuild][CrewModel] Could not reprogram ${original.flightNumber}; will stage as OPS PAUSE STBY.`);
                }
            }

            const stbyOccupied: { resourceId: string; start: number; end: number }[] = scheduledEvents
                .filter(e => e.resourceId?.startsWith('STBY') && !e.isCancelled)
                .map(e => ({ resourceId: e.resourceId, start: e.startTime, end: e.startTime + e.duration }));
            const getNextStbySlot = (evStart: number, evEnd: number): string => {
                let stbyLine = 1;
                while (true) {
                    const stbyId = `STBY ${stbyLine}`;
                    const hasOverlap = stbyOccupied.some(
                        o => o.resourceId === stbyId && o.start < evEnd && o.end > evStart
                    );
                    if (!hasOverlap) break;
                    stbyLine++;
                }
                stbyOccupied.push({ resourceId: `STBY ${stbyLine}`, start: evStart, end: evEnd });
                return `STBY ${stbyLine}`;
            };
            const stbyEvents = cancelledCrewEvents
                .filter(event => !rescheduledCancelledIds.has(event.id))
                .map(event => ({
                    ...event,
                    date: pauseDate,
                    resourceId: getNextStbySlot(event.startTime, event.startTime + event.duration),
                    isCancelled: true,
                    cancellationCode: 'OPS_PAUSE' as any,
                }));
            const seenIds = new Set<string>();
            const finalEvents = [...scheduledEvents, ...stbyEvents].filter(event => {
                if (seenIds.has(event.id)) return false;
                seenIds.add(event.id);
                return true;
            }).map(event => ({ ...event, date: pauseDate }));

            logRoutineAppDebug('[PauseBuild][CrewModel] Final staged events:', finalEvents.length,
                '(locked:', lockedEvents.length,
                'reprogrammed:', rescheduledCancelledIds.size,
                'STBY cancelled:', stbyEvents.length, ')');
            return finalEvents;
        }

        // ── Step 4: Gather the affected trainees and their next syllabus events ──────────
        // For each cancelled event, extract the trainee and their syllabus item
        interface AffectedTraineeEntry {
            trainee: Trainee;
            syllabusItem: SyllabusItemDetail;
            eventType: 'flight' | 'ftd' | 'cpt' | 'ground';
            originalPriorityScore: number;
        }

        // Build course medians for priority scoring
        const getMedianProgressLocal = (courseName: string): number => {
            const courseTrainees = allTraineesData.filter((t: Trainee) => t.course === courseName && !t.isPaused);
            if (courseTrainees.length === 0) return 0;
            const progresses = courseTrainees.map((t: Trainee) =>
                (scores.get(t.fullName) || []).filter((s: Score) => !isRemedialEventCode(s.event)).length
            );
            progresses.sort((a: number, b: number) => a - b);
            const mid = Math.floor(progresses.length / 2);
            return progresses.length % 2 !== 0 ? progresses[mid] : (progresses[mid - 1] + progresses[mid]) / 2;
        };

        const localCourseMedians = new Map<string, number>();
        coursePriorities.forEach((c: string) => localCourseMedians.set(c, getMedianProgressLocal(c)));

        // Helper: map SyllabusItemDetail.type (capitalised) to ScheduleEvent.type (lowercase)
        const syllabusTypeToEventType = (syllabusType: string, fallbackType: string): 'flight' | 'ftd' | 'cpt' | 'ground' => {
            const s = syllabusType?.toLowerCase() || '';
            if (s === 'flight') return 'flight';
            if (s === 'ftd') return 'ftd';
            if (s === 'cpt') return 'cpt';
            if (s.includes('ground')) return 'ground';
            // Fallback to the original cancelled event's type
            const f = fallbackType?.toLowerCase() || '';
            if (f === 'flight') return 'flight';
            if (f === 'ftd') return 'ftd';
            if (f === 'cpt') return 'cpt';
            return 'ground';
        };

        // Collect affected FLIGHT and FTD trainee entries from cancelled events for rescheduling.
        // CPT/Ground cancelled events are silently dropped.
        // Deduplicate by trainee name — each trainee gets scheduled once per type
        const seenTraineeNames = new Set<string>();
        const affectedEntries: AffectedTraineeEntry[] = [];

        for (const cancelledEvent of eventsAfterCancel) {
            if (!cancelledIds.has(cancelledEvent.id)) continue;

            // Only flight and FTD events are rescheduled in the slot-fill loop
            if (cancelledEvent.type !== 'flight' && cancelledEvent.type !== 'ftd') continue;

            const traineeName = cancelledEvent.student || cancelledEvent.pilot || '';
            if (!traineeName) continue;

            // For FTD, allow same trainee multiple times (they may have multiple FTD events)
            // For flight, deduplicate per trainee
            const dedupeKey = cancelledEvent.type === 'ftd'
                ? `ftd:${cancelledEvent.id}`   // each FTD event is its own entry
                : traineeName;                  // flights: one entry per trainee
            if (seenTraineeNames.has(dedupeKey)) continue;
            seenTraineeNames.add(dedupeKey);

            const trainee = allTraineesData.find((t: Trainee) => t.fullName === traineeName);
            if (!trainee) continue;

            if (cancelledEvent.type === 'ftd') {
                // For FTD: keep original cancelled event's syllabus item info intact
                // We'll use it directly to recreate the event on the FTD resource line
                const ftdSyllabusItem: SyllabusItemDetail = {
                    id: cancelledEvent.flightNumber || cancelledEvent.id,
                    code: cancelledEvent.flightNumber || '',
                    type: 'FTD',
                    duration: cancelledEvent.duration,
                    sortieType: 'Dual',
                    preFlightTime: cancelledEvent.preStart,
                    postFlightTime: cancelledEvent.postEnd,
                    isRemedial: false,
                } as SyllabusItemDetail;

                // Priority score for FTD: use original start time as tiebreaker (earlier = higher priority)
                const priorityScore = 10000 - Math.round(cancelledEvent.startTime * 60);

                affectedEntries.push({
                    trainee,
                    syllabusItem: ftdSyllabusItem,
                    eventType: 'ftd',
                    originalPriorityScore: priorityScore,
                });
            } else {
                // FLIGHT: find next syllabus event
                const { next: nextEvent } = computeNextEventsForTrainee(
                    trainee, traineeLMPs, scores, syllabusDetails, publishedSchedules, pauseDate
                );
                if (!nextEvent) continue;

                const eventType = syllabusTypeToEventType(nextEvent.type || '', cancelledEvent.type);

                const courseMedian = localCourseMedians.get(trainee.course) || 0;
                const traineeProgress = (scores.get(trainee.fullName) || [])
                    .filter((s: Score) => !isRemedialEventCode(s.event)).length;
                const isRemedial = nextEvent.isRemedial || false;
                const priorityScore = calculateTraineePriorityScore(
                    trainee, pauseDate, courseMedian, traineeProgress, isRemedial
                );

                affectedEntries.push({ trainee, syllabusItem: nextEvent, eventType, originalPriorityScore: priorityScore });
            }
        }

        // Sort: flights by priority score DESC; FTDs by original start time ASC (earlier first)
        affectedEntries.sort((a, b) => {
            if (a.eventType === 'ftd' && b.eventType === 'ftd') {
                return b.originalPriorityScore - a.originalPriorityScore; // higher = earlier start time
            }
            if (a.eventType !== 'ftd' && b.eventType !== 'ftd') {
                return b.originalPriorityScore - a.originalPriorityScore;
            }
            return 0; // mixed: process flights and FTDs independently
        });
        logRoutineAppDebug('[PauseBuild] Affected trainees to reschedule:', affectedEntries.length,
            '(flights:', affectedEntries.filter(e => e.eventType === 'flight').length,
            'FTDs:', affectedEntries.filter(e => e.eventType === 'ftd').length, ')');

        // ── Step 5: Slot-fill algorithm from pauseEnd at 5-min intervals ─────────────────
        // We maintain a running list of scheduled events (starts from lockedEvents)
        const scheduledEvents: ScheduleEvent[] = [...lockedEvents];
        const successfullyScheduled = new Set<string>(); // trainee fullNames

        // Helper: count flight starts in a rolling 1-hour window ending at 'time' (i.e. from time-1 to time)
        const flightsInLastHour = (time: number): number => {
            return scheduledEvents.filter(e =>
                e.type === 'flight' &&
                !e.isCancelled &&
                !e.resourceId.startsWith('STBY') &&
                e.startTime > time - 1 &&
                e.startTime <= time
            ).length;
        };

        const hasPauseBuildDispatchStaggerConflict = (eventType: string, time: number): boolean => {
            const minMinutes = getEffectiveDispatchStaggerMinutes(dispatchStaggerSettings, eventType);
            if (minMinutes <= 0) return false;
            const type = String(eventType || '').trim().toLowerCase();
            const isSimulator = type === 'ftd' || type === 'sim' || type === 'simulator' || type === 'cpt';
            return scheduledEvents.some(e => {
                if (e.isCancelled) return false;
                if (e.resourceId.startsWith('STBY')) return false;
                const existingType = String(e.type || '').trim().toLowerCase();
                const existingIsSimulator = existingType === 'ftd' || existingType === 'sim' || existingType === 'simulator' || existingType === 'cpt';
                if (type === 'flight') {
                    if (existingType !== 'flight') return false;
                } else if (isSimulator) {
                    if (!existingIsSimulator) return false;
                } else {
                    return false;
                }
                return Math.abs(e.startTime - time) * 60 < minMinutes - 0.001;
            });
        };

        // Helper: check if a person is busy at the given window
        const personIsBusy = (personName: string, windowStart: number, windowEnd: number): boolean => {
            return scheduledEvents.some(e => {
                if (e.isCancelled) return false;
                if (e.resourceId.startsWith('STBY')) return false;
                const isInvolved = e.student === personName || e.pilot === personName ||
                    e.instructor === personName || (e.attendees || []).includes(personName);
                if (!isInvolved) return false;
                const eEnd = e.startTime + e.duration;
                return e.startTime < windowEnd && eEnd > windowStart;
            });
        };

        // Helper: check if a resourceId is occupied at a given time window (with turnaround in hours)
        const isResourceOccupied = (resourceId: string, startTime: number, duration: number, turnaround: number): boolean => {
            const endTime = startTime + duration;
            return scheduledEvents.some(e => {
                if (e.isCancelled) return false;
                if (e.resourceId !== resourceId) return false;
                const eEnd = e.startTime + e.duration;
                // New event must not start before existing event ends + turnaround
                return (startTime < eEnd + turnaround) && (endTime > e.startTime);
            });
        };

        // Helper: find an available aircraft resourceId for flights
        // Cycles through configured aircraft rows, respecting turnaround time (in hours)
        const findAircraftResource = (startTime: number, duration: number): string | null => {
            for (let ac = 1; ac <= availableAircraftCount; ac++) {
                const resourceId = `${activeAircraftResourcePrefix} ${ac}`;
                if (!isResourceOccupied(resourceId, startTime, duration, flightTurnaround)) {
                    return resourceId;
                }
            }
            return null;
        };

        // Helper: find an available FTD resourceId
        const findFtdResource = (startTime: number, duration: number): string | null => {
            for (let ftd = 1; ftd <= availableFtdCount; ftd++) {
                const resourceId = `FTD ${ftd}`;
                if (!isResourceOccupied(resourceId, startTime, duration, ftdTurnaround)) {
                    return resourceId;
                }
            }
            return null;
        };

        // Helper: find an available CPT resourceId
        const findCptResource = (startTime: number, duration: number): string | null => {
            for (let cpt = 1; cpt <= availableCptCount; cpt++) {
                const resourceId = `CPT ${cpt}`;
                if (!isResourceOccupied(resourceId, startTime, duration, cptTurnaround)) {
                    return resourceId;
                }
            }
            return null;
        };

        // Helper: find the best available instructor for a trainee/syllabus item
        const findBestInstructor = (
            trainee: Trainee,
            syllabusItem: SyllabusItemDetail,
            windowStart: number,
            windowEnd: number
        ): string | null => {
            // Get instructor pool - prefer primary instructor, then secondary, then any
            const activeInstructors = instructorsData.filter((ip: Instructor) => {
                if (isPersonStaticallyUnavailable(ip, windowStart, windowEnd, pauseDate, 'flight')) return false;
                if (personIsBusy(ip.name, windowStart, windowEnd)) return false;

                // Check event limits
                const ipEventCount = scheduledEvents.filter(e =>
                    !e.isCancelled &&
                    (e.instructor === ip.name || e.pilot === ip.name) &&
                    !e.resourceId.startsWith('STBY')
                );
                const ipFlightFtdCount = ipEventCount.filter(e => e.type === 'flight' || e.type === 'ftd').length;
                const ipTotalCount = ipEventCount.length;

                if (ip.isExecutive) {
                    if (ipFlightFtdCount >= eventLimits.exec.maxFlightFtd) return false;
                    if (ipTotalCount >= eventLimits.exec.maxTotal) return false;
                } else {
                    if (ipFlightFtdCount >= eventLimits.instructor.maxFlightFtd) return false;
                    if (ipTotalCount >= eventLimits.instructor.maxTotal) return false;
                }
                return true;
            });

            if (activeInstructors.length === 0) return null;

            // Prefer primary instructor from trainee record
            const primaryNames = trainee.primaryInstructor
                ? (Array.isArray(trainee.primaryInstructor) ? trainee.primaryInstructor : [trainee.primaryInstructor])
                : [];
            for (const pName of primaryNames) {
                const found = activeInstructors.find((ip: Instructor) => ip.name === pName);
                if (found) return found.name;
            }

            // Then try secondary instructor
            const secondaryNames = trainee.secondaryInstructor
                ? (Array.isArray(trainee.secondaryInstructor) ? trainee.secondaryInstructor : [trainee.secondaryInstructor])
                : [];
            for (const sName of secondaryNames) {
                const found = activeInstructors.find((ip: Instructor) => ip.name === sName);
                if (found) return found.name;
            }

            // Fall back to any available instructor
            return activeInstructors[0].name;
        };

        // Helper: find available area for a flight
        const findAreaForFlight = (startTime: number, duration: number): string | undefined => {
            return findAvailableArea(startTime, duration, scheduledEvents);
        };

        // Round up to next 5-minute boundary
        const roundUpTo5Min = (time: number): number => {
            const totalMinutes = Math.round(time * 60);
            const remainder = totalMinutes % 5;
            if (remainder === 0) return totalMinutes / 60;
            return (totalMinutes + (5 - remainder)) / 60;
        };

        // Start scheduling from the first 5-min boundary at or after pauseEnd
        const slotStart = roundUpTo5Min(pauseEnd);
        logRoutineAppDebug('[PauseBuild] Scheduling window:', slotStart, 'to', dayEnd);

        // ── Step 5a: Reschedule FTD events ──────────────────────────────────────────────
        const ftdEntries = affectedEntries.filter(e => e.eventType === 'ftd');

        // Group FTD cancelled events by their original resource line
        const cancelledFtdEvents = eventsAfterCancel.filter(e =>
            cancelledIds.has(e.id) && e.type === 'ftd' && !completedEventIds.has(e.id)
        );

        // Build a map: resourceId → sorted list of (originalEvent, affectedEntry)
        const ftdByResource = new Map<string, Array<{ orig: ScheduleEvent; entry: AffectedTraineeEntry }>>();
        for (const orig of cancelledFtdEvents) {
            const resourceId = orig.resourceId || 'FTD 1';
            if (!ftdByResource.has(resourceId)) ftdByResource.set(resourceId, []);
            const entry = ftdEntries.find(e =>
                (e.trainee.fullName === (orig.student || orig.pilot)) &&
                e.syllabusItem.id === (orig.flightNumber || orig.id)
            );
            if (entry) {
                ftdByResource.get(resourceId)!.push({ orig, entry });
            }
        }

        // Process each FTD resource line
        for (const [ftdResourceId, ftdList] of ftdByResource.entries()) {
            ftdList.sort((a, b) => a.orig.startTime - b.orig.startTime);

            for (const { orig, entry } of ftdList) {
                const { trainee, syllabusItem } = entry;
                const duration = syllabusItem.duration;

                let slot = slotStart;
                const slotStep = 5 / 60;
                let scheduled = false;

                while (slot + duration <= dayEnd) {
                    const slotEnd = slot + duration;

                    if (slotEnd > dayEnd) break;

                    if (isResourceOccupied(ftdResourceId, slot, duration, ftdTurnaround)) {
                        slot += slotStep;
                        continue;
                    }

                    if (hasPauseBuildDispatchStaggerConflict('ftd', slot)) {
                        slot += slotStep;
                        continue;
                    }

                    if (personIsBusy(trainee.fullName, slot, slotEnd)) {
                        slot += slotStep;
                        continue;
                    }

                    if (isPersonStaticallyUnavailable(trainee, slot, slotEnd, pauseDate, 'ftd')) {
                        slot += slotStep;
                        continue;
                    }

                    const instructorName = findBestInstructor(trainee, syllabusItem, slot, slotEnd);
                    if (!instructorName) {
                        slot += slotStep;
                        continue;
                    }

                    const newEvent: ScheduleEvent = {
                        ...orig,
                        id: uuidv4(),
                        date: pauseDate,
                        type: 'ftd',
                        instructor: instructorName,
                        student: trainee.fullName,
                        pilot: instructorName,
                        duration,
                        startTime: slot,
                        resourceId: ftdResourceId,
                        isCancelled: false,
                        preStart: syllabusItem.preFlightTime,
                        postEnd: syllabusItem.postFlightTime,
                    };
                    scheduledEvents.push(newEvent);
                    successfullyScheduled.add(`ftd:${trainee.fullName}`);
                    scheduled = true;
                    logRoutineAppDebug(`[PauseBuild] Rescheduled FTD ${trainee.fullName} at ${slot.toFixed(2)} on ${ftdResourceId}`);
                    break;
                }

                if (!scheduled) {
                    logRoutineAppDebug(`[PauseBuild] FTD ${trainee.fullName} could not be rescheduled before dayEnd — dropped`);
                }
            }
        }

        // ── Step 5b: Reschedule FLIGHT events ──────────────────────────────────────────
        const flightEntries = affectedEntries.filter(e => e.eventType === 'flight');

        for (const entry of flightEntries) {
            const { trainee, syllabusItem, eventType } = entry;
            const duration = syllabusItem.duration;

            let scheduled = false;

            const slotStep = 5 / 60;
            let slot = slotStart;

            while (slot + duration <= dayEnd) {
                const slotEnd = slot + duration;

                if (isPersonStaticallyUnavailable(trainee, slot, slotEnd, pauseDate, eventType)) {
                    slot += slotStep;
                    continue;
                }

                if (personIsBusy(trainee.fullName, slot, slotEnd)) {
                    slot += slotStep;
                    continue;
                }

                if (slot < dayStart || slotEnd > dayEnd) {
                    slot += slotStep;
                    continue;
                }

                if (flightsInLastHour(slot) >= maxDispatchPerHour) {
                    slot += slotStep;
                    continue;
                }

                if (hasPauseBuildDispatchStaggerConflict('flight', slot)) {
                    slot += slotStep;
                    continue;
                }

                const resourceId = findAircraftResource(slot, duration);
                if (!resourceId) {
                    slot += slotStep;
                    continue;
                }

                const area = findAreaForFlight(slot, duration);
                if (!area) {
                    slot += slotStep;
                    continue;
                }

                let instructorName: string | null = null;
                if (syllabusItem.sortieType !== 'Solo') {
                    instructorName = findBestInstructor(trainee, syllabusItem, slot, slotEnd);
                    if (!instructorName) {
                        slot += slotStep;
                        continue;
                    }
                }

                const newEvent: ScheduleEvent = {
                    id: uuidv4(),
                    date: pauseDate,
                    type: 'flight',
                    instructor: syllabusItem.sortieType === 'Solo' ? '' : (instructorName || ''),
                    student: trainee.fullName,
                    pilot: syllabusItem.sortieType === 'Solo' ? trainee.fullName : (instructorName || ''),
                    flightNumber: syllabusItem.code,
                    duration,
                    startTime: slot,
                    resourceId,
                    color: courseColors[trainee.course] || 'bg-gray-500',
                    flightType: (syllabusItem.sortieType as 'Dual' | 'Solo') || 'Dual',
                    locationType: 'Local',
                    origin: school,
                    destination: school,
                    area,
                    preStart: syllabusItem.preFlightTime,
                    postEnd: syllabusItem.postFlightTime,
                };
                scheduledEvents.push(newEvent);
                successfullyScheduled.add(trainee.fullName);
                scheduled = true;
                logRoutineAppDebug(`[PauseBuild] Scheduled FLIGHT ${trainee.fullName} (${syllabusItem.code}) at ${slot.toFixed(2)} on ${resourceId}`);
                break;
            }

            if (!scheduled) {
                logRoutineAppDebug(`[PauseBuild] Could not schedule FLIGHT ${trainee.fullName} (${syllabusItem.code})`);
            }
        }

        logRoutineAppDebug('[PauseBuild] Successfully scheduled:', successfullyScheduled.size, 'entries');

        // ── Step 6: Place unscheduled flight/FTD trainees on STBY with red X ──────────
        const stbyOccupied: { resourceId: string; start: number; end: number }[] = scheduledEvents
            .filter(e => e.resourceId?.startsWith('STBY') && !e.isCancelled)
            .map(e => ({ resourceId: e.resourceId, start: e.startTime, end: e.startTime + e.duration }));

        const getNextStbySlot = (evStart: number, evEnd: number): string => {
            let stbyLine = 1;
            while (true) {
                const stbyId = `STBY ${stbyLine}`;
                const hasOverlap = stbyOccupied.some(
                    o => o.resourceId === stbyId && o.start < evEnd && o.end > evStart
                );
                if (!hasOverlap) break;
                stbyLine++;
            }
            stbyOccupied.push({ resourceId: `STBY ${stbyLine}`, start: evStart, end: evEnd });
            return `STBY ${stbyLine}`;
        };

        const stbyEvents: ScheduleEvent[] = [];

        for (const ev of eventsAfterCancel) {
            if (!cancelledIds.has(ev.id)) continue;
            if (completedEventIds.has(ev.id)) continue;

            // CPT and Ground are silently dropped — no STBY placement
            if (ev.type === 'cpt' || ev.type === 'ground') continue;

            const traineeName = ev.student || ev.pilot || '';

            if (ev.type === 'flight') {
                if (traineeName && successfullyScheduled.has(traineeName)) continue;
            }

            if (ev.type === 'ftd') {
                const ftdKey = `ftd:${traineeName}`;
                if (successfullyScheduled.has(ftdKey)) continue;
            }

            const stbyResourceId = getNextStbySlot(ev.startTime, ev.startTime + ev.duration);
            stbyEvents.push({
                ...ev,
                date: pauseDate,
                resourceId: stbyResourceId,
                isCancelled: true,
                cancellationCode: 'OPS_PAUSE' as any,
            });
        }

        logRoutineAppDebug('[PauseBuild] STBY (cancelled) events:', stbyEvents.length,
            '(unscheduled flights + unschedulable FTDs)');

        // ── Step 7: Combine and return ────────────────────────────────────────────────
        const seenIds = new Set<string>();
        const finalEvents: ScheduleEvent[] = [];
        for (const e of [...scheduledEvents, ...stbyEvents]) {
            if (seenIds.has(e.id)) continue;
            seenIds.add(e.id);
            finalEvents.push({ ...e, date: pauseDate });
        }

        logRoutineAppDebug('[PauseBuild] Final staged events:', finalEvents.length,
            '(locked:', lockedEvents.length,
            'newly scheduled:', successfullyScheduled.size,
            'STBY cancelled:', stbyEvents.length, ')');

        return finalEvents;
    };


    // ── Pause Flight Ops: handlePausePublish ─────────────────────────────────────────────────────
    const handlePausePublish = (stagedEvents: ScheduleEvent[]) => {
        const targetDate = date;

        // stagedEvents comes from handlePauseBuild which used the FULL raw publishedSchedules[date].
        // It already contains all events (including group/deployment events).
        // We just deduplicate by ID and ensure date fields are correct.

        const seenIds = new Set<string>();
        const dedupedEvents = stagedEvents.filter(e => {
            if (seenIds.has(e.id)) return false;
            seenIds.add(e.id);
            return true;
        });

        // Ensure every event has the correct date field
        const finalEvents: ScheduleEvent[] = dedupedEvents.map(e => ({ ...e, date: targetDate }));

        logRoutineAppDebug('[PausePublish] Publishing', finalEvents.length, 'events for', targetDate,
            '(was:', (publishedSchedules[targetDate] || []).length, 'before)');

        // 1. Update publishedSchedules (triggers re-render of Program Schedule view)
        setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => ({
            ...prev,
            [targetDate]: finalEvents,
        }));

        // 2. Snapshot as new baseline (for change-detection highlighting)
        setBaselineSchedules((prev) => ({
            ...prev,
            [`${school}:${targetDate}`]: JSON.parse(JSON.stringify(finalEvents)),
        }));

        // 3. Sync training reports with the updated schedule (delayed to let state settle)
        setTimeout(() => {
            setPublishedSchedules(currentSchedules => {
                setPt051Assessments(currentAssessments => {
                    syncPt051WithActiveDfp(currentSchedules, currentAssessments);
                    return currentAssessments;
                });
                return currentSchedules;
            });
        }, 500);

        // 4. Persist to database
        persistScheduleForDate(targetDate, finalEvents);

        // 5. Audit log
        const cancelledCount = finalEvents.filter(e =>
            e.isCancelled && (e as any).cancellationCode === 'OPS_PAUSE'
        ).length;
        const activeCount = finalEvents.filter(e => !e.isCancelled).length;

        logAudit(
            'Program Schedule',
            'Edit',
            `Pause Flight Ops committed for ${targetDate}`,
            `Cancelled: ${cancelledCount} (OPS PAUSE) | Active post-rebuild: ${activeCount} | By: ${authUser?.displayName || 'Unknown'}`
        );

        logRoutineAppDebug('[PausePublish] Done. Total:', finalEvents.length,
            'Active:', activeCount, 'Cancelled (OPS_PAUSE):', cancelledCount);
    };

    const handleConfirmPublish = async () => {
        // Close the confirmation flyout immediately
        setShowPublishConfirm(false);

        // Deduplicate build events by ID before publishing to prevent stacked tiles
        const seenPublishIds = new Set<string>();
        const dedupedBuildEvents = nextDayBuildEvents.filter(e => {
            if (seenPublishIds.has(e.id)) return false;
            seenPublishIds.add(e.id);
            return true;
        });
        logRoutineAppDebug('[PUBLISH] nextDayBuildEvents:', nextDayBuildEvents.length, '→ after dedup:', dedupedBuildEvents.length);

        const newEventsForDate = dedupedBuildEvents.map(e => ({ ...e, date: buildDfpDate }));
        const publishedPriorityEventIds = new Set(
            newEventsForDate
                .map(event => String(event.id || '').trim())
                .filter(Boolean)
        );
        const publishedCurrencyDraftIds = new Set(
            newEventsForDate
                .map(event => String(event.currencyDraftId || '').trim())
                .filter(Boolean)
        );
        const publishedTaskingRequestIds = new Set(
            newEventsForDate
                .map(event => String(event.taskingRequestId || '').trim())
                .filter(Boolean)
        );
        const publishedSctRequestIdsFromEvents = new Set(
            newEventsForDate
                .map(event => String(event.sctRequestId || '').trim())
                .filter(Boolean)
        );
        const publishedSpecificCurrencyRequestIdsByType = newEventsForDate.reduce((map, event) => {
            const draftId = String(event.currencyDraftId || '').trim();
            const parsedMatch = draftId.match(/^specific-currency-(flight|ftd)-(.+)$/);
            if (!parsedMatch) return map;
            map[parsedMatch[1] as 'flight' | 'ftd'].add(parsedMatch[2]);
            return map;
        }, { flight: new Set<string>(), ftd: new Set<string>() });
        const publishedSctRequestIdsByType = newEventsForDate.reduce((map, event) => {
            const explicitId = String(event.sctRequestId || '').trim();
            const parsedMatch = !explicitId ? String(event.id || '').match(/^sct-(flight|ftd)-(.+)$/) : null;
            const requestId = explicitId || parsedMatch?.[2] || '';
            const requestType = String(event.sctRequestType || parsedMatch?.[1] || '').trim();
            if (!requestId || (requestType !== 'flight' && requestType !== 'ftd')) return map;
            map[requestType].add(requestId);
            return map;
        }, { flight: new Set<string>(), ftd: new Set<string>() });
        publishedSpecificCurrencyRequestIdsByType.flight.forEach(requestId => publishedSctRequestIdsByType.flight.add(requestId));
        publishedSpecificCurrencyRequestIdsByType.ftd.forEach(requestId => publishedSctRequestIdsByType.ftd.add(requestId));
        const publishedSctRequestIds = [
            ...Array.from(publishedSctRequestIdsByType.flight),
            ...Array.from(publishedSctRequestIdsByType.ftd),
        ];
        if (publishedSctRequestIdsByType.flight.size > 0) {
            setSctFlights(prev => prev.filter(request => !publishedSctRequestIdsByType.flight.has(request.id)));
        }
        if (publishedSctRequestIdsByType.ftd.size > 0) {
            setSctFtds(prev => prev.filter(request => !publishedSctRequestIdsByType.ftd.has(request.id)));
        }
        if (publishedSctRequestIds.length > 0) {
            publishedSctRequestIds.forEach(requestId => {
                fetch(`/api/sct-requests/${requestId}`, { method: 'DELETE' })
                    .catch(err => console.error('Failed to delete published continuation request:', err));
            });
        }
        if (
            publishedPriorityEventIds.size > 0 ||
            publishedCurrencyDraftIds.size > 0 ||
            publishedTaskingRequestIds.size > 0 ||
            publishedSctRequestIdsFromEvents.size > 0
        ) {
            setHighestPriorityEvents(prevEvents =>
                prevEvents.filter(event => {
                    const eventId = String(event.id || '').trim();
                    const currencyDraftId = String(event.currencyDraftId || '').trim();
                    const taskingRequestId = String(event.taskingRequestId || '').trim();
                    const sctRequestId = String(event.sctRequestId || '').trim();
                    return !(
                        (eventId && publishedPriorityEventIds.has(eventId)) ||
                        (currencyDraftId && publishedCurrencyDraftIds.has(currencyDraftId)) ||
                        (taskingRequestId && publishedTaskingRequestIds.has(taskingRequestId)) ||
                        (sctRequestId && publishedSctRequestIdsFromEvents.has(sctRequestId))
                    );
                })
            );
        }

        const nextPublishedSchedulesForPublish: Record<string, ScheduleEvent[]> = {
            ...publishedSchedulesRef.current,
            [buildDfpDate]: newEventsForDate
        };
        // Keep the ref in step immediately. Program Schedule runs entry-time
        // snapshot guards before React's state/effect cycle has always caught up;
        // without this, it can force-load an empty DB snapshot while publish save
        // is still in flight and make the just-published DFP appear blank.
        publishedSchedulesRef.current = nextPublishedSchedulesForPublish;
        setPublishedSchedules(nextPublishedSchedulesForPublish);
        const publishedSnapshotKey = getDailySnapshotKey(buildDfpDate);
        setAircraftConfigStateByDate(prev => ({
            ...prev,
            [publishedSnapshotKey]: currentAircraftConfigState,
        }));

        // NEW APPROACH: Sync training reports with Active DFP after publish
        logRoutineAppDebug('\u{1F4CB} Triggering training report sync after publish...');
        setTimeout(() => {
            logRoutineAppDebug('\u{23F0} Executing delayed training report sync after publish...');
            setPublishedSchedules(currentSchedules => {
                setPt051Assessments(currentAssessments => {
                    syncPt051WithActiveDfp(currentSchedules, currentAssessments);
                    return currentAssessments;
                });
                return currentSchedules;
            });
        }, 500);

        // Snapshot the schedule as the baseline for change detection
        setBaselineSchedules((prev) => ({
            ...prev,

            [`${school}:${buildDfpDate}`]: JSON.parse(JSON.stringify(newEventsForDate))
        }));

           // Log the publish action to audit trail
           logAudit(
               "Next Day Build",
               "Edit",
               `Published schedule for ${buildDfpDate}`,
               `Total events: ${newEventsForDate.length}, Flight: ${newEventsForDate.filter(e => e.type === "flight").length}, ${resourceDisplayNames.ftd}: ${newEventsForDate.filter(e => e.type === "ftd").length}, Ground: ${newEventsForDate.filter(e => e.type === "ground").length}`
           );

        // ── SAVE DAILY SNAPSHOT TO DATABASE ──────────────────────────────────
        // Guard: skip if any event is seed data
        const hasSeedData = newEventsForDate.some(e => (e as any).isHistoricalSeed === true);
        if (!hasSeedData && newEventsForDate.length > 0) {
            // Build snapshot data from current state
            const staffEventsForDate = newEventsForDate.filter(e =>
                e.instructor && !e.student && e.type !== 'logbook'
            );
            const traineeEventsForDate = newEventsForDate.filter(e =>
                !!(e.student || (e as any).traineeId)
            );

            // Build per-instructor logbook map from all published schedules + new date
            const staffLogbookMap: Record<string, any[]> = {};
            const allPublishedForLogbook = {
                ...publishedSchedules,
                [buildDfpDate]: newEventsForDate
            };
            Object.entries(allPublishedForLogbook).forEach(([dateKey, events]) => {
                (events as ScheduleEvent[]).forEach(e => {
                    if ((e as any).isLogbook === true || e.type === 'logbook') {
                        const instName = e.instructor || '';
                        if (!staffLogbookMap[instName]) staffLogbookMap[instName] = [];
                        staffLogbookMap[instName].push({
                            date: dateKey,
                            eventCode: (e as any).eventCode || e.id,
                            flightNumber: (e as any).flightNumber,
                            duration: e.duration,
                            student: e.student,
                            flightType: (e as any).flightType || 'Dual',
                            locationType: (e as any).locationType || 'Local',
                            origin: (e as any).origin || '',
                            destination: (e as any).destination || '',
                        });
                    }
                });
            });

            // Build per-staff currency map
            const staffCurrencyMap: Record<string, any> = {};
            instructorsData.forEach((inst: any) => {
                if (inst.currencyStatus && inst.currencyStatus.length > 0) {
                    staffCurrencyMap[inst.name] = inst.currencyStatus;
                }
            });

            // Build trainee profiles snapshot
            const traineeProfilesSnapshot = traineesData.map((t: any) => ({
                idNumber: t.idNumber,
                fullName: t.fullName,
                name: t.name,
                rank: t.rank,
                course: t.course,
                lmpType: t.lmpType,
                service: t.service,
                unit: t.unit,
                primaryInstructor: t.primaryInstructor,
                currencyStatus: t.currencyStatus || [],
                isPaused: t.isPaused || false,
            }));

            const staffProfilesSnapshot = instructorsData.map((inst: any) => ({
                id: inst.id,
                idNumber: inst.idNumber,
                name: inst.name,
                rank: inst.rank,
                role: inst.role,
                unit: inst.unit,
                location: inst.location,
                flight: inst.flight,
                service: inst.service,
                category: inst.category,
                isQFI: !!inst.isQFI,
                isOFI: !!inst.isOFI,
                isCFI: !!inst.isCFI,
                isFlyingSupervisor: !!inst.isFlyingSupervisor,
                isTestingOfficer: !!inst.isTestingOfficer,
                isCommandingOfficer: !!inst.isCommandingOfficer,
                isExecutive: !!inst.isExecutive,
                isPaused: !!inst.isPaused,
                currencyStatus: inst.currencyStatus || [],
                snapshotSchool: school,
                snapshotUnit: activeUnitCode,
                operationalModel: activeOperationalModel,
                snapshotDate: buildDfpDate,
            }));

            // Build per-trainee LMP completedEventIds map
            const lmpCompletedIdsMap: Record<string, string[]> = {};
            traineesData.forEach((t: any) => {
                const individualLMP = traineeLMPs.get(t.fullName);
                if (individualLMP) {
                    const completedIds = (individualLMP as any[])
                        .filter((item: any) => item.completedAt || item.isComplete)
                        .map((item: any) => (item.id || item.code || '').replace('*', ''));
                    if (completedIds.length > 0) {
                        lmpCompletedIdsMap[t.fullName] = completedIds;
                    }
                }
            });

            const snapshotKey = getDailySnapshotKey(buildDfpDate);
            const snapshotPayload = {
                date: snapshotKey,
                locationCode: school,
                unitCode: activeUnitCode,
                operationalModel: activeOperationalModel,
                scheduleEvents: newEventsForDate,
                staffEvents: staffEventsForDate,
                traineeEvents: traineeEventsForDate,
                traineeProfiles: traineeProfilesSnapshot,
                staffProfiles: staffProfilesSnapshot,
                lmpCompletedIds: lmpCompletedIdsMap,
                staffCurrency: staffCurrencyMap,
                staffLogbook: staffLogbookMap,
                aircraftConfigState: currentAircraftConfigState,
                savedBy: authUser?.userId || (authUser as any)?.username || null,
                // Store the baseline (original published events) for change-bar detection after page reload
                baselineEvents: newEventsForDate,
            };

            const apiBase = getApiBaseUrl();
            // Publish is authoritative for this date immediately. Mark the snapshot
            // loaded before switching views so the date loader cannot race in with
            // an older DB snapshot and overwrite the freshly published NEO Build.
            loadedSnapshotDates.current.add(snapshotKey);
            loadingSnapshotDates.current.delete(snapshotKey);
            setSnapshotDates(prev => (
                [...new Set([...prev, buildDfpDate])]
                    .sort((a, b) => b.localeCompare(a))
            ));
            snapshotKeysByDateRef.current = {
                ...snapshotKeysByDateRef.current,
                [buildDfpDate]: [
                    ...(snapshotKeysByDateRef.current[buildDfpDate] || []),
                    snapshotKey,
                ].filter((key, index, keys) => key && keys.indexOf(key) === index),
            };
            cacheDailySnapshot(snapshotKey, snapshotPayload, buildDfpDate);
            try {
                const saveResponse = await fetch(`${apiBase}/daily-snapshot/save`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(snapshotPayload),
                });
                const result = await saveResponse.json().catch(() => ({}));
                if (!saveResponse.ok || !result.success) {
                    throw new Error(result.error || result.details || `Snapshot save failed with HTTP ${saveResponse.status}`);
                }
                logRoutineAppDebug(`\u2705 [Snapshot] Saved daily snapshot for ${buildDfpDate} (${school} - ${activeUnitCode}), ${newEventsForDate.length} events`);
                // Mark this date as loaded so loadSnapshotForDate won't overwrite it on navigation
                loadedSnapshotDates.current.add(snapshotKey);
                cacheDailySnapshot(snapshotKey, snapshotPayload, buildDfpDate);
            } catch (err) {
                console.warn(`\u26A0\uFE0F [Snapshot] Could not save daily snapshot for ${buildDfpDate}:`, err);
                await showDarkAlert(
                    `The DFP was built, but it was not saved to the published DFP database.\n\n${err instanceof Error ? err.message : String(err)}\n\nDo not hard refresh yet. Try Publish again, then confirm the save succeeds.`,
                    'Publish Save Failed',
                    'error'
                );
                return;
            }
        } else if (hasSeedData) {
            logRoutineAppDebug(`\u26A0\uFE0F [Snapshot] Skipped saving seed data for ${buildDfpDate}`);
            await showDarkAlert(
                'This DFP contains setup-only events, so it was not saved as a real published DFP.',
                'Publish Save Blocked',
                'error'
            );
            return;
        }
        // ─────────────────────────────────────────────────────────────────────

        setDate(buildDfpDate);
        setNextDayBuildEvents([]);
        setActiveView('Program Schedule');
        setSuccessMessage('DFP Successfully Published!');
    };


    // ─── Deployment-driven unavailability ──────────────────────────────────────
    // When a flight tile is dragged onto (overlapping) a deployment tile, automatically
    // insert a "Deployed" unavailability for the flight's personnel that spans from the
    // flight's start time to the end of the deployment.
    // When a tile is dragged away, the matching unavailability is removed.
    // Each auto-inserted period uses notes = `__deploy__${eventId}` as an internal tag.

    const handleDeploymentUnavailability = async (updatedSchedule: ScheduleEvent[]) => {
        const deploymentTiles = updatedSchedule.filter(e => e.type === 'deployment');

        const flightTiles = updatedSchedule.filter(e =>
            e.type === 'flight' || e.type === 'ftd' || e.type === 'cpt' || e.type === 'ground'
        );

        // Deployment unavailability check
        logRoutineAppDebug('[DeployUnavail] handleDeploymentUnavailability: deployments=' + deploymentTiles.length + ' flights=' + flightTiles.length);

        if (deploymentTiles.length === 0) {
            logRoutineAppDebug('[DeployUnavail] No deployment tiles - removing all lingering Deployed periods');
            // No deployments — remove any lingering Deployed periods tagged to all flight tiles
            for (const flight of flightTiles) {
                await removeDeployedUnavailability(flight.id);
            }
            // Also call server-side cleanup to remove any __deploy__ tags that may still be in the DB
            // (catches cases where previous PATCH calls failed or the data was loaded from a stale DB state)
            try {
                const cleanupRes = await fetch('/api/cleanup-deploy-unavailability', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                });
                if (cleanupRes.ok) {
                    const cleanupData = await cleanupRes.json();
                    if (cleanupData.personnelFixed > 0 || cleanupData.traineesFixed > 0) {
                        logRoutineAppDebug('[DeployUnavail] Server cleanup fixed', cleanupData.personnelFixed, 'personnel and', cleanupData.traineesFixed, 'trainees in DB');
                    }
                }
            } catch (err) { console.error('[DeployUnavail] Server cleanup call failed:', err); }
            return;
        }

        const parseDeploymentClock = (clock?: string): number | null => {
            if (!clock) return null;
            const match = clock.match(/^(\d{1,2}):?(\d{2})$/);
            if (!match) return null;
            return Number(match[1]) + Number(match[2]) / 60;
        };
        const dateTimeMs = (dateStr: string, hours: number): number =>
            new Date(`${dateStr}T00:00:00Z`).getTime() + hours * 60 * 60 * 1000;

        for (const flight of flightTiles) {
            // A flight is "on a deployment" only when it has actually been
            // dropped onto the same Deployed resource row and overlaps that
            // deployment tile. Date range alone is too broad and marks unrelated
            // same-day events as deployed.
            const overlappingDeploy = deploymentTiles.find(dep => {
                const assignedDeploymentId = (flight as any).assignedDeploymentId || (flight as any).deploymentId;
                if (assignedDeploymentId && assignedDeploymentId === dep.id) return true;
                if (!flight.resourceId?.startsWith('Deployed')) return false;
                if (dep.resourceId && flight.resourceId !== dep.resourceId) return false;

                const depStartDate = dep.deploymentStartDate || dep.date;
                const depStartTime = parseDeploymentClock(dep.deploymentStartTime) ?? dep.startTime;
                const depStartMs = dateTimeMs(depStartDate, depStartTime);

                let depEndMs: number;
                if (dep.deploymentEndDate && dep.deploymentEndTime) {
                    const depEndTime = parseDeploymentClock(dep.deploymentEndTime);
                    depEndMs = dateTimeMs(dep.deploymentEndDate, depEndTime ?? (dep.startTime + dep.duration));
                } else {
                    depEndMs = depStartMs + dep.duration * 60 * 60 * 1000;
                }

                const flightStartMs = dateTimeMs(flight.date, flight.startTime);
                const flightEndMs = dateTimeMs(flight.date, flight.startTime + flight.duration);
                return flightStartMs < depEndMs && flightEndMs > depStartMs;
            });

            if (overlappingDeploy) {
                await upsertDeployedUnavailability(flight, overlappingDeploy);
            } else {
                await removeDeployedUnavailability(flight.id);
            }
        }

    };

    const upsertDeployedUnavailability = async (flight: ScheduleEvent, deployment: ScheduleEvent) => {
        // Calculate unavailability period: deployment start → deployment end.
        const parseDeploymentClock = (clock?: string): number | null => {
            if (!clock) return null;
            const match = clock.match(/^(\d{1,2}):?(\d{2})$/);
            if (!match) return null;
            return Number(match[1]) + Number(match[2]) / 60;
        };
        const deploymentStartDate = deployment.deploymentStartDate || deployment.date || flight.date;
        const deploymentStartHour = parseDeploymentClock(deployment.deploymentStartTime) ?? deployment.startTime ?? flight.startTime;
        const startHour = Math.floor(deploymentStartHour);
        const startMin  = Math.round((deploymentStartHour % 1) * 60);
        const startTime = `${String(startHour).padStart(2, '0')}${String(startMin).padStart(2, '0')}`;

        // Deployment end: use deploymentEndDate/Time if available, else calculate from startTime+duration
        let endDateStr: string;
        let endTime: string;

        if (deployment.deploymentEndDate && deployment.deploymentEndTime) {
            endDateStr = deployment.deploymentEndDate;
            endTime = deployment.deploymentEndTime.replace(':', '');
        } else {
            // Calculate from startTime + duration (duration may span days)
            const totalEndHours = deployment.startTime + deployment.duration;
            const daysOffset = Math.floor(totalEndHours / 24);
            const endHour = Math.floor(totalEndHours % 24);
            const endMin  = Math.round(((totalEndHours % 24) % 1) * 60);
            const baseDate = new Date(deployment.date + 'T00:00:00Z');
            baseDate.setUTCDate(baseDate.getUTCDate() + daysOffset);
            endDateStr = baseDate.toISOString().slice(0, 10);
            endTime = `${String(endHour).padStart(2, '0')}${String(endMin).padStart(2, '0')}`;
        }

        const tag = `__deploy__${flight.id}`;
        const newPeriod: Omit<UnavailabilityPeriod, 'id'> & { id: string } = {
            id: `deploy-${flight.id}`,
            startDate: deploymentStartDate,
            endDate: endDateStr,
            startTime,
            endTime,
            allDay: false,
            reason: 'Deployed' as UnavailabilityReason,
            notes: tag,
        };


        // Collect personnel on this flight
        const personnelNames: string[] = [];
        if (flight.instructor) personnelNames.push(flight.instructor);
        if (flight.student) {
            const studentName = flight.student.split(' – ')[0] || flight.student;
            personnelNames.push(studentName);
        }
        if (flight.pilot) personnelNames.push(flight.pilot);
        if (flight.crew) personnelNames.push(flight.crew);


        // Use refs for latest data (avoid stale closures)
        const latestInstructorsForUpsert = allInstructorsDataRef.current;
        const latestTraineesForUpsert    = allTraineesDataRef.current;

        for (const personName of personnelNames) {
            // Check instructors
            const instructor = latestInstructorsForUpsert.find(i => i.name === personName);
            if (instructor) {
                const existing = (instructor.unavailability || []);
                const alreadyHas = existing.some(p => p.notes === tag);
                if (!alreadyHas) {
                    const updated = [...existing, newPeriod];
                    const updatedInstructor = { ...instructor, unavailability: updated };
                    setInstructorsData((prev: Instructor[]) => prev.map(i => i.name === personName ? updatedInstructor : i));
                    // Persist to DB
                    const dbId = (instructor as any).id;
                    if (dbId && (instructor as any)._dataSource === 'database') {
                        try {
                            await fetch(`/api/personnel/${dbId}`, {
                                method: 'PATCH',
                                headers: { 'Content-Type': 'application/json' },
                                credentials: 'include',
                                body: JSON.stringify({ unavailability: updated }),
                            });
                        } catch (err) { console.error('Failed to persist Deployed unavailability for instructor:', personName, err); }
                    }
                }
                continue;
            }
            // Check trainees
            const trainee = latestTraineesForUpsert.find(t => t.name === personName || t.fullName === personName);
            if (trainee) {
                const existing = (trainee.unavailability || []);
                const alreadyHas = existing.some(p => p.notes === tag);
                if (!alreadyHas) {
                    const updated = [...existing, newPeriod];
                    const updatedTrainee = { ...trainee, unavailability: updated };
                    setTraineesData((prev: Trainee[]) => prev.map(t => (t.name === personName || t.fullName === personName) ? updatedTrainee : t));
                    const dbId = (trainee as any).id;
                    if (dbId && (trainee as any)._dataSource === 'database') {
                        try {
                            await fetch(`/api/trainees/${dbId}`, {
                                method: 'PATCH',
                                headers: { 'Content-Type': 'application/json' },
                                credentials: 'include',
                                body: JSON.stringify({ unavailability: updated }),
                            });
                        } catch (err) { console.error('Failed to persist Deployed unavailability for trainee:', personName, err); }
                    }
                }
            }
        }

    };

    const removeDeployedUnavailability = async (flightId: string) => {
        const tag = `__deploy__${flightId}`;

        // Use refs to always read the LATEST instructor/trainee data (avoids stale closures
        // when called from setTimeout or inside state-setter callbacks).
        const latestInstructors = allInstructorsDataRef.current;
        const latestTrainees    = allTraineesDataRef.current;

        // Diagnostic logging
        const instructorsWithTag = latestInstructors.filter(i => (i.unavailability || []).some(p => p.notes === tag));
        const traineesWithTag    = latestTrainees.filter(t => (t.unavailability || []).some(p => p.notes === tag));
        logRoutineAppDebug('[DeployUnavail] removeDeployedUnavailability flightId="' + flightId + '" tag="' + tag + '"',
            'instructors with tag:', instructorsWithTag.map(i => i.name),
            'trainees with tag:', traineesWithTag.map(t => t.name)
        );

        // Instructors
        const affectedInstructors = latestInstructors.filter(i =>
            (i.unavailability || []).some(p => p.notes === tag)
        );
        for (const instructor of affectedInstructors) {
            const updated = (instructor.unavailability || []).filter(p => p.notes !== tag);
            const updatedInstructor = { ...instructor, unavailability: updated };
            setInstructorsData((prev: Instructor[]) => prev.map(i => i.name === instructor.name ? updatedInstructor : i));
            const dbId = (instructor as any).id;
            if (dbId && (instructor as any)._dataSource === 'database') {
                try {
                    const resp = await fetch(`/api/personnel/${dbId}`, {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'include',
                        body: JSON.stringify({ unavailability: updated }),
                    });
                    if (!resp.ok) console.error('[DeployUnavail] PATCH instructor failed:', instructor.name, resp.status);
                    else logRoutineAppDebug('[DeployUnavail] PATCH instructor OK:', instructor.name, 'removed tag', tag);
                } catch (err) { console.error('[DeployUnavail] Failed to remove Deployed unavailability for instructor:', instructor.name, err); }
            }
        }

        // Trainees
        const affectedTrainees = latestTrainees.filter(t =>
            (t.unavailability || []).some(p => p.notes === tag)
        );
        for (const trainee of affectedTrainees) {
            const updated = (trainee.unavailability || []).filter(p => p.notes !== tag);
            const updatedTrainee = { ...trainee, unavailability: updated };
            setTraineesData((prev: Trainee[]) => prev.map(t => (t.name === trainee.name || t.fullName === trainee.fullName) ? updatedTrainee : t));
            const dbId = (trainee as any).id;
            if (dbId && (trainee as any)._dataSource === 'database') {
                try {
                    const resp = await fetch(`/api/trainees/${dbId}`, {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'include',
                        body: JSON.stringify({ unavailability: updated }),
                    });
                    if (!resp.ok) console.error('[DeployUnavail] PATCH trainee failed:', trainee.name, resp.status);
                    else logRoutineAppDebug('[DeployUnavail] PATCH trainee OK:', trainee.name, 'removed tag', tag);
                } catch (err) { console.error('[DeployUnavail] Failed to remove Deployed unavailability for trainee:', trainee.name, err); }
            }
        }
    };
    // ───────────────────────────────────────────────────────────────────────────

    type ScheduleTileUpdate = { eventId: string; newStartTime?: number; newResourceId?: string; newAircraftNumber?: string; };
    const expandFormationScheduleUpdates = (scheduleForDate: ScheduleEvent[], updates: ScheduleTileUpdate[]): ScheduleTileUpdate[] => {
        const expanded = new Map<string, ScheduleTileUpdate>(updates.map(update => [update.eventId, update]));
        updates.forEach(update => {
            const movedEvent = scheduleForDate.find(event => event.id === update.eventId);
            const formationId = String(movedEvent?.formationId || '').trim();
            if (!movedEvent || !formationId) return;
            const startDelta = typeof update.newStartTime === 'number'
                ? update.newStartTime - movedEvent.startTime
                : null;
            if (startDelta === null) return;
            scheduleForDate
                .filter(event => event.id !== movedEvent.id && event.formationId === formationId && !expanded.has(event.id))
                .forEach(event => {
                    expanded.set(event.id, {
                        eventId: event.id,
                        newStartTime: event.startTime + startDelta,
                    });
                });
        });
        return Array.from(expanded.values());
    };

    const handleScheduleUpdate = (updates: ScheduleTileUpdate[]) => {
        if (!updates || updates.length === 0) return;
        if (isPastDfpDate(date)) {
            denyPastDfpEdit('move tiles');
            return;
        }

        let updatedEventsForDate: ScheduleEvent[] = [];
        let appliedUpdates: ScheduleTileUpdate[] = updates;
        setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
            const scheduleForDate = prev[date] || [];
            appliedUpdates = expandFormationScheduleUpdates(scheduleForDate, updates);
            const updatesMap = new Map(appliedUpdates.map(u => [u.eventId, u]));

            const newScheduleForDate = scheduleForDate.map(event => {
                if (updatesMap.has(event.id)) {
                    const update = updatesMap.get(event.id)!;
                    return {
                        ...event,
                        startTime: update.newStartTime ?? event.startTime,
                        resourceId: update.newResourceId ?? event.resourceId,
                        aircraftNumber: Object.prototype.hasOwnProperty.call(update, 'newAircraftNumber') ? update.newAircraftNumber : event.aircraftNumber,
                    };
                }
                return event;
            });
            updatedEventsForDate = newScheduleForDate; // capture for persist
            return { ...prev, [date]: newScheduleForDate };
        });
        // Persist the updated positions to database immediately
        // Use a short debounce (500ms) to avoid hammering DB during a drag
        if (_scheduleUpdatePersistTimer.current) clearTimeout(_scheduleUpdatePersistTimer.current);
        _scheduleUpdatePersistTimer.current = window.setTimeout(() => {
            if (updatedEventsForDate.length > 0) {
                persistScheduleForDate(date, updatedEventsForDate);
                // Handle deployment-driven unavailability after drag settles.
                // IMPORTANT: pass the FULL schedule across all dates so we can find
                // deployment tiles that may live on a different date than the dragged flight.
                setPublishedSchedules(prevSchedules => {
                    const allEvents = Object.values(prevSchedules).flat();
                    handleDeploymentUnavailability(allEvents);
                    return prevSchedules; // no state change, just reading
                });
            }
        }, 500);

        // Log the updates to audit trail
appliedUpdates.forEach(update => {
               const event = updatedEventsForDate.find(e => e.id === update.eventId);
               if (event) {
                      // Capture original values BEFORE they change
                      const originalStartTime = event.startTime;
                      const originalResourceId = event.resourceId;
                      const eventType = event.type || 'event';
                      const personName = event.student || event.pilot || event.instructor || 'Unknown';

                      // Use debounced logging - waits 3 seconds after last move
                      // Pass original and new values separately so debouncer can track them
                      debouncedAuditLog(
                          `schedule-move-${update.eventId}`,
                          {
                              page: "Program Schedule",
                              action: "Edit",
                              description: `Moved ${eventType} event for ${personName}`,
                              originalValues: {
                                  startTime: originalStartTime,
                                  resourceId: originalResourceId
                              },
                              newValues: {
                                  startTime: update.newStartTime,
                                  resourceId: update.newResourceId
                              }
                          },
                          logAudit
                      );
               }
           });
       };
    const handleNextDayScheduleUpdate = (updates: ScheduleTileUpdate[]) => {
        if (!updates || updates.length === 0) return;

        let appliedUpdates: ScheduleTileUpdate[] = updates;
        setNextDayBuildEvents(prev => {
            appliedUpdates = expandFormationScheduleUpdates(prev, updates);
            const updatesMap = new Map(appliedUpdates.map(u => [u.eventId, u]));
            return prev.map(event => {
                if (updatesMap.has(event.id)) {
                    const update = updatesMap.get(event.id)!;
                    return {
                        ...event,
                        startTime: update.newStartTime ?? event.startTime,
                        resourceId: update.newResourceId ?? event.resourceId,
                    };
                }
                return event;
            });
        });

// Log the updates to audit trail
           appliedUpdates.forEach(update => {
               const event = nextDayBuildEvents.find(e => e.id === update.eventId);
               if (event) {
                      // Capture original values BEFORE they change
                      const originalStartTime = event.startTime;
                      const originalResourceId = event.resourceId;
                      const eventType = event.type || 'event';
                      const personName = event.student || event.pilot || event.instructor || 'Unknown';

                      // Use debounced logging - waits 3 seconds after last move
                      // Pass original and new values separately so debouncer can track them
                      debouncedAuditLog(
                          `ndb-move-${update.eventId}`,
                          {
                              page: "Next Day Build",
                              action: "Edit",
                              description: `Moved ${eventType} event for ${personName}`,
                              originalValues: {
                                  startTime: originalStartTime,
                                  resourceId: originalResourceId
                              },
                              newValues: {
                                  startTime: update.newStartTime,
                                  resourceId: update.newResourceId
                              }
                          },
                          logAudit
                      );
               }
           });    };

    const getFormationCallsignBase = (callsign?: string) => {
        const raw = String(callsign || 'CSIGN').trim().toUpperCase();
        return raw.replace(/[^A-Z0-9]/g, '').replace(/\d+$/g, '') || 'CSIGN';
    };

    const formatDroppedDeploymentClock = (decimalHour: number): string => {
        const normalised = ((Number(decimalHour) || 0) % 24 + 24) % 24;
        const hours = Math.floor(normalised);
        const minutes = Math.round((normalised - hours) * 60);
        return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
    };

    const addDaysToIsoDate = (isoDate: string, daysToAdd: number): string => {
        const parts = String(isoDate || '').split('-').map(Number);
        if (parts.length !== 3 || parts.some(part => !Number.isFinite(part))) return isoDate;
        const result = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
        result.setUTCDate(result.getUTCDate() + daysToAdd);
        return `${result.getUTCFullYear()}-${String(result.getUTCMonth() + 1).padStart(2, '0')}-${String(result.getUTCDate()).padStart(2, '0')}`;
    };

    const getDeploymentDateRange = (startDate: string, endDate: string): string[] => {
        const startParts = String(startDate || '').split('-').map(Number);
        const endParts = String(endDate || '').split('-').map(Number);
        if (
            startParts.length !== 3 ||
            endParts.length !== 3 ||
            startParts.some(part => !Number.isFinite(part)) ||
            endParts.some(part => !Number.isFinite(part))
        ) return [startDate].filter(Boolean);
        const cursor = new Date(Date.UTC(startParts[0], startParts[1] - 1, startParts[2]));
        const end = new Date(Date.UTC(endParts[0], endParts[1] - 1, endParts[2]));
        const dates: string[] = [];
        while (cursor.getTime() <= end.getTime()) {
            dates.push(`${cursor.getUTCFullYear()}-${String(cursor.getUTCMonth() + 1).padStart(2, '0')}-${String(cursor.getUTCDate()).padStart(2, '0')}`);
            cursor.setUTCDate(cursor.getUTCDate() + 1);
        }
        return dates.length > 0 ? dates : [startDate].filter(Boolean);
    };

    const parseDeploymentClockHours = (clock?: string): number | null => {
        if (!clock) return null;
        const match = String(clock).trim().match(/^(\d{1,2}):?(\d{2})$/);
        if (!match) return null;
        return Number(match[1]) + Number(match[2]) / 60;
    };

    const buildDroppedNeoAssistEvents = useCallback((draft: ScheduleEvent, placement: NeoAssistDropPlacement, eventDate: string, resourcePool: string[]): ScheduleEvent[] => {
        const firstResourceId = placement.resourceId || draft.resourceId;
        const activeAircraftPrefix = `${activeAircraftResourcePrefix} `;
        const isActiveAircraftResource = (resourceId?: string): boolean =>
            String(resourceId || '').trim().startsWith(activeAircraftPrefix);
        const startTime = placement.startTime;
        if (draft.type === 'deployment') {
            const deploymentStartTime = Number.isFinite(Number(draft.startTime)) ? Number(draft.startTime) : startTime;
            const deploymentDuration = Math.max(0.1, Number(draft.duration) || 1);
            const deploymentStartDate = draft.deploymentStartDate || eventDate;
            const deploymentStartClock = draft.deploymentStartTime || formatDroppedDeploymentClock(deploymentStartTime);
            const deploymentEndClock = draft.deploymentEndTime || formatDroppedDeploymentClock(deploymentStartTime + deploymentDuration);
            const deploymentEndDate = draft.deploymentEndDate || addDaysToIsoDate(eventDate, Math.floor(Math.max(0, deploymentStartTime + deploymentDuration) / 24));
            const deploymentStartHour = parseDeploymentClockHours(deploymentStartClock) ?? deploymentStartTime;
            const deploymentEndHour = parseDeploymentClockHours(deploymentEndClock) ?? ((deploymentStartTime + deploymentDuration) % 24);
            const deploymentDates = getDeploymentDateRange(deploymentStartDate, deploymentEndDate);
            const deployedResourceNumbers = resourcePool
                .map(resourceId => /^Deployed\s+(\d+)$/i.exec(String(resourceId || '').trim()))
                .filter((match): match is RegExpExecArray => Boolean(match))
                .map(match => Number(match[1]))
                .filter(number => Number.isFinite(number));
            const nextDeploymentNumber = Math.max(0, ...deployedResourceNumbers) + 1;
            const resourceId = firstResourceId?.startsWith('Deployed')
                ? firstResourceId
                : `Deployed ${nextDeploymentNumber}`;

            return deploymentDates.map(currentDate => {
                const isFirstDate = currentDate === deploymentStartDate;
                const isLastDate = currentDate === deploymentEndDate;
                const segmentStartTime = isFirstDate ? deploymentStartHour : 0;
                const segmentEndTime = isLastDate ? deploymentEndHour : 24;
                const segmentDuration = Math.max(0.1, segmentEndTime - segmentStartTime);

                return {
                ...draft,
                id: uuidv4(),
                date: currentDate,
                type: 'deployment',
                flightNumber: 'DEPLOYMENT',
                pilot: '',
                instructor: '',
                student: '',
                crew: '',
                group: undefined,
                duration: segmentDuration,
                startTime: segmentStartTime,
                resourceId,
                color: draft.color || 'bg-gray-600/30',
                flightType: 'Dual',
                soloOrDual: 'Dual',
                locationType: 'Land Away',
                origin: 'DEPLOY',
                destination: 'DEPLOY',
                callsign: '',
                aircraftNumber: undefined,
                formationId: undefined,
                formationType: undefined,
                formationPosition: undefined,
                formationSize: undefined,
                crewSelectionOrder: [],
                fixedCrewGroup: undefined,
                fixedCrewPic: undefined,
                fixedCrewManifestStatus: undefined,
                isDeploy: true,
                deploymentStartDate,
                deploymentStartTime: deploymentStartClock,
                deploymentEndDate,
                deploymentEndTime: deploymentEndClock,
                deploymentAircraftCount: draft.deploymentAircraftCount || 1,
                preStart: undefined,
                postEnd: undefined,
                };
            }).filter(event => event.duration > 0);
        }
        const preOffset = typeof draft.preStart === 'number'
            ? Math.max(0, draft.startTime - draft.preStart)
            : 0;
        const postOffset = typeof draft.postEnd === 'number'
            ? Math.max(0, draft.postEnd - (draft.startTime + draft.duration))
            : 0;
        const requestedFormationSize = Math.max(1, Math.floor(Number(draft.formationSize) || 1));
        const firstResourceIndex = resourcePool.indexOf(firstResourceId);
        const availableFormationResources = firstResourceIndex >= 0
            ? resourcePool.slice(firstResourceIndex).filter(isActiveAircraftResource)
            : [firstResourceId].filter(isActiveAircraftResource);
        const isFlightFormation = requestedFormationSize > 1 && isActiveAircraftResource(firstResourceId);
        const formationSize = isFlightFormation
            ? Math.min(requestedFormationSize, Math.max(1, availableFormationResources.length))
            : 1;
        const formationId = formationSize > 1 ? uuidv4() : undefined;
        const callsignBase = getFormationCallsignBase(draft.callsign);
        const crewSelectionOrder = Array.isArray(draft.crewSelectionOrder)
            ? draft.crewSelectionOrder.filter((name): name is string => typeof name === 'string' && name.trim().length > 0)
            : [];

        return Array.from({ length: formationSize }, (_, index) => {
            const resourceId = formationSize > 1
                ? (availableFormationResources[index] || firstResourceId)
                : firstResourceId;
            const type: ScheduleEvent['type'] = resourceId.startsWith('FTD')
                ? 'ftd'
                : resourceId.startsWith('CPT')
                    ? 'cpt'
                    : draft.type || 'flight';
            const crewName = crewSelectionOrder[index] || (formationSize === 1 ? (draft.pilot || draft.instructor || '') : '') || draft.pilot || draft.instructor || '';

            return {
                ...draft,
                id: uuidv4(),
                date: eventDate,
                type,
                pilot: crewName,
                instructor: crewName,
                startTime,
                resourceId,
                preStart: preOffset > 0 ? startTime - preOffset : undefined,
                postEnd: postOffset > 0 ? startTime + draft.duration + postOffset : undefined,
                aircraftNumber: isActiveAircraftResource(resourceId) ? draft.aircraftNumber : undefined,
                callsign: formationSize > 1 ? `${callsignBase}${index + 1}` : draft.callsign,
                formationId,
                formationType: formationSize > 1 ? 'NEO Assist Formation' : draft.formationType,
                formationPosition: formationSize > 1 ? index + 1 : draft.formationPosition,
                formationSize: formationSize > 1 ? formationSize : draft.formationSize,
            };
        });
    }, [activeAircraftResourcePrefix]);

    const handleProgramScheduleExternalEventDrop = useCallback((draft: ScheduleEvent, placement: NeoAssistDropPlacement) => {
        if (isPastDfpDate(date)) {
            denyPastDfpEdit('add tiles');
            return;
        }
        const droppedEvents = buildDroppedNeoAssistEvents(draft, placement, date, buildResources);
        const droppedEventsByDate = droppedEvents.reduce<Record<string, ScheduleEvent[]>>((groups, event) => {
            const eventDate = event.date || date;
            groups[eventDate] = [...(groups[eventDate] || []), event];
            return groups;
        }, {});
        const nextSchedulesByDate = Object.fromEntries(
            Object.entries(droppedEventsByDate).map(([eventDate, eventsForDropDate]) => [
                eventDate,
                [...(publishedSchedules[eventDate] || []), ...eventsForDropDate],
            ])
        ) as Record<string, ScheduleEvent[]>;
        setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
            const next = { ...prev };
            Object.entries(droppedEventsByDate).forEach(([eventDate, eventsForDropDate]) => {
                next[eventDate] = [...(prev[eventDate] || []), ...eventsForDropDate];
            });
            return next;
        });
        Object.entries(nextSchedulesByDate).forEach(([eventDate, eventsForDate]) => {
            persistScheduleForDate(eventDate, eventsForDate);
        });
        logAudit('Program Schedule', 'Create', 'Added NEO Assist tile', `${droppedEvents.length} x ${draft.flightNumber} at ${placement.resourceId}`);
    }, [buildDroppedNeoAssistEvents, buildResources, date, denyPastDfpEdit, isPastDfpDate, persistScheduleForDate, publishedSchedules]);

    const handleNextDayExternalEventDrop = useCallback((draft: ScheduleEvent, placement: NeoAssistDropPlacement) => {
        const droppedEvents = buildDroppedNeoAssistEvents(draft, placement, buildDfpDate, buildResources);
        const nextDayEvents = droppedEvents.map(droppedEvent => {
            const { date: _date, ...nextDayEvent } = droppedEvent;
            return nextDayEvent;
        });
        setNextDayBuildEvents(prev => [...prev, ...nextDayEvents]);
        logAudit('Next Day Build', 'Create', 'Added NEO Assist tile', `${droppedEvents.length} x ${draft.flightNumber} at ${placement.resourceId}`);
    }, [buildDroppedNeoAssistEvents, buildDfpDate, buildResources]);

    const syllabusForModal = useMemo(() => {
        return syllabusDetails.map(item => item.id);
    }, [syllabusDetails]);

    const addTileSyllabusOptions = useMemo(() => {
        logRoutineAppDebug('addTileSyllabusOptions filtering visibleSyllabusDetails:', visibleSyllabusDetails);
        const filtered = visibleSyllabusDetails.filter(item =>
            item.type === 'Flight' ||
            item.type === 'FTD' ||
            (item.type === 'Ground School' && item.code.includes('CPT'))
        );
        logRoutineAppDebug('Filtered items:', filtered);
        const configuredContinuationOptions = getContinuationEventNames(sctEvents);
        const options = [...filtered.map(item => item.id), ...configuredContinuationOptions];

        return options;
    }, [sctEvents, visibleSyllabusDetails]);

    const handleAuthorise = async (eventId: string, notes: string, role: 'autho' | 'captain', isVerbal: boolean, selectedPersonName: string) => {
        const authEventDate = eventForAuth?.date || Object.entries(publishedSchedules).find(([, eventsList]) => (
            (eventsList as ScheduleEvent[]).some(e => e.id === eventId)
        ))?.[0];
        if (isPastDfpDate(authEventDate)) {
            denyPastDfpEdit('authorise events');
            return;
        }
        // System freeze check - read directly from localStorage to avoid stale closure
        const _freezeRaw = localStorage.getItem('systemFreezeState');
        if (_freezeRaw) {
            const _freeze = JSON.parse(_freezeRaw);
            if (_freeze.isFrozen && !_freeze.allowedActions?.flightAuthorisation) {
                showDarkAlert('System is currently frozen. Flight Authorisation entries are not permitted during a system freeze.', 'System Frozen', 'error');
                return;
            }
        }
        const now = new Date().toISOString();
        const authoSigner = selectedPersonName; // Use the selected person's name, not current user

        let wasFullyAuthed = false;
        let eventThatWasUpdated: ScheduleEvent | null = null;
        let affectedScheduleDate: string | null = null;

        const normaliseAuthSigner = (value: string | undefined) => value?.trim().toLowerCase() || '';
        const isSameAuthSigner = (a: string | undefined, b: string | undefined) => {
            const left = normaliseAuthSigner(a);
            const right = normaliseAuthSigner(b);
            if (!left || !right) return false;
            return left === right || left.endsWith(` ${right}`) || right.endsWith(` ${left}`);
        };

        const updateEventAuth = (e: ScheduleEvent): ScheduleEvent => {
            if (e.id !== eventId) return e;

            const updatedEvent = { ...e, authNotes: notes, isVerbalAuth: isVerbal };

            if (role === 'autho') {
                updatedEvent.authoSignedBy = authoSigner;
                updatedEvent.authoSignedAt = now;
                if (isVerbal && updatedEvent.captainSignedBy) {
                    updatedEvent.authoSignedOnBehalfBy = updatedEvent.captainSignedOnBehalfBy || updatedEvent.captainSignedBy;
                } else {
                    delete updatedEvent.authoSignedOnBehalfBy;
                }
            } else if (role === 'captain') {
                updatedEvent.captainSignedBy = authoSigner;
                updatedEvent.captainSignedAt = now;
                if (isVerbal && updatedEvent.authoSignedBy) {
                    updatedEvent.captainSignedOnBehalfBy = updatedEvent.authoSignedOnBehalfBy || updatedEvent.authoSignedBy;
                } else {
                    delete updatedEvent.captainSignedOnBehalfBy;
                }
            }

            const isNowFullyAuthorized = !!(updatedEvent.authoSignedBy && updatedEvent.captainSignedBy);
            const isDualSignedVerbalAuth = !!(
                updatedEvent.isVerbalAuth &&
                isNowFullyAuthorized &&
                (
                    updatedEvent.authoSignedOnBehalfBy ||
                    updatedEvent.captainSignedOnBehalfBy ||
                    isSameAuthSigner(updatedEvent.authoSignedBy, updatedEvent.captainSignedBy)
                )
            );
            if (isDualSignedVerbalAuth) {
                const signer = updatedEvent.captainSignedOnBehalfBy ||
                    updatedEvent.authoSignedOnBehalfBy ||
                    updatedEvent.authoSignedBy ||
                    updatedEvent.captainSignedBy ||
                    authoSigner;
                updatedEvent.dualAuthSignedBy = signer;
                updatedEvent.dualAuthSignedAt = now;
                if (updatedEvent.captainSignedOnBehalfBy) {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed PIC authorisation on behalf of ${updatedEvent.captainSignedBy} under verbal AUTH.`;
                } else if (updatedEvent.authoSignedOnBehalfBy) {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed AUTHO authorisation on behalf of ${updatedEvent.authoSignedBy} under verbal AUTH.`;
                } else {
                    updatedEvent.dualAuthSignedAnnotation = `${signer} signed both AUTHO and PIC for this verbal authorisation.`;
                }
            } else {
                delete updatedEvent.authoSignedOnBehalfBy;
                delete updatedEvent.captainSignedOnBehalfBy;
                delete updatedEvent.dualAuthSignedBy;
                delete updatedEvent.dualAuthSignedAt;
                delete updatedEvent.dualAuthSignedAnnotation;
            }

            if (isNowFullyAuthorized) {
                wasFullyAuthed = true;
            }

            eventThatWasUpdated = updatedEvent;
            return updatedEvent;
        };

        const updateEventsInState = (eventsList: ScheduleEvent[]) => eventsList.map(updateEventAuth);

        const updatedPublishedSchedules = Object.fromEntries(
            Object.entries(publishedSchedules).map(([key, eventsList]) => {
                const updatedEventsForDate = (eventsList as ScheduleEvent[]).map(e => {
                    if (e.id === eventId) {
                        affectedScheduleDate = key;
                    }
                    return updateEventAuth(e);
                });
                return [key, updatedEventsForDate];
            })
        );

        if (!affectedScheduleDate && eventThatWasUpdated?.date) {
            affectedScheduleDate = eventThatWasUpdated.date;
            updatedPublishedSchedules[affectedScheduleDate] = (updatedPublishedSchedules[affectedScheduleDate] || []).map(updateEventAuth);
        }

        if (affectedScheduleDate && updatedPublishedSchedules[affectedScheduleDate]) {
            persistScheduleForDate(affectedScheduleDate, updatedPublishedSchedules[affectedScheduleDate]);
        }

        setEvents(prev => updateEventsInState(prev));
        setPublishedSchedules(updatedPublishedSchedules);

        if (eventThatWasUpdated) {
            setEventForAuth(eventThatWasUpdated);
        }

        // Only close the modal if NOT fully authorized
        // If fully authorized, keep modal open to show completion view
        if (role === 'captain' && !wasFullyAuthed && !isVerbal) {
            setShowAuthFlyout(false);
            setEventForAuth(null);
        }

        if (wasFullyAuthed) {
            setSuccessMessage(eventThatWasUpdated?.dualAuthSignedAnnotation || 'Flight Authorised!');
        }
    };

    const clearAuthorisationForEvent = (eventId: string) => {
        const authEventDate = eventForAuth?.date || Object.entries(publishedSchedules).find(([, eventsList]) => (
            (eventsList as ScheduleEvent[]).some(e => e.id === eventId)
        ))?.[0];
        if (isPastDfpDate(authEventDate)) {
            denyPastDfpEdit('clear authorisations');
            return;
        }
        let affectedScheduleDate: string | null = null;

        const clearAuthFields = (e: ScheduleEvent): ScheduleEvent => {
            if (e.id !== eventId) return e;
            const {
                authoSignedBy,
                authoSignedAt,
                authoSignedOnBehalfBy,
                captainSignedBy,
                captainSignedAt,
                captainSignedOnBehalfBy,
                isVerbalAuth,
                dualAuthSignedBy,
                dualAuthSignedAt,
                dualAuthSignedAnnotation,
                ...rest
            } = e;
            return { ...rest, authNotes: '' };
        };

        const updatedPublishedSchedules = Object.fromEntries(
            Object.entries(publishedSchedules).map(([key, eventsList]) => {
                const updatedEventsForDate = (eventsList as ScheduleEvent[]).map(e => {
                    if (e.id === eventId) affectedScheduleDate = key;
                    return clearAuthFields(e);
                });
                return [key, updatedEventsForDate];
            })
        );

        if (affectedScheduleDate && updatedPublishedSchedules[affectedScheduleDate]) {
            persistScheduleForDate(affectedScheduleDate, updatedPublishedSchedules[affectedScheduleDate]);
        }

        setEvents((prev) => prev.map(clearAuthFields));
        setPublishedSchedules(updatedPublishedSchedules);
        setEventForAuth(null);
        setShowAuthFlyout(false);
    };

    const handleBulkUpdateInstructors = useCallback(async (updatedInstructors: Instructor[]) => {
        const normaliseImportedInstructor = (instructor: Instructor): Instructor => {
            const roleText = String(instructor.role || '').trim().toLowerCase();
            const unitCode = String(instructor.unit || '').trim().toUpperCase();
            const inferredQfi = roleText === 'qfi' || roleText === 'instructor';
            const inferredContractor = roleText === 'sim ip' || roleText === 'contractor staff';
            const normalisedRole =
                inferredContractor ? 'Pilot' :
                roleText === 'pilot' ? 'Pilot' :
                roleText === 'qfi' || roleText === 'instructor' ? 'Pilot' :
                normaliseFixedCrewStaffRole(instructor.role, unitCode) || 'Pilot';
            const nextInstructor: Instructor = {
                ...instructor,
                role: normalisedRole,
                isQFI: inferredContractor ? false : (instructor.isQFI ?? inferredQfi),
                isContractor: inferredContractor ? true : (instructor.isContractor ?? false),
                isOFI: instructor.isOFI ?? false,
                isCFI: instructor.isCFI ?? false,
                isAdminStaff: instructor.isAdminStaff ?? false,
                isTestingOfficer: instructor.isTestingOfficer ?? false,
                isExecutive: instructor.isExecutive ?? false,
                isFlyingSupervisor: instructor.isFlyingSupervisor ?? false,
                isIRE: instructor.isIRE ?? false,
                unavailability: instructor.unavailability || [],
            };
            return nextInstructor;
        };

        const normalisedInstructors = updatedInstructors.map(normaliseImportedInstructor);
        const updatedMap = new Map(normalisedInstructors.map(i => [i.idNumber, i]));

        setInstructorsData(prevInstructors => {
            const existingIds = new Set(prevInstructors.map(i => i.idNumber));
            const updatedExisting = prevInstructors.map(i => updatedMap.get(i.idNumber) || i);
            const newToAdd = normalisedInstructors.filter(ui => !existingIds.has(ui.idNumber));
            return [...updatedExisting, ...newToAdd];
        });

        const persistedInstructors: Instructor[] = [];
        for (const importedInstructor of normalisedInstructors) {
            const existingInstructor = allInstructorsDataRef.current.find(i => i.idNumber === importedInstructor.idNumber);
            const dbId = (existingInstructor as any)?.id || (importedInstructor as any).id;
            const payload = {
                ...existingInstructor,
                ...importedInstructor,
                id: undefined,
                _dataSource: undefined,
            };

            const response = await fetch(dbId ? `/api/personnel/${dbId}` : '/api/personnel', {
                method: dbId ? 'PATCH' : 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
                throw new Error(data.error || data.details || `Failed to save staff ${importedInstructor.name || importedInstructor.idNumber}`);
            }
            const savedPersonnel = data.personnel || data.updatedPersonnel || data.newPersonnel;
            if (savedPersonnel) {
                persistedInstructors.push({
                    ...normalisePersonnelRecord(savedPersonnel),
                    currencyStatus: savedPersonnel.qualifications?.currencyStatus || savedPersonnel.currencyStatus || [],
                    _dataSource: 'database' as const,
                });
            }
        }

        if (persistedInstructors.length > 0) {
            setInstructorsData(prevInstructors => {
                const persistedIds = new Set(persistedInstructors.map(i => i.idNumber));
                const withoutPersisted = prevInstructors.filter(i => !persistedIds.has(i.idNumber));
                return [...withoutPersisted, ...persistedInstructors];
            });
        }
    }, []);

    // Callbacks for StaffView/InstructorListView to prevent render loop
    const handleCloseStaffView = useCallback(() => {
        handleNavigation('Program Schedule');
    }, []);

    const handleProfileOpened = useCallback(() => {
        setSelectedPersonForProfile(null);
        setTraineeProfileInitialTab(null);
    }, []);

    const handleProfileTabConsumed = useCallback(() => {
        setProfileInitialTab(null);
    }, []);

    const handleRequestSct = useCallback((instructor: Instructor) => {
        setInstructorForSct(instructor);
        setShowSctRequest(true);
    }, []);

    const handleArchiveInstructor = useCallback(async (identifier: string | number | null | undefined) => {
        const identifierText = String(identifier ?? '').trim();
        const matchesArchiveIdentifier = (instructor: Instructor): boolean => {
            const dbId = String((instructor as any).id || '').trim();
            if (identifierText && dbId === identifierText) return true;
            if (identifierText && instructor.idNumber !== null && instructor.idNumber !== undefined) {
                return String(instructor.idNumber) === identifierText;
            }
            return false;
        };
        const instructorToArchive = allInstructorsDataRef.current.find(matchesArchiveIdentifier);
        if (!instructorToArchive) {
            return;
        }
        const dbId = String((instructorToArchive as any).id || '').trim();
        const targetIdNumber = instructorToArchive.idNumber;
        const matchesTargetInstructor = (instructor: Instructor): boolean => {
            const candidateDbId = String((instructor as any).id || '').trim();
            if (dbId && candidateDbId === dbId) return true;
            if (targetIdNumber !== null && targetIdNumber !== undefined) {
                return String(instructor.idNumber) === String(targetIdNumber);
            }
            return false;
        };
        const archivedInstructor = { ...instructorToArchive, isActive: false };

        try {
            if (dbId && (instructorToArchive as any)._dataSource === 'database') {
                const response = await fetch(scopedApiPath(`/api/personnel/${encodeURIComponent(dbId)}`), {
                    method: 'PATCH',
                    credentials: 'include',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ isActive: false }),
                });
                if (!response.ok) {
                    const errorData = await response.json().catch(() => ({}));
                    throw new Error(errorData.error || errorData.details || `Archive failed (${response.status})`);
                }
            }
            setInstructorsData(prev => {
                return prev.filter(i => !matchesTargetInstructor(i));
            });
            setArchivedInstructorsData(prev => {
                const withoutDuplicate = prev.filter(i => !matchesTargetInstructor(i));
                return [...withoutDuplicate, archivedInstructor];
            });
            logAudit({
                page: 'Staff',
                action: 'archive',
                description: 'Archived staff member',
                changes: `Archived: ${instructorToArchive.rank || ''} ${instructorToArchive.name}`.trim(),
            });
        } catch (error) {
            console.error('[Staff Archive] Failed:', error);
            setErrorMessage(`Could not archive ${instructorToArchive.name}. ${error instanceof Error ? error.message : String(error)}`);
        }
    }, [scopedApiPath]);

    const handleRestoreInstructor = useCallback(async (identifier: string | number | null | undefined) => {
        const identifierText = String(identifier ?? '').trim();
        const matchesRestoreIdentifier = (instructor: Instructor): boolean => {
            const dbId = String((instructor as any).id || '').trim();
            if (identifierText && dbId === identifierText) return true;
            if (identifierText && instructor.idNumber !== null && instructor.idNumber !== undefined) {
                return String(instructor.idNumber) === identifierText;
            }
            return false;
        };
        const instructorToRestore = archivedInstructorsData.find(matchesRestoreIdentifier)
            || allInstructorsDataRef.current.find(matchesRestoreIdentifier);
        if (!instructorToRestore) return;
        const dbId = String((instructorToRestore as any).id || '').trim();
        const targetIdNumber = instructorToRestore.idNumber;
        const matchesTargetInstructor = (instructor: Instructor): boolean => {
            const candidateDbId = String((instructor as any).id || '').trim();
            if (dbId && candidateDbId === dbId) return true;
            if (targetIdNumber !== null && targetIdNumber !== undefined) {
                return String(instructor.idNumber) === String(targetIdNumber);
            }
            return false;
        };
        const restoredInstructor = { ...instructorToRestore, isActive: true };

        try {
            if (dbId && (instructorToRestore as any)._dataSource === 'database') {
                const response = await fetch(scopedApiPath(`/api/personnel/${encodeURIComponent(dbId)}`), {
                    method: 'PATCH',
                    credentials: 'include',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ isActive: true }),
                });
                if (!response.ok) {
                    const errorData = await response.json().catch(() => ({}));
                    throw new Error(errorData.error || errorData.details || `Restore failed (${response.status})`);
                }
            }
            setArchivedInstructorsData(prev => prev.filter(i => !matchesTargetInstructor(i)));
            setInstructorsData(prev => {
                const exists = prev.some(matchesTargetInstructor);
                if (exists) {
                    return prev.map(i => (
                        matchesTargetInstructor(i) ? restoredInstructor : i
                    ));
                }
                return [...prev, restoredInstructor];
            });
            logAudit({
                page: 'Staff',
                action: 'restore',
                description: 'Restored archived staff member',
                changes: `Restored: ${instructorToRestore.rank || ''} ${instructorToRestore.name}`.trim(),
            });
        } catch (error) {
            console.error('[Staff Restore] Failed:', error);
            setErrorMessage(`Could not restore ${instructorToRestore.name}. ${error instanceof Error ? error.message : String(error)}`);
        }
    }, [archivedInstructorsData, scopedApiPath]);

    const handleReplaceInstructors = useCallback((newInstructors: Instructor[]) => {
        setInstructorsData(newInstructors.map(normalisePersonnelRecord));
        setSuccessMessage('Instructors successfully replaced!');
    }, []);

    useEffect(() => {
        if (!setupTestProfile) return;
        const applySetupTestPersonnel = () => {
            const setupPersonnel = readSetupTestPersonnel();
            const nextInstructors = (setupPersonnel.instructors || []).map((person: any) => ({
                ...normalisePersonnelRecord(person),
                _dataSource: 'setup-test' as const,
            }));
            const nextTrainees = (setupPersonnel.trainees || []).map((trainee: any) => ({
                ...trainee,
                _dataSource: 'setup-test' as const,
            }));
            pushSetupTestPersonnelDiag('event:personnel-updated', {
                instructors: nextInstructors.length,
                trainees: nextTrainees.length,
                instructorSample: nextInstructors.slice(0, 8).map((person: any) => ({
                    name: person.name,
                    unit: person.unit,
                    location: person.location,
                    role: person.role,
                    source: person._dataSource,
                })),
            });
            setInstructorsData(nextInstructors);
            setTraineesData(nextTrainees);
            registerSetupTestCoursesFromTrainees(nextTrainees);
            setIsStaffLoaded(true);
            setIsTraineeLoaded(true);
        };
        window.addEventListener(SETUP_TEST_PERSONNEL_EVENT, applySetupTestPersonnel);
        return () => window.removeEventListener(SETUP_TEST_PERSONNEL_EVENT, applySetupTestPersonnel);
    }, [pushSetupTestPersonnelDiag, registerSetupTestCoursesFromTrainees, setupTestProfile]);

    useEffect(() => {
        if (!setupTestProfile) return;
        const applySetupTestSyllabus = () => {
            const setupSyllabus = readSetupTestSyllabus();
            pushSetupTestLmpDiag('app:syllabus-event-received', {
                setupSyllabusItems: setupSyllabus.length,
                selectedLmpStorage: (() => {
                    try { return localStorage.getItem('neo_lmp_details_selected_package'); } catch { return null; }
                })(),
                sample: setupSyllabus.slice(0, 20).map((item: any) => ({
                    id: item?.id,
                    code: item?.code,
                    title: item?.eventDescription,
                    courses: item?.courses,
                    unit: item?.unit,
                    location: item?.location,
                    lmpType: item?.lmpType,
                    isActive: item?.isActive,
                })),
            });
            setSyllabusDetails(setupSyllabus as SyllabusItemDetail[]);
            setSyllabusError(null);
            setSyllabusLoading(false);
            logRoutineAppDebug(`✅ [Syllabus] Applied ${setupSyllabus.length} setup-test LMP item(s) from local browser data`);
        };
        window.addEventListener(SETUP_TEST_SYLLABUS_EVENT, applySetupTestSyllabus);
        return () => window.removeEventListener(SETUP_TEST_SYLLABUS_EVENT, applySetupTestSyllabus);
    }, [pushSetupTestLmpDiag, setupTestProfile]);

    // Refresh database data (personnel and trainees) - called when database is modified
    const handleDatabaseDataChanged = useCallback(async () => {
        logRoutineAppDebug('🔄 Refreshing database data after database modification...');

        if (isSetupTestMode()) {
            const setupPersonnel = readSetupTestPersonnel();
            const setupInstructors = (setupPersonnel.instructors || []).map((person: any) => ({
                ...normalisePersonnelRecord(person),
                _dataSource: 'setup-test' as const,
            }));
            setInstructorsData(setupInstructors);
            setArchivedInstructorsData(setupInstructors.filter((person: any) => !isRecordActive(person)));
            setTraineesData((setupPersonnel.trainees || []).map((trainee: any) => ({
                ...trainee,
                _dataSource: 'setup-test' as const,
            })));
            return;
        }

        try {
            // Fetch fresh personnel data
            const personnelRes = await fetch(scopedApiPath('/api/personnel'), { credentials: 'include' });
            if (personnelRes.ok) {
                const personnelData = await personnelRes.json();
                const dbPersonnel = (personnelData.personnel || []).map((p: any) => ({
                    ...normalisePersonnelRecord(p),
                    // Extract qualifications.currencyStatus to top-level so Post Flight
                    // and other in-memory reads can find it at person.currencyStatus
                    currencyStatus: p.qualifications?.currencyStatus || p.currencyStatus || [],
                    _dataSource: 'database' as const,
                }));

                // Update instructors - remove old database entries and add fresh ones
                setInstructorsData(prev => {
                    const nonDbInstructors = prev.filter(i => (i as any)._dataSource !== 'database');
                    return [...nonDbInstructors, ...dbPersonnel];
                });
                setArchivedInstructorsData(dbPersonnel.filter((person: any) => !isRecordActive(person)));
                logRoutineAppDebug(`✅ Refreshed ${dbPersonnel.length} personnel from database`);
            }

            // Fetch fresh trainees data
            const traineesRes = await fetch(scopedApiPath('/api/trainees'), { credentials: 'include' });
            if (traineesRes.ok) {
                const traineesData = await traineesRes.json();
                const dbTrainees = (traineesData.trainees || []).map((t: any) => ({
                    ...t,
                    _dataSource: 'database' as const,
                }));

                // Update trainees - replace old database entries with fresh ones, preserve mock
                setTraineesData(prev => {
                    const mockTrainees = prev.filter(t => (t as any)._dataSource === 'mockdata');
                    return [...mockTrainees, ...dbTrainees];
                });

                // Register any DB trainee courses that aren't in courseColors yet
                const defaultColors = [
                    'bg-sky-400/80', 'bg-purple-400/80', 'bg-yellow-400/80', 'bg-pink-400/80',
                    'bg-orange-400/80', 'bg-teal-400/80', 'bg-indigo-400/80', 'bg-green-400/80',
                    'bg-red-400/80', 'bg-cyan-400/80'
                ];
                const dbCourseNames = [...new Set(dbTrainees.map((t: any) => t.course).filter(Boolean))];
                setCourseColors(prev => {
                    const updated = { ...prev };
                    let colorIndex = Object.keys(updated).length;
                    dbCourseNames.forEach((course: any) => {
                        if (!updated[course]) {
                            updated[course] = defaultColors[colorIndex % defaultColors.length];
                            colorIndex++;
                            logRoutineAppDebug(`[DB Load] Added missing courseColor for "${course}"`);
                        }
                    });
                    return updated;
                });

                logRoutineAppDebug(`✅ Refreshed ${dbTrainees.length} trainees from database`);
            }
        } catch (error) {
            console.error('❌ Error refreshing database data:', error);
        }
    }, [scopedApiPath]);

    const handleBulkUpdateTrainees = useCallback(async (updatedTrainees: Trainee[]) => {
        logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] Called with ${updatedTrainees.length} trainees`);
        logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] Sample trainee:`, JSON.stringify(updatedTrainees[0] || null));

        const missingId = updatedTrainees.filter(t => !t.idNumber);
        const missingName = updatedTrainees.filter(t => !t.name);
        logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] Missing idNumber: ${missingId.length}, missing name: ${missingName.length}`);

        // Update in-memory state immediately
        const updatedMap = new Map(updatedTrainees.map(t => [t.idNumber, t]));
        setTraineesData(prevTrainees => {
            const existingIds = new Set(prevTrainees.map(t => t.idNumber));
            const updatedExisting = prevTrainees.map(t => updatedMap.get(t.idNumber) || t);
            const newToAdd = updatedTrainees.filter(ut => !existingIds.has(ut.idNumber));
            logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] State update: ${updatedExisting.length} existing updated, ${newToAdd.length} new added`);
            return [...updatedExisting, ...newToAdd];
        });

        // Persist to database via bulk API
        try {
            const courses = [...new Set(updatedTrainees.map(t => t.course).filter(Boolean))];
            const course = courses.length === 1 ? courses[0] : (updatedTrainees.length > 0 ? updatedTrainees[0].course : undefined);
            logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] Courses in payload: ${courses.join(', ')}, using: ${course}`);
            logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] Calling POST ${getApiBase()}/trainees/bulk`);

            const response = await fetch(`${getApiBase()}/trainees/bulk`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({
                    trainees: updatedTrainees,
                    course: course || undefined,
                    replaceAll: false
                })
            });
            logRoutineAppDebug(`🔵 [handleBulkUpdateTrainees] API response status: ${response.status}`);
            if (response.ok) {
                const result = await response.json();
                logRoutineAppDebug(`✅ [handleBulkUpdateTrainees] DB save success:`, JSON.stringify(result));
                setSuccessMessage(`Trainees saved: ${result.created} added, ${result.updated} updated, ${result.skipped} skipped.`);
                // Refresh from DB so the UI shows the newly saved trainees immediately
                await handleDatabaseDataChanged();
            } else {
                const err = await response.text();
                console.error('❌ [handleBulkUpdateTrainees] DB save failed. Status:', response.status, 'Body:', err);
                setSuccessMessage(`Warning: Trainees updated in session but DB save failed (${response.status}). Check console.`);
            }
        } catch (err) {
            console.error('❌ [handleBulkUpdateTrainees] DB save exception:', err);
            setSuccessMessage(`Warning: DB save error — ${(err as Error).message}`);
        }
    }, [handleDatabaseDataChanged]);

    const handleReplaceTrainees = useCallback(async (newTrainees: Trainee[], onSaved?: () => void) => {
        logRoutineAppDebug(`🔵 [handleReplaceTrainees] Called with ${newTrainees.length} total trainees`);

        // Update in-memory state immediately with ALL trainees (other courses + new course)
        setTraineesData(newTrainees);
        setSuccessMessage('Trainees successfully replaced!');

        // For DB persistence: SettingsView sends [otherCourseTrainees + newCourseTrainees]
        // We only want to replace the SPECIFIC course — so detect which course changed
        // by finding trainees whose course appears to be the "new" batch
        // The SettingsView always passes: otherCourseTrainees (untouched) + newTrainees (from file, all same course)
        // We identify the new course batch as trainees that don't exist in previous DB state
        //
        // Simpler approach: find the course(s) that have trainees in newTrainees but NOT from DB
        // Actually: SettingsView sets course explicitly — we can detect it from the duplicated course group
        const courseGroups = new Map<string, Trainee[]>();
        newTrainees.forEach(t => {
            const c = t.course || '';
            if (!courseGroups.has(c)) courseGroups.set(c, []);
            courseGroups.get(c)!.push(t);
        });
        logRoutineAppDebug(`🔵 [handleReplaceTrainees] Course groups:`, [...courseGroups.entries()].map(([c,ts]) => `${c}:${ts.length}`).join(', '));

        // Persist to database for EACH course group separately
        // For other existing courses: just upsert (replaceAll=false)
        // For the NEW/replaced course: replaceAll=true to deactivate old records first
        // We detect the "replaced" course as the one coming from the file upload
        // SettingsView hardcodes course for newTrainees so they all share same course
        // Find groups that look "new" (all trainees have same course from the upload)
        // Since we can't distinguish here, send ALL trainees to bulk API with replaceAll=false
        // but ALSO send the specific course's trainees with replaceAll=true separately

        // Find the course being replaced: it's the one where ALL trainees in that group
        // have idNumber values (i.e., came from the upload file, not pre-existing)
        // Actually the safest approach: just send the full list with replaceAll=false
        // (upsert behavior — existing trainees updated, new ones created, none deleted)
        // This is safe because the in-memory state already reflects the replace operation

        try {
            logRoutineAppDebug(`🔵 [handleReplaceTrainees] Calling POST ${getApiBase()}/trainees/bulk with ${newTrainees.length} trainees, replaceAll=false`);

            const response = await fetch(`${getApiBase()}/trainees/bulk`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({
                    trainees: newTrainees,
                    replaceAll: false  // Safe upsert — create new, update existing, don't deactivate
                })
            });

            logRoutineAppDebug(`🔵 [handleReplaceTrainees] API response status: ${response.status}`);

            if (response.ok) {
                const result = await response.json();
                logRoutineAppDebug(`✅ [handleReplaceTrainees] DB save success:`, JSON.stringify(result));
                setSuccessMessage(`Trainees saved: ${result.created} added, ${result.updated} updated, ${result.skipped} skipped.`);
                // Refresh from DB so the UI shows the newly saved trainees immediately
                await handleDatabaseDataChanged();
            } else {
                const err = await response.text();
                console.error('❌ [handleReplaceTrainees] DB save failed. Status:', response.status, 'Body:', err);
                setSuccessMessage(`Warning: Trainees replaced in session but DB save failed (${response.status}). Check console.`);
            }
        } catch (err) {
            console.error('❌ [handleReplaceTrainees] DB save exception:', err);
            setSuccessMessage(`Warning: DB save error — ${(err as Error).message}`);
        }
    }, [handleDatabaseDataChanged]);



    // ── Mobile unavailability live-refresh polling ────────────────────────
    // Poll every 5 seconds so that unavailability submitted from the iOS app
    // appears in the browser without a hard refresh.
    // lastPollTime/lastPollChanged are displayed in UI to confirm sync is running.
    const [liveSyncEnabled, setLiveSyncEnabled] = useState<boolean>(() => {
        try {
            return window.localStorage.getItem('dfp_live_sync_enabled') !== 'false';
        } catch {
            return true;
        }
    });
    const [isManualSyncing, setIsManualSyncing] = useState(false);
    const [lastPollTime, setLastPollTime] = useState<string>('');
    const [lastPollChanged, setLastPollChanged] = useState<boolean>(false);
    const isAddFlightTileModalOpen = isAddingTile;
    const isUserEditing = useCallback(() => {
        if (typeof document === 'undefined') return false;
        return isEditableElement(document.activeElement);
    }, []);

    useEffect(() => {
        try {
            window.localStorage.setItem('dfp_live_sync_enabled', liveSyncEnabled ? 'true' : 'false');
        } catch {
            // Ignore storage failures; live sync still works for this session.
        }
    }, [liveSyncEnabled]);

    const buildUnavailHash = useCallback((records: any[]): string => {
        return records
            .map(r => `${r.id}:${JSON.stringify((r.unavailability || []).map((u: any) => u.id).sort())}`)
            .sort()
            .join('|');
    }, []);

    const syncUnavailabilityFromDatabase = useCallback(async (): Promise<boolean> => {
        if (isSetupTestMode()) return false;
        if (isUserEditing()) return false;
        try {
            const apiBase = getAppApiBase();
            const [personnelRes, traineesRes] = await Promise.all([
                fetch(`${apiBase}/personnel`, { credentials: 'include' }),
                fetch(`${apiBase}/trainees`,  { credentials: 'include' }),
            ]);
            logRoutineAppDebug('[Poll] Personnel response:', personnelRes.status, 'Trainees response:', traineesRes.status);
            let pollChanged = false;
            if (personnelRes.ok) {
                const personnelData = await personnelRes.json();
                const dbPersonnel = (personnelData.personnel || []).map((p: any) => ({
                    ...normalisePersonnelRecord(p),
                    currencyStatus: p.qualifications?.currencyStatus || p.currencyStatus || [],
                    _dataSource: 'database' as const,
                }));
                logRoutineAppDebug('[Poll] Fetched', dbPersonnel.length, 'personnel. Unavailability total:', dbPersonnel.reduce((sum: number, p: any) => sum + (p.unavailability?.length || 0), 0));
                setInstructorsData(prev => {
                    const prevDbPersonnel = prev.filter(i => (i as any)._dataSource === 'database');
                    const prevHash = buildUnavailHash(prevDbPersonnel);
                    const newHash  = buildUnavailHash(dbPersonnel);
                    if (prevHash === newHash) return prev;
                    logRoutineAppDebug('[Poll] Personnel unavailability CHANGED - updating state');
                    pollChanged = true;
                    const nonDbInstructors = prev.filter(i => (i as any)._dataSource !== 'database');
                    return [...nonDbInstructors, ...dbPersonnel];
                });
            }
            if (traineesRes.ok) {
                const traineesData = await traineesRes.json();
                const dbTrainees = (traineesData.trainees || []).map((t: any) => ({
                    ...t,
                    _dataSource: 'database' as const,
                }));
                logRoutineAppDebug('[Poll] Fetched', dbTrainees.length, 'trainees. Unavailability total:', dbTrainees.reduce((sum: number, t: any) => sum + (t.unavailability?.length || 0), 0));
                setTraineesData(prev => {
                    const prevDbTrainees = prev.filter(t => (t as any)._dataSource === 'database');
                    const prevHash = buildUnavailHash(prevDbTrainees);
                    const newHash  = buildUnavailHash(dbTrainees);
                    if (prevHash === newHash) return prev;
                    logRoutineAppDebug('[Poll] Trainee unavailability CHANGED - updating state');
                    pollChanged = true;
                    const mockTrainees = prev.filter(t => (t as any)._dataSource === 'mockdata');
                    return [...mockTrainees, ...dbTrainees];
                });
            }
            const now = new Date();
            const timeStr = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}:${now.getSeconds().toString().padStart(2,'0')}`;
            setLastPollTime(timeStr);
            setLastPollChanged(pollChanged);
            return pollChanged;
        } catch (e) {
            console.error('[Poll] Error during poll:', e);
            return false;
        }
    }, [buildUnavailHash, isUserEditing]);

    useEffect(() => {
        if (!liveSyncEnabled || isAddFlightTileModalOpen) return;
        syncUnavailabilityFromDatabase();
        const pollInterval = setInterval(syncUnavailabilityFromDatabase, 5 * 1000);
        return () => clearInterval(pollInterval);
    }, [isAddFlightTileModalOpen, liveSyncEnabled, syncUnavailabilityFromDatabase]);

    useEffect(() => {
        const handleLiveDfpSnapshotChange = (event: Event) => {
            if (!liveSyncEnabled || isAddFlightTileModalOpen || Boolean(selectedEvent) || isUserEditing()) return;
            const change = (event as CustomEvent)?.detail || {};
            if (String(change.path || '') !== '/api/daily-snapshot/save') return;
            const snapshotDate = String(change.detail?.date || '').trim();
            const parsedSnapshotKey = parseDailySnapshotKey(snapshotDate);
            const targetDate = parsedSnapshotKey.date || getDailySnapshotDate(snapshotDate);
            if (!targetDate || !/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) return;
            if (targetDate !== date) return;

            const savedLocation = String(change.detail?.locationCode || parsedSnapshotKey.school || '').trim();
            const savedUnit = String(change.detail?.unitCode || parsedSnapshotKey.unit || '').trim();
            const currentLocationKeys = getDailySnapshotLocationAliases(school).map(normaliseDailySnapshotPart);
            const savedLocationKey = normaliseDailySnapshotPart(savedLocation);
            const currentUnitKey = normaliseDailySnapshotPart(activeUnitCode);
            const savedUnitKey = normaliseDailySnapshotPart(savedUnit);
            if (savedLocationKey && !currentLocationKeys.includes(savedLocationKey)) return;
            if (savedUnitKey && savedUnitKey !== currentUnitKey) return;

            void loadSnapshotForDate(targetDate, {
                force: true,
                replace: true,
                useCache: false,
                schoolOverride: savedLocation || school,
                unitOverride: savedUnit || activeUnitCode,
                exactSnapshotKey: snapshotDate,
            });
        };
        window.addEventListener(LIVE_CHANGE_EVENT, handleLiveDfpSnapshotChange);
        return () => window.removeEventListener(LIVE_CHANGE_EVENT, handleLiveDfpSnapshotChange);
    }, [activeUnitCode, date, getDailySnapshotLocationAliases, isAddFlightTileModalOpen, isUserEditing, liveSyncEnabled, loadSnapshotForDate, school, selectedEvent]);

    useEffect(() => {
        const handleLivePeopleChange = (event: Event) => {
            if (!liveSyncEnabled || isAddFlightTileModalOpen || Boolean(selectedEvent) || isUserEditing()) return;
            const change = (event as CustomEvent)?.detail || {};
            const path = String(change.path || '');
            const isPeoplePath = path === '/api/personnel'
                || path.startsWith('/api/personnel/')
                || path === '/api/trainees'
                || path.startsWith('/api/trainees/');
            if (!isPeoplePath) return;
            void handleDatabaseDataChanged();
        };
        window.addEventListener(LIVE_CHANGE_EVENT, handleLivePeopleChange);
        return () => window.removeEventListener(LIVE_CHANGE_EVENT, handleLivePeopleChange);
    }, [handleDatabaseDataChanged, isAddFlightTileModalOpen, isUserEditing, liveSyncEnabled, selectedEvent]);


    // ── Alert response polling ──────────────────────────────────────────────
    // Poll alert statuses for the current date every 5 seconds
    const syncAlertsForCurrentDate = useCallback(async () => {
        if (isUserEditing()) return;
        try {
            const apiBase = getAppApiBase();
            const res = await fetch(`${apiBase}/daily-snapshot/${encodeURIComponent(getDailySnapshotKey(date))}`);
            if (!res.ok) return;
            const data = await res.json();
            const snap = data.snapshot;
            if (!snap) return;
            // Always update alertsData so responses (accept/reject) are reflected immediately
            if (snap.alertsData) {
                setAlertsDataByDate(prev => ({
                    ...prev,
                    [date]: snap.alertsData,
                }));
            }
        } catch (err) {
            // Silent fail - polling
        }
    }, [date, isUserEditing, school]);

    useEffect(() => {
        if (!liveSyncEnabled || isAddFlightTileModalOpen) return;
        syncAlertsForCurrentDate();
        const interval = setInterval(syncAlertsForCurrentDate, 5 * 1000);
        return () => clearInterval(interval);
    }, [isAddFlightTileModalOpen, liveSyncEnabled, syncAlertsForCurrentDate]);

    const handleManualSync = useCallback(async () => {
        if (isManualSyncing) return;
        setIsManualSyncing(true);
        try {
            await Promise.all([
                syncUnavailabilityFromDatabase(),
                syncAlertsForCurrentDate(),
            ]);
        } finally {
            setIsManualSyncing(false);
        }
    }, [isManualSyncing, syncAlertsForCurrentDate, syncUnavailabilityFromDatabase]);

    const handleUpdateSyllabus = useCallback((newSyllabus: SyllabusItemDetail[]) => {
        const updatedMap = new Map(newSyllabus.map(s => [s.code.trim().replace(/\s/g, '').toLowerCase(), s]));
        setSyllabusDetails(prevSyllabus => {
            const finalSyllabus = prevSyllabus.map(s => {
                const key = s.code.trim().replace(/\s/g, '').toLowerCase();
                return updatedMap.get(key) || s;
            });
            const existingCodes = new Set(prevSyllabus.map(s => s.code.trim().replace(/\s/g, '').toLowerCase()));
            const newToAdd = newSyllabus.filter(s => !existingCodes.has(s.code.trim().replace(/\s/g, '').toLowerCase()));
            return [...finalSyllabus, ...newToAdd];
        });
    }, []);

    // New handler for single item updates
    const handleUpdateSyllabusItem = (updatedItem: SyllabusItemDetail) => {
        const itemMatchesUpdate = (item: SyllabusItemDetail) => {
            const candidates = [
                item.id,
                item.code,
                item.masterEventId,
            ].map(value => String(value || '').trim()).filter(Boolean);
            const updatedCandidates = [
                updatedItem.id,
                updatedItem.code,
                updatedItem.masterEventId,
            ].map(value => String(value || '').trim()).filter(Boolean);

            return candidates.some(candidate => updatedCandidates.includes(candidate));
        };

        setSyllabusDetails(prev => prev.map(item => itemMatchesUpdate(item) ? updatedItem : item));
    };

    const handleAddSyllabusItem = (newItem: SyllabusItemDetail) => {
        // Add the new blank item to the syllabus list so it appears in the left panel
        setSyllabusDetails(prev => {
            // Avoid duplicates if called multiple times
            if (prev.some(i => i.id === newItem.id)) return prev;
            return [...prev, newItem];
        });
    };

    const handleInsertAirCombatTrainingEvent = async (
        staff: Instructor,
        assignment: AirCombatTrainingAssignment,
        sequenceItems: SyllabusItemDetail[],
        request: InsertLmpEventRequest
    ): Promise<boolean> => {
        if (!sequenceItems.length) {
            await showDarkAlert(`Could not insert ${request.label}: no Air Combat sequence events are available for ${assignment.code}.`, 'Insert Event Failed', 'error');
            return false;
        }
        const insertionIndex = sequenceItems.findIndex(item => (
            (item.id || item.code) === request.followsEventId ||
            (item.code || item.id) === request.followsEventId
        ));
        if (insertionIndex === -1) {
            await showDarkAlert('Could not insert event: the selected follow-on event was not found in the Air Combat sequence.', 'Insert Event Failed', 'error');
            return false;
        }

        const cleanedLabel = request.label.trim().slice(0, 8).toUpperCase();
        const existingCodes = new Set(syllabusDetails.map(item => String(item.code || item.id || '').trim().toUpperCase()));
        let sequence = 1;
        let eventCode = cleanedLabel;
        while (existingCodes.has(eventCode.toUpperCase())) {
            const suffix = String(sequence);
            eventCode = `${cleanedLabel.slice(0, Math.max(1, 8 - suffix.length))}${suffix}`;
            sequence++;
        }

        const followsItem = sequenceItems[insertionIndex];
        const nextItem = sequenceItems[insertionIndex + 1];
        const followsSort = Number((followsItem as any).sortOrder ?? insertionIndex * 10);
        const nextSort = Number((nextItem as any)?.sortOrder);
        const sortOrder = Number.isFinite(nextSort) && nextSort > followsSort + 1
            ? Math.floor((followsSort + nextSort) / 2)
            : followsSort + 1;
        const physicalResources = Array.from({ length: request.resourceCount }, (_, index) => (
            request.resourceCount === 1 ? 'Aircraft' : `Aircraft ${index + 1}`
        ));

        const peopleRequired = request.peopleRequired.length > 0
            ? request.peopleRequired
            : (request.eventType.syllabusType === 'Academics' ? [] : ['Pilot']);

        const newItem = {
            code: eventCode,
            phase: followsItem.phase || assignment.code,
            module: assignment.title || followsItem.module || assignment.code,
            dayNight: request.dayNight,
            eventDescription: eventCode,
            prerequisites: [followsItem.code || followsItem.id].filter(Boolean),
            prerequisitesGround: [],
            prerequisitesFlying: [followsItem.code || followsItem.id].filter(Boolean),
            eventDetailsCommon: [],
            eventDetailsSortie: [],
            totalEventHours: request.totalEventHours,
            flightOrSimHours: request.flightOrSimHours,
            duration: request.duration,
            preFlightTime: request.preFlightTime,
            postFlightTime: request.postFlightTime,
            type: request.eventType.syllabusType,
            sortieType: request.eventType.syllabusType === 'Flight' ? 'Dual' : undefined,
            methodOfDelivery: [],
            methodOfAssessment: [],
            resourcesPhysical: physicalResources,
            resourceNumber: request.resourceCount,
            acceptableAircraftConfigs: [ANY_AIRCRAFT_CONFIG],
            resourcesHuman: peopleRequired,
            location: assignment.locationCode || followsItem.location || school,
            unit: assignment.unitCode || followsItem.unit || activeUnitCode,
            courses: [assignment.code],
            lmpType: assignment.kind === 'training_package' ? 'Staff CAT' : 'Master LMP',
            sortOrder,
        } as Partial<SyllabusItemDetail> & { sortOrder: number };

        try {
            const savedItem = await createSyllabusItem(newItem, `Inserted Air Combat training event ${eventCode} for ${assignment.code}`);
            setSyllabusDetails(prev => [...prev, savedItem]);
            logAudit(
                'Air Combat Training Progress',
                'Insert',
                `Inserted event ${savedItem.code} into ${assignment.code}`,
                [
                    `Staff profile: ${staff.rank ? `${staff.rank} ` : ''}${staff.name}`,
                    `Training: ${assignment.code}`,
                    `Type: ${request.eventType.label}`,
                    `Follows: ${followsItem.code}`,
                ].join('; ')
            );
            setSuccessMessage(`Inserted Air Combat event ${savedItem.code}.`);
            return true;
        } catch (error) {
            console.error('[Air Combat Training] Failed to insert event:', error);
            await showDarkAlert(
                `The Air Combat training event was not saved.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Insert Event Failed',
                'error'
            );
            return false;
        }
    };

    const handleUpdateAirCombatTrainingEvent = async (
        staff: Instructor,
        assignment: AirCombatTrainingAssignment,
        originalItem: SyllabusItemDetail,
        updatedItem: SyllabusItemDetail
    ): Promise<boolean> => {
        const originalId = originalItem.id || originalItem.code;
        const originalCode = originalItem.code || originalItem.id;
        const updatedCode = String(updatedItem.code || updatedItem.id || '').trim().toUpperCase();
        const duplicateCode = syllabusDetails.some(item => {
            const matchesOriginal = (item.id || item.code) === originalId || (item.code || item.id) === originalCode;
            if (matchesOriginal) return false;
            return String(item.code || item.id || '').trim().toUpperCase() === updatedCode;
        });
        if (duplicateCode) {
            await showDarkAlert(`Could not update ${originalItem.code}: another syllabus event already uses ${updatedItem.code}.`, 'Air Combat Training Save Failed', 'error');
            return false;
        }

        const {
            id: _id,
            completedAt: _completedAt,
            masterEventId: _masterEventId,
            lmpSource: _lmpSource,
            orderKey: _orderKey,
            anchorAfterMasterEventId: _anchorAfterMasterEventId,
            anchorBeforeMasterEventId: _anchorBeforeMasterEventId,
            anchorPolicy: _anchorPolicy,
            userLockedPosition: _userLockedPosition,
            placementNeedsReview: _placementNeedsReview,
            ...persistableUpdatedItem
        } = {
            ...updatedItem,
            location: updatedItem.location || assignment.locationCode || school,
            unit: updatedItem.unit || assignment.unitCode || activeUnitCode,
            courses: [assignment.code],
            lmpType: assignment.kind === 'training_package' ? 'Staff CAT' : 'Master LMP',
            sortOrder: (originalItem as any).sortOrder ?? (updatedItem as any).sortOrder ?? 0,
        } as any;

        try {
            const savedItem = await updateSyllabusItem(originalId, persistableUpdatedItem, `Updated Air Combat training event ${originalItem.code}`);
            setSyllabusDetails(prev => prev.map(item => (
                (item.id || item.code) === originalId || (item.code || item.id) === originalCode
                    ? savedItem
                    : item
            )));
            logAudit(
                'Air Combat Training Progress',
                'Edit',
                `Edited event ${originalItem.code} in ${assignment.code}`,
                [
                    `Staff profile: ${staff.rank ? `${staff.rank} ` : ''}${staff.name}`,
                    `Training: ${assignment.code}`,
                    `Original Event: ${originalItem.code}`,
                    `Updated Event: ${savedItem.code}`,
                    `Type: ${savedItem.type}`,
                    `Duration: ${savedItem.duration}`,
                ].join('; ')
            );
            setSuccessMessage(`Updated Air Combat event ${savedItem.code}.`);
            return true;
        } catch (error) {
            console.error('[Air Combat Training] Failed to update event:', error);
            await showDarkAlert(
                `The Air Combat training event was not saved.\n\n${error instanceof Error ? error.message : String(error)}`,
                'Air Combat Training Save Failed',
                'error'
            );
            return false;
        }
    };

    const handleUpdateGradDate = (courseName: string, newGradDate: string) => {
        setCourses(prevCourses =>
            prevCourses.map(course =>
                course.name === courseName ? { ...course, gradDate: newGradDate } : course
            )
        );
    };

    const handleUpdateStartDate = (courseName: string, newStartDate: string) => {
        setCourses(prevCourses =>
            prevCourses.map(course =>
                course.name === courseName ? { ...course, startDate: newStartDate } : course
            )
        );
    };

    const handleSetIsMultiSelectMode = (enabled: boolean) => {
        setIsMultiSelectMode(enabled);
        if (!enabled) {
            setSelectedEventIds(new Set());
        }
    };

    const allTraineesByCourse = useMemo(() => {
        const groups: { [course: string]: Trainee[] } = {};
        traineesData.forEach(trainee => {
            if (!groups[trainee.course]) {
                groups[trainee.course] = [];
            }
            groups[trainee.course].push(trainee);
        });
        return groups;
    }, [traineesData]);

    const addGroundTileTraineesByCourse = useMemo(() => {
        const groups: { [course: string]: Trainee[] } = {};
        traineesData.forEach((trainee: any) => {
            const courseName = String(trainee?.course || '').trim();
            if (!courseName || trainee?.isPaused) return;
            const traineeUnitCode = normalisePersonnelUnitCode(trainee?.unit);
            if (activeContextUnitCodeSet.size > 0 && (!traineeUnitCode || !activeContextUnitCodeSet.has(traineeUnitCode))) {
                return;
            }
            if (!groups[courseName]) {
                groups[courseName] = [];
            }
            groups[courseName].push(trainee);
        });
        return groups;
    }, [activeContextUnitCodeSet, traineesData]);

    const addGroundTileTrainees = useMemo(() => (
        Object.values(addGroundTileTraineesByCourse).flat()
    ), [addGroundTileTraineesByCourse]);

    const addGroundTileCourseColors = useMemo(() => {
        const entries = Object.entries(addGroundTileTraineesByCourse)
            .map(([courseName]) => [courseName, courseColors[courseName] || scopedCourseColors[courseName] || 'bg-sky-400/80']);
        return Object.fromEntries(entries);
    }, [addGroundTileTraineesByCourse, courseColors, scopedCourseColors]);

    const addGroundTileGroundResources = useMemo(() => (
        buildResources.filter(resourceId => /^Ground\s+\d+$/i.test(String(resourceId || '').trim()))
    ), [buildResources]);

    const addGroundTileCptResources = useMemo(() => (
        buildResources.filter(resourceId => /^CPT\s+\d+$/i.test(String(resourceId || '').trim()))
    ), [buildResources]);

    const handleSaveGroundEvent = (data: any) => {
        const syllabusItem = syllabusDetails.find(s => s.code === data.flightNumber);
        if (!syllabusItem) return;

        const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const eventDate = isNextDayContext ? buildDfpDate : date;
        const existingEventsForDate = isNextDayContext
            ? nextDayBuildEvents.map(event => ({ ...event, date: eventDate } as ScheduleEvent))
            : (publishedSchedules[eventDate] || []);
        const requestedResourceId = String(data.resourceId || '').trim() || 'Ground 1';
        const resourceMatch = requestedResourceId.match(/^(.+?)\s*(\d+)$/);
        const resourceBase = (resourceMatch?.[1] || requestedResourceId).trim();
        const selectedResourceNumber = Number(resourceMatch?.[2] || 1);
        const resourceLabelForNumber = (resourceNumber: number) => `${resourceBase} ${resourceNumber}`.trim();
        const configuredResourceCandidates = /^CPT\s+\d+$/i.test(requestedResourceId)
            ? addGroundTileCptResources
            : addGroundTileGroundResources;
        const proposedDuration = data.duration ?? syllabusItem.duration;
        const candidateEventBase: ScheduleEvent = {
            id: uuidv4(),
            date: eventDate,
            type: 'ground',
            flightNumber: data.flightNumber,
            startTime: data.startTime,
            duration: proposedDuration,
            instructor: data.instructor,
            attendees: data.attendees,
            resourceId: requestedResourceId,
            color: 'bg-teal-400/80',
            flightType: 'Dual',
            locationType: 'Local',
            origin: school,
            destination: school,
            authNotes: data.location // Using notes field as location for CPTs
        };
        const selectedResourceNumbers = [
            selectedResourceNumber,
            ...Array.from({ length: 23 }, (_, index) => index + 1).filter(resourceNumber => resourceNumber !== selectedResourceNumber),
        ];
        const resourceCandidates = configuredResourceCandidates.length > 0
            ? [requestedResourceId, ...configuredResourceCandidates.filter(resourceId => resourceId !== requestedResourceId)]
            : selectedResourceNumbers.map(resourceLabelForNumber);
        const firstClearResource = resourceCandidates
            .find(resourceId => !existingEventsForDate.some(existingEvent => (
                String(existingEvent.resourceId || '').trim() === resourceId &&
                checkTimeOverlap(candidateEventBase, existingEvent)
            )));
        const newEvent: ScheduleEvent = {
            ...candidateEventBase,
            resourceId: firstClearResource || requestedResourceId,
        };

        if (isNextDayContext) {
            setNextDayBuildEvents(prev => [...prev, newEvent]);
            setShowAddGroundEvent(false);
            setSuccessMessage(newEvent.resourceId === requestedResourceId
                ? 'Ground event added to the build.'
                : `Ground event added to the build on ${newEvent.resourceId}.`);
            return;
        }

        const updatedEventsForDate = [...(publishedSchedules[eventDate] || []), newEvent];
        setPublishedSchedules(prev => ({
            ...prev,
            [eventDate]: [...(prev[eventDate] || []), newEvent],
        }));
        setEvents(prev => [...prev, newEvent]);
        persistScheduleForDate(eventDate, updatedEventsForDate);
        setShowAddGroundEvent(false);
        setSuccessMessage(newEvent.resourceId === requestedResourceId
            ? 'Ground event added to the DFP.'
            : `Ground event added to the DFP on ${newEvent.resourceId}.`);
    };

    // Academic session save — creates one grouped ground event per trainee, flagged isAcademic=true
    // so NEO Build never touches it
    const handleSaveAcademicEvent = (data: import('./components/AcademicsTab').AcademicSaveData) => {
        logRoutineAppDebug('🎓 [AcademicPublish] ===== handleSaveAcademicEvent CALLED =====');
        logRoutineAppDebug('🎓 [AcademicPublish] data received:', {
            course: data.course,
            date: data.date,
            workStart: data.workStart,
            workEnd: data.workEnd,
            resourceId: data.resourceId,
            selectedTrainees: data.selectedTrainees,
            selectedTraineesCount: data.selectedTrainees?.length,
            tilesCount: data.timeline?.length,
            lessonsCount: data.lessons?.length,
            timeline: data.timeline,
            isAcademic: data.isAcademic,
        });

        // Guard: must have trainees and timeline tiles
        if (!data.selectedTrainees || data.selectedTrainees.length === 0) {
            console.error('🎓 [AcademicPublish] ❌ BLOCKED: no selectedTrainees — returning early');
            return;
        }
        if (!data.timeline || data.timeline.length === 0) {
            console.error('🎓 [AcademicPublish] ❌ BLOCKED: no timeline tiles — returning early');
            return;
        }

        // Build lesson codes summary (non-standard tiles only)
        const lessonCodes = data.lessons.map(l => l.code).join(', ');
        const sessionDuration = data.workEnd - data.workStart;

        logRoutineAppDebug('🎓 [AcademicPublish] lessonCodes:', lessonCodes);
        logRoutineAppDebug('🎓 [AcademicPublish] sessionDuration:', sessionDuration, '(workStart:', data.workStart, '→ workEnd:', data.workEnd, ')');

        if (sessionDuration <= 0) {
            console.error('🎓 [AcademicPublish] ❌ BLOCKED: sessionDuration is', sessionDuration, '— workStart/workEnd invalid');
            return;
        }

        const eventId = uuidv4();
        logRoutineAppDebug('🎓 [AcademicPublish] Generated event ID:', eventId);

        // ONE event per classroom resource — spans full working day (workStart → workEnd)
        // Contains all timeline tiles as academicTiles for inset rendering
        const academicDayEvent: ScheduleEvent = {
            id: eventId,
            date: data.date,
            type: 'ground' as const,
            flightNumber: 'ACAD',
            startTime: data.workStart,
            duration: sessionDuration,
            attendees: data.selectedTrainees,
            student: data.selectedTrainees[0] || '',
            instructor: data.instructor || '',
            resourceId: data.resourceId || 'Ground 1',
            color: 'bg-blue-800/90',
            flightType: 'Dual' as const,
            locationType: 'Local' as const,
            origin: school,
            destination: school,
            isAcademic: true,
            isTimeFixed: true,
            notes: `Academic session: ${lessonCodes}`,
            academicTiles: data.timeline.map(t => ({
                lessonCode: t.lessonCode,
                label: t.label,
                startTime: t.startTime,
                duration: t.duration,
                color: t.color,
                isStandard: t.isStandard,
            })),
        };

        logRoutineAppDebug('🎓 [AcademicPublish] academicDayEvent constructed:', {
            id: academicDayEvent.id,
            date: academicDayEvent.date,
            type: academicDayEvent.type,
            flightNumber: academicDayEvent.flightNumber,
            startTime: academicDayEvent.startTime,
            duration: academicDayEvent.duration,
            resourceId: academicDayEvent.resourceId,
            isAcademic: academicDayEvent.isAcademic,
            attendees: academicDayEvent.attendees,
            academicTilesCount: academicDayEvent.academicTiles?.length,
        });

        // FIX: Add event to publishedSchedules (the state the schedule view renders from),
        // NOT to the legacy 'events' state which is not rendered in the daily schedule view.
        const eventDate = data.date;
        logRoutineAppDebug('🎓 [AcademicPublish] Adding to publishedSchedules for date:', eventDate);
        logRoutineAppDebug('🎓 [AcademicPublish] Current publishedSchedules keys:', Object.keys(publishedSchedules));
        logRoutineAppDebug('🎓 [AcademicPublish] Current events for this date:', (publishedSchedules[eventDate] || []).length);

        setPublishedSchedules((prev: Record<string, ScheduleEvent[]>) => {
            const existing = prev[eventDate] || [];
            const updated = [...existing, academicDayEvent];
            logRoutineAppDebug('🎓 [AcademicPublish] setPublishedSchedules updater — was', existing.length, 'events, now', updated.length, 'for date', eventDate);
            return { ...prev, [eventDate]: updated };
        });

        // Also keep the legacy events state in sync (used by some sub-components)
        setEvents((prev: ScheduleEvent[]) => {
            logRoutineAppDebug('🎓 [AcademicPublish] setEvents updater — appending to', prev.length, 'events');
            return [...prev, academicDayEvent];
        });

        // Persist to DB so the event survives a page refresh
        // We must pass the updated array directly (not rely on state) to avoid async race
        const updatedEventsForDate = [...(publishedSchedules[eventDate] || []), academicDayEvent];
        logRoutineAppDebug('🎓 [AcademicPublish] Persisting', updatedEventsForDate.length, 'events for date', eventDate, 'to DB snapshot...');
        persistScheduleForDate(eventDate, updatedEventsForDate);

        setShowAddGroundEvent(false);
        const successMsg = `Academic session published for ${data.date}: ${lessonCodes || 'ACAD-SESSION'}`;
        logRoutineAppDebug('🎓 [AcademicPublish] ✅ Success:', successMsg);
        setSuccessMessage(successMsg);
        logRoutineAppDebug('🎓 [AcademicPublish] ===== handleSaveAcademicEvent COMPLETE =====');
    };


    // --- NEO ALGORITHM IMPLEMENTATION ---
    const replacementViolatesDayNightSeparation = useCallback((
        personName: string,
        personRole: PersonnelIdentityRole,
        candidateEvent: ScheduleEvent,
        allEvents: ScheduleEvent[]
    ): boolean => {
        const candidateClassification = getScheduleEventDayNightClassification(candidateEvent);
        if (candidateClassification === 'Day/Night') return false;

        return allEvents.some(event => {
            if (event.id === candidateEvent.id || !eventHasPersonWithRole(event, personName, personRole)) return false;
            const eventClassification = getScheduleEventDayNightClassification(event);
            if (eventClassification === 'Day/Night') return false;
            return candidateClassification !== eventClassification;
        });
    }, [getScheduleEventDayNightClassification]);

    const buildNeoCandidateEvent = useCallback((
        baseEvent: ScheduleEvent,
        replacementType: 'instructor' | 'trainee',
        replacementName: string,
        atTime: number = baseEvent.startTime
    ): ScheduleEvent => {
        const candidateEvent = { ...baseEvent, startTime: atTime };
        const isSctEvent = isContinuationScheduleEvent(candidateEvent);

        if (replacementType === 'instructor') {
            if (isSctEvent) {
                candidateEvent.pilot = replacementName;
                candidateEvent.instructor = '';
            } else {
                candidateEvent.instructor = replacementName;
                if (candidateEvent.type === 'flight' || candidateEvent.type === 'ftd') {
                    candidateEvent.pilot = candidateEvent.flightType === 'Solo'
                        ? (candidateEvent.student || candidateEvent.pilot || '')
                        : replacementName;
                }
            }
        } else {
            if (candidateEvent.flightType === 'Solo') {
                candidateEvent.pilot = replacementName;
                candidateEvent.student = '';
            } else {
                candidateEvent.student = replacementName;
            }
        }

        return candidateEvent;
    }, []);

    const isReplacementAvailableForCandidateEvent = useCallback((
        person: Instructor | Trainee,
        personName: string,
        candidateEvent: ScheduleEvent,
        allEvents: ScheduleEvent[]
    ): boolean => {
        const candidateEventType = candidateEvent.type as 'flight' | 'ground' | 'ftd' | 'duty_sup' | 'cpt';
        const eventWindow = getEventBookingWindow(candidateEvent, syllabusDetails);
        const personRole: PersonnelIdentityRole = 'fullName' in person ? 'trainee' : 'staff';

        if (isPersonStaticallyUnavailable(person, eventWindow.start, eventWindow.end, candidateEvent.date, candidateEventType)) {
            return false;
        }

        if (replacementViolatesDayNightSeparation(personName, personRole, candidateEvent, allEvents)) {
            return false;
        }

        const replacementHasOverlap = allEvents.some(event => {
            if (event.id === candidateEvent.id || !eventHasPersonWithRole(event, personName, personRole)) return false;
            const otherEventWindow = getEventBookingWindow(event, syllabusDetails);
            return eventWindow.start < otherEventWindow.end && eventWindow.end > otherEventWindow.start;
        });
        if (replacementHasOverlap) {
            return false;
        }

        const otherEvents = allEvents.filter(event => event.id !== candidateEvent.id);
        const candidateConflict = detectConflictsForEvent(candidateEvent, otherEvents, candidateEvent.date);
        if (candidateConflict.hasConflict) {
            return false;
        }

        if (shouldRequireTwrDiCoverage(candidateEvent, { allowStbySoloWithoutTwrDi: true }) && !hasTwrDiCoverageForSolo(candidateEvent, allEvents)) {
            return false;
        }

        return true;
    }, [detectConflictsForEvent, hasTwrDiCoverageForSolo, replacementViolatesDayNightSeparation, shouldRequireTwrDiCoverage, syllabusDetails]);

    const generateTraineeRemedies = useCallback((conflictedEvent: ScheduleEvent, allEvents: ScheduleEvent[]): NeoTraineeRemedy[] => {
        const suggestions: NeoTraineeRemedy[] = [];
        const conflictedSyllabusId = conflictedEvent.flightNumber;

        const otherTrainees = allTraineesData.filter(t => !personnelNamesMatch(t.fullName, conflictedEvent.student) && !t.isPaused);

        for (const trainee of otherTrainees) {
            // 1. Check if their next event matches
            const nextEvents = computeNextEventsForTrainee(trainee, traineeLMPs, scores, syllabusDetails, publishedSchedules, buildDfpDate);
            if (nextEvents.next?.id !== conflictedSyllabusId) {
                continue;
            }

            // 2. Check availability
            const candidateEvent = buildNeoCandidateEvent(conflictedEvent, 'trainee', trainee.fullName);
            if (!isReplacementAvailableForCandidateEvent(trainee, trainee.fullName, candidateEvent, allEvents)) {
                continue;
            }

            // All checks passed
            const daysSinceLastFlight = daysSince(trainee.lastFlightDate, conflictedEvent.date);
            const traineeEventsToday = allEvents.filter(e => eventHasPersonWithRole(e, trainee.fullName, 'trainee'));
            const flightsToday = traineeEventsToday.filter(e => e.type === 'flight').length;
            const ftdsToday = traineeEventsToday.filter(e => e.type === 'ftd').length;
            const cptsToday = traineeEventsToday.filter(e => e.type === 'cpt' || (e.type === 'ground' && e.flightNumber.includes('CPT'))).length;
            const groundToday = traineeEventsToday.filter(e => e.type === 'ground' && !(e.type === 'cpt' || e.flightNumber.includes('CPT'))).length;

            suggestions.push({
                type: 'trainee',
                trainee: {
                    name: trainee.fullName,
                    rank: trainee.rank,
                    course: trainee.course,
                    daysSinceLastFlight,
                    flightsToday,
                    ftdsToday,
                    cptsToday,
                    groundToday
                }
            });
        }

        // Sort by most needy (longest since last flight)
        return suggestions.sort((a, b) => b.trainee.daysSinceLastFlight - a.trainee.daysSinceLastFlight);
    }, [allTraineesData, traineeLMPs, scores, publishedSchedules, buildDfpDate, buildNeoCandidateEvent, isReplacementAvailableForCandidateEvent]);

    const generateInstructorRemediesAtTime = useCallback((conflictedEvent: ScheduleEvent, allEvents: ScheduleEvent[], atTime: number): NeoInstructorRemedy[] => {
        const suggestions: NeoInstructorRemedy[] = [];
        logNeoBuildUiDebug('🔍 generateInstructorRemediesAtTime called for:', conflictedEvent.flightNumber, 'at time:', atTime);
        logNeoBuildUiDebug('🔍 Total instructors to check:', instructorsData.length);
        let qualificationFailures = 0, unavailabilityFailures = 0, overlapFailures = 0;
        const eventAtNewTime = { ...conflictedEvent, startTime: atTime };

        for (const instructor of instructorsData) {
            // Check qualification
            const isQualified = isInstructorEligibleForBuildEventType(instructor, conflictedEvent.type || 'ground');
            if (!isQualified) { qualificationFailures++; continue; }

            const candidateEvent = buildNeoCandidateEvent(eventAtNewTime, 'instructor', instructor.name, atTime);
            if (!isReplacementAvailableForCandidateEvent(instructor, instructor.name, candidateEvent, allEvents)) {
                overlapFailures++;
                continue;
            }

            // All checks passed, add as a remedy
            const instructorEventsToday = allEvents.filter(e => e.id !== conflictedEvent.id && eventHasPersonWithRole(e, instructor.name, 'staff'));
            const flightsToday = instructorEventsToday.filter(e => e.type === 'flight').length;
            const ftdsToday = instructorEventsToday.filter(e => e.type === 'ftd').length;
            const cptsToday = instructorEventsToday.filter(e => e.type === 'cpt' || (e.type === 'ground' && e.flightNumber.includes('CPT'))).length;
            const groundToday = instructorEventsToday.filter(e => e.type === 'ground' && !(e.type === 'cpt' || e.flightNumber.includes('CPT'))).length;

            const dutyHours = calculateProjectedDuty(instructor.name, allEvents.filter(e => e.id !== conflictedEvent.id), eventAtNewTime, syllabusDetails);

            suggestions.push({
                type: 'instructor',
                instructor: {
                    name: instructor.name,
                    rank: instructor.rank,
                    dutyHours,
                    flightsToday,
                    ftdsToday,
                    cptsToday,
                    groundToday,
                }
            });
        }

        logNeoBuildUiDebug('🔍 Instructor remedy generation complete:');
        logNeoBuildUiDebug('🔍 - Qualification failures:', qualificationFailures);
        logNeoBuildUiDebug('🔍 - Unavailability failures:', unavailabilityFailures);
        logNeoBuildUiDebug('🔍 - Overlap failures:', overlapFailures);
        logNeoBuildUiDebug('🔍 - Total suggestions:', suggestions.length);
        return suggestions.sort((a, b) => {
            const eventCountA = a.instructor.flightsToday + a.instructor.ftdsToday + a.instructor.cptsToday + a.instructor.groundToday;
            const eventCountB = b.instructor.flightsToday + b.instructor.ftdsToday + b.instructor.cptsToday + b.instructor.groundToday;
            if (eventCountA !== eventCountB) return eventCountA - eventCountB;
            return a.instructor.dutyHours - b.instructor.dutyHours;
        });
    }, [instructorsData, syllabusDetails, buildNeoCandidateEvent, isReplacementAvailableForCandidateEvent]);

    // Generate pilot remedies for continuation events
    const generatePilotRemediesAtTime = useCallback((conflictedEvent: ScheduleEvent, allEvents: ScheduleEvent[], atTime: number): NeoInstructorRemedy[] => {
        const suggestions: NeoInstructorRemedy[] = [];
        logNeoBuildUiDebug('🔍 generatePilotRemediesAtTime called for:', conflictedEvent.flightNumber, 'at time:', atTime);

        // Get all qualified pilots (instructors who can fly as PIC)
        logNeoBuildUiDebug('🔍 [PILOT REMEDIES DEBUG] Input allInstructorsData:', instructorsData.map(i => ({ id: i.idNumber, name: i.name, role: i.role, unit: i.unit, location: i.location })));
        logNeoBuildUiDebug('🔍 [PILOT REMEDIES DEBUG] School:', school);

        const locationFilteredInstructors = instructorsData.filter(i => personMatchesConfiguredLocation(platformConfig, i, school));

        logNeoBuildUiDebug('🔍 [PILOT REMEDIES DEBUG] Location filtered instructors:', locationFilteredInstructors.map(i => ({ id: i.idNumber, name: i.name, role: i.role, unit: i.unit })));

        const qualifiedPilots = locationFilteredInstructors.filter(i => isInstructorEligibleForBuildEventType(i, 'flight'));
        logNeoBuildUiDebug('🔍 [PILOT REMEDIES DEBUG] Filtered qualifiedPilots:', qualifiedPilots.map(i => ({ id: i.idNumber, name: i.name, role: i.role, unit: i.unit })));
        logNeoBuildUiDebug('🔍 Total qualified pilots to check:', qualifiedPilots.length);

        let unavailabilityFailures = 0, overlapFailures = 0;
        const eventAtNewTime = { ...conflictedEvent, startTime: atTime };

        for (const pilot of qualifiedPilots) {
            const candidateEvent = buildNeoCandidateEvent(eventAtNewTime, 'instructor', pilot.name, atTime);
            if (!isReplacementAvailableForCandidateEvent(pilot, pilot.name, candidateEvent, allEvents)) {
                overlapFailures++;
                continue;
            }

            // All checks passed, add as a remedy
            const pilotEventsToday = allEvents.filter(e => e.id !== conflictedEvent.id && eventHasPersonWithRole(e, pilot.name, 'staff'));
            const flightsToday = pilotEventsToday.filter(e => e.type === 'flight').length;
            const ftdsToday = pilotEventsToday.filter(e => e.type === 'ftd').length;
            const cptsToday = pilotEventsToday.filter(e => e.type === 'cpt' || (e.type === 'ground' && e.flightNumber.includes('CPT'))).length;
            const groundToday = pilotEventsToday.filter(e => e.type === 'ground' && !(e.type === 'cpt' || e.flightNumber.includes('CPT'))).length;

            const dutyHours = calculateProjectedDuty(pilot.name, allEvents.filter(e => e.id !== conflictedEvent.id), eventAtNewTime, syllabusDetails);

            suggestions.push({
                type: 'instructor', // Reusing the same type for display purposes
                instructor: {
                    name: pilot.name,
                    rank: pilot.rank,
                    dutyHours,
                    flightsToday,
                    ftdsToday,
                    cptsToday,
                    groundToday,
                }
            });
        }

        logNeoBuildUiDebug('🔍 Pilot remedy generation complete:');
        logNeoBuildUiDebug('🔍 - Unavailability failures:', unavailabilityFailures);
        logNeoBuildUiDebug('🔍 - Overlap failures:', overlapFailures);
        logNeoBuildUiDebug('🔍 - Total suggestions:', suggestions.length);

        return suggestions.sort((a, b) => {
            const eventCountA = a.instructor.flightsToday + a.instructor.ftdsToday + a.instructor.cptsToday + a.instructor.groundToday;
            const eventCountB = b.instructor.flightsToday + b.instructor.ftdsToday + b.instructor.cptsToday + b.instructor.groundToday;
            if (eventCountA !== eventCountB) return eventCountA - eventCountB;
            return a.instructor.dutyHours - b.instructor.dutyHours;
        });
    }, [instructorsData, syllabusDetails, school, platformConfig, buildNeoCandidateEvent, isReplacementAvailableForCandidateEvent]);

    // --- New Iterative Turnaround Fix ---
    const findClosestTurnaroundFix = (
        problemEvent: ScheduleEvent,
        allEvents: ScheduleEvent[],
        context: AlgoContext,
        flyingWindow: { start: number; end: number }
    ): NeoTimeShiftRemedy | null => {
        const { flightTurnaround, ftdTurnaround, syllabusDetails, instructorsData, traineesData, getPersonnel, getEventBookingWindow, isPersonStaticallyUnavailable, maxCrewDutyPeriod } = context;

        const eventsOnResource = allEvents
            .filter(e => e.resourceId === problemEvent.resourceId && e.id !== problemEvent.id)
            .sort((a, b) => a.startTime - b.startTime);

        const prevEvent = eventsOnResource.filter(e => e.startTime < problemEvent.startTime).pop();
        const nextEvent = eventsOnResource.find(e => e.startTime > problemEvent.startTime);

        let waveType: 'first' | 'middle' | 'last' = 'middle';
        if (!prevEvent) waveType = 'first';
        if (!nextEvent) waveType = 'last';

        let baseTurnaround = 0;
        if (problemEvent.type === 'flight') baseTurnaround = flightTurnaround;
        else if (problemEvent.type === 'ftd') baseTurnaround = ftdTurnaround;

        const testTime = (newStartTime: number): boolean => {
            const tempEvent = { ...problemEvent, startTime: newStartTime };
            const eventWindow = getEventBookingWindow(tempEvent, syllabusDetails);

            if (eventWindow.start < flyingWindow.start || eventWindow.end > flyingWindow.end) return false;

            const nowInHours = new Date().getHours() + new Date().getMinutes() / 60;
            if (newStartTime < problemEvent.startTime && eventWindow.start < nowInHours) return false;

            const otherEvents = allEvents.filter(e => e.id !== problemEvent.id);
            const validationResult = detectConflictsForEvent(tempEvent, otherEvents, problemEvent.date);
            if (validationResult.hasConflict) return false;

            if (shouldRequireTwrDiCoverage(tempEvent, { allowStbySoloWithoutTwrDi: true }) && !hasTwrDiCoverageForSolo(tempEvent, allEvents)) {
                return false;
            }

            if (prevEvent) {
                let effectiveTurnaround = baseTurnaround;
                const hasCommonCrew = getCommonPersonnel(prevEvent, problemEvent).length > 0;
                if (hasCommonCrew) {
                    const prevSyllabus = syllabusDetails.find(s => s.id === prevEvent.flightNumber);
                    const currentSyllabus = syllabusDetails.find(s => s.id === problemEvent.flightNumber);
                    const crewGap = (prevSyllabus?.postFlightTime || 0) + (currentSyllabus?.preFlightTime || 0);
                    effectiveTurnaround = Math.max(baseTurnaround, crewGap);
                }
                if (newStartTime < prevEvent.startTime + prevEvent.duration + effectiveTurnaround) return false;
            }

            if (nextEvent) {
                 let effectiveTurnaround = baseTurnaround;
                 const hasCommonCrew = getCommonPersonnel(nextEvent, problemEvent).length > 0;
                 if (hasCommonCrew) {
                    const currentSyllabus = syllabusDetails.find(s => s.id === problemEvent.flightNumber);
                    const nextSyllabus = syllabusDetails.find(s => s.id === nextEvent.flightNumber);
                    const crewGap = (currentSyllabus?.postFlightTime || 0) + (nextSyllabus?.preFlightTime || 0);
                    effectiveTurnaround = Math.max(baseTurnaround, crewGap);
                 }
                if (newStartTime + problemEvent.duration + effectiveTurnaround > nextEvent.startTime) return false;
            }

            const originalCrew = getPersonnelIdentityRefs(problemEvent);
            for (const crewMember of originalCrew) {
                const personName = crewMember.label;
                const person = crewMember.role === 'staff'
                    ? allInstructorsData.find(p => personnelNamesMatch(p.name, personName))
                    : allTraineesData.find(p => personnelNamesMatch(p.fullName, personName));
                if (!person) continue;

                if (isPersonStaticallyUnavailable(person, eventWindow.start, eventWindow.end, problemEvent.date, problemEvent.type as any)) return false;

                const hasOverlap = allEvents.some(e => {
                    if (e.id === problemEvent.id) return false;
                    if (!eventHasPersonWithRole(e, personName, crewMember.role)) return false;
                    const otherEventWindow = getEventBookingWindow(e, syllabusDetails);
                    return eventWindow.start < otherEventWindow.end && eventWindow.end > otherEventWindow.start;
                });
                if (hasOverlap) return false;

                const otherEventsForPerson = allEvents.filter(e => e.id !== problemEvent.id && eventHasPersonWithRole(e, personName, crewMember.role));
                const projectedDuty = calculateProjectedDuty(personName, otherEventsForPerson, tempEvent, syllabusDetails);
                if (projectedDuty > maxCrewDutyPeriod) return false;
            }

            return true;
        };

        const offset = 5 / 60;
        const maxSearchSteps = Math.floor((flyingWindow.end - flyingWindow.start) / offset);

        for (let i = 1; i <= maxSearchSteps; i++) {
            const laterCandidate = problemEvent.startTime + i * offset;
            const earlierCandidate = problemEvent.startTime - i * offset;

            if (waveType === 'first' || (waveType === 'last' && !nextEvent)) {
                if (testTime(laterCandidate)) {
                    return { type: 'timeshift', newStartTime: laterCandidate, instructor: { name: problemEvent.instructor || '' } as any };
                }
            } else { // middle wave or last wave with next event
                if (testTime(laterCandidate)) {
                    return { type: 'timeshift', newStartTime: laterCandidate, instructor: { name: problemEvent.instructor || '' } as any };
                }
                if (testTime(earlierCandidate)) {
                    return { type: 'timeshift', newStartTime: earlierCandidate, instructor: { name: problemEvent.instructor || '' } as any };
                }
            }
        }
        return null;
    };

    const getFlightLineAircraftNumberForNeo = useCallback((event: ScheduleEvent, targetDate?: string): string => {
        const storageDate = targetDate || event.date || date;
        const storageKey = `dfp-flight-line-aircraft-event-assignments:${storageDate}:${school}:${activeUnitCode}`;
        let storedNumber = '';
        try {
            const storedAssignments = JSON.parse(window.localStorage.getItem(storageKey) || '{}');
            storedNumber = String(storedAssignments?.[event.id] || '').trim();
        } catch (error) {
            storedNumber = '';
        }

        const rawNumber = storedNumber || String(event.aircraftNumber || '').trim();
        if (!rawNumber) return '';
        const parsed = parseAircraftNumber(rawNumber, aircraftNumberSettings);
        return String(parsed.number || rawNumber).trim();
    }, [activeUnitCode, aircraftNumberSettings, date, school]);

    const getFlightLineAircraftConflictReasons = useCallback((
        event: ScheduleEvent,
        allEventsForDate: ScheduleEvent[],
        targetDate?: string,
    ): string[] => {
        if (event.type !== 'flight') return [];

        const settings = activePlatformResourcePool?.settings || {};
        const rawAircraftCount = Number(configuredAirframeCount ?? settings.aircraft ?? 0);
        const aircraftCount = Number.isFinite(rawAircraftCount) ? Math.max(0, Math.floor(rawAircraftCount)) : 0;
        const configuredNumbers = Array.isArray(settings.aircraftInventoryNumbers)
            ? settings.aircraftInventoryNumbers.map((value: any) => String(value ?? '').trim())
            : [];
        const validAircraftNumbers = Array.from({ length: aircraftCount }, (_, index) => (
            configuredNumbers[index] || String(index + 1).padStart(3, '0')
        ));

        const aircraftNumber = getFlightLineAircraftNumberForNeo(event, targetDate);
        if (!aircraftNumber || (validAircraftNumbers.length > 0 && !validAircraftNumbers.includes(aircraftNumber))) {
            return [];
        }

        const turnaroundHours = Math.max(0, Number(flightTurnaround) || 0);
        const requiredTurnaroundHoursText = turnaroundHours.toFixed(1);
        const eventProtectedEnd = event.startTime + event.duration + turnaroundHours;
        const epsilon = 0.001;

        return allEventsForDate
            .filter((candidate) => candidate.id !== event.id && candidate.type === 'flight')
            .map((candidate) => ({
                event: candidate,
                aircraftNumber: getFlightLineAircraftNumberForNeo(candidate, targetDate),
            }))
            .filter((candidate) => candidate.aircraftNumber === aircraftNumber)
            .filter(({ event: candidate }) => {
                const candidateProtectedEnd = candidate.startTime + candidate.duration + turnaroundHours;
                return event.startTime < candidateProtectedEnd - epsilon && candidate.startTime < eventProtectedEnd - epsilon;
            })
            .sort((a, b) => a.event.startTime - b.event.startTime)
            .map(({ event: conflictingEvent }) => {
                const earlier = event.startTime <= conflictingEvent.startTime ? event : conflictingEvent;
                const later = earlier.id === event.id ? conflictingEvent : event;
                const gapMinutes = Math.round((later.startTime - (earlier.startTime + earlier.duration)) * 60);
                const actualTurnaroundHours = Math.max(0, gapMinutes / 60);
                const actualTurnaroundText = actualTurnaroundHours.toFixed(1);
                const gapText = gapMinutes < 0
                    ? `the flights overlap by ${Math.abs(gapMinutes)} min`
                    : `actual turnaround time ${actualTurnaroundText} hours`;
                return `❌ Aircraft turnaround conflict - minimum ${requiredTurnaroundHoursText} hrs, ${gapText} after ${earlier.flightNumber}.`;
            });
    }, [activePlatformResourcePool?.settings, aircraftNumberSettings, configuredAirframeCount, flightTurnaround, getFlightLineAircraftNumberForNeo]);

    const handleNeoClick = (event: ScheduleEvent) => {
        const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const currentEvents = isNextDayContext ? nextDayBuildEvents.map(e => ({...e, date: buildDfpDate})) : eventsForDate;
        const latestEvent = currentEvents.find(e => e.id === event.id) || event;
        const eventForNeo = normaliseCrewFieldsForSave(latestEvent as ScheduleEvent);
        const allEvents = currentEvents.map(e => e.id === eventForNeo.id ? eventForNeo : e);

        logNeoBuildUiDebug('NEO: Resolved event for analysis:', {
            id: eventForNeo.id,
            originalInstructor: event.instructor,
            latestInstructor: latestEvent.instructor,
            analysisInstructor: eventForNeo.instructor,
            originalPilot: event.pilot,
            latestPilot: latestEvent.pilot,
            analysisPilot: eventForNeo.pilot,
        });

        // Check if this event is flagged by Validate mode
        const conflictingEventIds = isNextDayContext ? nextDayPersonnelAndResourceConflictIds : personnelAndResourceConflictIds;
        const isValidateFlagged = conflictingEventIds.has(getValidationEventKey(eventForNeo));

        let errors: string[] = [];

        // If Validate mode is active and this event is flagged, emphasize the validation conflicts
        if (showValidation && isValidateFlagged) {
            errors = findHardErrors(eventForNeo, allEvents, { allowStbySoloWithoutTwrDi: true });
            // Add specific validation context
            if (errors.length > 0) {
                errors.unshift("⚠️ VALIDATE MODE CONFLICTS DETECTED:");
                errors.push(""); // Empty line for readability
                errors.push("This event is marked RED because Validate mode found the following rule violations:");
            }
        } else {
            errors = findHardErrors(eventForNeo, allEvents, { allowStbySoloWithoutTwrDi: true });
        }

        if (errors.length === 0) {
            if (showValidation && !isValidateFlagged) {
                setShowInfoNotification('NEO analysis: This event has no conflicts and passes all validation rules.');
            } else {
                setShowInfoNotification('NEO found no hard errors for this event.');
            }
            return;
        }

        // If this is a validate-mode conflict, add specific context about validation
        if (showValidation && isValidateFlagged) {
            logNeoBuildUiDebug(`NEO: Analyzing validate-mode conflict for event ${eventForNeo.flightNumber} (${eventForNeo.id})`);
            logNeoBuildUiDebug(`Validation errors found:`, errors);
            setNeoProblemTileForFlyout({ event: eventForNeo, errors });
        } else {
            setNeoProblemTileForFlyout({ event: eventForNeo, errors });
        }

        const isTurnaroundViolationOnly = errors.every(e => e.toLowerCase().includes('turnaround')) && errors.length > 0;
        const instructorIsConflicted = errors.some(e => eventForNeo.instructor && e.includes(eventForNeo.instructor.split(',')[0]));

        if (isTurnaroundViolationOnly || !instructorIsConflicted) {
            const context: AlgoContext = { flightTurnaround, ftdTurnaround, syllabusDetails, instructorsData, traineesData, getPersonnel, getEventBookingWindow, isPersonStaticallyUnavailable, generateInstructorRemediesAtTime, maxCrewDutyPeriod };
            const timeRemedy = findClosestTurnaroundFix(eventForNeo, allEvents, context, { start: flyingStartTime, end: flyingEndTime });

            if (timeRemedy) {
                setTimeOnlyRemedyForConfirmation(timeRemedy);
                setShowTimeOnlyRemedyConfirm(true);
                setNeoRemediesForFlyout([]);
                return;
            } else if (isTurnaroundViolationOnly) {
                setShowInfoNotification("No resolution found for the turnaround violation. Changing crew will not fix this resource conflict.");
                setNeoProblemTileForFlyout(null);
                setNeoRemediesForFlyout([]);
                return;
            }
        }

        const traineeErrors = errors.filter(e => (eventForNeo.student && e.includes(eventForNeo.student.split(',')[0])));

        if (!instructorIsConflicted && traineeErrors.length > 0) {
            const remedies = generateTraineeRemedies(eventForNeo, allEvents);
            if (remedies.length > 0) {
                setNeoRemediesForFlyout(remedies);
                return;
            }
        }

        // Check if this is a continuation event - if so, generate pilot remedies instead of instructor remedies.
        const isSctEvent = isContinuationScheduleEvent(eventForNeo);

        if (isSctEvent) {
            logNeoBuildUiDebug('🔧 continuation event detected, generating pilot remedies');
            const remedies = generatePilotRemediesAtTime(eventForNeo, allEvents, eventForNeo.startTime);
            if (remedies.length > 0) {
                setNeoRemediesForFlyout(remedies);
            } else {
                setShowInfoNotification("No resolution found.");
                setNeoRemediesForFlyout([]);
            }
        } else {
            const remedies = generateInstructorRemediesAtTime(eventForNeo, allEvents, eventForNeo.startTime);
            if (remedies.length > 0) {
                setNeoRemediesForFlyout(remedies);
            } else {
                setShowInfoNotification("No resolution found.");
                setNeoRemediesForFlyout([]);
            }
        }
    };

    const handleApplyNeoRemedy = (remedy: NeoRemedy) => {
        logNeoBuildUiDebug('🔧 handleApplyNeoRemedy called with remedy:', remedy);
        logNeoBuildUiDebug('🔧 neoProblemTileForFlyout:', neoProblemTileForFlyout);

        if (!neoProblemTileForFlyout) {
            logNeoBuildUiDebug('❌ No problem tile found, returning early');
            return;
        }

        logNeoBuildUiDebug('🔧 Remedy type:', remedy.type);
        logNeoBuildUiDebug('🔧 Instructor duty hours:', remedy.type !== 'trainee' ? remedy.instructor.dutyHours : 'N/A');
        logNeoBuildUiDebug('🔧 Preferred duty period:', preferredDutyPeriod);

        if (remedy.type !== 'trainee' && remedy.instructor.dutyHours > preferredDutyPeriod) {
            logNeoBuildUiDebug('⚠️ Duty warning triggered');
            setDutyWarningRemedy(remedy);
            setShowDutyWarning(true);
        } else {
            logNeoBuildUiDebug('✅ Executing remedy directly');
            executeNeoRemedy(remedy, neoProblemTileForFlyout.event);
        }
    };

    const handleConfirmDutyWarning = () => {
        if (dutyWarningRemedy && neoProblemTileForFlyout) {
            executeNeoRemedy(dutyWarningRemedy, neoProblemTileForFlyout.event);
        }
        setShowDutyWarning(false);
        setDutyWarningRemedy(null);
    };

    const handleChooseTimeShift = () => {
        setShowNeoChoiceModal(false);
        setNeoRemediesForFlyout(timeShiftRemediesForChoice);
    };

    const handleChooseCrewChange = () => {
        setShowNeoChoiceModal(false);
        setNeoRemediesForFlyout(instructorRemediesForChoice);
    };

    const handleCancelTimeOnlyRemedy = () => {
        setShowTimeOnlyRemedyConfirm(false);
        setTimeOnlyRemedyForConfirmation(null);
        setNeoProblemTileForFlyout(null);
    };

    const handleSwitchToCrewChange = () => {
        setShowTimeOnlyRemedyConfirm(false);
        setTimeOnlyRemedyForConfirmation(null);

        if (neoProblemTileForFlyout) {
            logNeoBuildUiDebug('🔧 DEBUG: Generating instructor remedies for event:', neoProblemTileForFlyout.event.flightNumber);
            const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
            const allEvents = isNextDayContext ? nextDayBuildEvents.map(e => ({...e, date: buildDfpDate})) : eventsForDate;
            logNeoBuildUiDebug('🔧 DEBUG: Total events in context:', allEvents.length);
            const remedies = generateInstructorRemediesAtTime(neoProblemTileForFlyout.event, allEvents, neoProblemTileForFlyout.event.startTime);
            logNeoBuildUiDebug('🔧 DEBUG: Generated remedies:', remedies.length);
            logNeoBuildUiDebug('🔧 DEBUG: Remedies:', remedies);
            setNeoRemediesForFlyout(remedies);
        }
    };

    const handleConfirmTimeOnlyRemedy = () => {
        if (timeOnlyRemedyForConfirmation && neoProblemTileForFlyout) {
            executeNeoRemedy(timeOnlyRemedyForConfirmation, neoProblemTileForFlyout.event);
            // Close the time change confirmation modal
            setShowTimeOnlyConfirmation(false);
            setTimeOnlyRemedyForConfirmation(null);
            // Close the NEO problem flyout
            setNeoProblemTileForFlyout(null);
            setNeoRemediesForFlyout([]);
        }
    };

    const findHardErrors = (
        event: ScheduleEvent,
        allEventsForDate: ScheduleEvent[],
        options: { allowStbySoloWithoutTwrDi?: boolean } = {}
    ): string[] => {
        const errors: string[] = [];

        // Use the SAME conflict detection logic as the automatic system
        const conflictResult = detectConflictsForEvent(event, allEventsForDate, event.date);

        // If the conflict detection system found a conflict, explain it in detail
        if (conflictResult.hasConflict) {
            const conflictingEvent = allEventsForDate.find(e => e.id === conflictResult.conflictingEventId);
            const getConflictPersonLabel = (otherEvent?: ScheduleEvent): string => {
                const candidates = [
                    conflictResult.conflictedPersonnel,
                    ...(otherEvent ? getCommonPersonnel(event, otherEvent) : []),
                ].filter((name): name is string => !!name && !isPlaceholderPersonnelName(name));

                if (candidates.length === 0) return '';

                const personName = candidates[0];
                const roleLabels: string[] = [];
                const addRole = (label: string, value?: string) => {
                    if (personnelNamesMatch(value, personName) && !roleLabels.includes(label)) {
                        roleLabels.push(label);
                    }
                };

                addRole('Pilot/PIC', event.pilot);
                addRole('Pilot/PIC', otherEvent?.pilot);
                addRole('Instructor', event.instructor);
                addRole('Instructor', otherEvent?.instructor);
                addRole('Pilot 2 / WSO / Crew', event.crew);
                addRole('Pilot 2 / WSO / Crew', otherEvent?.crew);
                addRole('Student', event.student);
                addRole('Student', otherEvent?.student);

                return roleLabels.length > 0
                    ? `${personName.split(',')[0]} (${roleLabels.join(', ')})`
                    : personName.split(',')[0];
            };

            switch (conflictResult.conflictType) {
                case 'turnaround':
                    if (conflictingEvent) {
                        const conflictPerson = getConflictPersonLabel(conflictingEvent);
                        const personText = conflictPerson ? ` for ${conflictPerson}` : '';
                        const getTurnaroundRequirement = (candidate: ScheduleEvent): number => {
                            if (candidate.type === 'flight') return flightTurnaround;
                            if (candidate.type === 'ftd') return ftdTurnaround;
                            if (candidate.type === 'cpt' || (candidate.type === 'ground' && candidate.flightNumber.includes('CPT'))) return cptTurnaround;
                            return 0;
                        };
                        const selectedEventTurnaround = getTurnaroundRequirement(event);
                        const conflictingEventTurnaround = getTurnaroundRequirement(conflictingEvent);

                        if (event.startTime > conflictingEvent.startTime) {
                            const gap = event.startTime - (conflictingEvent.startTime + conflictingEvent.duration);
                            const requiredTurnaround = Math.max(selectedEventTurnaround, conflictingEventTurnaround);
                            errors.push(`❌ Turnaround violation${personText} - Only ${gap.toFixed(2)}hrs between ${event.flightNumber} and previous event ${conflictingEvent.flightNumber} (minimum required: ${requiredTurnaround}hrs)`);
                        } else {
                            const gap = conflictingEvent.startTime - (event.startTime + event.duration);
                            const requiredTurnaround = Math.max(selectedEventTurnaround, conflictingEventTurnaround);
                            errors.push(`❌ Turnaround violation${personText} - Only ${gap.toFixed(2)}hrs between ${event.flightNumber} and next event ${conflictingEvent.flightNumber} (minimum required: ${requiredTurnaround}hrs)`);
                        }
                    }
                    break;

                case 'resource':
                    if (conflictingEvent) {
                        errors.push(`❌ Resource conflict - Aircraft ${event.resourceId} is double-booked with ${conflictingEvent.flightNumber} at ${conflictingEvent.startTime.toFixed(2)}hrs`);
                    }
                    break;

                case 'personnel':
                    if (conflictingEvent) {
                        const conflictPerson = getConflictPersonLabel(conflictingEvent);
                        errors.push(`❌ ${conflictPerson || 'Crew member'} is double-booked - Scheduled for both ${event.flightNumber} and ${conflictingEvent.flightNumber} at overlapping times`);
                    }
                    break;

                case 'day-night':
                    if (conflictingEvent) {
                        const conflictPerson = getConflictPersonLabel(conflictingEvent);
                        const eventClassification = getScheduleEventDayNightClassification(event);
                        const conflictingEventClassification = getScheduleEventDayNightClassification(conflictingEvent);
                        errors.push(`❌ Day/Night separation violation - ${conflictPerson || 'Crew member'} cannot be scheduled for both ${eventClassification} event (${event.flightNumber}) and ${conflictingEventClassification} event (${conflictingEvent.flightNumber})`);
                    }
                    break;
            }
        }

        // ADDITIONAL CHECKS not covered by detectConflictsForEvent

        // Flight School dual flights require an instructor. Air Combat dual-crew
        // flights use pilot + crew positions instead, so no instructor is expected.
        const hasAirCombatCrewPair =
            normaliseOperationalModel(activeOperationalModel) === 'air_combat' &&
            String(event.pilot || '').trim().length > 0 &&
            String(event.crew || '').trim().length > 0;
        if (
            event.flightType === 'Dual' &&
            !hasAirCombatCrewPair &&
            (!event.instructor || event.instructor.trim() === '' || event.instructor === 'TBD')
        ) {
            errors.push('❌ No instructor assigned - Dual flights require an instructor.');
        }

        if (shouldRequireTwrDiCoverage(event, options) && !hasTwrDiCoverageForSolo(event, allEventsForDate)) {
            errors.push('❌ TWR DI coverage missing - Solo flights require a TWR DI event that starts before or at the solo start time and finishes after or at the solo finish time.');
        }

        // Check for static unavailability for all personnel
        const eventWindow = getEventBookingWindow(event, syllabusDetails);
        const personnel = getPersonnel(event);
        const allPersonnelData = [...allInstructorsData, ...allTraineesData];
        personnel.forEach(name => {
            const person = allPersonnelData.find(p => personnelNamesMatch('fullName' in p ? p.fullName : p.name, name));
            if (person && isPersonStaticallyUnavailable(person, eventWindow.start, eventWindow.end, event.date, event.type as any)) {
                const unavailability = person.unavailability.find(u => {
                    const isInDateRange = u.allDay
                        ? (event.date >= u.startDate && event.date < u.endDate)
                        : (event.date >= u.startDate && event.date <= u.endDate);
                    return isInDateRange;
                });
                const reason = unavailability?.reason || 'Unavailable';
                errors.push(`❌ ${(name || '').split(',')[0]} is unavailable - ${reason}`);
            }
        });

        const aircraftTailConflictReasons = getFlightLineAircraftConflictReasons(event, allEventsForDate, event.date || date);
        aircraftTailConflictReasons.forEach((reason) => errors.push(reason));

        return [...new Set(errors)];
    };


    const applyRemedyToEvents = (
        eventsList: Readonly<(ScheduleEvent | Omit<ScheduleEvent, 'date'>)[]>,
        remedy: NeoRemedy,
        problemTile: ScheduleEvent
    ): (ScheduleEvent | Omit<ScheduleEvent, 'date'>)[] => {
        logRoutineAppDebug('📝 applyRemedyToEvents called');
        logRoutineAppDebug('📝 Events list length:', eventsList.length);
        logRoutineAppDebug('📝 Problem tile ID:', problemTile.id);
        logRoutineAppDebug('📝 Remedy type:', remedy.type);

        return eventsList.map(event => {
            if (event.id === problemTile.id) {
                logRoutineAppDebug('✅ Found matching event, applying remedy');
                const updatedEvent = { ...event };
                logRoutineAppDebug('📝 Original instructor:', updatedEvent.instructor);

                if (remedy.type === 'timeshift') {
                    logRoutineAppDebug('📝 Applying timeshift remedy');
                    updatedEvent.startTime = remedy.newStartTime;
                    if (remedy.instructor.name) {
                        updatedEvent.instructor = remedy.instructor.name;
                    }
                } else if (remedy.type === 'instructor') {
                    logRoutineAppDebug('📝 Applying instructor remedy');
                    logRoutineAppDebug('📝 New instructor:', remedy.instructor.name);
                    updatedEvent.instructor = remedy.instructor.name;
                    if ((updatedEvent.type === 'flight' || updatedEvent.type === 'ftd') && updatedEvent.flightType !== 'Solo') {
                        updatedEvent.pilot = remedy.instructor.name;
                    }
                } else if (remedy.type === 'trainee') {
                    logRoutineAppDebug('📝 Applying trainee remedy');
                    if (updatedEvent.flightType === 'Solo') {
                        updatedEvent.pilot = remedy.trainee.name;
                        updatedEvent.student = '';
                    } else {
                        updatedEvent.student = remedy.trainee.name;
                    }
                }

                logNeoBuildUiDebug('📝 Updated instructor:', updatedEvent.instructor);
                return updatedEvent;
            }
            return event;
        });
    };

    const executeNeoRemedy = (remedy: NeoRemedy, problemTile: ScheduleEvent): void => {
        logNeoBuildUiDebug('🟣 ========== NEO REMEDY START ==========');
        logNeoBuildUiDebug('🟣 NEO: executeNeoRemedy called');
        logNeoBuildUiDebug('🟣 NEO: Remedy type:', remedy.type);
        logNeoBuildUiDebug('🟣 NEO: Problem tile ID:', problemTile.id);
        logNeoBuildUiDebug('🟣 NEO: Problem tile instructor:', problemTile.instructor);
        logNeoBuildUiDebug('🟣 NEO: Problem tile student:', problemTile.student);
        logNeoBuildUiDebug('🟣 NEO: Problem tile pilot:', problemTile.pilot);

        const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const targetDate = isNextDayContext ? buildDfpDate : date;

        logNeoBuildUiDebug('🟣 NEO: isNextDayContext:', isNextDayContext);
        logNeoBuildUiDebug('🟣 NEO: targetDate:', targetDate);
        logNeoBuildUiDebug('🟣 NEO: activeView:', activeView);

        // Get the current events
        const currentEvents = isNextDayContext
            ? nextDayBuildEvents.map(e => ({ ...e, date: buildDfpDate }))
            : (publishedSchedules[targetDate] || []);

        logNeoBuildUiDebug('🟣 NEO: currentEvents count:', currentEvents.length);

        // Find the event to update
        const eventToUpdate = currentEvents.find(e => e.id === problemTile.id);
        if (!eventToUpdate) {
            console.error('🟣 ❌ NEO: Event not found:', problemTile.id);
            logNeoBuildUiDebug('🟣 NEO: Available event IDs:', currentEvents.map(e => e.id));
            return;
        }

        logNeoBuildUiDebug('🟣 NEO: Found event to update:', {
            id: eventToUpdate.id,
            instructor: eventToUpdate.instructor,
            student: eventToUpdate.student,
            pilot: eventToUpdate.pilot,
            date: eventToUpdate.date,
            resourceId: eventToUpdate.resourceId
        });

        // Apply the remedy to create the updated event
        const updatedEvent = { ...eventToUpdate };

        // Check if this is a continuation event.
        const isSctEvent = isContinuationScheduleEvent(eventToUpdate);

        // Apply Dual/Solo logic from Individual LMP for LMP events.
        if (!isSctEvent) {
            const traineeName = updatedEvent.student || updatedEvent.pilot;
            if (traineeName && updatedEvent.flightNumber) {
                const individualLMPFlightType = getDualSoloFromIndividualLMP(updatedEvent.flightNumber, traineeName);
                updatedEvent.flightType = individualLMPFlightType;

                // Apply Solo logic: if Solo, set trainee as PIC and clear crew
                if (individualLMPFlightType === 'Solo' && traineeName) {
                    updatedEvent.pilot = traineeName;
                    updatedEvent.crew = '';
                    logNeoBuildUiDebug(`✈️ [NEO Solo Logic] Applied: ${traineeName} as PIC, crew cleared for ${updatedEvent.flightNumber}`);
                }

            }
        }

        if (remedy.type === 'instructor') {
            if (isSctEvent) {
                // For continuation events, change the pilot (PIC) instead of instructor
                logNeoBuildUiDebug('🟣 NEO: Applying pilot change for continuation event:', eventToUpdate.pilot, '→', remedy.instructor.name);
                updatedEvent.pilot = remedy.instructor.name;
                // Clear instructor field for continuation events (they don't have instructors)
                updatedEvent.instructor = '';
            } else {
                // For training flights, change the instructor
                logNeoBuildUiDebug('🟣 NEO: Applying instructor change:', eventToUpdate.instructor, '→', remedy.instructor.name);
                updatedEvent.instructor = remedy.instructor.name;
                if ((updatedEvent.type === 'flight' || updatedEvent.type === 'ftd') && updatedEvent.flightType !== 'Solo') {
                    updatedEvent.pilot = remedy.instructor.name;
                }
            }
        } else if (remedy.type === 'trainee') {
            logNeoBuildUiDebug('🟣 NEO: Applying trainee change:', eventToUpdate.student, '→', remedy.trainee.name);
            if (updatedEvent.flightType === 'Solo') {
                updatedEvent.pilot = remedy.trainee.name;
                updatedEvent.student = '';
            } else {
                updatedEvent.student = remedy.trainee.name;
            }
        } else if (remedy.type === 'timeshift') {
            logNeoBuildUiDebug('🟣 NEO: Applying time shift:', eventToUpdate.startTime, '→', remedy.newStartTime);
            updatedEvent.startTime = remedy.newStartTime;
            if (remedy.instructor.name) {
                if (isSctEvent) {
                    updatedEvent.pilot = remedy.instructor.name;
                    updatedEvent.instructor = '';
                } else {
                    updatedEvent.instructor = remedy.instructor.name;
                    if ((updatedEvent.type === 'flight' || updatedEvent.type === 'ftd') && updatedEvent.flightType !== 'Solo') {
                        updatedEvent.pilot = remedy.instructor.name;
                    }
                }
            }
        }

        logNeoBuildUiDebug('🟣 NEO: Updated event created:', {
            id: updatedEvent.id,
            instructor: updatedEvent.instructor,
            student: updatedEvent.student,
            pilot: updatedEvent.pilot,
            date: updatedEvent.date,
            resourceId: updatedEvent.resourceId
        });

        logNeoBuildUiDebug('🟣 NEO: Calling handleSaveEvents...');

        // Use the SAME save pathway as Flight Details modal.
        // Then mirror the normalized result into the canonical in-memory stores immediately.
        // This prevents the tile label, validation pass, and next NEO explanation from reading
        // different versions of the same event while React state updates settle.
        const savedUpdatedEvent = normaliseCrewFieldsForSave(updatedEvent as ScheduleEvent);
        handleSaveEvents([savedUpdatedEvent], false);

        if (isNextDayContext) {
            setNextDayBuildEvents(prev => prev.map(event => {
                if (event.id !== savedUpdatedEvent.id) return event;
                const { date: _savedDate, ...eventForBuild } = savedUpdatedEvent;
                return eventForBuild as ScheduleEvent;
            }));
        } else {
            setPublishedSchedules(prev => {
                const scheduleDate = savedUpdatedEvent.date || targetDate;
                const currentEventsForDate = prev[scheduleDate] || [];
                const nextEventsForDate = currentEventsForDate.map(event =>
                    event.id === savedUpdatedEvent.id ? savedUpdatedEvent : event
                );
                const eventExists = currentEventsForDate.some(event => event.id === savedUpdatedEvent.id);
                const mergedEventsForDate = eventExists
                    ? nextEventsForDate
                    : [...currentEventsForDate, savedUpdatedEvent];

                return {
                    ...prev,
                    [scheduleDate]: mergedEventsForDate,
                };
            });
        }

        setEvents(prev => prev.map(event =>
            event.id === savedUpdatedEvent.id ? savedUpdatedEvent : event
        ));

        setNeoProblemTileForFlyout(null);
        setNeoRemediesForFlyout([]);
        setDutyWarningRemedy(null);
        setShowDutyWarning(false);
        setTimeOnlyRemedyForConfirmation(null);
        setShowTimeOnlyRemedyConfirm(false);
        setSelectedEvent(null);

        logNeoBuildUiDebug('🟣 NEO: handleSaveEvents returned, closing NEO and Flight Details windows');
        logNeoBuildUiDebug('🟣 ========== NEO REMEDY END ==========');
    };

    // This effect creates the reactive loop for Neo.
    useEffect(() => {
        logNeoBuildUiDebug('🟠 ========== NEO USEEFFECT TRIGGERED ==========');
        logNeoBuildUiDebug('🟠 neoProblemTileForFlyout:', neoProblemTileForFlyout ? 'OPEN' : 'CLOSED');

        // Only run if the NEO flyout is currently open.
        if (!neoProblemTileForFlyout) {
            logNeoBuildUiDebug('🟠 NEO flyout is closed, skipping useEffect');
            logNeoBuildUiDebug('🟠 ========== NEO USEEFFECT END (CLOSED) ==========');
            return;
        }

        logNeoBuildUiDebug('🟠 NEO flyout is open, processing...');
        logNeoBuildUiDebug('🟠 Problem tile ID:', neoProblemTileForFlyout.event.id);
        logNeoBuildUiDebug('🟠 Problem tile instructor:', neoProblemTileForFlyout.event.instructor);

        const isNextDayContext = ['NextDayBuild', 'Priorities', 'ProgramData', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule'].includes(activeView);
        const currentEvents = isNextDayContext ? nextDayBuildEvents.map(e => ({ ...e, date: buildDfpDate })) : eventsForDate;

        logNeoBuildUiDebug('🟠 isNextDayContext:', isNextDayContext);
        logNeoBuildUiDebug('🟠 currentEvents count:', currentEvents.length);

        // Find the LATEST version of the problem tile from the current state.
        const updatedProblemTile = currentEvents.find(e => e.id === neoProblemTileForFlyout.event.id);

        if (!updatedProblemTile) {
            logNeoBuildUiDebug('🟠 ❌ Event not found in current state, closing flyout');
            // The event was deleted or somehow disappeared. Clean up and close.
            setNeoProblemTileForFlyout(null);
            setNeoRemediesForFlyout([]);
            logNeoBuildUiDebug('🟠 ========== NEO USEEFFECT END (NOT FOUND) ==========');
            return;
        }

        logNeoBuildUiDebug('🟠 Found updated problem tile:', {
            id: updatedProblemTile.id,
            instructor: updatedProblemTile.instructor,
            student: updatedProblemTile.student,
            pilot: updatedProblemTile.pilot
        });

        // Re-run the error analysis on the updated tile and schedule.
        logNeoBuildUiDebug('🟠 Running findHardErrors on updated tile...');
        const newErrors = findHardErrors(updatedProblemTile, currentEvents, { allowStbySoloWithoutTwrDi: true });
        logNeoBuildUiDebug('🟠 Errors found:', newErrors.length);
        if (newErrors.length > 0) {
            logNeoBuildUiDebug('🟠 Error details:', newErrors);
        }

        if (newErrors.length === 0) {
            logNeoBuildUiDebug('🟠 ✅ All conflicts resolved! Closing flyout and showing success message');
            // All problems are solved! Close the flyout and show success.
            setSuccessMessage(`All conflicts for ${updatedProblemTile.flightNumber} resolved.`);
            setNeoProblemTileForFlyout(null);
            setNeoRemediesForFlyout([]);
            setDutyWarningRemedy(null);
            setShowDutyWarning(false);
            setTimeOnlyRemedyForConfirmation(null);
            setShowTimeOnlyRemedyConfirm(false);
        } else {
            logNeoBuildUiDebug('🟠 ⚠️ Conflicts still exist, generating new remedies...');
            // Conflicts still exist. Generate new remedies and update the flyout's state.
            // This logic is simplified; a full implementation would call the same remedy generation
            // logic as handleNeoClick, but for brevity we'll just update the errors for now.
            // In a full re-analysis, you'd call generate...Remedies functions here.

            // Re-generate remedies based on the new state of errors
            const instructorErrors = newErrors.filter(e => e.toLowerCase().includes('instructor') || (updatedProblemTile.instructor && e.includes(updatedProblemTile.instructor.split(',')[0])));
            const traineeErrors = newErrors.filter(e => (updatedProblemTile.student && e.includes(updatedProblemTile.student.split(',')[0])));

            logNeoBuildUiDebug('🟠 Instructor errors:', instructorErrors.length);
            logNeoBuildUiDebug('🟠 Trainee errors:', traineeErrors.length);

            let newRemedies: NeoRemedy[] = [];

            if (instructorErrors.length === 0 && traineeErrors.length > 0) {
                logNeoBuildUiDebug('🟠 Generating trainee remedies...');
                newRemedies = generateTraineeRemedies(updatedProblemTile, currentEvents);
            } else {
                logNeoBuildUiDebug('🟠 Generating instructor remedies...');
                newRemedies = generateInstructorRemediesAtTime(updatedProblemTile, currentEvents, updatedProblemTile.startTime);
            }

            logNeoBuildUiDebug('🟠 Generated', newRemedies.length, 'new remedies');
            setNeoProblemTileForFlyout({ event: updatedProblemTile, errors: newErrors });
            setNeoRemediesForFlyout(newRemedies);
        }

        logNeoBuildUiDebug('🟠 ========== NEO USEEFFECT END ==========');

    // We depend on the schedules and the flyout's open state.
    // CRITICAL: We must re-run when the actual schedule data changes, not just when the event ID changes
    }, [publishedSchedules, nextDayBuildEvents, neoProblemTileForFlyout?.event.id, eventsForDate, activeView, buildDfpDate]); // Re-run when schedules change if flyout is open


    const handleCancelNeo = () => {
        setNeoProblemTileForFlyout(null);
        setNeoRemediesForFlyout([]);
    };

    const handleSaveCurrencies = (allCurrencies: CurrencyDefinition[]) => {
        const newMasters = allCurrencies.filter(c => c.type === 'composite') as MasterCurrency[];
        const newReqs = allCurrencies.filter(c => c.type === 'primitive') as CurrencyRequirement[];
        setMasterCurrencies(newMasters);
        setCurrencyRequirements(newReqs);
        if (activeCurrencyUnitKey) {
            setUnitCurrencyDefinitions(prev => ({
                ...prev,
                [activeCurrencyUnitKey]: {
                    masterCurrencies: newMasters,
                    currencyRequirements: newReqs,
                },
            }));
            setSuccessMessage(`Currency and recency rules saved for ${activeCurrencyUnitKey}!`);
        } else {
            setFallbackMasterCurrencies(newMasters);
            setFallbackCurrencyRequirements(newReqs);
            // Save directly to dedicated /api/currencies endpoint for legacy/global fallback persistence
            saveCurrenciesToDB(newMasters, newReqs, sessionUser?.userId);
            setSuccessMessage('Currency rules saved!');
        }
    };

    const handleDeleteCurrency = (id: string) => {
        const nextMasters = masterCurrencies.filter(c => c.id !== id);
        const nextReqs = currencyRequirements.filter(c => c.id !== id);
        setMasterCurrencies(nextMasters);
        setCurrencyRequirements(nextReqs);
        if (activeCurrencyUnitKey) {
            setUnitCurrencyDefinitions(prev => ({
                ...prev,
                [activeCurrencyUnitKey]: {
                    masterCurrencies: nextMasters,
                    currencyRequirements: nextReqs,
                },
            }));
        } else {
            setFallbackMasterCurrencies(nextMasters);
            setFallbackCurrencyRequirements(nextReqs);
        }
        setSuccessMessage('Currency deleted.');
    };

    const importCurrencyDefinitionsFromUnit = (sourceUnitCode: string) => {
        const normalisedSourceUnit = String(sourceUnitCode || '').trim().toUpperCase();
        if (!activeCurrencyUnitKey || !normalisedSourceUnit) return;
        const sourceDefinitions = unitCurrencyDefinitions[normalisedSourceUnit] || {
            masterCurrencies: fallbackMasterCurrencies,
            currencyRequirements: fallbackCurrencyRequirements,
        };
        const importedMasters = sourceDefinitions.masterCurrencies.map(currency => ({ ...currency }));
        const importedRequirements = sourceDefinitions.currencyRequirements.map(currency => ({ ...currency }));
        setMasterCurrencies(importedMasters);
        setCurrencyRequirements(importedRequirements);
        setUnitCurrencyDefinitions(prev => ({
            ...prev,
            [activeCurrencyUnitKey]: {
                masterCurrencies: importedMasters,
                currencyRequirements: importedRequirements,
            },
        }));
        setSuccessMessage(`Imported currency and recency rules from ${normalisedSourceUnit} to ${activeCurrencyUnitKey}.`);
    };

    const currencyNames = useMemo(() => {
        return [...masterCurrencies.map(c => c.name), ...currencyRequirements.map(c => c.name)].sort();
    }, [masterCurrencies, currencyRequirements]);

    const unitCurrencyImportOptions = useMemo(() => {
        const knownUnits = new Set([
            ...units,
            ...Object.keys(unitCurrencyDefinitions),
        ].map(unit => String(unit || '').trim().toUpperCase()).filter(Boolean));
        return Array.from(knownUnits)
            .filter(unit => unit !== activeCurrencyUnitKey)
            .sort((a, b) => a.localeCompare(b))
            .map(unit => {
                const definitions = unitCurrencyDefinitions[unit] || {
                    masterCurrencies: fallbackMasterCurrencies,
                    currencyRequirements: fallbackCurrencyRequirements,
                };
                return {
                    unitCode: unit,
                    label: unit,
                    currencyCount: (definitions.masterCurrencies?.length || 0)
                        + (definitions.currencyRequirements?.length || 0),
                    recencyCount: [
                        ...(definitions.masterCurrencies || []),
                        ...(definitions.currencyRequirements || []),
                    ].filter(currency => currency.showInPostFlightRecency).length,
                    usesFallback: !unitCurrencyDefinitions[unit],
                };
            });
    }, [activeCurrencyUnitKey, fallbackCurrencyRequirements, fallbackMasterCurrencies, unitCurrencyDefinitions, units]);

    // --- ORACLE HANDLERS ---
    const runOracleAnalysis = useCallback(() => {
        const isNextDayContext = oracleContext === 'nextDayBuild';
        const currentEvents = (isNextDayContext ? nextDayBuildEvents.map(e => ({...e, date: buildDfpDate})) : eventsForDate).filter(e => !e.resourceId.startsWith('STBY') && !e.resourceId.startsWith('BNF-STBY'));
        const analysisDate = isNextDayContext ? buildDfpDate : date;

        const instructorsAnalysis: OracleInstructorAnalysis[] = instructorsData.map(instructor => {
            const events = currentEvents.filter(e => getPersonnel(e).includes(instructor.name));
            return { instructor, availableWindows: [] }; // Placeholder
        });


        const traineesAnalysis: OracleTraineeAnalysis[] = allTraineesData.map(trainee => {
            const events = currentEvents.filter(e => getPersonnel(e).includes(trainee.fullName));

            // Count events by type for the analysis date
            const hasFtd = events.some(e => e.type === 'ftd' && e.date === analysisDate);
            const hasFlight = events.some(e => e.type === 'flight' && e.date === analysisDate);
            const groundEventsToday = events.filter(e => e.type === 'ground' && e.date === analysisDate).length;

            const nextSyllabusEvent = computeNextEventsForTrainee(trainee, traineeLMPs, scores, syllabusDetails, publishedSchedules, buildDfpDate).next;

            // Enhanced eligibility logic for Oracle - proper trainee duty rules
            let isEligible = nextSyllabusEvent?.type === 'Flight';

            // Rule 0: EXCLUDE PAUSED/NTSC TRAINEES - Oracle should NOT offer these trainees
            if (trainee.isPaused) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} excluded - trainee is PAUSED`);
            }

            // Check for NTSC status (assume it might be in course name or a status field)
            const isNtsc = trainee.course.includes('NTSC') || trainee.fullName.includes('NTSC');
            if (isNtsc) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} excluded - trainee is NTSC`);
            }

            // Rule 1: EXCLUDE TRAINEES WHOSE NEXT EVENT IS REMEDIAL
            if (nextSyllabusEvent && nextSyllabusEvent.isRemedial) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} excluded - next event ${nextSyllabusEvent.code} is REMEDIAL`);
            }

            // Rule 2: Only one flight per day
            if (hasFlight) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} ineligible - already has flight scheduled for ${analysisDate}`);
            }

            // Rule 3: Max 1 FTD + 1 flight per day
            if (hasFtd && hasFlight) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} ineligible - has both FTD and flight scheduled for ${analysisDate}`);
            }

            // Rule 4: Max 2 ground events per day
            if (groundEventsToday >= 2) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} ineligible - already has ${groundEventsToday} ground events for ${analysisDate}`);
            }

            // Rule 5: Must have valid next syllabus event
            if (!nextSyllabusEvent) {
                isEligible = false;
                logRoutineAppDebug(`Oracle: ${trainee.fullName} ineligible - no next syllabus event found`);
            }


            return { trainee, availableWindows: [], nextSyllabusEvent, isEligible };
        });

        const eligibleCount = traineesAnalysis.filter(t => t.isEligible).length;

        setOracleAnalysis({ instructors: instructorsAnalysis, trainees: traineesAnalysis });
    }, [allInstructorsData, allTraineesData, eventsForDate, date, nextDayBuildEvents, buildDfpDate, oracleContext, traineeLMPs, scores, syllabusDetails]);

    const handleToggleOracleMode = useCallback(() => {
        if (!canRunNeoBuild) {
            denyPlatformAction('NEO tile assistance is not permitted for your assigned permission profile');
            return;
        }
        if (!isNeoCapableOperationalModel) {
            setShowInfoNotification(`${activeOperationalModelLabel} is selected for ${school} - ${activeUnitCode}. NEO tile assistance is not available for this operational model yet.`);
            return;
        }
        const isNextDay = ['NextDayBuild', 'NextDayInstructorSchedule', 'NextDayTraineeSchedule', 'Priorities', 'ProgramData'].includes(activeView);
        setOracleContext(isNextDay ? 'nextDayBuild' : 'program');

        if (!isOracleMode) {
            // runOracleAnalysis will now be called inside this effect, after context is set
        } else {
            setOracleAnalysis(null);
            setOraclePreviewEvent(null);
        }
        setIsOracleMode(prev => !prev);
    }, [activeOperationalModel, activeOperationalModelLabel, activeUnitCode, isNeoCapableOperationalModel, isOracleMode, activeView, canRunNeoBuild, denyPlatformAction, school]);

    const handleQuickTile = useCallback(() => {
        if (!isFixedCrewLikeOperationalModel(activeOperationalModel)) {
            handleToggleOracleMode();
            return;
        }
        if (isViewingPastDfp) {
            denyPastDfpEdit('add quick tiles');
            return;
        }
        if (!canEditDfpTiles) {
            denyPlatformAction('Add or edit flight tiles is not permitted for your assigned permission profile');
            return;
        }

        const scheduleForDate = publishedSchedules[date] || [];
        const quickStartTime = Number.isFinite(flyingStartTime) ? flyingStartTime : 8;
        const quickDuration = 2;
        const aircraftResourcePrefix = `${activeAircraftResourcePrefix} `;
        const isNormalAircraftResource = (resourceId: string): boolean => {
            const cleanResourceId = String(resourceId || '').trim();
            if (!cleanResourceId.startsWith(aircraftResourcePrefix)) return false;
            return /^\d+$/.test(cleanResourceId.slice(aircraftResourcePrefix.length).trim());
        };
        const aircraftResources = buildResources.filter(isNormalAircraftResource);
        const hasAnyEventOnResource = (resourceId: string): boolean =>
            scheduleForDate.some(event => !event.isCancelled && event.resourceId === resourceId);
        const overlapsQuickWindow = (event: ScheduleEvent, resourceId: string): boolean =>
            !event.isCancelled &&
            event.resourceId === resourceId &&
            event.startTime < quickStartTime + quickDuration &&
            quickStartTime < event.startTime + event.duration;
        const resourceId = aircraftResources.find(resource => !hasAnyEventOnResource(resource)) ||
            aircraftResources.find(resource => !scheduleForDate.some(event => overlapsQuickWindow(event, resource)));

        if (!resourceId) {
            setShowInfoNotification('Quick Tile could not find a free aircraft resource line on the active DFP.');
            return;
        }

        const quickTile: ScheduleEvent = {
            id: uuidv4(),
            date,
            type: 'flight',
            flightNumber: 'Quick Tile',
            syllabusItem: 'Quick Tile',
            startTime: quickStartTime,
            duration: quickDuration,
            resourceId,
            color: 'bg-emerald-500',
            flightType: 'Dual',
            soloOrDual: 'Dual',
            locationType: 'Local',
            origin: school,
            destination: school,
            isTimeFixed: true,
            aircraftConfigId: BASE_AIRCRAFT_CONFIG.id,
            acceptableAircraftConfigs: [BASE_AIRCRAFT_CONFIG.id],
            fixedCrewUnit: activeUnitCode,
            eventCategory: 'quick_tile',
            pilot: 'Select PIC',
            instructor: 'Select PIC',
            student: '',
            crew: '',
            group: '',
        };

        const nextEventsForDate = [...scheduleForDate, quickTile];
        setPublishedSchedules(prev => ({
            ...prev,
            [date]: [...(prev[date] || []), quickTile],
        }));
        persistScheduleForDate(date, nextEventsForDate, scheduleForDate);
        logAudit('Program Schedule', 'Create', 'Added Quick Tile', `Time: ${quickStartTime}, Duration: ${quickDuration}hrs, Resource: ${resourceId}`);
    }, [
        activeOperationalModel,
        activeAircraftResourcePrefix,
        activeUnitCode,
        buildResources,
        canEditDfpTiles,
        date,
        denyPastDfpEdit,
        denyPlatformAction,
        flyingStartTime,
        handleToggleOracleMode,
        isViewingPastDfp,
        logAudit,
        persistScheduleForDate,
        publishedSchedules,
        school,
    ]);

    useEffect(() => {
        if (isOracleMode) {
            runOracleAnalysis();
        }
    }, [isOracleMode, oracleContext, runOracleAnalysis]);


    const handleOracleMouseDown = useCallback((startTime: number, resourceId: string) => {
        const mockEvent: ScheduleEvent = {
            id: 'oracle-preview',
            date: oracleContext === 'nextDayBuild' ? buildDfpDate : date,
            startTime,
            duration: 1.2,
            resourceId,
            type: 'flight',
            flightNumber: 'Next Event',
            instructor: 'Checking...',
            student: 'Checking...',
            color: 'bg-sky-500/50',
            flightType: 'Dual',
            locationType: 'Local',
            origin: school,
            destination: school
        };
        setOraclePreviewEvent(mockEvent);
    }, [date, buildDfpDate, oracleContext, school]);

    const handleOracleMouseMove = useCallback((newStartTime: number, newResourceId: string) => {
        if (!oraclePreviewEvent || !oracleAnalysis) return;

        const currentEvents = (oracleContext === 'nextDayBuild' ? nextDayBuildEvents.map(e => ({...e, date: buildDfpDate})) : eventsForDate).filter(e => !e.resourceId.startsWith('STBY') && !e.resourceId.startsWith('BNF-STBY'));
        const analysisDate = oracleContext === 'nextDayBuild' ? buildDfpDate : date;

        const preFlightTime = 1.0;
        const postFlightTime = 0.5;
        const duration = 1.2;
        const bookingWindow = {
            start: newStartTime - preFlightTime,
            end: newStartTime + duration + postFlightTime
        };

        const instructorAvailable = oracleAnalysis.instructors.some(inst => {
            const personEvents = currentEvents.filter(e => getPersonnel(e).includes(inst.instructor.name));
            const hasOverlap = personEvents.some(e => {
                const existingWindow = getEventBookingWindow(e, syllabusDetails);
                return bookingWindow.start < existingWindow.end && bookingWindow.end > existingWindow.start;
            });
            return !isPersonStaticallyUnavailable(inst.instructor, bookingWindow.start, bookingWindow.end, analysisDate, 'flight') && !hasOverlap;
        });

        const traineeAvailable = oracleAnalysis.trainees.some(tr => {
            if (!tr.isEligible) return false;
            const personEvents = currentEvents.filter(e => getPersonnel(e).includes(tr.trainee.fullName));
            const hasOverlap = personEvents.some(e => {
                const existingWindow = getEventBookingWindow(e, syllabusDetails);
                return bookingWindow.start < existingWindow.end && bookingWindow.end > existingWindow.start;
            });
            return !isPersonStaticallyUnavailable(tr.trainee, bookingWindow.start, bookingWindow.end, analysisDate, 'flight') && !hasOverlap;
        });

        setOraclePreviewEvent({
            ...oraclePreviewEvent,
            startTime: newStartTime,
            resourceId: newResourceId,
            instructor: instructorAvailable ? 'Instructor ✓' : 'NO INSTRUCTOR ✕',
            student: traineeAvailable ? 'Trainee ✓' : 'NO TRAINEE ✕',
        });
    }, [oraclePreviewEvent, oracleAnalysis, eventsForDate, date, nextDayBuildEvents, buildDfpDate, oracleContext, syllabusDetails]);

    const handleOracleMouseUp = useCallback(() => {
        if (!oraclePreviewEvent || !oracleAnalysis) return;

        const currentEvents = (oracleContext === 'nextDayBuild' ? nextDayBuildEvents.map(e => ({...e, date: buildDfpDate})) : eventsForDate).filter(e => !e.resourceId.startsWith('STBY') && !e.resourceId.startsWith('BNF-STBY'));
        const analysisDate = oracleContext === 'nextDayBuild' ? buildDfpDate : date;

        const { startTime, duration } = oraclePreviewEvent;
        const preFlightTime = 1.0;
        const postFlightTime = 0.5;
        const bookingWindow = { start: startTime - preFlightTime, end: startTime + duration + postFlightTime };

        const availableInstructors = oracleAnalysis.instructors.filter(inst => {
             const personEvents = currentEvents.filter(e => getPersonnel(e).includes(inst.instructor.name));
             const hasOverlap = personEvents.some(e => {
                 const existingWindow = getEventBookingWindow(e, syllabusDetails);
                 return bookingWindow.start < existingWindow.end && bookingWindow.end > existingWindow.start;
             });
            return !isPersonStaticallyUnavailable(inst.instructor, bookingWindow.start, bookingWindow.end, analysisDate, 'flight') && !hasOverlap;
        }).map(i => i.instructor.name);

        const availableTraineesAnalysis = oracleAnalysis.trainees.filter(tr => {
            if (!tr.isEligible) return false;

            const personEvents = currentEvents.filter(e => getPersonnel(e).includes(tr.trainee.fullName));

            // CRITICAL FIX 1: Check if trainee already has a flight scheduled for this day (one flight per day rule)
            const hasExistingFlightToday = personEvents.some(e =>
                e.type === 'flight' && e.date === analysisDate
            );
            if (hasExistingFlightToday) {
                logRoutineAppDebug(`Oracle: Excluding ${tr.trainee.fullName} - already has a flight scheduled for ${analysisDate}`);
                return false;
            }

            // CRITICAL FIX 2: Check if trainee is already scheduled for this specific event
            // We'll use the next syllabus event to determine what they would be scheduled for
            if (tr.nextSyllabusEvent) {
                const nextSyllabusEventRefs = new Set([
                    tr.nextSyllabusEvent.code,
                    tr.nextSyllabusEvent.id,
                ].map(ref => String(ref || '').trim()).filter(Boolean));
                const hasThisEventAlready = personEvents.some(e =>
                    nextSyllabusEventRefs.has(String(e.flightNumber || '').trim()) && e.date === analysisDate
                );
                if (hasThisEventAlready) {
                    logRoutineAppDebug(`Oracle: Excluding ${tr.trainee.fullName} - already scheduled for event ${tr.nextSyllabusEvent.code || tr.nextSyllabusEvent.id} on ${analysisDate}`);
                    return false;
                }
            }

            // Check for time-based availability conflicts
            const hasOverlap = personEvents.some(e => {
                const existingWindow = getEventBookingWindow(e, syllabusDetails);
                return bookingWindow.start < existingWindow.end && bookingWindow.end > existingWindow.start;
            });

               // Log day/night classification for debugging
               const nextEventClassification = tr.nextSyllabusEvent ? getEventDayNightClassification({ flightNumber: tr.nextSyllabusEvent.code }, syllabusDetails, sctEvents) : 'Unknown';

               // CRITICAL: Check if proposed time matches next event's day/night classification
               // If next event is Night, only show trainee as available during night hours
               // If next event is Day, only show trainee as available during day hours
               if (tr.nextSyllabusEvent && nextEventClassification !== 'Day/Night') {
                   const proposedIsNight = classifyStartBySolarDaylight(bookingWindow.start, analysisDate) === 'Night';
                   const proposedIsDay = !proposedIsNight;

                   if (nextEventClassification === 'Night' && proposedIsDay) {
                       logRoutineAppDebug(`Oracle: Excluding ${tr.trainee.fullName} - Next event is Night but proposed time is Day (${bookingWindow.start.toFixed(2)})`);
                       return false;
                   }

                   if (nextEventClassification === 'Day' && proposedIsNight) {
                       logRoutineAppDebug(`Oracle: Excluding ${tr.trainee.fullName} - Next event is Day but proposed time is Night (${bookingWindow.start.toFixed(2)})`);
                       return false;
                   }
               }

            // HARD-WIRED: Check day/night separation violations
            const dayNightCheck = enforceDayNightSeparation(
                tr.trainee.fullName,
                bookingWindow.start,
                bookingWindow.end - bookingWindow.start,
                'flight',
                analysisDate,
                tr.nextSyllabusEvent?.id
            );

            // Check static unavailability
            const isUnavailable = isPersonStaticallyUnavailable(tr.trainee, bookingWindow.start, bookingWindow.end, analysisDate, 'flight');

            if (!dayNightCheck.isAllowed) {
                logRoutineAppDebug(`Oracle: Excluding ${tr.trainee.fullName} - ${dayNightCheck.reason}`);
                return false;
            }

            return !isUnavailable && !hasOverlap;
        });

        setOracleContextForModal({
            availableInstructors,
            availableTraineesAnalysis
        });

        const newEvent: ScheduleEvent = {
            id: uuidv4(),
            date: analysisDate,
            type: 'flight',
            flightNumber: '',
            duration: oraclePreviewEvent.duration,
            startTime: oraclePreviewEvent.startTime,
            resourceId: oraclePreviewEvent.resourceId,
            color: 'bg-sky-400/80',
            flightType: 'Dual',
            locationType: 'Local',
            origin: school,
            destination: school,
        };

        setSelectedEvent(newEvent);
        setIsEditingDefault(true);
        setOraclePreviewEvent(null);

    }, [oraclePreviewEvent, oracleAnalysis, date, school, eventsForDate, nextDayBuildEvents, buildDfpDate, oracleContext, syllabusDetails, classifyStartBySolarDaylight]);

    const handleSelectMyProfile = () => {
        const user = instructorsData.find(i => i.name === currentUserName);
        if (user) {
            setSelectedPersonForProfile(user);
            handleNavigation('Instructors');
        }
    };

    const handleNavigateToCurrency = useCallback((person: Instructor | Trainee) => {
        setSelectedPersonForCurrency(person);
        // Detect whether this person is a trainee (has 'course' field) or instructor
        const pType: 'instructor' | 'trainee' = 'course' in person ? 'trainee' : 'instructor';
        setSelectedPersonForCurrencyType(pType);
        handleNavigation('Currency');
    }, []);

    const handleSelectMyCurrency = () => {
        const user = instructorsData.find(i => i.name === currentUserName);
        if (user) {
            setSelectedPersonForProfile(user);
            setProfileInitialTab('currency');
            handleNavigation('Instructors');
        }
    };

    const handleSelectMySct = () => {
        const user = instructorsData.find(i => i.name === currentUserName); // Current logged in user
        if (user) {
            setInstructorForSct(user);
            setShowSctRequest(true);
        }
    };

    const handleCurrencyBack = () => {
        handleNavigation(previousView);
    };

    const buildIntelligenceActiveCourses = useMemo(() => {
        const priorityCourses = coursePriorities.filter(course => scopedCourseColors[course]);
        if (priorityCourses.length > 0) return priorityCourses;
        return [...new Set(
            traineesData
                .map(trainee => trainee.course)
                .filter(course => course && scopedCourseColors[course])
        )];
    }, [coursePriorities, scopedCourseColors, traineesData]);

    const buildIntelligenceCourseSet = useMemo(
        () => new Set(buildIntelligenceActiveCourses),
        [buildIntelligenceActiveCourses],
    );

    const buildIntelligencePersonnelSet = useMemo(() => {
        const names = new Set<string>();
        instructorsData.forEach(instructor => {
            if (instructor.name) names.add(instructor.name);
        });
        traineesData.forEach(trainee => {
            if (trainee.fullName) names.add(trainee.fullName);
            if (trainee.name) names.add(trainee.name);
        });
        return names;
    }, [instructorsData, traineesData]);

    const buildIntelligenceTraineeCourseLookup = useMemo(() => {
        const lookup = new Map<string, string>();
        traineesData.forEach(trainee => {
            if (trainee.fullName && trainee.course) lookup.set(trainee.fullName, trainee.course);
            if (trainee.name && trainee.course) lookup.set(trainee.name, trainee.course);
        });
        return lookup;
    }, [traineesData]);

    const getBuildIntelligenceEventCourse = useCallback((event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): string | null => {
        const traineeName = event.student || event.pilot || '';
        if (!traineeName) return null;
        const directCourse = buildIntelligenceTraineeCourseLookup.get(traineeName);
        if (directCourse) return directCourse;
        const legacyCourseMatch = traineeName.match(/ \u2013 (.*)$/);
        return legacyCourseMatch ? legacyCourseMatch[1] : null;
    }, [buildIntelligenceTraineeCourseLookup]);

    const eventMatchesBuildIntelligenceScope = useCallback((event: Omit<ScheduleEvent, 'date'> | ScheduleEvent): boolean => {
        const eventCourse = getBuildIntelligenceEventCourse(event);
        if (eventCourse) return buildIntelligenceCourseSet.has(eventCourse);
        return getPersonnel(event).some(person => buildIntelligencePersonnelSet.has(person));
    }, [buildIntelligenceCourseSet, buildIntelligencePersonnelSet, getBuildIntelligenceEventCourse]);

    const buildIntelligenceEvents = useMemo(
        () => nextDayBuildEvents
            .map(event => ({ ...event, date: buildDfpDate }))
            .filter(eventMatchesBuildIntelligenceScope),
        [buildDfpDate, eventMatchesBuildIntelligenceScope, nextDayBuildEvents],
    );

    const buildIntelligenceAnalysis = useMemo<BuildAnalysis | null>(() => {
        if (!lastBuildAnalysis) return null;
        const scopedCourseAnalysis = (lastBuildAnalysis.courseAnalysis || [])
            .filter(course => buildIntelligenceCourseSet.has(course.courseName));
        const scheduledEvents = buildIntelligenceEvents.filter(event => {
            if (event.flightNumber.includes('Duty Sup')) return false;
            if (event.resourceId.startsWith('STBY') || event.resourceId.startsWith('BNF-STBY')) return false;
            return true;
        });
        const totalEvents = scheduledEvents.length;
        const eventsByHour = new Map<number, number>();
        for (let hour = 0; hour < 24; hour++) eventsByHour.set(hour, 0);
        scheduledEvents.forEach(event => {
            const hour = Math.floor(event.startTime);
            eventsByHour.set(hour, (eventsByHour.get(hour) || 0) + 1);
        });

        const averageEventsPerHour = totalEvents > 0 ? totalEvents / 24 : 0;
        let clusteringScore = 0;
        if (totalEvents > 0) {
            eventsByHour.forEach(count => {
                clusteringScore += Math.abs(count - averageEventsPerHour);
            });
            clusteringScore = clusteringScore / (totalEvents * 2);
        }
        const flightEvents = scheduledEvents.filter(event => event.type === 'flight').length;
        const standbyCount = buildIntelligenceEvents.filter(event =>
            event.resourceId.startsWith('STBY') || event.resourceId.startsWith('BNF-STBY')
        ).length;
        const aircraftUtilization = lastBuildAnalysis.availableAircraft > 0
            ? (flightEvents / lastBuildAnalysis.availableAircraft) * 100
            : 0;

        return {
            ...lastBuildAnalysis,
            totalEvents,
            courseAnalysis: scopedCourseAnalysis,
            timeDistribution: {
                eventsByHour,
                clusteringScore,
                uniformityScore: 1 - clusteringScore,
            },
            resourceUtilization: {
                ...lastBuildAnalysis.resourceUtilization,
                aircraftUtilization,
                standbyCount,
            },
            insights: lastBuildAnalysis.insights || [],
        };
    }, [buildIntelligenceCourseSet, buildIntelligenceEvents, lastBuildAnalysis]);

    const buildIntelligenceCancellationRecords = useMemo(() => {
        const scopedEventIds = new Set(buildIntelligenceEvents.map(event => event.id));
        return cancellationRecords.filter(record => {
            if (record.eventId && scopedEventIds.has(record.eventId)) return true;
            const affectedPersonnel = String(record.personnelAffected || '')
                .split(/[,;\n]/)
                .map(person => person.trim())
                .filter(Boolean);
            return affectedPersonnel.some(person => buildIntelligencePersonnelSet.has(person));
        });
    }, [buildIntelligenceEvents, buildIntelligencePersonnelSet, cancellationRecords]);

    const closeDfpContextMenu = useCallback(() => {
        setDfpContextMenu(null);
    }, []);

    useEffect(() => {
        if (!dfpContextMenu) return;
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') closeDfpContextMenu();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [closeDfpContextMenu, dfpContextMenu]);

    useEffect(() => {
        closeDfpContextMenu();
    }, [activeView, closeDfpContextMenu]);

    const formatContextMenuTime = useCallback((time?: number) => {
        if (typeof time !== 'number' || !Number.isFinite(time)) return '';
        const hours = Math.floor(time);
        const minutes = Math.round((time - hours) * 60);
        return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
    }, []);

    const getContextMenuEvent = useCallback((eventId: string): ScheduleEvent | null => {
        if (!eventId) return null;
        return (
            (eventSegmentsForDate || []).find((event: any) => event.id === eventId) ||
            (publishedSchedules[date] || []).find((event: ScheduleEvent) => event.id === eventId) ||
            null
        ) as ScheduleEvent | null;
    }, [date, eventSegmentsForDate, publishedSchedules]);

    const copyContextSummary = useCallback((summary: string) => {
        if (!summary) return;
        navigator.clipboard?.writeText(summary).catch(() => {});
    }, []);

    const handleDfpWorkspaceContextMenu = useCallback((event: React.MouseEvent<HTMLDivElement>) => {
        const target = event.target as HTMLElement | null;
        const workspace = event.currentTarget;
        if (!target || !workspace.contains(target)) return;

        event.preventDefault();
        event.stopPropagation();

        const contextElement = target.closest('[data-dfp-context-kind]') as HTMLElement | null;
        const gridElement = target.closest('[data-schedule-grid="true"]') as HTMLElement | null;
        const contextKind = getContextDatasetValue(contextElement, 'dfpContextKind');
        const eventId = getContextDatasetValue(contextElement, 'dfpEventId');
        const resourceId = getContextDatasetValue(contextElement, 'dfpResourceId');
        const aircraftNumber = getContextDatasetValue(contextElement, 'dfpAircraftNumber');
        const resourceLabel = getContextDatasetValue(contextElement, 'dfpResourceLabel') || resourceId;
        const eventLabel = getContextDatasetValue(contextElement, 'dfpEventLabel');
        const primaryPerson = getContextDatasetValue(contextElement, 'dfpPrimaryPerson');
        const secondaryPerson = getContextDatasetValue(contextElement, 'dfpSecondaryPerson');
        const selectedEvent = getContextMenuEvent(eventId);
        const canEditActiveDfp = canEditDfpTiles && !isViewingPastDfp;
        const canUseValidation = canRunValidation;
        const menuItems: DfpContextMenuItem[] = [];
        let title = 'DFP Workspace';
        let subtitle = activeView;
        let kind = contextKind || 'workspace';

        const openEventDetails = () => {
            if (selectedEvent) handleOpenModal(selectedEvent);
        };
        const eventSummary = selectedEvent
            ? `${selectedEvent.flightNumber || eventLabel || selectedEvent.id} ${selectedEvent.resourceId || ''} ${formatContextMenuTime(selectedEvent.startTime)}-${formatContextMenuTime(selectedEvent.startTime + selectedEvent.duration)}`.trim()
            : '';

        if (selectedEvent && contextKind !== 'aircraft' && contextKind !== 'aircraft-slot') {
            const isSimulatorEvent = selectedEvent.type === 'ftd' || selectedEvent.type === 'cpt';
            const isDutySupervisor = contextKind === 'duty-supervisor' || selectedEvent.resourceId === 'Duty Sup';
            title = isDutySupervisor
                ? 'Duty Supervisor'
                : isSimulatorEvent
                    ? `Simulator ${selectedEvent.flightNumber || eventLabel || ''}`.trim()
                    : selectedEvent.type === 'flight'
                        ? `Flight ${selectedEvent.flightNumber || eventLabel || ''}`.trim()
                        : selectedEvent.flightNumber || eventLabel || 'Schedule Event';
            subtitle = [
                selectedEvent.resourceId,
                `${formatContextMenuTime(selectedEvent.startTime)}-${formatContextMenuTime(selectedEvent.startTime + selectedEvent.duration)}`,
                primaryPerson || selectedEvent.instructor || selectedEvent.pilot || '',
                secondaryPerson || selectedEvent.student || selectedEvent.crew || '',
            ].filter(Boolean).join(' | ');
            menuItems.push(
                { label: 'Open Details', detail: 'Open the selected schedule event.', onSelect: openEventDetails },
                { label: 'Edit Event', detail: canEditActiveDfp ? 'Open details in the normal edit workflow.' : 'Tile editing is not available for this DFP.', disabled: !canEditActiveDfp, onSelect: openEventDetails },
                { label: selectedEvent.type === 'flight' ? 'Assign Aircraft' : 'Open Flight Line', detail: 'Open the aircraft flight-line panel.', disabled: !canEditActiveDfp, onSelect: () => {
                    setShowDfpSidePanel(false);
                    setShowFlightLinePanel(true);
                }},
                { label: 'Select Tile', detail: 'Add this tile to the current DFP selection.', onSelect: () => {
                    setSelectedEventIds(new Set([...Array.from(selectedEventIds), selectedEvent.id]));
                }},
                { label: 'Copy Event Summary', detail: eventSummary, onSelect: () => copyContextSummary(eventSummary) }
            );
            if (canUseValidation) {
                menuItems.push({ label: showValidation ? 'Hide Validation' : 'Show Validation', detail: 'Toggle schedule validation overlay.', onSelect: () => setShowValidation(!showValidation) });
            }
        } else if (aircraftNumber || contextKind === 'aircraft' || contextKind === 'aircraft-slot') {
            title = aircraftNumber ? `Aircraft ${aircraftNumber}` : 'Aircraft';
            subtitle = [resourceLabel || 'Flight Line', selectedEvent ? selectedEvent.flightNumber || eventLabel : ''].filter(Boolean).join(' | ');
            kind = 'aircraft';
            menuItems.push(
                { label: 'Open Flight Line', detail: 'Open aircraft inventory and unavailable bays.', onSelect: () => {
                    setShowDfpSidePanel(false);
                    setShowFlightLinePanel(true);
                }},
                { label: 'Copy Aircraft Number', detail: aircraftNumber || resourceLabel, disabled: !(aircraftNumber || resourceLabel), onSelect: () => copyContextSummary(aircraftNumber || resourceLabel) }
            );
        } else if (resourceId || contextKind === 'aircraft-resource' || contextKind === 'simulator-resource' || contextKind === 'resource') {
            const isSimulatorResource = contextKind === 'simulator-resource';
            const isDutySupervisorResource = contextKind === 'duty-supervisor' || resourceId === 'Duty Sup';
            title = isDutySupervisorResource
                ? 'Duty Supervisor Row'
                : isSimulatorResource
                    ? `Simulator ${resourceLabel || resourceId}`.trim()
                    : contextKind === 'aircraft-resource'
                        ? `Aircraft Row ${resourceLabel || resourceId}`.trim()
                        : resourceLabel || resourceId || 'Resource Row';
            subtitle = 'Schedule resource';
            menuItems.push(
                { label: 'Copy Resource Name', detail: resourceLabel || resourceId, onSelect: () => copyContextSummary(resourceLabel || resourceId) },
                { label: 'Open Flight Line', detail: 'Open aircraft inventory and unavailable bays.', onSelect: () => {
                    setShowDfpSidePanel(false);
                    setShowFlightLinePanel(true);
                }}
            );
            if (canUseValidation) {
                menuItems.push({ label: showValidation ? 'Hide Validation' : 'Show Validation', detail: 'Toggle schedule validation overlay.', onSelect: () => setShowValidation(!showValidation) });
            }
        } else if (gridElement) {
            const rect = gridElement.getBoundingClientRect();
            const pixelsPerHour = Number(gridElement.dataset.schedulePixelsPerHour || 200);
            const startHour = Number(gridElement.dataset.scheduleStartHour || 0);
            const time = startHour + Math.max(0, event.clientX - rect.left) / Math.max(1, pixelsPerHour);
            const rowIndex = Math.floor(Math.max(0, event.clientY - rect.top) / 32);
            const gridResource = buildResources[rowIndex] || '';
            title = 'Empty Schedule Space';
            subtitle = [gridResource, formatContextMenuTime(time)].filter(Boolean).join(' | ');
            kind = 'empty-schedule-space';
            menuItems.push(
                { label: 'Add Flight Tile', detail: canEditActiveDfp ? 'Create a new flight event.' : 'Tile editing is not available for this DFP.', disabled: !canEditActiveDfp, onSelect: () => {
                    setIsAddingTile(true);
                    handleOpenModal(null, { type: 'flight' });
                }},
                { label: 'Add Ground Tile', detail: canEditActiveDfp ? 'Create a new ground event.' : 'Tile editing is not available for this DFP.', disabled: !canEditActiveDfp, onSelect: () => setShowAddGroundEvent(true) },
                { label: 'Open Flight Line', detail: 'Open aircraft inventory and unavailable bays.', onSelect: () => {
                    setShowDfpSidePanel(false);
                    setShowFlightLinePanel(true);
                }}
            );
            if (canUseValidation) {
                menuItems.push({ label: showValidation ? 'Hide Validation' : 'Show Validation', detail: 'Toggle schedule validation overlay.', onSelect: () => setShowValidation(!showValidation) });
            }
        } else {
            title = 'DFP Workspace';
            subtitle = activeView;
            kind = 'workspace';
            menuItems.push(
                { label: activeView === 'Program Schedule' ? 'Open Flight Line' : 'Go To DFP', detail: 'Return to the main schedule workspace.', onSelect: () => {
                    if (activeView !== 'Program Schedule') handleNavigation('Program Schedule');
                    else setShowFlightLinePanel(true);
                }},
                { label: 'Open Admin Panel', detail: 'Available to platform administrators.', disabled: !['ADMIN', 'SUPER_ADMIN'].includes(String(sessionUser?.role || authUser?.role || '').toUpperCase()), onSelect: () => setShowAdminPanel(true) }
            );
        }

        if (menuItems.length === 0) return;
        setDfpContextMenu({
            x: event.clientX,
            y: event.clientY,
            title,
            subtitle,
            kind,
            items: menuItems,
        });
    }, [
        activeView,
        authUser?.role,
        buildResources,
        canEditDfpTiles,
        canRunValidation,
        closeDfpContextMenu,
        copyContextSummary,
        formatContextMenuTime,
        getContextMenuEvent,
        handleNavigation,
        handleOpenModal,
        isViewingPastDfp,
        selectedEventIds,
        sessionUser?.role,
        setSelectedEventIds,
        showValidation,
    ]);

    const handleDfpWorkspaceMouseDownCapture = useCallback((event: React.MouseEvent<HTMLDivElement>) => {
        if (event.button === 0 && dfpContextMenu) {
            closeDfpContextMenu();
        }
    }, [closeDfpContextMenu, dfpContextMenu]);

    const handleDeleteTraineeFromRoster = useCallback(async (trainee: Trainee) => {
        const dbId = String((trainee as any).id || '').trim();
        const traineeName = trainee.fullName || trainee.name || 'trainee';

        try {
            if (dbId && (trainee as any)._dataSource === 'database') {
                const response = await fetch(scopedApiPath(`/api/trainees/${encodeURIComponent(dbId)}`), {
                    method: 'DELETE',
                    credentials: 'include',
                });
                if (!response.ok) {
                    const errorText = await response.text().catch(() => '');
                    throw new Error(errorText || `Delete failed (${response.status})`);
                }
            } else {
                console.warn(`[Trainee Delete] ${traineeName} has no database id; removing from local roster only.`);
            }

            setTraineesData(prev => prev.filter(t => (
                t.idNumber !== trainee.idNumber
                && String((t as any).id || '') !== dbId
                && t.fullName !== trainee.fullName
            )));
            setTraineeLMPs(prev => {
                const newLMPs = new Map(prev);
                newLMPs.delete(trainee.fullName);
                newLMPs.delete(trainee.name);
                return newLMPs;
            });
            logAudit({
                page: 'Trainee Roster',
                action: 'delete',
                description: 'Deleted trainee from roster',
                changes: `Removed: ${trainee.rank} ${trainee.name} (${trainee.course}) - ID: ${trainee.idNumber}`
            });
            setSuccessMessage(`${traineeName} deleted.`);
        } catch (error) {
            console.error('[Trainee Delete] Failed:', error);
            setErrorMessage(`Could not delete ${traineeName}. ${error instanceof Error ? error.message : String(error)}`);
        }
    }, [scopedApiPath]);


